def load_admin_config() -> dict:
    cfg = {"admin_password": os.environ.get("H3_ADMIN_PASSWORD", "admin123")}
    if ADMIN_CFG_FILE.is_file():
        try:
            saved = json.loads(ADMIN_CFG_FILE.read_text(encoding="utf-8"))
            if isinstance(saved, dict) and saved.get("admin_password"):
                cfg.update(saved)
        except Exception:
            pass
    return cfg


def save_admin_config(new_pass: str) -> dict:
    cfg = load_admin_config()
    if new_pass and str(new_pass).strip():
        cfg["admin_password"] = str(new_pass).strip()
    try:
        ADMIN_CFG_FILE.write_text(json.dumps(cfg, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass
    return cfg

def parse_ref2va_prompt_text(txt: str) -> dict:
    """Tự động phân tích prompt Ref2VA, prompt thô hoặc JSON và bóc tách thành các trường dữ liệu."""
    txt = (txt or "").strip()
    if not txt:
        return {}
    
    if txt.startswith("{") and txt.endswith("}"):
        try:
            return json.loads(txt)
        except Exception:
            pass

    sections = [
        "subject_definitions",
        "summary",
        "retention_analysis",
        "detailed_description",
        "overall_soundscape",
        "non_diegetic_music"
    ]
    aliases = {
        "subjects": "subject_definitions",
        "subject": "subject_definitions",
        "retention": "retention_analysis",
        "shots": "detailed_description",
        "description": "detailed_description",
        "soundscape": "overall_soundscape",
        "sound": "overall_soundscape",
        "audio": "overall_soundscape",
        "music": "non_diegetic_music",
        "bgm": "non_diegetic_music"
    }

    all_keys = list(sections) + list(aliases.keys())
    keys_pat = "|".join(re.escape(k) for k in all_keys)
    res = {s: "" for s in sections}

    pattern = rf'(?:^|\n)\s*(?:\d+[\.\)]\s*)?({keys_pat})\s*[:：]\s*(.*?)(?=(?:\n\s*(?:\d+[\.\)]\s*)?(?:{keys_pat})\s*[:：]|$))'
    matches = list(re.finditer(pattern, txt, re.DOTALL | re.IGNORECASE))

    if matches:
        for m in matches:
            raw_key = m.group(1).lower().strip()
            val = m.group(2).strip()
            norm_key = aliases.get(raw_key, raw_key)
            if norm_key in res:
                res[norm_key] = val
    else:
        # Fallback phân tích prompt thô tự do
        sub_lines = []
        other_lines = []
        for line in txt.splitlines():
            line_s = line.strip()
            if not line_s:
                continue
            if re.search(r'<Picture\s+\d+>|\(S\d+\)', line_s, re.IGNORECASE):
                sub_lines.append(line_s)
            else:
                other_lines.append(line_s)
        
        if sub_lines:
            res["subject_definitions"] = "\n".join(sub_lines)
        else:
            res["subject_definitions"] = "(S1) is the main character shown in <Picture 1>."
            
        remaining = " ".join(other_lines)
        res["summary"] = remaining[:150] + ("..." if len(remaining) > 150 else "")
        res["retention_analysis"] = "Maintain facial structure, costume details, and character proportions across motion."
        res["detailed_description"] = remaining if remaining else "[Shot 1] The camera captures (S1) in dynamic motion."
        res["overall_soundscape"] = "Natural ambient soundscape, environment noise."
        res["non_diegetic_music"] = "N/A"

    # Phân tích danh sách Shot từ detailed_description
    det = res.get("detailed_description", "").strip()
    shots = []
    shot_matches = list(re.finditer(r'(?:\[Shot\s*(\d+)\]|Shot\s*(\d+)[:\.]?)\s*(.*?)(?=(?:\[Shot\s*\d+\]|Shot\s*\d+[:\.]?|$))', det, re.DOTALL | re.IGNORECASE))
    if shot_matches:
        for idx, sm in enumerate(shot_matches):
            b = sm.group(3).strip()
            if not b:
                continue
            t_m = re.search(r'At\s+(\d{1,2}):(\d{2}(?:\.\d+)?)', b, re.IGNORECASE)
            if t_m:
                start_s = round(float(t_m.group(1)) * 60 + float(t_m.group(2)), 2)
            else:
                t_m2 = re.search(r'(?:At\s+)?(\d+(?:\.\d+)?)\s*s(?:ec)?', b, re.IGNORECASE)
                start_s = float(t_m2.group(1)) if t_m2 else (0.0 if not shots else round(shots[-1]["start"] + 4.0, 1))

            d_m = re.search(r'<d>(?:\[Chinese\])?\s*(.*?)</d>', b, re.DOTALL | re.IGNORECASE)
            dialogue = ""
            speaker = "(S1)"
            clean_desc = b
            if d_m:
                dialogue = d_m.group(1).strip()
                before = b[:d_m.start()].strip()
                spk_m = re.search(r'(?:the\s+subject\s+)?(\(S\d+\)|[A-Za-z0-9_\s]{1,30})?\s+says,?\s*$', before, re.IGNORECASE)
                if spk_m:
                    if spk_m.group(1):
                        speaker = spk_m.group(1).strip()
                    clean_desc = before[:spk_m.start()].strip()
                else:
                    clean_desc = before
                after = b[d_m.end():].strip()
                if after:
                    clean_desc = (clean_desc + " " + after).strip()
            else:
                q_m = re.search(r'(\(S\d+\)|[A-Za-z0-9_\s]{1,30})?\s+says[:,\s]+["“\']([^"”\']+)["”\']', b, re.IGNORECASE)
                if q_m:
                    dialogue = q_m.group(2).strip()
                    if q_m.group(1):
                        speaker = q_m.group(1).strip()
                    clean_desc = b[:q_m.start()].strip() + " " + b[q_m.end():].strip()

            clean_desc = re.sub(r'^At\s+[\d:\.]+,?\s*', '', clean_desc, flags=re.IGNORECASE).strip(' ,.')
            shots.append({"start": start_s, "desc": clean_desc, "speaker": speaker, "dialogue": dialogue})
    else:
        shots = [{"start": 0.0, "desc": det or "Cinematic view of the scene.", "speaker": "(S1)", "dialogue": ""}]

    if shots:
        shots[0]["start"] = 0.0

    if not res.get("summary"):
        res["summary"] = (res.get("subject_definitions") or "Cinematic dynamic video scene.")[:150]
    if not res.get("retention_analysis"):
        res["retention_analysis"] = "Maintain facial structure, costume details, and character proportions across motion."
    if not res.get("overall_soundscape"):
        res["overall_soundscape"] = "Natural ambient soundscape, environment noise."
    if not res.get("non_diegetic_music"):
        res["non_diegetic_music"] = "N/A"

    res["shots"] = shots
    return res

def select_save_path(initial_dir: str = ""):
    """Mở hộp thoại chọn thư mục lưu video chuẩn Windows native (UTF-8, topmost)."""
    picker_script = SCRIPT_DIR / "scripts" / "picker.py"
    cmd = [sys.executable, str(picker_script), "folder"]
    if initial_dir and os.path.isdir(initial_dir):
        cmd.append(initial_dir)
    try:
        res = subprocess.run(
            cmd,
            capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=60
        )
        out = (res.stdout or "").strip()
        if out:
            folder = os.path.normpath(out)
            ts = time.strftime("%Y%m%d_%H%M%S")
            return os.path.join(folder, f"minimax_h3_{ts}.mp4")
    except Exception:
        pass
    return ""

def select_folder_path(initial_dir: str = ""):
    """Mở hộp thoại chọn thư mục Windows native (UTF-8, topmost)."""
    picker_script = SCRIPT_DIR / "scripts" / "picker.py"
    cmd = [sys.executable, str(picker_script), "folder"]
    if initial_dir and os.path.isdir(initial_dir):
        cmd.append(initial_dir)
    try:
        res = subprocess.run(
            cmd,
            capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=60
        )
        out = (res.stdout or "").strip()
        if out:
            return os.path.normpath(out)
    except Exception:
        pass
    return ""

def _find_ffmpeg():
    """Tự động chọn binary FFmpeg chuẩn theo Hệ điều hành (Linux Ubuntu VPS dùng /usr/bin/ffmpeg, Windows dùng ffmpeg.exe)."""
    if os.name != "nt":
        for linux_c in [SCRIPT_DIR / "ffmpeg", Path("/usr/bin/ffmpeg"), Path("/usr/local/bin/ffmpeg")]:
            if linux_c.is_file() and os.access(str(linux_c), os.X_OK):
                return str(linux_c)
        return shutil.which("ffmpeg") or "ffmpeg"
    candidates = [
        SCRIPT_DIR / "ffmpeg.exe",
        Path(r"C:\Users\Admin\Desktop\Dự án Riêng\Tạo video seedance vip\ffmpeg.exe"),
        Path(r"D:\capcut_tho\ffmpeg-2025-12-24-git-abb1524138-full_build\bin\ffmpeg.exe"),
    ]
    for c in candidates:
        if c.exists():
            return str(c.resolve())
    return shutil.which("ffmpeg") or "ffmpeg"


def _find_ffprobe():
    """Tự động chọn binary FFprobe chuẩn trên cả Linux Ubuntu VPS lẫn Windows."""
    if os.name != "nt":
        for linux_p in [SCRIPT_DIR / "ffprobe", Path("/usr/bin/ffprobe"), Path("/usr/local/bin/ffprobe")]:
            if linux_p.is_file() and os.access(str(linux_p), os.X_OK):
                return str(linux_p)
        return shutil.which("ffprobe") or "ffprobe"
    ff_bin = _find_ffmpeg()
    cand = Path(ff_bin).with_name("ffprobe.exe")
    if cand.is_file():
        return str(cand)
    return shutil.which("ffprobe") or "ffprobe"

def _normalize_linux_cross_path(p: str) -> str:
    p_clean = str(p or "").strip().replace("\\", "/")
    if not p_clean:
        return ""
    low = p_clean.lower()
    for prefix in ("d:/h3 video/minimax-h3-colab-skill-main/", "/mnt/d/h3 video/minimax-h3-colab-skill-main/"):
        if low.startswith(prefix):
            rel = p_clean[len(prefix):]
            return str((SCRIPT_DIR / rel).resolve())
    if low.startswith("c:/") or low.startswith("/mnt/c/") or low.startswith("d:/") or low.startswith("/mnt/d/"):
        bname = p_clean.rstrip("/").split("/")[-1]
        dl_dir = Path.home() / "Downloads"
        dl_dir.mkdir(parents=True, exist_ok=True)
        if bname.lower() in ("downloads", "h3_batch_videos", "admin"):
            return str(dl_dir.resolve())
        return str((dl_dir / bname).resolve())
    return os.path.abspath(p_clean)

def wsl_path(p):
    if os.name != "nt":
        return _normalize_linux_cross_path(p)
    p = os.path.abspath(p).replace("\\", "/")
    return f"/mnt/{p[0].lower()}{p[2:]}" if len(p) >= 2 and p[1] == ":" else p

def win_path(p):
    if not p: return ""
    if os.name != "nt":
        return _normalize_linux_cross_path(p)
    p = str(p).replace("\\", "/")
    if p.startswith("/mnt/") and len(p) > 6 and p[6] == "/":
        drive = p[5].upper()
        rest = p[7:].replace("/", "\\")
        return f"{drive}:\\{rest}"
    return os.path.abspath(p)

H3_RECORDS_FILE = SCRIPT_DIR / "temp" / "h3_library_records.json"
_h3_last_record_ts = {}  # job_id -> thời điểm ghi video gần nhất (ước tính thời gian tạo từng video trong batch)
VIDEO_META_DIR = SCRIPT_DIR / "output" / "video_meta"
VIDEO_META_REFS_DIR = VIDEO_META_DIR / "refs"
H3_VIDEO_REFS_ARCHIVE_DIR = VIDEO_META_REFS_DIR


def normalize_ref_image_items(raw_refs) -> list[dict]:
    """Chuẩn hóa danh sách ảnh tham chiếu (<Picture 1..N>) và tự động sao lưu ảnh từ temp/ sang kho vĩnh viễn output/video_meta/refs/."""
    if not raw_refs:
        return []
    VIDEO_META_REFS_DIR.mkdir(parents=True, exist_ok=True)
    items = []
    temp_dir_norm = str((SCRIPT_DIR / "temp").resolve()).lower()
    for idx, r in enumerate(raw_refs):
        if isinstance(r, dict):
            raw_p = r.get("path") or r.get("local_path") or ""
            disp_name = r.get("display_name") or r.get("name") or ""
            cat_vi = r.get("category_vi") or ""
            tag = r.get("tag") or r.get("picture_tag") or f"<Picture {idx + 1}>"
            slot = int(r.get("slot") or r.get("picture_index") or (idx + 1))
            orig_url = r.get("url") or r.get("image_url") or ""
            fname = r.get("name") or r.get("filename") or (Path(win_path(raw_p)).name if raw_p else f"Ref_{slot}.png")
        else:
            raw_p = str(r or "")
            disp_name = ""
            cat_vi = ""
            tag = f"<Picture {idx + 1}>"
            slot = idx + 1
            orig_url = ""
            fname = Path(win_path(raw_p)).name if raw_p else f"Ref_{slot}.png"

        p_win = win_path(raw_p) if raw_p else ""
        if p_win and os.path.isfile(p_win):
            p_obj = Path(p_win).resolve()
            # Nếu ảnh đang nằm trong thư mục temp/, sao lưu sang output/video_meta/refs/ để không bao giờ bị mất khi dọn temp
            if str(p_obj).lower().startswith(temp_dir_norm):
                perm_p = VIDEO_META_REFS_DIR / p_obj.name
                if not perm_p.is_file():
                    try:
                        shutil.copy2(p_obj, perm_p)
                    except Exception:
                        perm_p = p_obj
                p_obj = perm_p.resolve()
            p_clean = str(p_obj).replace("\\", "/")
            img_url = f"/api/local-image?path={urllib.parse.quote(str(p_obj))}"
            if not fname:
                fname = p_obj.name
        else:
            p_clean = raw_p.replace("\\", "/") if raw_p else ""
            img_url = orig_url or (f"/api/storyboard/ref-image?name={urllib.parse.quote(fname)}" if fname.startswith("Ref_") else "")

        clean_disp = disp_name or Path(fname).stem.replace("Ref_", "").replace("_s_", "'s ").replace("_", " ")
        items.append({
            "slot": slot,
            "tag": tag,
            "name": fname,
            "filename": fname,
            "short_name": r.get("short_name") if isinstance(r, dict) and r.get("short_name") else clean_disp,
            "display_name": clean_disp,
            "category_vi": cat_vi,
            "path": p_clean,
            "url": img_url,
        })
    return items


def record_h3_video(
    file_path,
    title=None,
    duration=None,
    seed=None,
    prompt=None,
    reference_images=None,
    scene_id=None,
    visual_style=None,
    mode=None,
    lora=None,
    width=None,
    height=None,
    gpu=None,
    job_id=None,
    gen_seconds=None,
    used_cu=None,
    owner_user_id=None,
    owner_username=None,
    prompt_index=None,
):
    """Lưu vết các video do MiniMax H3 tạo ra kèm ĐẦY ĐỦ Ảnh Tham Chiếu (<Picture 1..N>) + Prompt + Cấu hình + Chủ sở hữu để xem lại & Tạo lại."""
    if not file_path:
        return
    try:
        H3_RECORDS_FILE.parent.mkdir(exist_ok=True)
        VIDEO_META_DIR.mkdir(parents=True, exist_ok=True)
        records = []
        if H3_RECORDS_FILE.exists():
            try:
                records = json.loads(H3_RECORDS_FILE.read_text(encoding="utf-8"))
            except Exception:
                records = []
        p_obj = Path(win_path(file_path))
        p_str = str(p_obj.resolve())
        norm_refs = normalize_ref_image_items(reference_images) if reference_images else []

        # Tự động suy luận scene_id (ví dụ E01S001) từ tên file nếu chưa truyền vào
        if not scene_id:
            m_sid = re.search(r"\b(E\d{2}S\d{3})\b", p_obj.name, flags=re.IGNORECASE)
            if m_sid:
                scene_id = m_sid.group(1).upper()

        if job_id and job_id in active_jobs:
            if not owner_user_id:
                owner_user_id = active_jobs[job_id].get("owner_user_id")
            if not owner_username:
                owner_username = active_jobs[job_id].get("owner_username")

        existing = next((r for r in records if r.get("path") == p_str), None)
        if existing:
            if title:
                existing["title"] = title
            if duration is not None:
                existing["duration"] = duration
            if seed is not None:
                existing["seed"] = seed
            if prompt:
                existing["prompt"] = prompt
            if norm_refs:
                existing["reference_images"] = norm_refs
            if scene_id:
                existing["scene_id"] = scene_id
            if visual_style:
                existing["visual_style"] = visual_style
            if mode:
                existing["mode"] = mode
            if lora:
                existing["lora"] = lora
            if width:
                existing["width"] = width
            if height:
                existing["height"] = height
            if gpu:
                existing["gpu"] = gpu
            if job_id:
                existing["job_id"] = job_id
            if owner_user_id:
                existing["owner_user_id"] = owner_user_id
            if owner_username:
                existing["owner_username"] = owner_username
            if prompt_index is not None:
                existing["prompt_index"] = prompt_index
            rec_to_save = existing
        else:
            rec_to_save = {
                "path": p_str,
                "name": p_obj.name,
                "title": title or p_obj.name,
                "duration": duration,
                "seed": seed,
                "prompt": prompt or "",
                "reference_images": norm_refs,
                "scene_id": scene_id or "",
                "visual_style": visual_style or "",
                "mode": mode or "reference",
                "lora": lora or "pdmd",
                "width": width or 1376,
                "height": height or 768,
                "gpu": gpu or "A100",
                "job_id": job_id or "",
                "owner_user_id": owner_user_id or "",
                "owner_username": owner_username or "",
                "prompt_index": prompt_index,
                "created_at": time.time(),
            }
            records.append(rec_to_save)

        # Tổng thời gian tạo video (giây): giá trị truyền vào luôn được ưu tiên;
        # nếu thiếu thì ước tính theo mốc bắt đầu job hoặc video trước đó của cùng job (không ghi đè giá trị đã có).
        try:
            now_ts = time.time()
            if gen_seconds is not None and float(gen_seconds) > 0:
                rec_to_save["gen_seconds"] = int(float(gen_seconds))
            elif (not rec_to_save.get("gen_seconds") and job_id and job_id in active_jobs
                  and active_jobs[job_id].get("status") in ("starting", "running")):
                base_ts = active_jobs[job_id].get("start_time_ts")
                last_ts = _h3_last_record_ts.get(job_id)
                if last_ts and (not base_ts or last_ts > base_ts):
                    base_ts = last_ts
                if base_ts and now_ts > base_ts:
                    rec_to_save["gen_seconds"] = int(now_ts - base_ts)
                    _h3_last_record_ts[job_id] = now_ts
            if used_cu is not None and float(used_cu) > 0:
                rec_to_save["used_cu"] = round(float(used_cu), 2)
        except Exception:
            pass

        H3_RECORDS_FILE.write_text(json.dumps(records, ensure_ascii=False, indent=2), encoding="utf-8")
        # Lưu thêm bản sidecar JSON vĩnh viễn trong output/video_meta/
        if rec_to_save.get("prompt") or rec_to_save.get("reference_images"):
            sidecar = VIDEO_META_DIR / f"{p_obj.stem}.json"
            sidecar.write_text(json.dumps(rec_to_save, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass


def get_h3_video_meta(file_path) -> dict:
    """Đọc lại đầy đủ hồ sơ Ảnh Tham Chiếu + Prompt + Thông số của 1 file video."""
    if not file_path:
        return {}
    p_obj = Path(win_path(file_path))
    p_str = str(p_obj.resolve())
    base_stem = re.sub(r"_Upscale_(?:1080p|2K|4K)$", "", p_obj.stem, flags=re.IGNORECASE)

    # 1. Tìm trong sidecar output/video_meta/
    for cand_stem in (p_obj.stem, base_stem):
        sc_fp = VIDEO_META_DIR / f"{cand_stem}.json"
        if sc_fp.is_file():
            try:
                d = json.loads(sc_fp.read_text(encoding="utf-8"))
                if d.get("prompt") or d.get("reference_images"):
                    return d
            except Exception:
                pass

    # 2. Tìm trong H3_RECORDS_FILE
    if H3_RECORDS_FILE.is_file():
        try:
            records = json.loads(H3_RECORDS_FILE.read_text(encoding="utf-8"))
            for r in reversed(records):
                rp = str(r.get("path") or "")
                r_stem = Path(rp).stem if rp else ""
                if rp == p_str or r_stem in (p_obj.stem, base_stem):
                    if r.get("prompt") or r.get("reference_images"):
                        return r
        except Exception:
            pass

    # 3. Đối chiếu từ active_jobs nếu vừa chạy trong phiên hiện tại
    for jid, j in active_jobs.items():
        j_out = win_path(j.get("output") or "")
        if j_out and (Path(j_out).stem in (p_obj.stem, base_stem)):
            return {
                "prompt": j.get("prompt") or "",
                "reference_images": normalize_ref_image_items(j.get("ref_items") or j.get("images") or []),
                "mode": j.get("mode") or "reference",
                "lora": j.get("lora") or "pdmd",
                "duration": j.get("duration") or 15,
                "width": j.get("width") or 1376,
                "height": j.get("height") or 768,
                "seed": j.get("seed"),
                "gpu": j.get("gpu") or "A100",
                "job_id": jid,
            }
        for v in j.get("videos") or []:
            vp = win_path(v.get("path") or "")
            if vp and (Path(vp).stem in (p_obj.stem, base_stem)):
                return {
                    "prompt": v.get("prompt") or j.get("prompt") or "",
                    "reference_images": normalize_ref_image_items(v.get("reference_images") or j.get("ref_items") or j.get("images") or []),
                    "scene_id": v.get("scene_id") or "",
                    "visual_style": v.get("visual_style") or "",
                    "mode": v.get("mode") or j.get("mode") or "reference",
                    "lora": v.get("lora") or j.get("lora") or "pdmd",
                    "duration": v.get("duration") or j.get("duration") or 15,
                    "width": v.get("width") or j.get("width") or 1376,
                    "height": v.get("height") or j.get("height") or 768,
                    "seed": v.get("seed") or j.get("seed"),
                    "gpu": j.get("gpu") or "A100",
                    "job_id": jid,
                }

    # 4. Nếu tên file có mã cảnh Storyboard (ví dụ Storyboard_E01S001.mp4), tự động lấy từ current_storyboard.json
    m_sid = re.search(r"\b(E\d{2}S\d{3})\b", p_obj.name, flags=re.IGNORECASE)
    if m_sid:
        try:
            from scripts.blocking_storyboard import load_cached_storyboard
            sb = load_cached_storyboard()
            sid = m_sid.group(1).upper()
            sc = next((x for x in (sb.get("scenes") or []) if str(x.get("scene_id") or "").upper() == sid), None)
            if sc:
                return {
                    "scene_id": sid,
                    "title": sc.get("title") or sid,
                    "prompt": sc.get("h3_prompt") or "",
                    "visual_style": sc.get("visual_style") or sb.get("visual_style") or "",
                    "reference_images": normalize_ref_image_items(sc.get("picture_bindings") or []),
                    "mode": "reference",
                    "lora": "pdmd",
                    "duration": 15,
                    "width": 1376,
                    "height": 768,
                }
        except Exception:
            pass

    return {}


def remove_h3_record(file_path):
    """Xóa bỏ vết video gốc thừa khỏi danh sách thư viện khi đã có bản upscale."""
    if not file_path:
        return
    try:
        if not H3_RECORDS_FILE.exists():
            return
        records = json.loads(H3_RECORDS_FILE.read_text(encoding="utf-8"))
        p_obj = Path(win_path(file_path))
        p_str = str(p_obj.resolve())
        new_records = [r for r in records if r.get("path") != p_str and r.get("name") != p_obj.name]
        H3_RECORDS_FILE.write_text(json.dumps(new_records, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass

def collect_library_video_files():
    """Thu thập toàn bộ file MP4 đang hiển thị trong Thư Viện (không ghi hồ sơ, không dọn dẹp)."""
    cands = []
    try:
        if H3_RECORDS_FILE.exists():
            for r in json.loads(H3_RECORDS_FILE.read_text(encoding="utf-8")) or []:
                cands.append(Path(win_path(r.get("path", ""))))
    except Exception:
        pass
    try:
        for j in list(active_jobs.values()):
            if j.get("output"):
                cands.append(Path(win_path(j.get("output"))))
            for v in j.get("videos", []) or []:
                cands.append(Path(win_path(v.get("path", ""))))
    except Exception:
        pass
    for d in (SCRIPT_DIR / "output", Path(r"C:\Users\Admin\Downloads\H3_Batch_Videos")):
        try:
            if d.exists():
                cands.extend(d.rglob("*.mp4"))
        except Exception:
            pass
    try:
        dl_dir = Path.home() / "Downloads"
        if dl_dir.exists():
            for f in dl_dir.glob("*.mp4"):
                fn = f.name.lower()
                if "minimax_h3" in fn or "h3_batch" in fn or "storyboard_" in fn or fn.startswith("minimax_") or fn.startswith("h3_"):
                    cands.append(f)
    except Exception:
        pass
    out, seen = [], set()
    for f in cands:
        try:
            if str(f) in ("", ".") or f.suffix.lower() != ".mp4" or not f.is_file():
                continue
            k = str(f.resolve()).lower()
            if k in seen:
                continue
            seen.add(k)
            out.append(f)
        except Exception:
            pass
    return out

def delete_all_library_videos():
    """Xoá toàn bộ video thư viện: ưu tiên đưa vào Thùng rác Windows, lỗi thì xoá vĩnh viễn."""
    files = collect_library_video_files()
    deleted, failed = [], []
    if not files:
        return deleted, failed
    if os.name == "nt":
        try:
            list_file = SCRIPT_DIR / "temp" / "_delete_all_list.txt"
            list_file.parent.mkdir(parents=True, exist_ok=True)
            list_file.write_text("\n".join(str(f.resolve()) for f in files), encoding="utf-8")
            ps = (
                "Add-Type -AssemblyName Microsoft.VisualBasic; "
                f"Get-Content -LiteralPath '{str(list_file)}' -Encoding UTF8 | ForEach-Object {{ "
                "if ($_ -and (Test-Path -LiteralPath $_)) { try { "
                "[Microsoft.VisualBasic.FileIO.FileSystem]::DeleteFile($_, 'OnlyErrorDialogs', 'SendToRecycleBin') "
                "} catch {} } }"
            )
            subprocess.run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", ps],
                           capture_output=True, timeout=600)
            try:
                list_file.unlink(missing_ok=True)
            except Exception:
                pass
        except Exception:
            pass
    for f in files:
        try:
            if f.exists():
                f.unlink()
            deleted.append(str(f))
        except Exception as e:
            failed.append({"path": str(f), "error": str(e)})
    # Dọn hồ sơ thư viện của các file đã xoá (kể cả hồ sơ bản gốc của video đã upscale)
    try:
        if H3_RECORDS_FILE.exists():
            gone = {str(Path(p).resolve()).lower() for p in deleted}
            gone_stems = {re.sub(r"_Upscale_(?:1080p|2K|4K)$", "", Path(p).stem, flags=re.IGNORECASE).lower() for p in deleted}
            records = json.loads(H3_RECORDS_FILE.read_text(encoding="utf-8")) or []
            keep = []
            for r in records:
                try:
                    rp = Path(win_path(r.get("path", "")))
                    if str(rp.resolve()).lower() in gone or (not rp.is_file() and rp.stem.lower() in gone_stems):
                        continue
                except Exception:
                    pass
                keep.append(r)
            H3_RECORDS_FILE.write_text(json.dumps(keep, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass
    return deleted, failed

def delete_selected_library_videos(target_paths, include_variants=True):
    """Xoá CHỈ các video được chọn trong thư viện (không xoá toàn bộ thư viện)."""
    raw_list = [str(p).strip() for p in (target_paths or []) if str(p).strip()]
    if not raw_list:
        return [], []
    target_files = []
    seen_resolved = set()
    target_stems = set()
    for p_str in raw_list:
        try:
            fp = Path(win_path(p_str))
            if fp.exists() and fp.is_file():
                res_k = str(fp.resolve()).lower()
                if res_k not in seen_resolved:
                    seen_resolved.add(res_k)
                    target_files.append(fp)
            stem_base = re.sub(r"_Upscale_(?:1080p|2K|4K)$", "", fp.stem, flags=re.IGNORECASE).lower()
            if stem_base:
                target_stems.add(stem_base)
        except Exception:
            pass

    if include_variants and target_stems:
        for cand in collect_library_video_files():
            try:
                c_stem = re.sub(r"_Upscale_(?:1080p|2K|4K)$", "", cand.stem, flags=re.IGNORECASE).lower()
                if c_stem in target_stems:
                    res_k = str(cand.resolve()).lower()
                    if res_k not in seen_resolved:
                        seen_resolved.add(res_k)
                        target_files.append(cand)
            except Exception:
                pass

    deleted, failed = [], []
    if os.name == "nt" and target_files:
        try:
            list_file = SCRIPT_DIR / "temp" / "_delete_selected_list.txt"
            list_file.parent.mkdir(parents=True, exist_ok=True)
            list_file.write_text("\n".join(str(f.resolve()) for f in target_files), encoding="utf-8")
            ps = (
                "Add-Type -AssemblyName Microsoft.VisualBasic; "
                f"Get-Content -LiteralPath '{str(list_file)}' -Encoding UTF8 | ForEach-Object {{ "
                "if ($_ -and (Test-Path -LiteralPath $_)) { try { "
                "[Microsoft.VisualBasic.FileIO.FileSystem]::DeleteFile($_, 'OnlyErrorDialogs', 'SendToRecycleBin') "
                "} catch {} } }"
            )
            subprocess.run(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", ps],
                           capture_output=True, timeout=120)
            try:
                list_file.unlink(missing_ok=True)
            except Exception:
                pass
        except Exception:
            pass

    for f in target_files:
        try:
            if f.exists():
                f.unlink()
            deleted.append(str(f))
        except Exception as e:
            failed.append({"path": str(f), "error": str(e)})

    gone = set()
    for p in (deleted + raw_list):
        try:
            gone.add(str(Path(win_path(p)).resolve()).lower())
        except Exception:
            pass

    try:
        if H3_RECORDS_FILE.exists():
            records = json.loads(H3_RECORDS_FILE.read_text(encoding="utf-8")) or []
            keep = []
            for r in records:
                try:
                    rp = Path(win_path(r.get("path", "")))
                    r_stem = re.sub(r"_Upscale_(?:1080p|2K|4K)$", "", rp.stem, flags=re.IGNORECASE).lower()
                    if str(rp.resolve()).lower() in gone or (include_variants and r_stem in target_stems):
                        continue
                except Exception:
                    pass
                keep.append(r)
            H3_RECORDS_FILE.write_text(json.dumps(keep, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass

    # Đồng bộ gỡ khỏi active_jobs nếu trùng file output đã xoá
    try:
        to_pop = []
        for jid, j in list(active_jobs.items()):
            if j.get("status") in ("running", "starting", "queued", "upscaling"):
                continue
            out_p = j.get("output") or ""
            if out_p:
                try:
                    op_res = str(Path(win_path(out_p)).resolve()).lower()
                    op_stem = re.sub(r"_Upscale_(?:1080p|2K|4K)$", "", Path(win_path(out_p)).stem, flags=re.IGNORECASE).lower()
                    if op_res in gone or (include_variants and op_stem in target_stems):
                        to_pop.append(jid)
                except Exception:
                    pass
        for jid in to_pop:
            active_jobs.pop(jid, None)
        if to_pop:
            save_persisted_jobs()
    except Exception:
        pass

    return deleted, failed

_active_jobs_loaded_once = False

def save_persisted_jobs():
    """Lưu trạng thái active_jobs ra đĩa (kể cả khi rỗng {}) để các job đã xoá không bao giờ tự hồi phục lại."""
    try:
        cache_fp = SCRIPT_DIR / "temp" / "active_jobs_cache.json"
        cache_fp.parent.mkdir(parents=True, exist_ok=True)
        cache_fp.write_text(json.dumps(active_jobs, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass

def delete_selected_jobs(job_ids, delete_files=False):
    """Xoá CHỈ các tác vụ (job_id) được chỉ định khỏi lịch sử hàng đợi."""
    ids = [str(x).strip().replace("h3_", "") for x in (job_ids or []) if str(x).strip()]
    removed = []
    paths_to_del = []
    for jid in ids:
        j = active_jobs.get(jid)
        if j:
            if j.get("status") in ("running", "starting", "queued", "upscaling") and (jid in current_running_jobs or jid in job_queue):
                try:
                    cancel_job(jid)
                except Exception:
                    pass
            if delete_files:
                if j.get("output"):
                    paths_to_del.append(j.get("output"))
                for v in (j.get("videos") or []):
                    if isinstance(v, dict) and v.get("path"):
                        paths_to_del.append(v.get("path"))
            active_jobs.pop(jid, None)
            removed.append(jid)
        else:
            # Ngay cả khi chỉ còn trong file cache trên đĩa thì cũng ghi nhận đã xoá
            removed.append(jid)
    # Bắt buộc ghi đè file active_jobs_cache.json (kể cả khi active_jobs rỗng {})
    save_persisted_jobs()
    if delete_files and paths_to_del:
        delete_selected_library_videos(paths_to_del, include_variants=True)
    return removed

def _detect_held_frames(diffs, min_motion=0.6, ratio=0.3):
    """diffs[i] = độ khác biệt giữa frame i và i-1 (diffs[0]=0). Trả về danh sách index frame bị 'đứng hình'
    đơn lẻ (frame i gần như trùng frame i-1 trong khi xung quanh đang chuyển động)."""
    held = []
    n = len(diffs)
    for i in range(1, n - 1):
        win = [diffs[j] for j in range(max(1, i - 4), min(n, i + 5)) if j != i]
        if not win:
            continue
        med = sorted(win)[len(win) // 2]
        if med < min_motion:
            continue  # cảnh gần như tĩnh -> không coi là giật
        if diffs[i] < ratio * med and diffs[i + 1] > 0.8 * med:
            if held and held[-1] == i - 1:
                continue  # chỉ xử lý frame đứng đơn lẻ
            held.append(i)
    return held


def smooth_video_post(input_path, target_fps=24, destutter=False):
    """Hậu kỳ làm mượt video H3 (chạy local, ghi đè đúng file cũ để giữ hồ sơ prompt/ảnh tham chiếu).
    - destutter: phát hiện frame bị lặp/đứng hình đơn lẻ và thay bằng frame nội suy optical-flow (Farneback).
    - target_fps > 24: nội suy chuyển động bù trừ (ffmpeg minterpolate mci/aobmc) lên 30/48/60 fps.
    Âm thanh gốc được giữ nguyên. Trả về (ok, message)."""
    import cv2
    import numpy as np
    ff = _find_ffmpeg()
    inp = Path(win_path(input_path))
    if not inp.exists():
        return False, "Tệp video không tồn tại"
    try:
        target_fps = int(target_fps or 24)
    except Exception:
        target_fps = 24
    target_fps = max(24, min(60, target_fps))
    if target_fps <= 24 and not destutter:
        return True, "Bỏ qua (24 fps gốc, không khử giật)"
    cap = cv2.VideoCapture(str(inp))
    src_fps = cap.get(cv2.CAP_PROP_FPS) or 24.0
    src_fps = src_fps if 1 < src_fps < 121 else 24.0
    work_src = inp
    held = []
    tmp_destut = inp.with_name(inp.stem + "__destut_tmp.mp4")
    if destutter:
        diffs, small_prev = [], None
        while True:
            ok, fr = cap.read()
            if not ok:
                break
            sm = cv2.cvtColor(cv2.resize(fr, (192, max(2, int(192 * fr.shape[0] / fr.shape[1])))), cv2.COLOR_BGR2GRAY).astype(np.float32)
            diffs.append(0.0 if small_prev is None else float(np.mean(np.abs(sm - small_prev))))
            small_prev = sm
        cap.release()
        held = set(_detect_held_frames(diffs))
        if held:
            cap = cv2.VideoCapture(str(inp))
            writer = None
            idx = -1

            def _mid(a, b):
                ga = cv2.cvtColor(a, cv2.COLOR_BGR2GRAY)
                gb = cv2.cvtColor(b, cv2.COLOR_BGR2GRAY)
                h, w = ga.shape
                hs, ws = max(2, h // 2), max(2, w // 2)
                flow = cv2.calcOpticalFlowFarneback(cv2.resize(ga, (ws, hs)), cv2.resize(gb, (ws, hs)), None, 0.5, 4, 21, 3, 5, 1.1, 0)
                flow = cv2.resize(flow, (w, h)) * 2.0
                gx, gy = np.meshgrid(np.arange(w, dtype=np.float32), np.arange(h, dtype=np.float32))
                wa = cv2.remap(a, gx - 0.5 * flow[..., 0], gy - 0.5 * flow[..., 1], cv2.INTER_LINEAR, borderMode=cv2.BORDER_REPLICATE)
                wb = cv2.remap(b, gx + 0.5 * flow[..., 0], gy + 0.5 * flow[..., 1], cv2.INTER_LINEAR, borderMode=cv2.BORDER_REPLICATE)
                return cv2.addWeighted(wa, 0.5, wb, 0.5, 0)

            frames = []
            while True:
                ok, fr = cap.read()
                if not ok:
                    break
                frames.append(fr)
                idx += 1
                # khi đã có frame i+1 thì quyết định frame i
                if len(frames) >= 3:
                    i = idx - 1
                    cur = _mid(frames[-3], frames[-1]) if i in held else frames[-2]
                    if writer is None:
                        hh, ww = cur.shape[:2]
                        writer = cv2.VideoWriter(str(tmp_destut), cv2.VideoWriter_fourcc(*"mp4v"), src_fps, (ww, hh))
                        writer.write(frames[0])
                    writer.write(cur)
                    frames = frames[-2:]
            if frames:
                if writer is None:
                    hh, ww = frames[-1].shape[:2]
                    writer = cv2.VideoWriter(str(tmp_destut), cv2.VideoWriter_fourcc(*"mp4v"), src_fps, (ww, hh))
                    for f0 in frames:
                        writer.write(f0)
                else:
                    writer.write(frames[-1])
            cap.release()
            if writer is not None:
                writer.release()
            if tmp_destut.exists() and tmp_destut.stat().st_size > 1000:
                work_src = tmp_destut
    else:
        cap.release()
    if work_src == inp and (target_fps <= 24 or src_fps >= target_fps - 0.5):
        return True, f"Video đã đạt {round(src_fps)} fps trên GPU Colab — giữ nguyên"
    vf = []
    if target_fps > 24 and src_fps < target_fps - 0.5:
        vf.append(f"minterpolate=fps={target_fps}:mi_mode=mci:mc_mode=aobmc:me_mode=bidir:vsbmc=1:scd=fdiff:scd_threshold=8")
    out_tmp = inp.with_name(inp.stem + "__smooth_tmp" + inp.suffix)
    ok_enc = False
    err = ""
    for encoder in ["h264_nvenc", "libx264"]:
        cmd = [ff, "-y", "-hide_banner", "-i", str(work_src.resolve()), "-i", str(inp.resolve()),
               "-map", "0:v:0", "-map", "1:a:0?"]
        if vf:
            cmd += ["-vf", ",".join(vf)]
        cmd += ["-c:v", encoder, "-pix_fmt", "yuv420p"]
        cmd += (["-cq", "18", "-preset", "p5"] if "nvenc" in encoder else ["-crf", "18", "-preset", "medium"])
        cmd += ["-c:a", "aac", "-b:a", "256k", "-shortest", str(out_tmp.resolve())]
        try:
            res = subprocess.run(cmd, capture_output=True, text=True, timeout=1800)
            if res.returncode == 0 and out_tmp.exists() and out_tmp.stat().st_size > 1000:
                ok_enc = True
                break
            err = (res.stderr or "")[-400:]
        except Exception as e:
            err = str(e)
    try:
        if tmp_destut.exists():
            tmp_destut.unlink()
    except Exception:
        pass
    if not ok_enc:
        try:
            if out_tmp.exists():
                out_tmp.unlink()
        except Exception:
            pass
        return False, f"FFmpeg lỗi khi làm mượt: {err}"
    os.replace(str(out_tmp), str(inp))
    parts = []
    if destutter:
        parts.append(f"khử giật {len(held)} frame đứng hình")
    if target_fps > 24:
        parts.append(f"nội suy lên {target_fps} fps")
    return True, "Đã làm mượt: " + ", ".join(parts)


def auto_upscale_video(input_path, target="2K", delete_original=True):
    """Nâng cấp video lên 1080p, 2K (1440p) hoặc 4K (2160p) bằng FFmpeg Lanczos + Unsharp (Hỗ trợ GPU NVIDIA NVENC siêu tốc).
    Khi delete_original=True: Chỉ giữ lại duy nhất 1 video upscale chất lượng cao, xóa bản gốc chưa upscale nhưng GIỮ NGUYÊN hồ sơ Ảnh Tham Chiếu + Prompt."""
    ff = _find_ffmpeg()
    inp = Path(win_path(input_path))
    if not inp.exists():
        return None, "Tệp video không tồn tại"
    orig_meta = get_h3_video_meta(str(inp))
    
    probe = subprocess.run([ff, "-i", str(inp.resolve()), "-hide_banner"], capture_output=True, text=True)
    m = re.search(r'Video:.*?\s(\d{3,5})x(\d{3,5})', probe.stderr)
    if not m:
        return None, "Không đọc được độ phân giải gốc của video"
    in_w, in_h = int(m.group(1)), int(m.group(2))
    
    target_str = str(target or "2K").strip()
    if "1080" in target_str:
        base = (1920, 1080)
        target_label = "1080p"
    elif "4K" in target_str.upper():
        base = (3840, 2160)
        target_label = "4K"
    else:
        base = (2560, 1440)
        target_label = "2K"
        
    if in_h > in_w:
        target_w, target_h = base[1], base[0]  # Dọc (9:16)
    elif in_w == in_h:
        target_w, target_h = base[1], base[1]  # Vuông (1:1)
    else:
        target_w, target_h = base[0], base[1]  # Ngang (16:9)
        
    target_w = target_w - (target_w % 2)
    target_h = target_h - (target_h % 2)
    
    out_name = f"{inp.stem}_Upscale_{target_label}{inp.suffix}"
    out_path = inp.parent / out_name
    
    vf = f"scale={target_w}:{target_h}:flags=lanczos,unsharp=5:5:0.5:5:5:0.0"
    for encoder in ["h264_nvenc", "libx264"]:
        cmd = [
            ff, "-y", "-hide_banner", "-i", str(inp.resolve()),
            "-vf", vf, "-c:v", encoder, "-pix_fmt", "yuv420p",
            "-c:a", "aac", "-b:a", "256k"
        ]
        if "nvenc" in encoder:
            cmd.extend(["-cq", "20", "-preset", "p5"])
        else:
            cmd.extend(["-crf", "20", "-preset", "medium"])
        cmd.append(str(out_path.resolve()))
        
        t0 = time.time()
        try:
            res = subprocess.run(cmd, capture_output=True, text=True, timeout=600)
            if res.returncode == 0 and out_path.exists() and out_path.stat().st_size > 1000:
                record_h3_video(
                    out_path,
                    title=orig_meta.get("title") or f"{inp.stem} ({target_label})",
                    duration=orig_meta.get("duration"),
                    seed=orig_meta.get("seed"),
                    prompt=orig_meta.get("prompt"),
                    reference_images=orig_meta.get("reference_images"),
                    scene_id=orig_meta.get("scene_id"),
                    visual_style=orig_meta.get("visual_style"),
                    mode=orig_meta.get("mode"),
                    lora=orig_meta.get("lora"),
                    width=target_w,
                    height=target_h,
                    gpu=orig_meta.get("gpu"),
                    job_id=orig_meta.get("job_id"),
                )
                if delete_original and inp.resolve() != out_path.resolve():
                    remove_h3_record(inp)
                    try:
                        inp.unlink(missing_ok=True)
                    except Exception:
                        pass
                return str(out_path), f"Đã upscale thành công {in_w}x{in_h} → {target_w}x{target_h} ({target_label}) trong {round(time.time()-t0, 1)}s"
        except Exception:
            pass
    return None, "Quá trình upscale thất bại"

def extract_video_last_frame(input_path: str):
    """Trích xuất khung hình cuối cùng sắc nét nhất từ video MP4 để nối tiếp cảnh sau (First-Frame / Ref2VA)."""
    ff = _find_ffmpeg()
    inp = Path(win_path(input_path))
    if not inp.exists():
        return None, None, "Tệp video không tồn tại"
    td = SCRIPT_DIR / "temp"
    td.mkdir(exist_ok=True)
    out_png = td / f"lastframe_{inp.stem}_{uuid.uuid4().hex[:6]}.png"
    for sseof in ["-0.1", "-0.25", "-0.5"]:
        cmd = [
            ff, "-y", "-hide_banner", "-sseof", sseof,
            "-i", str(inp.resolve()), "-frames:v", "1", "-q:v", "2", str(out_png.resolve())
        ]
        try:
            subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            if out_png.exists() and out_png.stat().st_size > 500:
                b64 = base64.b64encode(out_png.read_bytes()).decode("ascii")
                return out_png.name, f"data:image/png;base64,{b64}", None
        except Exception:
            pass
    return None, None, "Không thể trích xuất khung hình cuối từ video này"

def extract_scene_last_frame_to_ref_dir(prev_scene_id: str, video_path: str) -> Path | None:
    """Trích xuất khung hình cuối từ video của cảnh trước (prev_scene_id) và lưu vào output/storyboard_refs/LastFrame_{prev_scene_id}.png."""
    ff = _find_ffmpeg()
    inp = Path(win_path(video_path)) if video_path else None
    if not inp or not inp.is_file():
        return None
    sb_refs_dir = SCRIPT_DIR / "output" / "storyboard_refs"
    sb_refs_dir.mkdir(parents=True, exist_ok=True)
    safe_id = re.sub(r"[^A-Za-z0-9_-]+", "_", str(prev_scene_id or inp.stem))
    out_png = sb_refs_dir / f"LastFrame_{safe_id}.png"
    try:
        if out_png.is_file() and out_png.stat().st_size > 500 and out_png.stat().st_mtime >= inp.stat().st_mtime:
            return out_png
    except Exception:
        pass
    for sseof in ["-0.06", "-0.15", "-0.3"]:
        cmd = [
            ff, "-y", "-hide_banner", "-sseof", sseof,
            "-i", str(inp.resolve()), "-frames:v", "1", "-q:v", "1", str(out_png.resolve())
        ]
        try:
            subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            if out_png.is_file() and out_png.stat().st_size > 500:
                return out_png
        except Exception:
            pass
    return None

def merge_videos_ffmpeg(video_paths: list[str], audio_path: str | None = None, trim_chained_frame: bool = False, head_trims: list | None = None, clip_durations: list | None = None):
    """Ghép nối nhiều video clip ngắn thành 1 bộ phim dài hoàn chỉnh liền mạch (24fps, khớp âm thanh & hậu cảnh) bằng FFmpeg.
    head_trims: số giây cắt bỏ ở đầu từng clip (vd 1.625s phần mồi 39 frame mang từ đoạn trước khi nối kiểu 1.6s).
    clip_durations: độ dài giữ lại của từng clip (giây, sau head_trim) — dùng khi clip gen dài hơn đoạn nhạc tương ứng."""
    ff = _find_ffmpeg()
    valid_paths = []
    valid_trims = []
    valid_durs = []
    for i_vp, vp in enumerate(video_paths):
        p = Path(win_path(vp))
        if p.is_file():
            valid_paths.append(p.resolve())
            try:
                valid_trims.append(float((head_trims or [])[i_vp] or 0) if head_trims and i_vp < len(head_trims) else 0.0)
            except Exception:
                valid_trims.append(0.0)
            try:
                valid_durs.append(float((clip_durations or [])[i_vp] or 0) if clip_durations and i_vp < len(clip_durations) else 0.0)
            except Exception:
                valid_durs.append(0.0)
    if len(valid_paths) < 2:
        return None, "Cần chọn ít nhất 2 video hợp lệ để ghép thành phim dài"
    has_head_trims = any(t > 0.001 for t in valid_trims) or any(t > 0.001 for t in valid_durs)

    td = SCRIPT_DIR / "temp"
    td.mkdir(exist_ok=True)
    ts = time.strftime("%Y%m%d_%H%M%S")
    out_dir = valid_paths[0].parent
    out_path = out_dir / f"minimax_h3_Merged_{len(valid_paths)}Clips_{ts}.mp4"
    concat_txt = td / f"concat_{uuid.uuid4().hex[:8]}.txt"

    lines = []
    for idx_v, vp in enumerate(valid_paths):
        safe_p = str(vp).replace("\\", "/").replace("'", "'\\''")
        lines.append(f"file '{safe_p}'")
        _inp = 0.0
        if has_head_trims and valid_trims[idx_v] > 0.001:
            _inp = valid_trims[idx_v]
            lines.append(f"inpoint {_inp:.3f}")
        elif trim_chained_frame and idx_v > 0:
            # Bỏ đúng 1 frame đầu (0.042s ở 24fps) trùng với frame cuối của đoạn trước để chuyển động trôi mượt 100%
            _inp = 0.042
            lines.append("inpoint 0.042")
        if valid_durs[idx_v] > 0.001:
            lines.append(f"outpoint {_inp + valid_durs[idx_v]:.3f}")
    concat_txt.write_text("\n".join(lines) + "\n", encoding="utf-8")
    if has_head_trims:
        trim_chained_frame = True  # buộc re-encode để cắt chính xác theo frame

    t0 = time.time()
    try:
        has_ext_audio = False
        aud_p = None
        if audio_path and os.path.isfile(win_path(audio_path)):
            aud_p = Path(win_path(audio_path)).resolve()
            probe_a = subprocess.run(
                [ff, "-i", str(aud_p), "-hide_banner"],
                capture_output=True, text=True
            )
            has_ext_audio = ("Audio:" in (probe_a.stderr or ""))

        if has_ext_audio and aud_p is not None and not trim_chained_frame:
            cmd = [
                ff, "-y", "-hide_banner", "-f", "concat", "-safe", "0",
                "-i", str(concat_txt.resolve()), "-i", str(aud_p),
                "-map", "0:v:0", "-map", "1:a:0", "-c:v", "copy", "-c:a", "aac", "-b:a", "192k",
                "-shortest", str(out_path.resolve())
            ]
        elif not trim_chained_frame:
            cmd = [
                ff, "-y", "-hide_banner", "-f", "concat", "-safe", "0",
                "-i", str(concat_txt.resolve()), "-c", "copy", str(out_path.resolve())
            ]
        else:
            cmd = []

        res = subprocess.run(cmd, capture_output=True, text=True, timeout=300) if cmd else None
        if res is None or res.returncode != 0 or not out_path.exists() or out_path.stat().st_size < 1000:
            probe = subprocess.run([ff, "-i", str(valid_paths[0]), "-hide_banner"], capture_output=True, text=True)
            m = re.search(r'Video:.*?\s(\d{3,5})x(\d{3,5})', probe.stderr)
            w, h = (int(m.group(1)), int(m.group(2))) if m else (768, 1376)
            if has_ext_audio and aud_p is not None:
                cmd_re = [
                    ff, "-y", "-hide_banner", "-f", "concat", "-safe", "0",
                    "-i", str(concat_txt.resolve()), "-i", str(aud_p),
                    "-map", "0:v:0", "-map", "1:a:0",
                    "-vf", f"scale={w}:{h}:force_original_aspect_ratio=decrease,pad={w}:{h}:(ow-iw)/2:(oh-ih)/2,fps=24",
                    "-c:v", "libx264", "-crf", "18", "-preset", "fast", "-pix_fmt", "yuv420p",
                    "-c:a", "aac", "-b:a", "192k", "-shortest", str(out_path.resolve())
                ]
            else:
                cmd_re = [
                    ff, "-y", "-hide_banner", "-f", "concat", "-safe", "0",
                    "-i", str(concat_txt.resolve()),
                    "-vf", f"scale={w}:{h}:force_original_aspect_ratio=decrease,pad={w}:{h}:(ow-iw)/2:(oh-ih)/2,fps=24",
                    "-c:v", "libx264", "-crf", "18", "-preset", "fast", "-pix_fmt", "yuv420p",
                    "-c:a", "aac", "-b:a", "192k", str(out_path.resolve())
                ]
            subprocess.run(cmd_re, capture_output=True, text=True, timeout=600)

        if out_path.exists() and out_path.stat().st_size > 1000:
            record_h3_video(out_path, title=f"Phim Ghép ({len(valid_paths)} cảnh)")
            return str(out_path), f"Đã ghép nối liền mạch {len(valid_paths)} đoạn thành 1 video hoàn chỉnh ({round(time.time()-t0, 1)}s)!"
    except Exception as e:
        return None, f"Lỗi khi ghép video: {e}"
    finally:
        try:
            concat_txt.unlink(missing_ok=True)
        except Exception:
            pass
    return None, "Không thể ghép các video đã chọn"


_V2V_MOTION_CACHE = {}

def v2v_motion_profile(video_path: str, samples_per_sec: float = 8.0):
    """Đo mức chuyển động theo thời gian (khác biệt khung hình xám thu nhỏ) — không cần khung xương.
    Trả về (times, motion) đã làm mượt; motion càng nhỏ = nhân vật càng đứng yên."""
    import cv2
    import numpy as np
    wp = win_path(video_path)
    try:
        key = (str(Path(wp).resolve()).lower(), os.path.getmtime(wp))
    except Exception:
        return [], []
    if key in _V2V_MOTION_CACHE:
        return _V2V_MOTION_CACHE[key]
    cap = cv2.VideoCapture(wp)
    if not cap.isOpened():
        return [], []
    fps = float(cap.get(cv2.CAP_PROP_FPS) or 24.0)
    if fps <= 1.0 or fps > 240.0:
        fps = 24.0
    step = max(1, int(round(fps / max(1.0, samples_per_sec))))
    times, motion = [], []
    prev = None
    idx = 0
    while True:
        ok = cap.grab()
        if not ok:
            break
        if idx % step == 0:
            ok2, frm = cap.retrieve()
            if ok2 and frm is not None:
                h, w = frm.shape[:2]
                sw = 160
                sh = max(16, int(round(h * sw / max(1, w))))
                g = cv2.cvtColor(cv2.resize(frm, (sw, sh), interpolation=cv2.INTER_AREA), cv2.COLOR_BGR2GRAY)
                g = cv2.GaussianBlur(g, (5, 5), 0).astype(np.float32)
                if prev is not None:
                    times.append(round(idx / fps, 3))
                    motion.append(float(np.mean(np.abs(g - prev))))
                prev = g
        idx += 1
    cap.release()
    if len(motion) >= 3:
        k = 3
        m_arr = np.array(motion, dtype=np.float32)
        m_pad = np.pad(m_arr, (k // 2, k // 2), mode="edge")
        motion = [float(x) for x in np.convolve(m_pad, np.ones(k) / k, mode="valid")]
    res = (times, motion)
    _V2V_MOTION_CACHE[key] = res
    return res


def v2v_snap_to_still(times, motion, t_target: float, window: float = 1.0, lo: float = None, hi: float = None) -> float:
    """Dịch điểm cắt t_target tới khoảnh khắc ít chuyển động nhất trong khoảng ±window (giới hạn [lo, hi])."""
    if not times:
        return t_target
    a = t_target - window
    b = t_target + window
    if lo is not None:
        a = max(a, lo)
    if hi is not None:
        b = min(b, hi)
    best_t, best_v = t_target, None
    for t, v in zip(times, motion):
        if a <= t <= b:
            # ưu tiên nhẹ điểm gần mốc gốc khi mức chuyển động tương đương
            score = v * (1.0 + 0.15 * abs(t - t_target) / max(window, 0.01))
            if best_v is None or score < best_v:
                best_t, best_v = t, score
    return float(best_t)


def v2v_suggest_still_trim(video_path: str, target_sec: float):
    """Gợi ý điểm bắt đầu đoạn cắt sao cho cả đầu và cuối đoạn đều rơi vào lúc nhân vật ít chuyển động nhất."""
    times, motion = v2v_motion_profile(video_path)
    total = probe_video_duration_v2v(video_path)
    if not times or total <= target_sec + 0.3:
        return {"ok": False, "start": 0.0, "total": total}
    import bisect
    def m_at(t):
        i = bisect.bisect_left(times, t)
        i = min(max(i, 0), len(times) - 1)
        return motion[i]
    max_start = max(0.0, total - target_sec)
    best_s, best_v = 0.0, None
    s = 0.0
    while s <= max_start + 1e-6:
        v = m_at(s) + m_at(s + target_sec)
        if best_v is None or v < best_v:
            best_s, best_v = s, v
        s += 0.1
    med = float(sorted(motion)[len(motion) // 2]) if motion else 0.0
    return {"ok": True, "start": round(best_s, 1), "total": round(total, 2),
            "edge_motion": round(best_v or 0.0, 3), "median_motion": round(med, 3)}


def timeline_clause_for_window(timeline, start: float, src_length: float, speed: float = 1.0) -> str:
    """Chuyển timeline động tác (mốc giây theo video nguồn gốc) sang mốc của video đầu ra.
    Cửa sổ nguồn = [start, start+src_length]; thời gian đầu ra = (t - start) / speed."""
    if not isinstance(timeline, list) or src_length <= 0:
        return ""
    speed = speed if speed and speed > 0 else 1.0
    w0, w1 = float(start), float(start) + float(src_length)
    out_len = src_length / speed
    items = []
    for it in timeline:
        if not isinstance(it, dict):
            continue
        txt = re.sub(r"\s+", " ", str(it.get("text") or "")).strip().rstrip(".")
        if not txt:
            continue
        try:
            t0, t1 = float(it.get("t0", 0)), float(it.get("t1", 0))
        except Exception:
            continue
        a, b = max(t0, w0), min(t1, w1)
        if b - a < 0.4:
            continue
        o0 = max(0.0, (a - w0) / speed)
        o1 = min(out_len, (b - w0) / speed)
        items.append(f"{o0:.1f}s-{o1:.1f}s: {txt}")
    if not items:
        return ""
    return "Motion timeline (follow <Video 1> timing): " + "; ".join(items) + "."


def split_video_segments_v2v(video_path: str, segment_sec: float = 15.0, max_segments: int = 20, balanced: bool = False):
    """Tự động đo độ dài <Video 1> và cắt thành các đoạn chuẩn 24fps nếu video dài hơn thời lượng chọn (chế độ V2V).
    balanced=True: chia ĐỀU (VD 19s -> 2 x 9.5s) để không đoạn nào quá ngắn / bị bỏ mất đuôi."""
    ff = _find_ffmpeg()
    inp = Path(win_path(video_path))
    if not inp.is_file():
        return [], 0.0, "Không tìm thấy file Video Nguồn (<Video 1>)"
    probe = subprocess.run([ff, "-i", str(inp.resolve()), "-hide_banner"], capture_output=True, text=True)
    m = re.search(r"Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)", probe.stderr)
    total_sec = 0.0
    if m:
        total_sec = int(m.group(1)) * 3600 + int(m.group(2)) * 60 + float(m.group(3))
    segment_sec = min(15.0, max(4.0, float(segment_sec or 15.0)))
    if total_sec <= 0 or total_sec <= segment_sec + 0.6:
        eff_dur = min(15.0, max(4.0, round(total_sec if total_sec > 0 else segment_sec, 1)))
        return [{"path": str(inp.resolve()), "start": 0.0, "duration": eff_dur, "index": 1}], round(total_sec or eff_dur, 1), None

    bounds = None
    if balanced:
        import math
        n_parts = max(2, min(max_segments, int(math.ceil((total_sec - 0.3) / segment_sec))))
        step_sec = total_sec / n_parts
        # Mốc cắt danh nghĩa chia đều, sau đó dịch ±1s tới lúc nhân vật đứng yên nhất (frame-difference OpenCV)
        bounds = [0.0] + [step_sec * i for i in range(1, n_parts)] + [total_sec]
        try:
            m_times, m_vals = v2v_motion_profile(str(inp))
            if m_times:
                for bi in range(1, n_parts):
                    prev_b = bounds[bi - 1]
                    lo = max(prev_b + 4.0, total_sec - 15.0 * (n_parts - bi))
                    hi = min(prev_b + 15.0, total_sec - 4.0 * (n_parts - bi))
                    if lo > hi:
                        continue
                    bounds[bi] = round(v2v_snap_to_still(m_times, m_vals, bounds[bi], 1.0, lo, hi), 3)
        except Exception as _snap_e:
            print(f"[V2V-SPLIT] snap-to-still lỗi (dùng mốc đều): {_snap_e}")
    else:
        n_parts = max_segments
        step_sec = segment_sec

    td = SCRIPT_DIR / "temp"
    td.mkdir(exist_ok=True)
    uid = uuid.uuid4().hex[:6]
    segments = []
    idx = 0
    cur = 0.0
    while cur < total_sec - 0.8 and idx < min(max_segments, n_parts):
        idx += 1
        if balanced:
            cur = bounds[idx - 1]
            rem = bounds[idx] - cur
        else:
            rem = min(segment_sec, total_sec - cur)
        if rem < 2.0 and idx > 1:
            break
        eff_rem = max(4.0, min(15.0, round(rem, 1)))
        out_seg = td / f"v2v_seg_{uid}_{idx:02d}.mp4"
        cmd = [
            ff, "-y", "-hide_banner", "-ss", f"{cur:.3f}", "-t", f"{rem:.3f}",
            "-i", str(inp.resolve()),
            "-vf", "fps=24",
            "-c:v", "libx264", "-crf", "18", "-preset", "fast", "-pix_fmt", "yuv420p",
            "-c:a", "aac", "-b:a", "192k", str(out_seg.resolve())
        ]
        subprocess.run(cmd, capture_output=True, text=True, timeout=120)
        if out_seg.is_file() and out_seg.stat().st_size > 1000:
            segments.append({
                "path": str(out_seg.resolve()),
                "start": round(cur, 2),
                "duration": eff_rem,
                "raw_duration": round(rem, 2),
                "index": idx,
            })
        cur = bounds[idx] if balanced else (cur + step_sec)
    return segments, round(total_sec, 1), None


def probe_video_duration_v2v(video_path: str) -> float:
    """Đo độ dài (giây) của 1 video bằng ffmpeg."""
    try:
        ff = _find_ffmpeg()
        inp = Path(win_path(video_path))
        if not inp.is_file():
            return 0.0
        probe = subprocess.run([ff, "-i", str(inp.resolve()), "-hide_banner"], capture_output=True, text=True)
        m = re.search(r"Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)", probe.stderr or "")
        if m:
            return int(m.group(1)) * 3600 + int(m.group(2)) * 60 + float(m.group(3))
    except Exception:
        pass
    return 0.0


def trim_video_v2v(video_path: str, start_sec: float, length_sec: float):
    """Cắt 1 đoạn [start, start+length] của video V2V (giữ âm thanh, chuẩn 24fps)."""
    ff = _find_ffmpeg()
    inp = Path(win_path(video_path))
    if not inp.is_file():
        return None
    td = SCRIPT_DIR / "temp"
    td.mkdir(exist_ok=True)
    out = td / f"v2v_trim_{uuid.uuid4().hex[:8]}.mp4"
    base = [ff, "-y", "-hide_banner", "-ss", f"{max(0.0, float(start_sec)):.3f}", "-t", f"{float(length_sec):.3f}",
            "-i", str(inp.resolve()), "-vf", "fps=24",
            "-c:v", "libx264", "-crf", "18", "-preset", "fast", "-pix_fmt", "yuv420p"]
    for tail in (["-c:a", "aac", "-b:a", "192k"], ["-an"]):
        subprocess.run(base + tail + [str(out.resolve())], capture_output=True, text=True, timeout=180)
        if out.is_file() and out.stat().st_size > 1000:
            return str(out.resolve())
    return None


def compress_video_v2v(video_path: str, target_sec: float):
    """Giữ TRỌN nội dung video nhưng nén thời gian (tăng tốc) cho vừa target_sec. Âm thanh tăng tốc giữ cao độ (atempo)."""
    ff = _find_ffmpeg()
    inp = Path(win_path(video_path))
    total = probe_video_duration_v2v(str(inp))
    if not inp.is_file() or total <= 0 or target_sec <= 0:
        return None, 1.0
    factor = total / float(target_sec)
    if factor <= 1.0:
        return str(inp.resolve()), 1.0
    td = SCRIPT_DIR / "temp"
    td.mkdir(exist_ok=True)
    out = td / f"v2v_fit_{uuid.uuid4().hex[:8]}.mp4"
    atempo = []
    f = factor
    while f > 2.0:
        atempo.append("atempo=2.0")
        f /= 2.0
    atempo.append(f"atempo={f:.5f}")
    vf = f"setpts=PTS/{factor:.5f},fps=24"
    enc = ["-c:v", "libx264", "-crf", "18", "-preset", "fast", "-pix_fmt", "yuv420p"]
    cmd_a = [ff, "-y", "-hide_banner", "-i", str(inp.resolve()),
             "-filter_complex", f"[0:v]{vf}[v];[0:a]{','.join(atempo)}[a]",
             "-map", "[v]", "-map", "[a]"] + enc + ["-c:a", "aac", "-b:a", "192k", "-t", f"{float(target_sec):.3f}", str(out.resolve())]
    cmd_v = [ff, "-y", "-hide_banner", "-i", str(inp.resolve()), "-vf", vf] + enc + ["-an", "-t", f"{float(target_sec):.3f}", str(out.resolve())]
    for cmd in (cmd_a, cmd_v):
        subprocess.run(cmd, capture_output=True, text=True, timeout=300)
        if out.is_file() and out.stat().st_size > 1000:
            return str(out.resolve()), factor
    return None, factor


def _decode_audio_mono16k(ff, path):
    """Giải mã audio → numpy float32 mono 16kHz (None nếu lỗi)."""
    try:
        import numpy as np
        r = subprocess.run([ff, "-v", "error", "-i", str(path), "-ac", "1", "-ar", "16000", "-f", "s16le", "-"],
                           capture_output=True, timeout=180)
        if r.returncode != 0 or not r.stdout:
            return None
        return np.frombuffer(r.stdout, dtype=np.int16).astype(np.float32) / 32768.0
    except Exception:
        return None


def _try_whisper_transcribe(path, start=0.0, dur=None):
    """Phiên âm lời thoại 1 đoạn nếu máy có faster_whisper / whisper (không bắt buộc). Trả về '' nếu không có."""
    try:
        import importlib.util as _iu
        if _iu.find_spec("faster_whisper"):
            from faster_whisper import WhisperModel
            global _H3_WHISPER_MODEL
            try:
                _H3_WHISPER_MODEL
            except NameError:
                _H3_WHISPER_MODEL = None
            if _H3_WHISPER_MODEL is None:
                _H3_WHISPER_MODEL = WhisperModel("small", device="cpu", compute_type="int8")
            segs, _info = _H3_WHISPER_MODEL.transcribe(str(path), vad_filter=True)
            return " ".join(s.text.strip() for s in segs).strip()
        if _iu.find_spec("whisper"):
            import whisper
            mdl = whisper.load_model("small")
            return str(mdl.transcribe(str(path)).get("text") or "").strip()
    except Exception as e:
        print(f"[whisper] {e}")
    return ""


def split_audio_segments(audio_path: str, segment_sec: float = 15.0, max_segments: int = 10, smart_cut: bool = True, analyze: bool = True, transcribe: bool = False):
    """Tự động cắt file MP3/WAV dài thành các đoạn ≤ segment_sec để chạy nối tiếp nhiều video khớp nhạc.
    smart_cut: lùi điểm cắt (tối đa 3s) về chỗ lặng nhất để không cắt giữa từ.
    analyze: đánh giá từng đoạn có tiếng nói/âm thanh hay im lặng (speech_ratio, silent).
    transcribe: phiên âm lời thoại bằng Whisper nếu máy có cài (tùy chọn)."""
    ff = _find_ffmpeg()
    inp = Path(win_path(audio_path))
    if not inp.is_file():
        return [], 0.0, "Không tìm thấy file âm thanh"
    probe = subprocess.run([ff, "-i", str(inp.resolve()), "-hide_banner"], capture_output=True, text=True)
    m = re.search(r"Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)", probe.stderr)
    total_sec = 0.0
    if m:
        total_sec = int(m.group(1)) * 3600 + int(m.group(2)) * 60 + float(m.group(3))
    if total_sec <= 0:
        return [str(inp.resolve())], 15.0, None

    pcm = _decode_audio_mono16k(ff, inp.resolve()) if (smart_cut or analyze) else None
    sr = 16000
    win = int(0.1 * sr)
    rms = None
    if pcm is not None and len(pcm) > win:
        import numpy as np
        n_w = len(pcm) // win
        rms = np.sqrt(np.mean(pcm[: n_w * win].reshape(n_w, win) ** 2, axis=1) + 1e-12)
        noise_floor = float(np.percentile(rms, 10))
        speech_thr = max(0.012, noise_floor * 3.0)

    td = SCRIPT_DIR / "temp"
    td.mkdir(exist_ok=True)
    uid = uuid.uuid4().hex[:6]
    segments = []
    idx = 0
    cur = 0.0
    while cur < total_sec - 0.5 and idx < max_segments:
        idx += 1
        end = min(cur + segment_sec, total_sec)
        if smart_cut and rms is not None and end < total_sec - 0.5:
            # tìm cửa sổ 100ms lặng nhất trong [end-3s, end]
            w_lo = max(int((cur + 4.0) * 10), int((end - 3.0) * 10))
            w_hi = min(int(end * 10), len(rms))
            if w_hi - w_lo >= 2:
                best = w_lo + int(np.argmin(rms[w_lo:w_hi]))
                end = max(cur + 4.0, (best + 0.5) / 10.0)
        if total_sec - end < 2.0 and (total_sec - cur) <= segment_sec + 0.01:
            end = total_sec  # gộp phần đuôi quá ngắn vào đoạn cuối
        rem = end - cur
        if rem < 2.0 and idx > 1:
            break
        out_seg = td / f"aud_seg_{uid}_{idx:02d}.mp3"
        cmd = [
            ff, "-y", "-hide_banner", "-ss", f"{cur:.2f}", "-t", f"{rem:.2f}",
            "-i", str(inp.resolve()), "-c:a", "libmp3lame", "-q:a", "2", str(out_seg.resolve())
        ]
        subprocess.run(cmd, capture_output=True, text=True, timeout=60)
        if out_seg.is_file() and out_seg.stat().st_size > 200:
            seg = {"path": str(out_seg.resolve()), "duration": round(rem, 2), "raw_duration": round(rem, 3), "index": idx, "start": round(cur, 3)}
            if analyze and rms is not None:
                a, b = int(cur * 10), max(int(cur * 10) + 1, int(end * 10))
                chunk = rms[a:b]
                ratio = float((chunk > speech_thr).mean()) if len(chunk) else 0.0
                seg["speech_ratio"] = round(ratio, 3)
                seg["silent"] = ratio < 0.06
            if transcribe and not seg.get("silent"):
                seg["transcript"] = _try_whisper_transcribe(out_seg)
            segments.append(seg)
        cur = end
    return segments, round(total_sec, 1), None


AUDIO_SILENT_CHUNK_CLAUSE = "This part has no dialogue: no one speaks, all mouths stay closed; only ambient sound and natural body motion."


def save_keyframe_guides(items, td=None, duration=15.0, max_items=8):
    """Lưu các mốc khung hình (ảnh/âm thanh) người dùng chọn → list guide cho MiniMaxH3AddGuide.
    items: [{data: dataURL | path, name, second: số giây | 'end', kind?: image|audio}]"""
    td = Path(td or (SCRIPT_DIR / "temp"))
    td.mkdir(exist_ok=True)
    out = []
    for i, it in enumerate((items or [])[:max_items]):
        if not isinstance(it, dict):
            continue
        name = str(it.get("name") or f"kf_{i+1}.png")
        ext = (Path(name).suffix or ".png").lower()
        kind = str(it.get("kind") or ("audio" if ext in (".mp3", ".wav", ".m4a", ".aac", ".ogg", ".flac") else "image")).lower()
        p = None
        data = it.get("data") or ""
        if data:
            b64 = data.split(",", 1)[1] if "," in data else data
            try:
                p = td / f"kf_{i+1}_{uuid.uuid4().hex[:6]}{ext}"
                p.write_bytes(base64.b64decode(b64))
            except Exception:
                p = None
        elif it.get("path") and os.path.isfile(win_path(str(it.get("path")))):
            p = Path(win_path(str(it.get("path"))))
        if not p:
            continue
        sec_raw = str(it.get("second", "0")).strip().lower()
        g = {"path": str(p), "kind": kind}
        if sec_raw in ("end", "cuối", "cuoi", "last", "-1"):
            g["frame"] = -1
        else:
            try:
                g["second"] = max(0.0, min(float(duration), float(sec_raw)))
            except Exception:
                g["second"] = 0.0
        if kind == "audio":
            g["with_audio"] = True
        out.append(g)
    return out

CHAR_PRESETS_DIR = SCRIPT_DIR / "assets" / "character_presets"

def list_character_presets():
    CHAR_PRESETS_DIR.mkdir(parents=True, exist_ok=True)
    items = []
    for f in sorted(CHAR_PRESETS_DIR.glob("*.json"), key=lambda x: x.stat().st_mtime, reverse=True):
        try:
            d = json.loads(f.read_text(encoding="utf-8"))
            items.append({
                "id": d.get("id") or f.stem,
                "name": d.get("name", f.stem),
                "desc": d.get("desc", ""),
                "images": d.get("images", []),
                "count": len(d.get("images", []))
            })
        except Exception:
            pass
    return items

def save_character_preset(name: str, images: list, desc: str = ""):
    CHAR_PRESETS_DIR.mkdir(parents=True, exist_ok=True)
    clean_name = (name or "").strip()
    if not clean_name:
        return None, "Vui lòng nhập tên nhân vật"
    if not images:
        return None, "Cần ít nhất 1 ảnh tham chiếu để lưu nhân vật"
    slug = re.sub(r"[^a-zA-Z0-9_-]+", "_", clean_name.lower()).strip("_") or "char"
    pid = f"{slug}_{uuid.uuid4().hex[:5]}"
    payload = {
        "id": pid,
        "name": clean_name,
        "desc": (desc or "").strip(),
        "images": images[:9],
        "created_at": time.time()
    }
    target = CHAR_PRESETS_DIR / f"{pid}.json"
    target.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    return payload, None

def delete_character_preset(preset_id: str):
    CHAR_PRESETS_DIR.mkdir(parents=True, exist_ok=True)
    safe_id = Path(preset_id).stem
    target = CHAR_PRESETS_DIR / f"{safe_id}.json"
    if target.is_file():
        target.unlink(missing_ok=True)
        return True
    return False

def clean_temp_folder(max_age_hours: float = 6.0):
    """Dọn dẹp các file ảnh/audio/json tạm cũ trong thư mục temp/ để giải phóng ổ cứng."""
    td = SCRIPT_DIR / "temp"
    if not td.exists():
        return 0, 0.0
    protected = {"h3_library_records.json", "workers_config.json", "active_jobs_cache.json"}
    now = time.time()
    cutoff = now - (max_age_hours * 3600.0)
    removed_count = 0
    freed_bytes = 0
    for f in td.iterdir():
        if not f.is_file() or f.name in protected:
            continue
        try:
            st = f.stat()
            if max_age_hours <= 0 or st.st_mtime < cutoff:
                sz = st.st_size
                f.unlink(missing_ok=True)
                removed_count += 1
                freed_bytes += sz
        except Exception:
            pass
    return removed_count, round(freed_bytes / (1024 * 1024), 2)

auth_state = {
    "status": "unknown",
    "balance": None,
    "rate": None,
    "email": None,
    "name": None,
    "picture": None,
    "accounts": [],
    "total_cu": 0.0,
    "total_cu_all": 0.0,
    "funded_count": 0,
    "checked_at": "",
    "last_refresh_ts": 0.0
}
auth_refresh_lock = threading.Lock()
auth_flow = {"active": False, "url": None, "needs_code": False, "message": "", "output_lines": [], "process": None}
active_jobs: dict[str, dict] = {}

def _shell_Wrap(cmd_str: str) -> list[str]:
    """Tự động chạy qua WSL khi ở trên Windows hoặc chạy bash trực tiếp khi triển khai trên Linux VPS."""
    full_cmd = f"export PATH=\"$HOME/.local/bin:/root/.local/bin:/usr/local/bin:$PATH\"; source ~/.local/bin/env 2>/dev/null; {cmd_str}"
    if os.name == "nt":
        return ["wsl", "-d", WSL_DISTRO, "--", "bash", "-c", full_cmd]
    return ["bash", "-c", full_cmd]


def run_wsl(cmd, timeout=30):
    try:
        r = subprocess.run(_shell_Wrap(cmd),
                           capture_output=True, text=True, timeout=timeout, encoding="utf-8", errors="replace")
        return r.returncode, (r.stdout + r.stderr).strip()
    except subprocess.TimeoutExpired: return -1, "Timeout"
    except Exception as e: return -1, str(e)

def _apply_auto_select_funded(accounts: list, force: bool = False):
    """Tự động bật chọn (enabled=True) toàn bộ tài khoản còn CU (> 0.05) và bỏ chọn tài khoản 0 CU."""
    if not accounts:
        return
    cfg = load_workers_config()
    auto_sel = cfg.get("auto_select_funded", True)
    if not auto_sel and not force:
        return
    if "accounts" not in cfg:
        cfg["accounts"] = {}
    changed = False
    for acc in accounts:
        em = acc.get("email")
        if not em:
            continue
        bal = acc.get("balance")
        bal_f = 0.0
        if bal is not None:
            try:
                bal_f = float(str(bal).split()[0])
            except Exception:
                pass
        should_enable = (bal is None) or (bal_f > 0.05)
        prev = cfg["accounts"].get(em, {}).get("enabled")
        if prev != should_enable:
            if em not in cfg["accounts"]:
                cfg["accounts"][em] = {}
            cfg["accounts"][em]["enabled"] = should_enable
            changed = True
    if changed or force:
        cfg["auto_select_funded"] = True
        save_workers_config(cfg)

def _recompute_auth_totals():
    """Tính toán lại Tổng CU còn lại (của các TK đang chọn và toàn bộ TK)."""
    accs = auth_state.get("accounts", []) or []
    total_enabled = 0.0
    total_all = 0.0
    funded_cnt = 0
    for acc in accs:
        em = acc.get("email")
        bal = acc.get("balance")
        bal_f = 0.0
        if bal is not None:
            try:
                bal_f = float(str(bal).split()[0])
            except Exception:
                pass
        if bal_f > 0:
            total_all += bal_f
        if bal_f > 0.05:
            funded_cnt += 1
        en_flag = bool(is_worker_enabled(em) and (bal is None or bal_f > 0.05))
        acc["enabled"] = en_flag
        acc["worker_enabled"] = en_flag
        acc["is_ready"] = en_flag
        if en_flag and bal_f > 0:
            total_enabled += bal_f
    if not accs and auth_state.get("balance"):
        try:
            b0 = float(auth_state["balance"])
            total_enabled = b0
            total_all = b0
            funded_cnt = 1 if b0 > 0.05 else 0
        except Exception:
            pass
    auth_state["total_cu"] = round(total_enabled, 2)
    auth_state["total_cu_all"] = round(total_all, 2)
    auth_state["funded_count"] = funded_cnt

def _get_account_balance(email):
    """Số dư CU của đúng 1 tài khoản (theo email); nếu không tìm thấy thì trả về số dư tài khoản đang chọn."""
    if email:
        for a in auth_state.get("accounts", []) or []:
            if a.get("email") == email and a.get("balance") is not None:
                return a.get("balance")
    if not email or email == auth_state.get("email") or email == "default":
        return auth_state.get("balance")
    return None


def _get_account_balance_fresh(email):
    """Làm mới số dư tất cả tài khoản rồi đọc số dư của đúng tài khoản đã chạy job."""
    try:
        check_auth(refresh_all=True)
    except Exception:
        pass
    return _get_account_balance(email)


def preload_cached_auth_state():
    """Nạp nhanh danh sách tài khoản & số dư CU từ bộ nhớ đệm ngay khi khởi động để UI hiển thị tức thì."""
    try:
        mgr_script = wsl_path(str(SCRIPT_DIR / "scripts" / "account_manager.py"))
        list_code, list_out = run_wsl(f"python3 '{mgr_script}' list", timeout=10)
        if list_code == 0 and list_out:
            accs = json.loads(list_out)
            if isinstance(accs, list) and accs:
                auth_state["accounts"] = accs
                _apply_auto_select_funded(accs, force=False)
                active_acc = next((a for a in accs if a.get("is_active")), accs[0])
                auth_state.update({
                    "status": "connected",
                    "balance": active_acc.get("balance"),
                    "rate": active_acc.get("rate"),
                    "email": active_acc.get("email"),
                    "name": active_acc.get("name"),
                    "picture": active_acc.get("picture"),
                    "checked_at": active_acc.get("updated_at") or time.strftime("%H:%M:%S")
                })
                _recompute_auth_totals()
    except Exception:
        pass

def check_auth(refresh_all: bool = True, auto_select_funded: bool = None):
    """Quét song song số dư CU của TẤT CẢ các tài khoản đã lưu, tự chọn tài khoản còn CU và tính tổng CU."""
    with auth_refresh_lock:
        mgr_script = wsl_path(str(SCRIPT_DIR / "scripts" / "account_manager.py"))
        handled_multi = False

        if refresh_all:
            ref_code, ref_out = run_wsl(f"python3 '{mgr_script}' refresh_all", timeout=45)
            if ref_code == 0 and ref_out:
                try:
                    lines = [ln.strip() for ln in ref_out.splitlines() if ln.strip().startswith("{")]
                    payload = json.loads(lines[-1] if lines else ref_out)
                    accs = payload.get("accounts") or []
                    if accs:
                        handled_multi = True
                        auth_state["accounts"] = accs
                        if auto_select_funded is True:
                            _apply_auto_select_funded(accs, force=True)
                        else:
                            _apply_auto_select_funded(accs, force=False)
                        active_acc = next((a for a in accs if a.get("is_active")), accs[0])
                        auth_state.update({
                            "status": "connected",
                            "balance": active_acc.get("balance"),
                            "rate": active_acc.get("rate"),
                            "email": active_acc.get("email"),
                            "name": active_acc.get("name"),
                            "picture": active_acc.get("picture"),
                            "checked_at": payload.get("checked_at") or time.strftime("%H:%M:%S"),
                            "last_refresh_ts": time.time()
                        })
                        _recompute_auth_totals()
                except Exception:
                    handled_multi = False

        if not handled_multi:
            code, out = run_wsl("colab --auth=oauth2 usage", timeout=30)
            bal, rate = None, None
            if code == 0:
                b = re.search(r"balance:\s*([\d,.]+)", out, re.I)
                r = re.search(r"rate:\s*([\d,.]+)", out, re.I)
                bal = float(b.group(1).replace(",", "")) if b else None
                rate = float(r.group(1).replace(",", "")) if r else None
                auth_state.update({
                    "status": "connected",
                    "balance": bal,
                    "rate": rate,
                    "checked_at": time.strftime("%H:%M:%S"),
                    "last_refresh_ts": time.time()
                })
            else:
                auth_state.update({
                    "status": "not_connected",
                    "balance": None,
                    "rate": None,
                    "email": None,
                    "name": None,
                    "picture": None,
                    "checked_at": time.strftime("%H:%M:%S"),
                    "error": out[:300]
                })

            if auth_state.get("status") == "connected":
                sync_code, sync_out = run_wsl(f"python3 '{mgr_script}' sync {bal} {rate}", timeout=15)
                if sync_code == 0:
                    try:
                        prof = json.loads(sync_out)
                        auth_state["email"] = prof.get("email")
                        auth_state["name"] = prof.get("name")
                        auth_state["picture"] = prof.get("picture")
                    except Exception:
                        pass

            list_code, list_out = run_wsl(f"python3 '{mgr_script}' list", timeout=15)
            if list_code == 0:
                try:
                    auth_state["accounts"] = json.loads(list_out)
                except Exception:
                    auth_state["accounts"] = []
            else:
                auth_state["accounts"] = []

            if auth_state["accounts"]:
                _apply_auto_select_funded(auth_state["accounts"], force=bool(auto_select_funded))
            _recompute_auth_totals()

        # Dọn dẹp session GPU mồ côi để tránh bị trừ điểm ngầm khi không có việc
        threading.Thread(target=cleanup_orphaned_sessions, daemon=True).start()

        return auth_state

