def start_auth_flow():
    """Tạo liên kết Google Colab OAuth2 tức thì (0ms) với PKCE cố định (không bao giờ lệch verifier khi F5/restart)."""
    import hashlib, base64, urllib.parse
    code_verifier = COLAB_OAUTH_PKCE_VERIFIER
    digest = hashlib.sha256(code_verifier.encode("ascii")).digest()
    code_challenge = base64.urlsafe_b64encode(digest).rstrip(b"=").decode("ascii")
    params = {
        "response_type": "code",
        "client_id": COLAB_OAUTH_CLIENT_ID,
        "redirect_uri": COLAB_OAUTH_REDIRECT_URI,
        "scope": " ".join(COLAB_OAUTH_SCOPES),
        "access_type": "offline",
        "prompt": "consent",
        "token_usage": "remote",
        "code_challenge": code_challenge,
        "code_challenge_method": "S256",
    }
    auth_url = "https://accounts.google.com/o/oauth2/auth?" + urllib.parse.urlencode(params)
    auth_flow.update({
        "active": True,
        "url": auth_url,
        "needs_code": True,
        "code_verifier": code_verifier,
        "message": "URL sẵn sàng. Bấm nút Mở Trang Cấp Quyền bên dưới.",
        "output_lines": [auth_url],
        "process": None,
    })
    return {"status": "started", "url": auth_url, "needs_code": True}

def send_auth_code(code):
    """Đổi mã xác thực OAuth2 lấy token.json trực tiếp qua HTTPS và đồng bộ số dư CU ngay lập tức."""
    import base64, urllib.parse, urllib.request, urllib.error
    clean_code = (code or "").strip()
    if "code=" in clean_code:
        try:
            parsed_q = urllib.parse.parse_qs(urllib.parse.urlsplit(clean_code).query or clean_code)
            if "code" in parsed_q and parsed_q["code"]:
                clean_code = parsed_q["code"][0].strip()
        except Exception:
            pass
    if "&" in clean_code:
        clean_code = clean_code.split("&")[0].strip()
    clean_code = urllib.parse.unquote(clean_code).strip()
    if not clean_code:
        return {"status": "error", "ok": False, "msg": "Mã xác thực trống"}
    try:
        base_payload = {
            "code": clean_code,
            "client_id": COLAB_OAUTH_CLIENT_ID,
            "client_secret": COLAB_OAUTH_CLIENT_SECRET,
            "redirect_uri": COLAB_OAUTH_REDIRECT_URI,
            "grant_type": "authorization_code",
        }
        verifiers_to_try = [
            COLAB_OAUTH_PKCE_VERIFIER,
            auth_flow.get("code_verifier"),
            None,
        ]
        seen_v = set()
        tok_res = None
        last_err_detail = ""
        for v in verifiers_to_try:
            if v in seen_v:
                continue
            seen_v.add(v)
            payload = dict(base_payload)
            if v:
                payload["code_verifier"] = v
            req = urllib.request.Request(
                "https://oauth2.googleapis.com/token",
                data=urllib.parse.urlencode(payload).encode("utf-8"),
                headers={"Content-Type": "application/x-www-form-urlencoded"},
            )
            try:
                with urllib.request.urlopen(req, timeout=15) as resp:
                    tok_res = json.loads(resp.read().decode("utf-8"))
                break
            except urllib.error.HTTPError as he:
                err_body = he.read().decode("utf-8", errors="ignore")
                last_err_detail = f"HTTP {he.code}: {err_body}"
                continue
        if not tok_res:
            raise RuntimeError("Mã xác thực cũ đã hết hạn hoặc thuộc phiên trước. Bạn vui lòng bấm lại nút '+ Thêm Tài Khoản Colab (+)' -> '↗ Mở Link' để lấy mã mới nhé!")
        token_json = {
            "token": tok_res.get("access_token"),
            "refresh_token": tok_res.get("refresh_token"),
            "token_uri": "https://oauth2.googleapis.com/token",
            "client_id": COLAB_OAUTH_CLIENT_ID,
            "client_secret": COLAB_OAUTH_CLIENT_SECRET,
            "scopes": COLAB_OAUTH_SCOPES,
            "universe_domain": "googleapis.com",
            "account": "",
        }
        tok_str = json.dumps(token_json, indent=2)
        if os.name != "nt":
            cfg_dir = Path("/root/.config/colab-cli")
            cfg_dir.mkdir(parents=True, exist_ok=True)
            (cfg_dir / "token.json").write_text(tok_str, encoding="utf-8")
        else:
            b64_tok = base64.b64encode(tok_str.encode("utf-8")).decode("ascii")
            run_wsl(f"mkdir -p /root/.config/colab-cli && echo '{b64_tok}' | base64 -d > /root/.config/colab-cli/token.json", timeout=10)
        mgr_script = wsl_path(str(SCRIPT_DIR / "scripts" / "account_manager.py"))
        _, sync_out = run_wsl(f"python3 '{mgr_script}' sync", timeout=15)
        try:
            sync_info = json.loads(sync_out.strip().splitlines()[-1])
            new_em = sync_info.get("email", "")
            new_bal = float(sync_info.get("balance") or 0.0)
            if new_em and new_bal > 0.05:
                set_worker_enabled(new_em, True)
        except Exception:
            pass
        st = check_auth(refresh_all=True, auto_select_funded=True)
        auth_flow.update({"active": False, "message": "Connected! Success", "process": None})
        return {"status": "sent", "ok": True, "auth": st}
    except Exception as e:
        auth_flow["message"] = f"Lỗi xác thực: {e}"
        return {"status": "error", "ok": False, "msg": str(e)}

# HỆ THỐNG QUẢN LÝ ĐA TÀI KHOẢN & HÀNG ĐỢI LỆNH SONG SONG (MULTI-WORKER QUEUE POOL)
queue_lock = threading.Lock()
job_queue = []              # Danh sách ID các lệnh đang xếp hàng chờ
job_handlers = {}           # jid -> callback hàm thực thi (nhận allocated_target)
current_running_jobs = {}   # jid -> email hoặc list[email]
account_workers = {}        # email -> {"status": "idle"|"running", "current_jid": str|None}
current_running_job = None  # Giữ tương thích ngược với code cũ

WORKERS_CONFIG_FILE = SCRIPT_DIR / "temp" / "workers_config.json"

def load_workers_config() -> dict:
    if WORKERS_CONFIG_FILE.exists():
        try:
            return json.loads(WORKERS_CONFIG_FILE.read_text(encoding="utf-8"))
        except Exception:
            pass
    return {"multi_account_enabled": True, "auto_select_funded": True, "accounts": {}}

def save_workers_config(cfg: dict):
    WORKERS_CONFIG_FILE.parent.mkdir(exist_ok=True)
    WORKERS_CONFIG_FILE.write_text(json.dumps(cfg, indent=2, ensure_ascii=False), encoding="utf-8")

def is_worker_enabled(email: str) -> bool:
    if not email:
        return False
    cfg = load_workers_config()
    acc_cfg = cfg.get("accounts", {}).get(email, {})
    if "enabled" in acc_cfg:
        return bool(acc_cfg["enabled"])
    for a in auth_state.get("accounts", []):
        if a.get("email") == email:
            bal = a.get("balance")
            return bal is None or bal > 0.05
    return True

def set_worker_enabled(email: str, enabled: bool):
    cfg = load_workers_config()
    if "accounts" not in cfg:
        cfg["accounts"] = {}
    if email not in cfg["accounts"]:
        cfg["accounts"][email] = {}
    cfg["accounts"][email]["enabled"] = bool(enabled)
    # Nếu người dùng tự tay bật 1 tài khoản 0 CU hoặc tắt 1 tài khoản còn CU, vẫn lưu trạng thái riêng
    save_workers_config(cfg)
    _recompute_auth_totals()

def select_all_workers(mode: str = "funded") -> dict:
    """
    Chọn nhanh tài khoản chạy song song:
    - mode == 'funded': Tự động chọn tất cả tài khoản còn CU (> 0.05) và bỏ chọn tài khoản hết CU
    - mode == 'all': Chọn tất cả tài khoản trong danh sách
    - mode == 'none': Bỏ chọn tất cả (chỉ giữ lại tài khoản chính nếu cần)
    """
    cfg = load_workers_config()
    if "accounts" not in cfg:
        cfg["accounts"] = {}
    accs = auth_state.get("accounts", []) or []
    selected_count = 0
    for acc in accs:
        em = acc.get("email")
        if not em:
            continue
        bal = acc.get("balance")
        bal_f = 0.0
        if bal is not None:
            try:
                bal_f = float(str(bal).split()[0])
            except Exception:
                pass
        if mode == "funded":
            en = (bal is None) or (bal_f > 0.05)
        elif mode == "all":
            en = True
        elif mode == "none":
            en = False
        else:
            en = (bal is None) or (bal_f > 0.05)
        if em not in cfg["accounts"]:
            cfg["accounts"][em] = {}
        cfg["accounts"][em]["enabled"] = en
        if en:
            selected_count += 1
    cfg["auto_select_funded"] = (mode == "funded")
    save_workers_config(cfg)
    _recompute_auth_totals()
    return {
        "ok": True,
        "mode": mode,
        "selected_count": selected_count,
        "total_cu": auth_state.get("total_cu", 0.0),
        "total_cu_all": auth_state.get("total_cu_all", 0.0),
        "funded_count": auth_state.get("funded_count", 0)
    }

def get_eligible_accounts():
    """Lấy danh sách các tài khoản sẵn sàng chạy tác vụ, sắp xếp theo CU giảm dần."""
    accounts = auth_state.get("accounts", [])
    if not accounts:
        try:
            preload_cached_auth_state()
        except Exception:
            pass
        accounts = auth_state.get("accounts", [])
    valid = []
    for acc in accounts:
        em = acc.get("email")
        if not em:
            continue
        bal = acc.get("balance")
        bal_f = None
        if bal is not None:
            try:
                bal_f = float(str(bal).split()[0])
            except Exception:
                bal_f = None
        if is_worker_enabled(em) and (bal_f is None or bal_f > 0.05):
            valid.append(acc)
    if not valid and auth_state.get("email"):
        valid = [acc for acc in accounts if acc.get("is_active")] or accounts[:1]
    if not valid:
        cfg = load_workers_config()
        for em, info in (cfg.get("accounts") or {}).items():
            if em and info.get("enabled", True):
                valid.append({"email": em, "name": em.split("@")[0], "balance": None})
    valid.sort(key=lambda a: (float(str(a.get("balance")).split()[0]) if a.get("balance") is not None else 0.0), reverse=True)
    return valid

MAX_COALESCED_BATCH = 10
COALESCE_WINDOW_SECONDS = 3.0
_coalesce_groups: dict[str, list[str]] = {}
_coalesce_timer = None
_coalesce_timer_lock = threading.Lock()


def _can_coalesce_single_job(jinfo: dict) -> bool:
    if not isinstance(jinfo, dict):
        return False
    spec = jinfo.get("_coalesce_spec")
    if not isinstance(spec, dict):
        return False
    m = str(spec.get("mode") or "reference").strip().lower()
    lr = str(spec.get("lora") or "pdmd").strip().lower()
    if m not in ("reference", "r2v", "t2v", "text_to_video"):
        return False
    if lr not in ("pdmd", "mystic"):
        return False
    if spec.get("source_video") or spec.get("audio_path") or spec.get("director_pack") or spec.get("guides"):
        return False
    return True


def _save_jobs_cache_now():
    try:
        cache_fp = SCRIPT_DIR / "temp" / "active_jobs_cache.json"
        cache_fp.parent.mkdir(exist_ok=True)
        cache_fp.write_text(json.dumps(active_jobs, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass


def run_coalesced_multi_user_batch(batch_jids: list[str], allocated_account=None):
    """Gom tối đa 10 prompt (từ 1 hoặc nhiều user khác nhau) chạy chung trong 1 phiên VRAM Colab
    để tiết kiệm 65%-75% CU, và trả ngay video hoàn chỉnh về đúng tài khoản user sở hữu từng lệnh."""
    cancel_idle_gpu_stop()
    t_start = time.time()
    acc_email = (
        allocated_account if isinstance(allocated_account, str)
        else (allocated_account[0] if (allocated_account and isinstance(allocated_account, list)) else (auth_state.get("email") or "default"))
    )
    start_cu = _get_account_balance(acc_email)
    td = SCRIPT_DIR / "temp"
    td.mkdir(exist_ok=True)
    batch_uid = f"coal_{uuid.uuid4().hex[:6]}"
    prog_file = td / f"prog_{batch_uid}.json"
    manifest_file = td / f"manifest_{batch_uid}.json"

    specs = []
    manifest_jobs = []
    for idx, sub_jid in enumerate(batch_jids):
        jinfo = active_jobs.get(sub_jid) or {}
        spec = jinfo.get("_coalesce_spec") or {}
        specs.append((sub_jid, spec))
        manifest_jobs.append({
            "id": sub_jid,
            "title": f"Video #{idx + 1} ({sub_jid})",
            "reference_images": list(spec.get("images") or []),
            "prompt": spec.get("prompt_text") or jinfo.get("prompt") or "",
            "duration_seconds": float(spec.get("duration") or jinfo.get("duration") or 10.0),
            "width": int(spec.get("width") or jinfo.get("width") or 1024),
            "height": int(spec.get("height") or jinfo.get("height") or 576),
            "ref_size": str(spec.get("ref_size") or "match"),
            "seed": int(spec.get("seed") or random.randint(1, 2**31 - 1)),
            "output_path": str(spec.get("wsl_output_path") or wsl_path(jinfo.get("output") or "")),
            "mode": str(spec.get("mode") or jinfo.get("mode") or "reference"),
            "lora": str(spec.get("lora") or jinfo.get("lora") or "pdmd"),
            "chain_last_frame": False,
            "chain_join": "cut",
        })
        active_jobs[sub_jid].update({
            "status": "running",
            "stage": "setup",
            "stage_label": f"Bước 1/3: Đang khởi tạo máy ảo GPU & nạp mô hình (Lô #{idx + 1}/{len(batch_jids)})...",
            "progress": 15,
            "started_at": time.strftime("%H:%M:%S"),
            "start_time_ts": t_start,
            "start_cu": start_cu,
            "account_email": acc_email,
            "log": f"Đang xử lý trong lô {len(batch_jids)} lệnh chung 1 phiên VRAM để tối ưu tốc độ & tiết kiệm CU...",
        })
    _save_jobs_cache_now()

    manifest_payload = {"jobs": manifest_jobs, "chain_last_frame": False, "chain_join": "cut"}
    manifest_file.write_text(json.dumps(manifest_payload, ensure_ascii=False, indent=2), encoding="utf-8")

    first_spec = specs[0][1] if specs else {}
    gpu = str(first_spec.get("gpu") or "A100")
    lora = str(first_spec.get("lora") or "pdmd")
    mode = str(first_spec.get("mode") or "reference")
    total_timeout = max(2400, 1200 * len(batch_jids))

    def _build_batch_wsl_cmd(target_acc: str) -> str:
        runner = wsl_path(str(SCRIPT_DIR / "scripts" / "runner.py"))
        prog_wsl = wsl_path(str(prog_file))
        man_wsl = wsl_path(str(manifest_file))
        out_dir_wsl = wsl_path(str(Path(first_spec.get("output_path") or (Path.home() / "Downloads" / "out.mp4")).parent))
        safe_acc = re.sub(r"[^a-zA-Z0-9_]", "_", target_acc or "default")
        token_env = f"COLAB_TOKEN_PATH='/root/.config/colab-cli/tokens/{target_acc}.json'" if target_acc and target_acc != "default" else ""
        session_env = f"COLAB_SESSION_NAME='h3_warm_{safe_acc}' H3_STOP_ON_COMPLETE=0"
        return (
            f"{token_env} {session_env} H3_INFERENCE_MODE={mode} H3_LORA={lora} H3_AI_UPSCALE=0 "
            f"python3 '{runner}' batch --manifest '{man_wsl}' --output-dir '{out_dir_wsl}' "
            f"--gpu {gpu} --progress '{prog_wsl}' --timeout {total_timeout}"
        )

    stop_poll = threading.Event()
    delivered_jids: set[str] = set()

    def _finalize_single_subjob(sub_jid: str, spec: dict, ok_clip: bool, log_tail_str: str = "", err_override: str = ""):
        if sub_jid in delivered_jids:
            return
        j_cur = active_jobs.get(sub_jid)
        if not j_cur or j_cur.get("status") == "cancelled":
            delivered_jids.add(sub_jid)
            return
        out_p = str(spec.get("output_path") or j_cur.get("output") or "")
        el_sec = max(1, int(time.time() - t_start))
        el_str = f"{el_sec // 60} phút {el_sec % 60} giây" if el_sec >= 60 else f"{el_sec} giây"
        if ok_clip and out_p and os.path.exists(out_p) and os.path.getsize(out_p) > 1000:
            delivered_jids.add(sub_jid)
            record_h3_video(
                out_p,
                duration=spec.get("duration"),
                seed=spec.get("seed"),
                prompt=spec.get("prompt_text"),
                reference_images=spec.get("ref_items"),
                scene_id=spec.get("scene_id"),
                visual_style=spec.get("visual_style"),
                mode=spec.get("mode"),
                lora=spec.get("lora"),
                width=spec.get("width"),
                height=spec.get("height"),
                gpu=spec.get("gpu"),
                job_id=sub_jid,
                gen_seconds=el_sec,
                owner_user_id=spec.get("owner_user_id"),
                owner_username=spec.get("owner_username"),
            )
            j_cur.update({
                "status": "completed",
                "stage": "completed",
                "stage_label": "✅ Hoàn tất! Video đã sẵn sàng phát.",
                "finished_at": time.strftime("%H:%M:%S (%d/%m/%Y)"),
                "elapsed_seconds": el_sec,
                "elapsed_str": el_str,
                "progress": 100,
                "output": out_p,
                "video_url": f"/api/video?path={urllib.parse.quote(out_p)}",
                "error_diag": None,
            })
            if log_tail_str:
                j_cur["log"] = log_tail_str
            _save_jobs_cache_now()
        elif err_override:
            delivered_jids.add(sub_jid)
            j_cur.update({
                "status": "failed",
                "stage": "failed",
                "stage_label": "❌ Quá trình tạo video thất bại.",
                "finished_at": time.strftime("%H:%M:%S (%d/%m/%Y)"),
                "elapsed_seconds": el_sec,
                "elapsed_str": el_str,
                "progress": 0,
                "video_url": None,
                "error_diag": diagnose_job_error(err_override or log_tail_str),
            })
            _save_jobs_cache_now()

    def _poll_coalesced():
        while not stop_poll.is_set():
            time.sleep(2)
            if not prog_file.exists():
                continue
            try:
                pdata = json.loads(prog_file.read_text(encoding="utf-8"))
                jobs_p = pdata.get("jobs") or []
                log_tail = pdata.get("log_tail") or []
                tail_str = "\n".join(log_tail[-25:]) if log_tail else ""
                last_ln = log_tail[-1] if log_tail else ""
                step_hint = f" ({last_ln.split('|')[-1].strip()[:60]})" if "|" in last_ln else ""
                for idx, (sub_jid, spec) in enumerate(specs):
                    if sub_jid in delivered_jids or idx >= len(jobs_p):
                        continue
                    j_cur = active_jobs.get(sub_jid)
                    if not j_cur or j_cur.get("status") in ("completed", "cancelled", "failed"):
                        continue
                    jp = jobs_p[idx] or {}
                    jst = jp.get("status") or ""
                    if tail_str:
                        j_cur["log"] = tail_str
                    if jst == "generating":
                        j_cur["stage"] = "generating"
                        j_cur["stage_label"] = f"Bước 2/3: 🎬 AI đang sinh khung hình & render video (Video #{idx + 1}/{len(specs)}){step_hint}..."
                        j_cur["progress"] = 65
                    elif jst == "downloading":
                        j_cur["stage"] = "downloading"
                        j_cur["stage_label"] = "Bước 3/3: ⬇️ Đang tải video hoàn chỉnh về máy..."
                        j_cur["progress"] = 90
                    elif jst == "completed":
                        out_p = str(spec.get("output_path") or j_cur.get("output") or "")
                        if out_p and os.path.exists(out_p) and os.path.getsize(out_p) > 1000:
                            _finalize_single_subjob(sub_jid, spec, True, log_tail_str=tail_str)
                    elif jst == "failed":
                        _finalize_single_subjob(sub_jid, spec, False, log_tail_str=tail_str, err_override=str(jp.get("error") or "Render failed"))
                    elif jst in ("queued", "uploading"):
                        j_cur["stage"] = "setup"
                        j_cur["stage_label"] = f"⏳ Đang xếp lượt render trực tiếp trong cùng phiên VRAM (Vị trí #{idx + 1}/{len(specs)})..."
                        j_cur["progress"] = max(int(j_cur.get("progress") or 15), 25)
            except Exception:
                pass

    t_poller = threading.Thread(target=_poll_coalesced, daemon=True)
    t_poller.start()

    cmd_args = _build_batch_wsl_cmd(acc_email)
    code, out = run_wsl(cmd_args, timeout=total_timeout + 180)

    out_low = (out or "").lower()
    if code != 0 and not delivered_jids and any(k in out_low for k in ("allocation refused", "precondition failed", "0.00 compute units", "insufficient compute units", "quota")):
        fallback_acc = None
        with queue_lock:
            busy_other = set()
            for r_accs in current_running_jobs.values():
                if isinstance(r_accs, list):
                    busy_other.update(r_accs)
                elif isinstance(r_accs, str):
                    busy_other.add(r_accs)
            for cand in get_eligible_accounts():
                c_em = cand.get("email")
                if c_em and c_em != acc_email and c_em not in busy_other:
                    fallback_acc = c_em
                    break
        if fallback_acc:
            acc_email = fallback_acc
            for sub_jid, _ in specs:
                if sub_jid in active_jobs and sub_jid not in delivered_jids:
                    active_jobs[sub_jid].update({
                        "account_email": acc_email,
                        "stage_label": "🔄 Đang tự động chuyển sang luồng GPU dự phòng & khởi tạo...",
                    })
            cmd_args = _build_batch_wsl_cmd(acc_email)
            code, out2 = run_wsl(cmd_args, timeout=total_timeout + 180)
            out = f"{out}\n\n--- [FAILOVER GPU] ---\n{out2}"

    stop_poll.set()
    schedule_idle_gpu_stop(480)

    t_end = time.time()
    elapsed_sec = max(1, int(t_end - t_start))
    end_cu = _get_account_balance_fresh(acc_email)
    used_cu = round(start_cu - end_cu, 2) if (start_cu is not None and end_cu is not None and start_cu >= end_cu) else None
    if (used_cu is None or used_cu <= 0) and elapsed_sec > 0:
        _cu_rate = 0.00158 if str(gpu).upper() == "A100" else 0.00048
        used_cu = max(0.01, round(elapsed_sec * _cu_rate, 2))

    ok_sub_jids = []
    for sub_jid, spec in specs:
        out_p = str(spec.get("output_path") or active_jobs.get(sub_jid, {}).get("output") or "")
        is_sub_ok = bool(out_p and os.path.exists(out_p) and os.path.getsize(out_p) > 1000 and os.path.getmtime(out_p) >= t_start - 10)
        if is_sub_ok:
            ok_sub_jids.append((sub_jid, spec, out_p))
            _finalize_single_subjob(sub_jid, spec, True, log_tail_str=out)
        else:
            _finalize_single_subjob(sub_jid, spec, False, log_tail_str=out, err_override=out or "Batch render failed")

    if ok_sub_jids and used_cu:
        per_vid_cu = max(0.01, round(used_cu / max(1, len(ok_sub_jids)), 2))
        for sub_jid, spec, out_p in ok_sub_jids:
            if sub_jid in active_jobs:
                active_jobs[sub_jid]["start_cu"] = start_cu
                active_jobs[sub_jid]["end_cu"] = end_cu
                active_jobs[sub_jid]["used_cu"] = per_vid_cu
            record_h3_video(
                out_p,
                job_id=sub_jid,
                used_cu=per_vid_cu,
                owner_user_id=spec.get("owner_user_id"),
                owner_username=spec.get("owner_username"),
            )
    _save_jobs_cache_now()
    threading.Thread(target=check_auth, daemon=True).start()


def _schedule_coalesce_dispatch():
    global _coalesce_timer
    with _coalesce_timer_lock:
        if _coalesce_timer is not None:
            return
        def _fire():
            global _coalesce_timer
            with _coalesce_timer_lock:
                _coalesce_timer = None
            _process_queue(from_timer=True)
        _coalesce_timer = threading.Timer(COALESCE_WINDOW_SECONDS, _fire)
        _coalesce_timer.daemon = True
        _coalesce_timer.start()


def _process_queue(from_timer: bool = False):
    global current_running_job
    to_launch = []
    with queue_lock:
        # 1. Dọn dẹp các lệnh đã xong khỏi current_running_jobs
        finished = []
        for jid, allocated in list(current_running_jobs.items()):
            if jid in _coalesce_groups:
                sub_ids = _coalesce_groups.get(jid) or []
                if all(active_jobs.get(sid, {}).get("status") not in ("starting", "running") for sid in sub_ids):
                    finished.append(jid)
            else:
                st = active_jobs.get(jid, {}).get("status")
                if st not in ("starting", "running"):
                    finished.append(jid)
        for jid in finished:
            _coalesce_groups.pop(jid, None)
            alloc = current_running_jobs.pop(jid, None)
            if isinstance(alloc, list):
                for em in alloc:
                    if em in account_workers:
                        account_workers[em]["status"] = "idle"
                        account_workers[em]["current_jid"] = None
                        account_workers[em]["last_active_ts"] = time.time()
            elif isinstance(alloc, str):
                if alloc in account_workers:
                    account_workers[alloc]["status"] = "idle"
                    account_workers[alloc]["current_jid"] = None
                    account_workers[alloc]["last_active_ts"] = time.time()

        current_running_job = next(iter(current_running_jobs.keys())) if current_running_jobs else None

        if not job_queue:
            return

        eligible = get_eligible_accounts()
        if not eligible:
            return

        # Xác định các tài khoản đang bận
        busy_emails = set()
        for alloc in current_running_jobs.values():
            if isinstance(alloc, list):
                busy_emails.update(alloc)
            elif isinstance(alloc, str):
                busy_emails.add(alloc)

        # Lọc ra các tài khoản rảnh rỗi (IDLE) và ƯU TIÊN GPU ĐANG NÓNG (Warm Session Affinity trong 8 phút gần nhất)
        idle_accounts = [acc for acc in eligible if acc.get("email") and acc["email"] not in busy_emails]
        now_ts_q = time.time()
        idle_accounts.sort(
            key=lambda a: (
                1 if (now_ts_q - float(account_workers.get(a.get("email"), {}).get("last_active_ts") or 0.0)) < 480 else 0,
                float(str(a.get("balance")).split()[0]) if a.get("balance") is not None else 0.0,
            ),
            reverse=True,
        )

        # TIẾT KIỆM CU:
        # 1) Nếu chưa có GPU nào chạy và lệnh đầu tiên có thể gom lô (< 10 lệnh), chờ 3 giây để gom các lệnh gửi liền kề vào chung 1 lần chạy.
        first_q_info = active_jobs.get(job_queue[0], {})
        if not current_running_jobs and not from_timer and _can_coalesce_single_job(first_q_info) and len(job_queue) < MAX_COALESCED_BATCH:
            for idx, qid in enumerate(job_queue):
                if qid in active_jobs:
                    active_jobs[qid]["queue_pos"] = idx + 1
                    active_jobs[qid]["stage_label"] = f"⏳ Đang gom lô xử lý chung (tối đa {MAX_COALESCED_BATCH} lệnh/phiên GPU — Thứ tự #{idx + 1})..."
            _schedule_coalesce_dispatch()
            return

        # 2) Nếu đã có ít nhất 1 GPU đang chạy và số lệnh đang chờ <= 10 * số GPU đang chạy,
        #    KHÔNG đánh thức thêm Colab lạnh mới (đỡ tốn 3 phút nạp model), mà gom tối đa 10 lệnh chờ GPU ấm chạy xong xử lý 1 mẻ!
        if current_running_jobs and all(_can_coalesce_single_job(active_jobs.get(qid, {})) for qid in job_queue):
            active_gpu_cnt = max(1, len(current_running_jobs))
            if len(job_queue) <= MAX_COALESCED_BATCH * active_gpu_cnt:
                for idx, qid in enumerate(job_queue):
                    if qid in active_jobs:
                        active_jobs[qid]["queue_pos"] = idx + 1
                        active_jobs[qid]["stage_label"] = f"⏳ Đang gom lô trên GPU ấm (Vị trí #{idx + 1}/{MAX_COALESCED_BATCH} — Chạy liền mạch ngay khi phiên trước xong)..."
                return

        # Phân phối các lệnh trong hàng chờ (Gom tối đa 10 lệnh đơn cùng loại vào 1 phiên VRAM Colab)
        while job_queue and idle_accounts:
            next_jid = job_queue.pop(0)
            job_info = active_jobs.get(next_jid, {})
            handler = job_handlers.get(next_jid)
            if not handler:
                continue

            is_multi_batch = job_info.get("worker_mode") == "multi_parallel" and int(job_info.get("total_jobs") or 1) >= 2
            if is_multi_batch:
                allocated_target = [acc["email"] for acc in idle_accounts]
                idle_accounts = []
                current_running_jobs[next_jid] = allocated_target
                for em in allocated_target:
                    account_workers[em] = {"status": "running", "current_jid": next_jid}
                    busy_emails.add(em)
                active_jobs[next_jid]["worker_accounts"] = allocated_target
                active_jobs[next_jid]["worker_count"] = len(allocated_target)
                active_jobs[next_jid]["status"] = "starting"
                active_jobs[next_jid]["queue_pos"] = 0
                current_running_job = next_jid
                to_launch.append((next_jid, handler, allocated_target))
            else:
                # Kiểm tra xem có thể gom thêm tới tối đa 10 lệnh đơn trong hàng đợi vào cùng 1 phiên VRAM không
                coalesced_jids = [next_jid]
                if _can_coalesce_single_job(job_info):
                    base_lora = str((job_info.get("_coalesce_spec") or {}).get("lora") or "pdmd").strip().lower()
                    rem_queue = []
                    for cand_jid in job_queue:
                        cand_info = active_jobs.get(cand_jid, {})
                        cand_lora = str((cand_info.get("_coalesce_spec") or {}).get("lora") or "pdmd").strip().lower()
                        if len(coalesced_jids) < MAX_COALESCED_BATCH and _can_coalesce_single_job(cand_info) and cand_lora == base_lora:
                            coalesced_jids.append(cand_jid)
                        else:
                            rem_queue.append(cand_jid)
                    job_queue[:] = rem_queue

                pref_em = job_info.get("preferred_account")
                chosen_acc = None
                if pref_em:
                    for idx_a, acc_a in enumerate(idle_accounts):
                        if acc_a.get("email") == pref_em:
                            chosen_acc = idle_accounts.pop(idx_a)
                            break
                if not chosen_acc:
                    chosen_acc = idle_accounts.pop(0)
                allocated_target = chosen_acc["email"]
                busy_emails.add(allocated_target)

                if len(coalesced_jids) >= 2:
                    group_key = f"coalesce_{uuid.uuid4().hex[:6]}"
                    _coalesce_groups[group_key] = list(coalesced_jids)
                    current_running_jobs[group_key] = allocated_target
                    account_workers[allocated_target] = {"status": "running", "current_jid": group_key, "last_active_ts": time.time()}
                    for idx_c, c_jid in enumerate(coalesced_jids):
                        if c_jid in active_jobs:
                            active_jobs[c_jid]["account_email"] = allocated_target
                            active_jobs[c_jid]["account_name"] = chosen_acc.get("name", "")
                            active_jobs[c_jid]["status"] = "starting"
                            active_jobs[c_jid]["queue_pos"] = 0
                            active_jobs[c_jid]["stage_label"] = f"🚀 Đang khởi tạo lô {len(coalesced_jids)} video chung 1 phiên GPU (Vị trí #{idx_c + 1}/{len(coalesced_jids)})..."
                    current_running_job = coalesced_jids[0]
                    batch_copy = list(coalesced_jids)
                    to_launch.append((group_key, lambda target, bj=batch_copy: run_coalesced_multi_user_batch(bj, target), allocated_target))
                else:
                    current_running_jobs[next_jid] = allocated_target
                    account_workers[allocated_target] = {"status": "running", "current_jid": next_jid, "last_active_ts": time.time()}
                    active_jobs[next_jid]["account_email"] = allocated_target
                    active_jobs[next_jid]["account_name"] = chosen_acc.get("name", "")
                    active_jobs[next_jid]["status"] = "starting"
                    active_jobs[next_jid]["queue_pos"] = 0
                    active_jobs[next_jid]["stage_label"] = "🚀 Đang khởi tạo tiến trình tạo video..."
                    current_running_job = next_jid
                    to_launch.append((next_jid, handler, allocated_target))

        # Cập nhật lại số thứ tự các lệnh còn lại trong hàng chờ
        for idx, qid in enumerate(job_queue):
            if qid in active_jobs:
                active_jobs[qid]["queue_pos"] = idx + 1
                active_jobs[qid]["stage_label"] = f"⏳ Đang chờ trong hàng đợi (Thứ tự #{idx + 1})..."

    for l_jid, l_handler, l_target in to_launch:
        def _make_worker(w_jid, w_handler, w_target):
            def _worker():
                global current_running_job
                try:
                    w_handler(w_target)
                finally:
                    with queue_lock:
                        _coalesce_groups.pop(w_jid, None)
                        released = current_running_jobs.pop(w_jid, None) or w_target
                        if isinstance(released, list):
                            for em in released:
                                if em in account_workers:
                                    account_workers[em]["status"] = "idle"
                                    account_workers[em]["current_jid"] = None
                                    account_workers[em]["last_active_ts"] = time.time()
                        elif isinstance(released, str):
                            if released in account_workers:
                                account_workers[released]["status"] = "idle"
                                account_workers[released]["current_jid"] = None
                                account_workers[released]["last_active_ts"] = time.time()
                        current_running_job = next(iter(current_running_jobs.keys())) if current_running_jobs else None
                    _process_queue(from_timer=True)
            return _worker
        threading.Thread(target=_make_worker(l_jid, l_handler, l_target), daemon=True).start()

def prioritize_job(jid):
    with queue_lock:
        if jid in job_queue:
            job_queue.remove(jid)
            job_queue.insert(0, jid)
            for idx, qid in enumerate(job_queue):
                if qid in active_jobs:
                    active_jobs[qid]["queue_pos"] = idx + 1
                    active_jobs[qid]["stage_label"] = f"⏳ Đang chờ trong hàng đợi (Thứ tự #{idx + 1})..."
            return {"ok": True, "pos": 1}
    return {"ok": False, "msg": "Tác vụ không còn nằm trong hàng chờ hoặc đang chạy"}

def cancel_job(jid):
    with queue_lock:
        if jid in job_queue:
            job_queue.remove(jid)
            if jid in active_jobs:
                active_jobs[jid]["status"] = "cancelled"
                active_jobs[jid]["stage"] = "cancelled"
                active_jobs[jid]["stage_label"] = "❌ Đã hủy lệnh bởi người dùng"
            for idx, qid in enumerate(job_queue):
                if qid in active_jobs:
                    active_jobs[qid]["queue_pos"] = idx + 1
                    active_jobs[qid]["stage_label"] = f"⏳ Đang chờ trong hàng đợi (Thứ tự #{idx + 1})..."
            return {"ok": True}
        if jid in active_jobs and active_jobs[jid].get("status") in ("starting", "running"):
            active_jobs[jid]["status"] = "cancelled"
            active_jobs[jid]["stage"] = "cancelled"
            active_jobs[jid]["stage_label"] = "❌ Đã buộc dừng lệnh đang chạy bởi người dùng"
            alloc = current_running_jobs.pop(jid, None)
            if isinstance(alloc, list):
                for em in alloc:
                    if em in account_workers:
                        account_workers[em]["status"] = "idle"
                        account_workers[em]["current_jid"] = None
            elif isinstance(alloc, str) and alloc in account_workers:
                account_workers[alloc]["status"] = "idle"
                account_workers[alloc]["current_jid"] = None
    try:
        subprocess.run(
            _shell_Wrap(f"pkill -9 -f 'prog_{jid}' 2>/dev/null || true"),
            capture_output=True, timeout=5
        )
    except Exception:
        pass
    _process_queue()
    if jid in active_jobs and active_jobs[jid].get("status") == "cancelled":
        return {"ok": True}
    return {"ok": False, "msg": "Tác vụ không tồn tại hoặc đã kết thúc"}

def diagnose_job_error(log_text: str) -> dict:
    if not log_text:
        return {"reason": "Tác vụ kết thúc bất ngờ không rõ nguyên nhân", "tip": "Kiểm tra lại kết nối mạng hoặc thử tạo lại."}
    lt = log_text.lower()
    if "permission denied" in lt and ("prog_" in lt or ".tmp" in lt):
        return {
            "reason": "Xung đột khóa file tiến trình tạm thời trên Windows/WSL",
            "tip": "Đã được kích hoạt cơ chế chống khóa file tự động. Bạn có thể bấm Tạo lại ngay để tiếp tục."
        }
    if "0.00 compute units" in lt or "insufficient compute units" in lt or "cannot allocate compute units" in lt or "out of compute units" in lt:
        return {
            "reason": "Tài khoản máy chủ Cloud đã hết điểm Compute Units (CU = 0)",
            "tip": "Vào mục Cài Đặt để đổi sang tài khoản máy chủ khác có CU, hoặc nạp thêm CU."
        }
    if "invalid_grant" in lt or "token has been expired" in lt or "token expired" in lt or "re-authenticate" in lt:
        return {
            "reason": "Mã ủy quyền máy chủ đã hết hạn",
            "tip": "Bấm vào 'Cài Đặt' để xác thực và kết nối lại máy chủ."
        }
    if "no gpu available" in lt or "cannot assign requested gpu" in lt or "all instances are busy" in lt:
        return {
            "reason": "Cụm máy chủ tạm thời hết card GPU A100",
            "tip": "Chờ khoảng 5-10 phút để máy chủ giải phóng tài nguyên, hoặc đổi GPU sang V100/T4."
        }
    if "cuda out of memory" in lt or "oom" in lt or "out of memory" in lt:
        return {
            "reason": "Tràn bộ nhớ GPU (CUDA Out of Memory)",
            "tip": "Hãy giảm độ dài video xuống 8-10 giây hoặc chọn GPU A100 có VRAM lớn hơn."
        }
    if "timeout" in lt or "exceeded" in lt:
        return {
            "reason": "Hết thời gian chờ phản hồi từ máy chủ Cloud (Timeout)",
            "tip": "Mạng bị ngắt hoặc phiên làm việc bị treo. Hãy bật 'GPU Nóng' và thử lại."
        }
    if "connection was lost" in lt or "connection lost" in lt:
        return {
            "reason": "Mất kết nối WebSocket tới máy chủ Cloud (do máy tính ngủ/Sleep hoặc rớt mạng)",
            "tip": "Phiên kết nối bị ngắt khi máy tính chuyển sang chế độ Sleep hoặc rớt mạng. Hãy bấm 'Tạo lại' để chạy lại ngay!"
        }
    if "download failed: file or directory not found" in lt or "output.mp4: no such file" in lt or ("output.mp4" in lt and "not found" in lt):
        return {
            "reason": "Máy chủ chưa tạo ra video đầu ra (Lỗi cấu hình node hoặc thiếu tham số tương thích)",
            "tip": "Đã cập nhật bản vá tương thích mới nhất cho máy chủ (Hỗ trợ toàn diện T2V, PDMD, và Reference). Hãy bấm 'Tạo lại' để chạy tiếp!"
        }
    if "prompt references picture" in lt:
        return {
            "reason": "Số lượng ảnh tham chiếu tải lên ít hơn số thẻ <Picture N> trong kịch bản",
            "tip": "Hệ thống đã bật chế độ tự động nhân bản ảnh bù vào các thẻ Picture còn thiếu. Bạn cũng có thể tải thêm ảnh tham chiếu thứ 3 hoặc sửa thẻ <Picture 3> trong kịch bản thành <Picture 1> hoặc <Picture 2>."
        }
    if "filenotfounderror" in lt or "no such file or directory" in lt:
        return {
            "reason": "Không tìm thấy file ảnh tham chiếu hoặc thư mục xuất không hợp lệ",
            "tip": "Kiểm tra lại xem ảnh tham chiếu có tồn tại trên máy và đường dẫn lưu có dấu tiếng Việt không."
        }
    lines = [ln.strip() for ln in log_text.splitlines() if ln.strip()]
    err_line = next((ln for ln in reversed(lines) if "error" in ln.lower() or "exception" in ln.lower()), "")
    if err_line:
        clean_err = err_line[:130]
        return {
            "reason": f"Lỗi thực thi: {clean_err}",
            "tip": "Xem chi tiết nhật ký (Log console) bên dưới để xem chi tiết."
        }
    return {
        "reason": "Quá trình sinh video gặp lỗi từ máy chủ",
        "tip": "Vui lòng xem chi tiết nhật ký bên dưới hoặc bấm tạo lại."
    }

_idle_stop_timer = None
_idle_stop_lock = threading.Lock()

def stop_all_warm_sessions() -> tuple[int, str]:
    """Dừng toàn bộ các phiên GPU ấm trên tất cả tài khoản để bảo vệ Compute Units (CU)."""
    runner = wsl_path(str(SCRIPT_DIR / "scripts" / "runner.py"))
    accounts = [a.get("email") for a in auth_state.get("accounts", []) if a.get("email")]
    if auth_state.get("email") and auth_state.get("email") not in accounts:
        accounts.append(auth_state.get("email"))
    logs = []
    for em in (accounts or ["default"]):
        safe_acc = re.sub(r'[^a-zA-Z0-9_]', '_', em or 'default')
        tok = f"COLAB_TOKEN_PATH='/root/.config/colab-cli/tokens/{em}.json' " if em and em != 'default' else ""
        sess = f"h3_warm_{safe_acc}"
        c, o = run_wsl(f"{tok}python3 '{runner}' stop --session '{sess}'", timeout=45)
        if o:
            logs.append(f"[{em}] {o.strip()}")
    c2, o2 = run_wsl(f"python3 '{runner}' stop --session h3_warm_session", timeout=30)
    if o2:
        logs.append(o2.strip())
    return 0, "\n".join(logs) or "Đã thu hồi toàn bộ phiên GPU."

def cancel_idle_gpu_stop():
    global _idle_stop_timer
    with _idle_stop_lock:
        if _idle_stop_timer is not None:
            _idle_stop_timer.cancel()
            _idle_stop_timer = None

def schedule_idle_gpu_stop(idle_seconds: int = 480):
    """Tự động ngắt GPU ấm nếu sau 10 phút không có lệnh mới nào chạy hoặc chờ."""
    global _idle_stop_timer
    with _idle_stop_lock:
        if _idle_stop_timer is not None:
            _idle_stop_timer.cancel()
        def _auto_stop():
            with queue_lock:
                has_active = bool(current_running_jobs or job_queue)
            if not has_active:
                try:
                    stop_all_warm_sessions()
                except Exception:
                    pass
        _idle_stop_timer = threading.Timer(idle_seconds, _auto_stop)
        _idle_stop_timer.daemon = True
        _idle_stop_timer.start()

def _find_latest_cam01_previs_mp4():
    try:
        pdir = SCRIPT_DIR / "output" / "previs"
        if pdir.is_dir():
            cands = sorted(pdir.glob("cam01_previs_*.mp4"), key=lambda x: x.stat().st_mtime, reverse=True)
            if cands and cands[0].stat().st_size > 1000:
                return str(cands[0])
    except Exception:
        pass
    return None

def run_single_video(images, prompt_file, output_path, gpu="A100", duration=12, timeout=2400, width=1024, height=576, ref_size="match", seed=-1, warm_session=True, enable_upscale=False, upscale_target="2K", prompt_text="", mode="reference", lora="pdmd", audio_path=None, director_pack=None, source_video=None, preferred_account=None, scene_id="", visual_style="", ui_mode=None, output_fps=24, destutter=False, guides=None, owner_user_id="guest", owner_username="guest", dispatch_now=True):
    cancel_idle_gpu_stop()
    mode = (str(mode or "reference").strip().lower()) or "reference"
    ui_mode = (str(ui_mode or mode).strip().lower()) or mode
    if mode in ("cam_previs", "audio_sync", "fasth3_omni"):
        if mode == "fasth3_omni":
            if not images and not source_video:
                mode = "t2v"
                lora = "fasth3_t2v"
            else:
                mode = "reference"
                lora = "fasth3_omni"
        else:
            mode = "reference"
    elif mode in ("fasth3_t2v", "fasth3_trim"):
        if lora not in ("fasth3_t2v", "fasth3_trim"):
            lora = "fasth3_trim" if mode == "fasth3_trim" else "fasth3_t2v"
        mode = "t2v"
    elif mode == "skeleton_v2v":
        mode = "reference"
    if mode != "director":
        director_pack = None
    # Chỉ chế độ Vẽ Đường Máy Quay mới được tự lấy video Cam01 mới nhất
    if not source_video and ui_mode == "cam_previs" and ("<Video 1>" in str(prompt_text or "")):
        source_video = _find_latest_cam01_previs_mp4()
    if source_video and mode not in ("char_swap", "v2v", "reference", "r2v", "ai_upscale"):
        mode = "reference"
    jid = uuid.uuid4().hex[:8]
    td = SCRIPT_DIR / "temp"
    td.mkdir(exist_ok=True)
    prog_file = td / f"prog_{jid}.json"

    if not prompt_text and prompt_file and os.path.isfile(str(prompt_file)):
        try:
            prompt_text = Path(prompt_file).read_text(encoding="utf-8")
        except Exception:
            pass

    if not prompt_file or not os.path.isfile(str(prompt_file)):
        pf_tmp = td / f"p_{jid}.txt"
        pf_tmp.write_text(prompt_text or "Photorealistic cinematic scene, 8k resolution, natural lighting.", encoding="utf-8")
        prompt_file = str(pf_tmp)
    
    norm_single_refs = normalize_ref_image_items(images)
    with queue_lock:
        q_pos = len(job_queue) + 1 if current_running_jobs else 1
        active_jobs[jid] = {
            "id": jid,
            "scene_id": scene_id or "",
            "visual_style": visual_style or "",
            "status": "queued",
            "stage": "queued",
            "queue_pos": q_pos,
            "stage_label": f"⏳ Đang chờ trong hàng đợi (Thứ tự #{q_pos})...",
            "images": images,
            "ref_items": norm_single_refs,
            "reference_images": norm_single_refs,
            "prompt": prompt_text or "",
            "output": output_path,
            "gpu": gpu,
            "duration": duration,
            "width": width,
            "height": height,
            "mode": mode,
            "ui_mode": ui_mode,
            "lora": lora,
            "has_audio": bool(audio_path),
            "has_source_video": bool(source_video),
            "source_video": str(source_video).replace("\\", "/") if source_video else None,
            "source_video_name": Path(source_video).name if source_video else None,
            "source_video_url": f"/api/video?path={urllib.parse.quote(str(source_video))}" if source_video else None,
            "has_pack": bool(director_pack),
            "seed": seed if (seed is not None and str(seed) != "-1" and str(seed).strip()) else "Ngẫu nhiên",
            "warm_session": bool(warm_session),
            "enable_upscale": bool(enable_upscale),
            "upscale_target": upscale_target,
            "started_at": time.strftime("%H:%M:%S"),
            "log": "Đang xếp hàng chờ xử lý trên máy chủ GPU...",
            "progress": 0,
            "video_url": None,
            "error_diag": None,
            "account_email": preferred_account,
            "preferred_account": preferred_account,
            "guides": list(guides or []),
            "owner_user_id": owner_user_id or "guest",
            "owner_username": owner_username or "guest",
            "_coalesce_spec": {
                "id": jid,
                "images": [wsl_path(img) for img in images],
                "ref_items": norm_single_refs,
                "prompt_file": prompt_file,
                "prompt_text": prompt_text or "",
                "output_path": output_path,
                "wsl_output_path": wsl_path(output_path),
                "gpu": gpu,
                "duration": float(duration),
                "timeout": int(timeout),
                "width": int(width),
                "height": int(height),
                "ref_size": ref_size,
                "seed": int(seed) if (seed is not None and str(seed) != "-1" and str(seed).strip()) else random.randint(1, 2**31 - 1),
                "enable_upscale": bool(enable_upscale),
                "upscale_target": upscale_target,
                "mode": mode,
                "ui_mode": ui_mode,
                "lora": lora,
                "audio_path": audio_path,
                "director_pack": director_pack,
                "source_video": source_video,
                "scene_id": scene_id or "",
                "visual_style": visual_style or "",
                "output_fps": int(output_fps or 24),
                "destutter": bool(destutter),
                "guides": list(guides or []),
                "owner_user_id": owner_user_id or "guest",
                "owner_username": owner_username or "guest",
            },
        }

    def _poll_prog():
        while active_jobs.get(jid, {}).get("status") in ("starting", "running"):
            time.sleep(2)
            if prog_file.exists():
                try:
                    pdata = json.loads(prog_file.read_text(encoding="utf-8"))
                    jobs_p = pdata.get("jobs", [{}])
                    job_st = jobs_p[0].get("status") if jobs_p else ""
                    log_tail = pdata.get("log_tail", [])
                    if log_tail:
                        active_jobs[jid]["log"] = "\n".join(log_tail[-25:])
                    if job_st == "generating":
                        active_jobs[jid]["stage"] = "generating"
                        last_ln = log_tail[-1] if log_tail else ""
                        step_hint = f" ({last_ln.split('|')[-1].strip()[:60]})" if "|" in last_ln else ""
                        if "[h3-upsampler]" in last_ln.lower() or "h3videoupsampler" in last_ln.lower():
                            active_jobs[jid]["stage_label"] = f"Bước 2.5/3: 💎 Đang chạy H3VideoUpsampler (AI Latent x2) trên Colab{step_hint}..."
                            active_jobs[jid]["progress"] = 82
                        else:
                            active_jobs[jid]["stage_label"] = f"Bước 2/3: 🎬 AI đang sinh khung hình & render video{step_hint}..."
                            active_jobs[jid]["progress"] = 65
                    elif job_st == "downloading":
                        active_jobs[jid]["stage"] = "downloading"
                        active_jobs[jid]["stage_label"] = "Bước 3/3: ⬇️ Đang tải video hoàn chỉnh về máy..."
                        active_jobs[jid]["progress"] = 90
                    elif job_st == "completed":
                        active_jobs[jid]["stage"] = "completed"
                        active_jobs[jid]["stage_label"] = "✅ Hoàn tất! Video đã sẵn sàng phát."
                        active_jobs[jid]["progress"] = 100
                except Exception:
                    pass

    def _execute(allocated_account=None):
        cancel_idle_gpu_stop()
        t_start = time.time()
        acc_email = allocated_account if isinstance(allocated_account, str) else (allocated_account[0] if (allocated_account and isinstance(allocated_account, list)) else preferred_account or auth_state.get("email") or "default")
        start_cu = auth_state.get("balance")
        for a in auth_state.get("accounts", []):
            if a.get("email") == acc_email and a.get("balance") is not None:
                start_cu = a.get("balance")
                break

        def _build_wsl_args(target_acc):
            runner = wsl_path(str(SCRIPT_DIR / "scripts" / "runner.py"))
            prog_wsl = wsl_path(str(prog_file))
            safe_acc = re.sub(r'[^a-zA-Z0-9_]', '_', target_acc or 'default')
            token_env = f"COLAB_TOKEN_PATH='/root/.config/colab-cli/tokens/{target_acc}.json'" if target_acc and target_acc != 'default' else ""
            session_env = f"COLAB_SESSION_NAME='h3_warm_{safe_acc}' H3_STOP_ON_COMPLETE=0"
            seed_env = f"H3_SEED={seed}" if (seed is not None and str(seed) != "-1" and str(seed).strip()) else ""
            mode_env = f"H3_INFERENCE_MODE={mode}"
            lora_env = f"H3_LORA={lora}"
            dim_env = f"H3_DURATION_SECONDS={duration} H3_WIDTH={width} H3_HEIGHT={height} H3_REF_SIZE={ref_size}"
            if audio_path and ui_mode in ("audio_sync", "fasth3_omni"):
                dim_env += " H3_AUDIO_AS_REF=1"
            dim_env += (" H3_AI_UPSCALE=1" if (enable_upscale and str(upscale_target) == "AI_x2_deep") else " H3_AI_UPSCALE=0")
            cmd_args = f"{token_env} {session_env} {seed_env} {mode_env} {lora_env} {dim_env} python3 '{runner}' single"
            for img in images:
                cmd_args += f" --image '{wsl_path(img)}'"
            cmd_args += f" --prompt '{wsl_path(prompt_file)}' --output '{wsl_path(output_path)}' --gpu {gpu} --progress '{prog_wsl}' --timeout {timeout} --mode '{mode}' --lora '{lora}'"
            if audio_path:
                cmd_args += f" --audio '{wsl_path(audio_path)}'"
            if source_video and mode in ("char_swap", "v2v", "reference", "r2v", "ai_upscale"):
                cmd_args += f" --source-video '{wsl_path(source_video)}'"
            if director_pack and mode == "director":
                cmd_args += f" --pack '{wsl_path(director_pack)}'"
            if guides:
                try:
                    g_file = td / f"guides_{jid}.json"
                    g_list = [{**g, "path": wsl_path(str(g.get("path")))} for g in guides if g.get("path")]
                    g_file.write_text(json.dumps(g_list, ensure_ascii=False), encoding="utf-8")
                    cmd_args += f" --guides '{wsl_path(str(g_file))}'"
                except Exception as g_err:
                    print(f"[guides] {g_err}")
            return cmd_args

        active_jobs[jid].update({
            "status": "starting",
            "stage": "setup",
            "stage_label": "Bước 1/3: Đang khởi tạo máy ảo GPU & nạp mô hình MiniMax H3...",
            "progress": 15,
            "started_at": time.strftime("%H:%M:%S"),
            "start_time_ts": t_start,
            "start_cu": start_cu,
            "account_email": acc_email,
            "log": "Đang kết nối cụm máy chủ GPU & khởi tạo tiến trình..."
        })
        threading.Thread(target=_poll_prog, daemon=True).start()
        args = _build_wsl_args(acc_email)
        active_jobs[jid]["status"] = "running"
        code, out = run_wsl(args, timeout=timeout+120)

        # Tự động chuyển đổi dự phòng (Failover) sang tài khoản rảnh khác nếu tài khoản hiện tại bị từ chối cấp phát GPU / hết CU
        out_low = (out or "").lower()
        if code != 0 and any(k in out_low for k in ("allocation refused", "precondition failed", "0.00 compute units", "insufficient compute units", "quota")):
            fallback_acc = None
            with queue_lock:
                busy_other = set()
                for r_jid, r_accs in current_running_jobs.items():
                    if r_jid != jid:
                        busy_other.update(r_accs)
                for cand in get_eligible_accounts():
                    c_em = cand.get("email")
                    if c_em and c_em != acc_email and c_em not in busy_other:
                        fallback_acc = c_em
                        current_running_jobs[jid] = [fallback_acc]
                        break
            if fallback_acc:
                acc_email = fallback_acc
                active_jobs[jid].update({
                    "account_email": acc_email,
                    "stage_label": "🔄 Đang tự động chuyển sang luồng GPU dự phòng & khởi tạo...",
                    "log": (active_jobs[jid].get("log") or "") + "\n[Failover] Luồng GPU trước bận -> Tự động chuyển sang luồng GPU dự phòng..."
                })
                args = _build_wsl_args(acc_email)
                code, out2 = run_wsl(args, timeout=timeout+120)
                out = f"{out}\n\n--- [FAILOVER GPU] ---\n{out2}"
        
        t_end = time.time()
        elapsed_sec = int(t_end - t_start)
        elapsed_str = f"{elapsed_sec // 60} phút {elapsed_sec % 60} giây" if elapsed_sec >= 60 else f"{elapsed_sec} giây"
        
        is_ok = code == 0 and os.path.exists(output_path) and os.path.getsize(output_path) > 1000 and os.path.getmtime(output_path) >= t_start - 5
        final_video_path = output_path
        if is_ok:
            record_h3_video(
                output_path,
                duration=duration,
                seed=seed,
                prompt=prompt_text,
                reference_images=norm_single_refs,
                scene_id=scene_id,
                visual_style=visual_style,
                mode=mode,
                lora=lora,
                width=width,
                height=height,
                gpu=gpu,
                job_id=jid,
                gen_seconds=elapsed_sec,
            )
            try:
                _ofps = int(output_fps or 24)
            except Exception:
                _ofps = 24
            if _ofps > 24 or destutter:
                active_jobs[jid]["stage"] = "smoothing"
                active_jobs[jid]["stage_label"] = f"Bước 3.4: 🎞️ Làm mượt chuyển động ({'khử giật' if destutter else ''}{' + ' if destutter and _ofps > 24 else ''}{str(_ofps) + ' fps' if _ofps > 24 else ''})..."
                try:
                    sm_ok, sm_msg = smooth_video_post(output_path, target_fps=_ofps, destutter=bool(destutter))
                    out = f"{out}\n[Smooth] {sm_msg}"
                except Exception as _se:
                    out = f"{out}\n[Smooth] lỗi: {_se}"
            # Tất cả video tạo ra đều đã tự động chạy qua H3VideoUpsampler (AI Latent x2) trên Colab trước khi trả về.
            # Upscale 0 CU (Lanczos + NVENC 1080p/2K/4K) chỉ chạy thủ công khi bấm nút ⬆️ trong Thư Viện.
        schedule_idle_gpu_stop(480)
        # Số dư cuối phải lấy ĐÚNG tài khoản đã chạy job (trước đây lấy nhầm tài khoản đang chọn -> hiện sai ~120 CU)
        end_cu = _get_account_balance_fresh(acc_email)
        used_cu = round(start_cu - end_cu, 2) if (start_cu is not None and end_cu is not None and start_cu >= end_cu) else None
        if is_ok and (used_cu is None or used_cu <= 0) and elapsed_sec > 0:
            _cu_rate = 0.00158 if str(gpu or "A100").upper() == "A100" else (0.00048 if str(gpu or "").upper() == "L4" else 0.00033)
            used_cu = max(0.01, round(elapsed_sec * _cu_rate, 2))
        if is_ok and used_cu:
            record_h3_video(output_path, job_id=jid, gen_seconds=elapsed_sec, used_cu=used_cu)
            if final_video_path and final_video_path != output_path:
                record_h3_video(final_video_path, job_id=jid, gen_seconds=elapsed_sec, used_cu=used_cu)
        active_jobs[jid].update({
            "log": out,
            "status": "completed" if is_ok else "failed",
            "stage": "completed" if is_ok else "failed",
            "stage_label": "✅ Hoàn tất! Video đã qua H3VideoUpsampler (AI Latent x2) và sẵn sàng phát." if is_ok else "❌ Quá trình tạo video thất bại.",
            "finished_at": time.strftime("%H:%M:%S (%d/%m/%Y)"),
            "elapsed_seconds": elapsed_sec,
            "elapsed_str": elapsed_str,
            "progress": 100 if is_ok else 0,
            "start_cu": start_cu,
            "end_cu": end_cu,
            "used_cu": used_cu,
            "output": final_video_path,
            "video_url": f"/api/video?path={urllib.parse.quote(final_video_path)}" if is_ok else None,
            "error_diag": None if is_ok else diagnose_job_error(out)
        })
        threading.Thread(target=check_auth, daemon=True).start()

    with queue_lock:
        job_handlers[jid] = _execute
        job_queue.append(jid)

    if dispatch_now:
        _process_queue()
    st_after = active_jobs.get(jid, {})
    is_dispatched = st_after.get("status") in ("starting", "running")
    return {
        "job_id": jid,
        "dispatched": is_dispatched,
        "account_email": st_after.get("account_email"),
        "queue_pos": 0 if is_dispatched else st_after.get("queue_pos", q_pos),
    }

def run_batch_video(manifest_data, output_dir, gpu="A100", timeout=7200, seed=-1, enable_upscale=False, upscale_target="2K", multi_account=True, auto_merge_episode=False, episode_title="", episode_audio_path=None, chain_last_frame=True, final_output_path=None, chain_join=None, output_fps=0, destutter=False, seed_group=False, owner_user_id="guest", owner_username="guest"):
    jid = f"{'ep' if auto_merge_episode else ('seeds' if seed_group else 'batch')}_{uuid.uuid4().hex[:6]}"
    td = SCRIPT_DIR / "temp"
    td.mkdir(exist_ok=True)
    prog_file = td / f"prog_{jid}.json"
    
    raw_jobs = manifest_data.get("jobs", [])
    total = len(raw_jobs)
    use_chain = bool(chain_last_frame and total >= 2 and not seed_group)
    manifest_data["chain_last_frame"] = use_chain
    # Kiểu nối đoạn: last_frame | av (mồi 1.6s hình+tiếng) | video (mồi 1.6s hình) | cut (cảnh mới)
    _cj = str(chain_join or manifest_data.get("chain_join") or "last_frame").strip().lower()
    if _cj not in ("last_frame", "av", "video", "cut"):
        _cj = "last_frame"
    if episode_audio_path and _cj in ("av", "video"):
        _cj = "last_frame"  # audio tổng đã căn thời gian → không chèn phần mồi làm lệch tiếng
    if not use_chain and _cj != "cut":
        _cj = "last_frame"
    manifest_data["chain_join"] = _cj

    # Chuẩn hóa & lưu vết hồ sơ Ảnh Tham Chiếu + Prompt cho từng clip trong batch/storyboard
    job_meta_by_id = {}
    job_meta_by_idx = {}
    batch_all_refs = []
    seen_ref_paths = set()
    for idx_j, jb in enumerate(raw_jobs):
        c_refs = normalize_ref_image_items(jb.get("ref_items") or jb.get("picture_bindings") or jb.get("reference_images") or [])
        jb["ref_items"] = c_refs
        for ri in c_refs:
            rk = ri.get("path") or ri.get("name")
            if rk and rk not in seen_ref_paths:
                seen_ref_paths.add(rk)
                batch_all_refs.append(ri)
        raw_sv = jb.get("source_video")
        _jb_ui = str(jb.get("ui_mode") or "").strip().lower()
        if not raw_sv and (not _jb_ui or _jb_ui == "cam_previs") and "<Video 1>" in str(jb.get("prompt") or ""):
            latest_cam = _find_latest_cam01_previs_mp4()
            if latest_cam:
                raw_sv = wsl_path(latest_cam)
                jb["source_video"] = raw_sv
        sv_win = win_path(str(raw_sv)) if raw_sv else None
        meta_entry = {
            "id": jb.get("id") or f"clip_{idx_j+1:02d}",
            "scene_id": jb.get("scene_id") or (jb.get("id") if re.match(r"^E\d{2}S\d{3}$", str(jb.get("id") or ""), re.I) else ""),
            "title": jb.get("title") or f"Clip {idx_j+1:02d}",
            "prompt": jb.get("prompt") or "",
            "visual_style": jb.get("visual_style") or "",
            "ref_items": c_refs,
            "source_video": sv_win.replace("\\", "/") if sv_win else None,
            "mode": jb.get("mode") or "reference",
            "lora": jb.get("lora") or "pdmd",
            "duration": jb.get("duration_seconds") or 15,
            "width": jb.get("width") or 1376,
            "height": jb.get("height") or 768,
            "seed": jb.get("seed") if jb.get("seed") is not None else seed,
            "ui_mode": jb.get("ui_mode") or "",
            "audio_file": jb.get("audio_file") or "",
            "audio_as_ref": bool(jb.get("audio_as_ref")),
            "guides": jb.get("guides") or [],
            "ref_size": jb.get("ref_size") or "match",
            "trim_to": float(jb.get("trim_to") or 0),
        }
        job_meta_by_id[str(meta_entry["id"])] = meta_entry
        job_meta_by_idx[idx_j] = meta_entry

    m_file = td / f"manifest_{jid}.json"
    m_file.write_text(json.dumps(manifest_data, ensure_ascii=False, indent=2), encoding="utf-8")

    clean_out = str(final_output_path or output_dir).replace("\\", "/")
    
    eligible = get_eligible_accounts()
    # Khi bật nối khít khung hình cuối (use_chain) hoặc chỉ có 1 video (total == 1), chỉ dùng 1 tài khoản rảnh
    is_multi_parallel = (multi_account and total >= 2 and len(eligible) >= 2 and not use_chain)
    worker_accounts_list = [a["email"] for a in eligible] if is_multi_parallel else ([eligible[0]["email"]] if eligible else ([auth_state.get("email")] if auth_state.get("email") else []))

    first_meta = job_meta_by_idx.get(0) or {}
    init_refs = (first_meta.get("ref_items") if total == 1 else batch_all_refs[:18]) or batch_all_refs[:18]
    first_sv = first_meta.get("source_video")

    with queue_lock:
        q_pos = len(job_queue) + 1 if current_running_jobs else 1
        active_jobs[jid] = {
            "id": jid,
            "scene_id": first_meta.get("scene_id") or "",
            "title": first_meta.get("title") or episode_title or jid,
            "status": "queued",
            "stage": "queued",
            "queue_pos": q_pos,
            "stage_label": f"⏳ Đang chờ trong hàng đợi (Thứ tự #{q_pos})...",
            "output": clean_out,
            "gpu": gpu,
            "mode": first_meta.get("mode") or "reference",
            "lora": first_meta.get("lora") or "pdmd",
            "duration": first_meta.get("duration") or 15,
            "has_source_video": bool(first_sv),
            "source_video": first_sv,
            "source_video_name": Path(first_sv).name if first_sv else None,
            "source_video_url": f"/api/video?path={urllib.parse.quote(str(first_sv))}" if first_sv else None,
            "seed": seed if (seed is not None and str(seed) != "-1" and str(seed).strip()) else "Khóa đồng nhất",
            "enable_upscale": bool(enable_upscale),
            "upscale_target": upscale_target,
            "total_jobs": total,
            "is_episode": bool(auto_merge_episode),
            "chain_last_frame": bool(chain_last_frame),
            "chain_join": _cj,
            "seed_group": bool(seed_group),
            "output_fps": int(output_fps or 0),
            "destutter": bool(destutter),
            "episode_audio_path": str(episode_audio_path) if episode_audio_path else "",
            "output_dir": str(output_dir),
            "episode_title": episode_title or "Tap_Phim_H3",
            "worker_mode": "multi_parallel" if is_multi_parallel else "single_chained" if use_chain else "single",
            "worker_count": len(worker_accounts_list),
            "worker_accounts": worker_accounts_list,
            "account_email": worker_accounts_list[0] if worker_accounts_list else (auth_state.get("email") or ""),
            "started_at": time.strftime("%H:%M:%S"),
            "log": (
                f"Khởi tạo dây chuyền Auto Cắt Frame Cuối + Ref cảnh tiếp theo ({total} phân đoạn liên hoàn)..."
                if use_chain else (
                    f"Khởi tạo cụm {len(worker_accounts_list)} tài khoản GPU chạy song song cho {total} phân đoạn..."
                    if is_multi_parallel else f"Khởi tạo hàng đợi {total} phân đoạn trên 1 máy chủ GPU..."
                )
            ),
            "progress": 0,
            "videos": [],
            "video_url": None,
            "prompt": first_meta.get("prompt") or "",
            "visual_style": first_meta.get("visual_style") or "",
            "reference_images": init_refs,
            "ref_items": batch_all_refs[:18],
            "job_items_meta": list(job_meta_by_idx.values()),
            "prompts": [j.get("prompt") for j in raw_jobs],
            "owner_user_id": owner_user_id or "guest",
            "owner_username": owner_username or "guest",
            "error_diag": None
        }

    def _execute(allocated_workers=None):
        t_start = time.time()
        start_cu = auth_state.get("balance")

        # Chuẩn hóa danh sách workers được cấp phát (loại bỏ tài khoản đang bận ở job khác)
        workers_to_use = []
        if isinstance(allocated_workers, list):
            workers_to_use = [w for w in allocated_workers if w]
        elif isinstance(allocated_workers, str):
            workers_to_use = [allocated_workers]
        if not workers_to_use:
            with queue_lock:
                busy_other = set()
                for r_jid, r_accs in current_running_jobs.items():
                    if r_jid != jid:
                        busy_other.update(r_accs)
            free_cands = [em for em in worker_accounts_list if em not in busy_other]
            workers_to_use = free_cands or worker_accounts_list or [auth_state.get("email") or "default"]

        is_parallel_run = multi_account and total >= 2 and len(workers_to_use) >= 2 and not use_chain

        # Số dư CU ban đầu = tổng số dư của đúng các tài khoản chạy job này (không dùng tài khoản đang chọn toàn cục)
        cu_accounts = list(workers_to_use) if is_parallel_run else list(workers_to_use[:1])
        _cu_vals = [_get_account_balance(em) for em in cu_accounts]
        _cu_per_acc = bool(_cu_vals) and all(v is not None for v in _cu_vals)
        if _cu_per_acc:
            start_cu = round(sum(float(v) for v in _cu_vals), 2)

        active_jobs[jid].update({
            "status": "starting",
            "stage": "setup",
            "stage_label": (
                f"Bước 1/3: Khởi tạo cụm {len(workers_to_use)} luồng GPU song song ({total} phân đoạn)..."
                if is_parallel_run else (
                    f"Bước 1/3: Khởi tạo phiên GPU nối khít hậu cảnh ({total} phân đoạn)..."
                    if use_chain else f"Bước 1/3: Khởi tạo phiên GPU ({total} phân đoạn)..."
                )
            ),
            "progress": 10,
            "started_at": time.strftime("%H:%M:%S"),
            "start_time_ts": t_start,
            "start_cu": start_cu,
            "account_email": workers_to_use[0] if workers_to_use else "",
            "worker_count": 1 if not is_parallel_run else len(workers_to_use),
            "worker_accounts": workers_to_use[:1] if not is_parallel_run else workers_to_use
        })

        runner = wsl_path(str(SCRIPT_DIR / "scripts" / "runner.py"))
        done_vids = []

        if is_parallel_run:
            # === CHẾ ĐỘ ĐA TÀI KHOẢN CHẠY SONG SONG (WORKER POOL ĐỘNG) ===
            scene_queue = queue.Queue()
            for idx, job_item in enumerate(raw_jobs):
                scene_queue.put((idx, job_item))

            completed_lock = threading.Lock()
            worker_states = {em: {"status": "idle", "current_clip": None, "done_count": 0} for em in workers_to_use}
            active_jobs[jid]["status"] = "running"

            def _scene_worker(acc_email):
                safe_acc = re.sub(r'[^a-zA-Z0-9_]', '_', acc_email)
                token_env = f"COLAB_TOKEN_PATH='/root/.config/colab-cli/tokens/{acc_email}.json'"
                session_env = f"COLAB_SESSION_NAME='h3_warm_{safe_acc}' H3_STOP_ON_COMPLETE=0"

                while True:
                    try:
                        idx, clip_job = scene_queue.get_nowait()
                    except queue.Empty:
                        break

                    clip_id = clip_job.get("id", f"clip_{idx+1:02d}")
                    clip_title = clip_job.get("title", f"Clip {idx+1:02d}")
                    c_meta = job_meta_by_id.get(str(clip_id)) or job_meta_by_idx.get(idx) or {}
                    worker_states[acc_email]["status"] = "generating"
                    worker_states[acc_email]["current_clip"] = clip_title

                    with completed_lock:
                        done_cnt = len(done_vids)
                        active_jobs[jid]["progress"] = int(10 + (done_cnt / max(1, total)) * 85)
                        worker_status_str = " | ".join([
                            f"{st.get('current_clip') or 'Đang xử lý'}"
                            for em, st in worker_states.items() if st.get('status') == 'generating'
                        ])
                        active_jobs[jid]["stage_label"] = f"🎬 Đang render ({done_cnt}/{total} xong)" + (f" &mdash; {worker_status_str}" if worker_status_str else "")

                    pf_clip = td / f"p_{jid}_{clip_id}.txt"
                    pf_clip.write_text(clip_job.get("prompt", ""), encoding="utf-8")
                    clip_prog = td / f"prog_{jid}_{clip_id}.json"
                    clip_out_name = clip_job.get("output_name", clip_id)
                    clip_out = Path(output_dir) / f"{clip_out_name}.mp4"

                    c_mode = clip_job.get("mode", "reference")
                    mode_env = f"H3_INFERENCE_MODE={c_mode}"
                    lora_env = f"H3_LORA={clip_job.get('lora', 'pdmd')}"
                    seed_val = clip_job.get("seed", -1)
                    seed_env = f"H3_SEED={seed_val}" if seed_val != -1 else ""
                    dim_env = f"H3_DURATION_SECONDS={clip_job.get('duration_seconds', 15)} H3_WIDTH={clip_job.get('width', 576)} H3_HEIGHT={clip_job.get('height', 1024)} H3_REF_SIZE=max H3_AI_UPSCALE=0"
                    clip_timeout = 3600  # base gen + bắt buộc H3VideoUpsampler 2K trên Colab

                    cmd = f"{token_env} {session_env} {seed_env} {mode_env} {lora_env} {dim_env} python3 '{runner}' single"
                    for img in clip_job.get("reference_images", []):
                        cmd += f" --image '{img}'"
                    cmd += f" --prompt '{wsl_path(str(pf_clip))}' --output '{wsl_path(str(clip_out))}' --gpu {gpu} --progress '{wsl_path(str(clip_prog))}' --timeout {clip_timeout} --mode '{c_mode}' --lora '{clip_job.get('lora', 'pdmd')}'"
                    if clip_job.get("director_pack"):
                        cmd += f" --pack '{clip_job['director_pack']}'"
                    if clip_job.get("source_video"):
                        cmd += f" --source-video '{clip_job['source_video']}'"
                    if clip_job.get("audio_file") or clip_job.get("audio"):
                        cmd += f" --audio '{clip_job.get('audio_file') or clip_job.get('audio')}'"

                    clip_t0 = time.time()
                    code, out = run_wsl(cmd, timeout=clip_timeout+180)

                    wp_out = str(clip_out)
                    is_clip_ok = code == 0 and os.path.exists(wp_out) and os.path.getsize(wp_out) > 1000

                    if is_clip_ok:
                        record_h3_video(
                            wp_out,
                            title=clip_title,
                            duration=c_meta.get("duration"),
                            seed=c_meta.get("seed"),
                            prompt=c_meta.get("prompt"),
                            reference_images=c_meta.get("ref_items"),
                            scene_id=c_meta.get("scene_id"),
                            visual_style=c_meta.get("visual_style"),
                            mode=c_meta.get("mode"),
                            lora=c_meta.get("lora"),
                            width=c_meta.get("width"),
                            height=c_meta.get("height"),
                            gpu=gpu,
                            job_id=jid,
                            gen_seconds=int(time.time() - clip_t0),
                        )
                        final_wp = wp_out
                        mtime = os.path.getmtime(final_wp)
                        vid_item = {
                            "id": clip_id,
                            "scene_id": c_meta.get("scene_id") or "",
                            "order_idx": idx,
                            "title": clip_title,
                            "path": final_wp.replace("\\", "/"),
                            "url": f"/api/video?path={urllib.parse.quote(final_wp)}",
                            "completed_at": time.strftime("%H:%M:%S", time.localtime(mtime)),
                            "size_mb": round(os.path.getsize(final_wp) / (1024 * 1024), 2),
                            "rendered_by": acc_email,
                            "prompt": c_meta.get("prompt") or "",
                            "visual_style": c_meta.get("visual_style") or "",
                            "reference_images": c_meta.get("ref_items") or [],
                            "mode": c_meta.get("mode") or "reference",
                            "lora": c_meta.get("lora") or "pdmd",
                            "duration": c_meta.get("duration") or 15,
                            "seed": c_meta.get("seed"),
                        }
                        with completed_lock:
                            done_vids.append(vid_item)
                            done_vids.sort(key=lambda x: x.get("order_idx", 999))
                            active_jobs[jid]["videos"] = list(done_vids)
                            active_jobs[jid]["video_url"] = vid_item["url"]
                            worker_states[acc_email]["done_count"] += 1
                            worker_states[acc_email]["status"] = "idle"
                            worker_states[acc_email]["current_clip"] = None
                    else:
                        lt = out.lower()
                        if (
                            "0.00 compute units" in lt
                            or "insufficient compute units" in lt
                            or "invalid_grant" in lt
                            or "allocation refused" in lt
                            or "precondition failed" in lt
                        ):
                            scene_queue.put((idx, clip_job))
                            worker_states[acc_email]["status"] = "exhausted"
                            if "0.00 compute units" in lt or "insufficient compute units" in lt:
                                for a in auth_state.get("accounts", []):
                                    if a.get("email") == acc_email:
                                        a["balance"] = 0.0
                            break
                        else:
                            worker_states[acc_email]["status"] = "idle"
                            worker_states[acc_email]["current_clip"] = None

            threads = [threading.Thread(target=_scene_worker, args=(em,), daemon=True) for em in workers_to_use]
            for t in threads: t.start()
            for t in threads: t.join()
            out = f"Hoàn tất xử lý cụm đa tài khoản ({len(done_vids)}/{total} phân đoạn)."
            code = 0 if len(done_vids) > 0 else -1

        else:
            # === CHẾ ĐỘ ĐƠN TÀI KHOẢN (TUẦN TỰ & KHÓA FRAME CUỐI LIÊN HOÀN + TỰ ĐỘNG XOAY VÒNG KHI TÀI KHOẢN ĐẦU BẬN/HẾT PHIÊN) ===
            candidate_accounts = []
            for acc_em in (workers_to_use or []) + [a.get("email") for a in eligible if a.get("email")]:
                if acc_em and acc_em not in candidate_accounts:
                    candidate_accounts.append(acc_em)
            if not candidate_accounts:
                candidate_accounts = [auth_state.get("email") or "default"]
            single_acc = candidate_accounts[0]

            def _sync_chained_meta(p_idx, jp):
                c_meta = job_meta_by_id.get(str(jp.get("id"))) or job_meta_by_idx.get(p_idx) or {}
                if not c_meta:
                    return c_meta
                lf_raw = jp.get("chained_last_frame")
                if lf_raw:
                    lf_win = Path(win_path(str(lf_raw)))
                    if lf_win.is_file():
                        existing_refs = list(c_meta.get("ref_items") or [])
                        if not any(Path(str(r.get("path") or r.get("filename") or "")).name == lf_win.name for r in existing_refs):
                            if len(existing_refs) >= 9:
                                existing_refs = existing_refs[:8]
                            new_idx = len(existing_refs) + 1
                            lf_item = {
                                "index": new_idx,
                                "tag": f"<Picture {new_idx}>",
                                "filename": lf_win.name,
                                "short_name": lf_win.stem,
                                "role_vi": "🎞️ Frame cuối cảnh trước",
                                "path": str(lf_win).replace("\\", "/"),
                                "url": f"/api/local-image?path={urllib.parse.quote(str(lf_win).replace(chr(92), '/'))}",
                                "is_last_frame": True,
                            }
                            existing_refs.append(lf_item)
                            c_meta["ref_items"] = existing_refs
                            if lf_win.name not in seen_ref_paths:
                                seen_ref_paths.add(lf_win.name)
                                batch_all_refs.append(lf_item)
                                active_jobs[jid]["ref_items"] = batch_all_refs[:18]
                                active_jobs[jid]["reference_images"] = batch_all_refs[:18]
                if jp.get("updated_prompt"):
                    c_meta["prompt"] = jp["updated_prompt"]
                active_jobs[jid]["job_items_meta"] = list(job_meta_by_idx.values())
                return c_meta

            def _poll_prog():
                while active_jobs.get(jid, {}).get("status") in ("starting", "running"):
                    time.sleep(2)
                    if prog_file.exists():
                        try:
                            pdata = json.loads(prog_file.read_text(encoding="utf-8"))
                            jobs_p = pdata.get("jobs", [])
                            for p_idx, jp in enumerate(jobs_p):
                                _sync_chained_meta(p_idx, jp)
                            completed = sum(1 for j in jobs_p if j.get("status") == "completed")
                            current = next((j for j in jobs_p if j.get("status") in ("generating", "downloading", "uploading")), None)
                            if current:
                                cur_st = current.get("status")
                                active_jobs[jid]["stage"] = cur_st
                                chain_tag = " [🎞️ Auto Frame Cuối + Ref]" if (use_chain and completed >= 1) else ""
                                lbl = f"Đang vẽ đoạn ({completed+1}/{total}){chain_tag}: {current.get('title')}..." if cur_st == 'generating' else f"Đang tải đoạn {current.get('title')}..."
                                active_jobs[jid]["stage_label"] = f"Bước 2/3: {lbl}"
                                active_jobs[jid]["progress"] = int(20 + (completed / max(1, total)) * 75)
                            
                            d_vids = []
                            for p_idx, jp in enumerate(jobs_p):
                                if jp.get("status") == "completed":
                                    wp = win_path(jp.get("output", ""))
                                    if os.path.exists(wp) and os.path.getsize(wp) > 1000 and os.path.getmtime(wp) >= t_start - 5:
                                        mtime = os.path.getmtime(wp)
                                        c_meta = _sync_chained_meta(p_idx, jp)
                                        record_h3_video(
                                            wp,
                                            title=jp.get("title"),
                                            duration=c_meta.get("duration"),
                                            seed=c_meta.get("seed"),
                                            prompt=c_meta.get("prompt"),
                                            reference_images=c_meta.get("ref_items"),
                                            scene_id=c_meta.get("scene_id"),
                                            visual_style=c_meta.get("visual_style"),
                                            mode=c_meta.get("mode"),
                                            lora=c_meta.get("lora"),
                                            width=c_meta.get("width"),
                                            height=c_meta.get("height"),
                                            gpu=gpu,
                                            job_id=jid,
                                        )
                                        d_vids.append({
                                            "id": jp.get("id"),
                                            "scene_id": c_meta.get("scene_id") or "",
                                            "order_idx": p_idx,
                                            "title": jp.get("title"),
                                            "path": wp.replace("\\", "/"),
                                            "url": f"/api/video?path={urllib.parse.quote(wp)}",
                                            "completed_at": time.strftime("%H:%M:%S", time.localtime(mtime)),
                                            "size_mb": round(os.path.getsize(wp) / (1024 * 1024), 2),
                                            "rendered_by": single_acc,
                                            "prompt": c_meta.get("prompt") or "",
                                            "visual_style": c_meta.get("visual_style") or "",
                                            "reference_images": c_meta.get("ref_items") or [],
                                            "mode": c_meta.get("mode") or "reference",
                                            "lora": c_meta.get("lora") or "pdmd",
                                            "duration": c_meta.get("duration") or 15,
                                            "seed": c_meta.get("seed"),
                                        })
                            if d_vids:
                                active_jobs[jid]["videos"] = d_vids
                                active_jobs[jid]["video_url"] = d_vids[-1]["url"]
                        except Exception:
                            pass

            threading.Thread(target=_poll_prog, daemon=True).start()
            prog_wsl = wsl_path(str(prog_file))
            active_jobs[jid]["status"] = "running"
            code, out = -1, ""
            for acc_try_idx, cand_acc in enumerate(candidate_accounts):
                single_acc = cand_acc
                safe_acc = re.sub(r'[^a-zA-Z0-9_]', '_', single_acc)
                token_env = f"COLAB_TOKEN_PATH='/root/.config/colab-cli/tokens/{single_acc}.json'" if single_acc and single_acc != 'default' else ""
                session_env = f"COLAB_SESSION_NAME='h3_warm_{safe_acc}' H3_STOP_ON_COMPLETE=0"
                active_jobs[jid]["account_email"] = single_acc
                active_jobs[jid]["worker_accounts"] = [single_acc]
                if acc_try_idx > 0:
                    active_jobs[jid]["stage_label"] = f"🔄 Đang tự động chuyển sang luồng GPU dự phòng ({acc_try_idx+1}/{len(candidate_accounts)})..."
                args = f"{token_env} {session_env} python3 '{runner}' batch --manifest '{wsl_path(str(m_file))}' --output-dir '{wsl_path(output_dir)}' --gpu {gpu} --progress '{prog_wsl}' --timeout {timeout}"
                code, out = run_wsl(args, timeout=timeout+300)
                if code == 0:
                    break
                lt_err = (out or "").lower()
                if prog_file.exists():
                    try:
                        lt_err += " " + prog_file.read_text(encoding="utf-8", errors="ignore").lower()
                    except Exception:
                        pass
                if (
                    "allocation refused" in lt_err
                    or "precondition failed" in lt_err
                    or "0.00 compute units" in lt_err
                    or "insufficient compute units" in lt_err
                    or "invalid_grant" in lt_err
                ) and acc_try_idx + 1 < len(candidate_accounts):
                    continue
                break

            if prog_file.exists():
                try:
                    pdata = json.loads(prog_file.read_text(encoding="utf-8"))
                    for p_idx, jp in enumerate(pdata.get("jobs", [])):
                        c_meta = _sync_chained_meta(p_idx, jp)
                        if jp.get("status") == "completed":
                            wp = win_path(jp.get("output", ""))
                            if os.path.exists(wp) and os.path.getsize(wp) > 1000 and os.path.getmtime(wp) >= t_start - 5:
                                mtime = os.path.getmtime(wp)
                                done_vids.append({
                                    "id": jp.get("id"),
                                    "scene_id": c_meta.get("scene_id") or "",
                                    "order_idx": p_idx,
                                    "title": jp.get("title"),
                                    "path": wp.replace("\\", "/"),
                                    "url": f"/api/video?path={urllib.parse.quote(wp)}",
                                    "completed_at": time.strftime("%H:%M:%S", time.localtime(mtime)),
                                    "size_mb": round(os.path.getsize(wp) / (1024 * 1024), 2),
                                    "rendered_by": single_acc,
                                    "prompt": c_meta.get("prompt") or "",
                                    "visual_style": c_meta.get("visual_style") or "",
                                    "reference_images": c_meta.get("ref_items") or [],
                                    "mode": c_meta.get("mode") or "reference",
                                    "lora": c_meta.get("lora") or "pdmd",
                                    "duration": c_meta.get("duration") or 15,
                                    "seed": c_meta.get("seed"),
                                })
                except Exception:
                    pass

        done_vids.sort(key=lambda x: x.get("order_idx", 999))
        is_ok = len(done_vids) > 0
        if is_ok:
            if not is_parallel_run:
                for dv in done_vids:
                    record_h3_video(
                        dv.get("path"),
                        title=dv.get("title"),
                        duration=dv.get("duration"),
                        seed=dv.get("seed"),
                        prompt=dv.get("prompt"),
                        reference_images=dv.get("reference_images"),
                        scene_id=dv.get("scene_id"),
                        visual_style=dv.get("visual_style"),
                        mode=dv.get("mode"),
                        lora=dv.get("lora"),
                        gpu=gpu,
                        job_id=jid,
                    )
            # Mọi phân đoạn đã tự động chạy qua H3VideoUpsampler (AI Latent x2) trên Colab trước khi tải về.

            # Làm mượt từng clip khi KHÔNG ghép (khi ghép sẽ làm mượt bản ghép để nội suy qua cả mối nối)
            _ofps = int(output_fps or 0)
            if (_ofps > 24 or destutter) and not seed_group and not is_parallel_run and not auto_merge_episode:
                active_jobs[jid]["stage"] = "smoothing"
                active_jobs[jid]["stage_label"] = f"🎞️ Đang làm mượt {len(done_vids)} phân đoạn..."
                for dv in done_vids:
                    try:
                        if dv.get("path") and os.path.exists(dv["path"]):
                            smooth_video_post(dv["path"], _ofps, bool(destutter))
                    except Exception as _se:
                        print(f"[smooth] {_se}")

            # === TỰ ĐỘNG GHÉP MASTER VIDEO DÀI LIỀN MẠCH (AUTO-MASTER) ===
            if auto_merge_episode and len(done_vids) >= 1:
                active_jobs[jid]["stage"] = "merging_episode"
                active_jobs[jid]["stage_label"] = f"🎞️ Bước cuối: Đang ghép khít chuyển động {len(done_vids)} đoạn thành 1 Video Hoàn Chỉnh..."
                _dvs_ok = [dv for dv in done_vids if dv.get("path") and os.path.exists(dv["path"])]
                seq_paths = [dv["path"] for dv in _dvs_ok]
                is_v2v_or_audio_timed = bool(episode_audio_path)
                _cj_now = active_jobs[jid].get("chain_join") or _cj
                _head_trims = None
                if _cj_now in ("av", "video") and not is_v2v_or_audio_timed:
                    # Bỏ 39 frame mồi (1.625s) mang từ đoạn trước ở đầu mỗi đoạn tiếp theo
                    _head_trims = [0.0 if (k == 0 or int(dv.get("order_idx", k)) == 0) else 39 / 24.0 for k, dv in enumerate(_dvs_ok)]
                if len(seq_paths) >= 2 or episode_audio_path:
                    merged_p, merge_msg = merge_videos_ffmpeg(
                        seq_paths,
                        episode_audio_path,
                        trim_chained_frame=bool(use_chain and not is_v2v_or_audio_timed and _cj_now == "last_frame"),
                        head_trims=_head_trims,
                        clip_durations=([float((job_meta_by_idx.get(int(dv.get("order_idx", -1))) or {}).get("trim_to") or 0) for dv in _dvs_ok] if is_v2v_or_audio_timed else None),
                    )
                elif len(seq_paths) == 1:
                    merged_p, merge_msg = seq_paths[0], "Hoàn tất 1 phân đoạn"
                else:
                    merged_p, merge_msg = None, ""
                if merged_p and os.path.exists(merged_p) and (_ofps > 24 or destutter) and len(seq_paths) >= 2:
                    active_jobs[jid]["stage_label"] = f"🎞️ Đang làm mượt video ghép ({_ofps or 24}fps)..."
                    try:
                        smooth_video_post(merged_p, _ofps, bool(destutter))
                    except Exception as _se:
                        print(f"[smooth merged] {_se}")

                if merged_p and os.path.exists(merged_p):
                    if final_output_path:
                        final_ep_file = Path(final_output_path)
                        final_ep_file.parent.mkdir(parents=True, exist_ok=True)
                    else:
                        safe_ep = re.sub(r'[^a-zA-Z0-9_-]', '_', (episode_title or "Video_Dai_H3").strip())[:40] or "Video_Dai_H3"
                        final_ep_file = Path(output_dir) / f"Full_{safe_ep}_{int(time.time())}.mp4"
                    try:
                        if os.path.abspath(merged_p) != os.path.abspath(str(final_ep_file)):
                            shutil.copy2(merged_p, str(final_ep_file))
                        else:
                            final_ep_file = Path(merged_p)
                    except Exception:
                        final_ep_file = Path(merged_p)

                    ep_wp = str(final_ep_file)
                    ep_lbl = f"🎬 [VIDEO GHÉP HOÀN CHỈNH] {episode_title or final_ep_file.stem}"
                    merged_prompt_summary = "\n\n---\n\n".join(
                        f"[{dv.get('title') or dv.get('id')}]\n{dv.get('prompt') or ''}" for dv in done_vids if not dv.get("is_master_episode")
                    )
                    record_h3_video(
                        ep_wp,
                        title=ep_lbl,
                        duration=sum(float(dv.get("duration") or 15) for dv in done_vids if not dv.get("is_master_episode")),
                        seed=seed,
                        prompt=merged_prompt_summary,
                        reference_images=batch_all_refs[:18],
                        mode="reference",
                        lora="pdmd",
                        gpu=gpu,
                        job_id=jid,
                        gen_seconds=int(time.time() - t_start),
                    )
                    mtime = os.path.getmtime(ep_wp)
                    master_item = {
                        "id": "master_episode",
                        "order_idx": -1,
                        "is_master_episode": True,
                        "title": ep_lbl,
                        "path": ep_wp.replace("\\", "/"),
                        "url": f"/api/video?path={urllib.parse.quote(ep_wp)}",
                        "completed_at": time.strftime("%H:%M:%S", time.localtime(mtime)),
                        "size_mb": round(os.path.getsize(ep_wp) / (1024 * 1024), 2),
                        "rendered_by": "FFmpeg Seamless Master",
                        "prompt": merged_prompt_summary,
                        "reference_images": batch_all_refs[:18],
                    }
                    done_vids.insert(0, master_item)
                    active_jobs[jid]["master_episode"] = master_item
                    active_jobs[jid]["output"] = ep_wp.replace("\\", "/")

        t_end = time.time()
        elapsed_sec = int(t_end - t_start)
        elapsed_str = f"{elapsed_sec // 60} phút {elapsed_sec % 60} giây" if elapsed_sec >= 60 else f"{elapsed_sec} giây"
        try:
            check_auth(refresh_all=True)
        except Exception:
            pass
        _end_vals = [_get_account_balance(em) for em in cu_accounts]
        end_cu = round(sum(float(v) for v in _end_vals), 2) if (_cu_per_acc and _end_vals and all(v is not None for v in _end_vals)) else None
        used_cu = round(start_cu - end_cu, 2) if (start_cu is not None and end_cu is not None and start_cu >= end_cu) else None
        if is_ok and (used_cu is None or used_cu <= 0) and elapsed_sec > 0:
            _cu_rate = 0.00158 if str(gpu or "A100").upper() == "A100" else (0.00048 if str(gpu or "").upper() == "L4" else 0.00033)
            used_cu = max(0.01, round(elapsed_sec * _cu_rate, 2))
        if is_ok and used_cu and done_vids:
            _clip_vids = [dv for dv in done_vids if not dv.get("is_master_episode")]
            _per_clip_cu = max(0.01, round(used_cu / max(1, len(_clip_vids)), 2))
            for dv in done_vids:
                dv_path = dv.get("path")
                if dv_path:
                    record_h3_video(dv_path, job_id=jid, used_cu=used_cu if dv.get("is_master_episode") else _per_clip_cu)
        avg_time = f"~{elapsed_sec // max(1, len(done_vids)) // 60}p {elapsed_sec // max(1, len(done_vids)) % 60}s" if done_vids else None

        if auto_merge_episode and is_ok:
            summary_label = f"🎉 Đã ghép hoàn chỉnh ({episode_title or 'Full Video'}) từ {total} phân đoạn nối khít hậu cảnh!"
        elif is_ok and is_parallel_run:
            summary_label = f"✅ Hoàn tất mẻ chạy ({len(done_vids)}/{total} video sẵn sàng) qua cụm {len(workers_to_use)} tài khoản song song!"
        elif is_ok:
            summary_label = f"✅ Hoàn tất mẻ chạy ({len(done_vids)}/{total} video sẵn sàng)!"
        else:
            summary_label = "❌ Quá trình chạy hàng loạt gặp lỗi."

        active_jobs[jid].update({
            "log": out,
            "status": "completed" if is_ok else "failed",
            "stage": "completed" if is_ok else "failed",
            "stage_label": summary_label,
            "finished_at": time.strftime("%H:%M:%S (%d/%m/%Y)"),
            "elapsed_seconds": elapsed_sec,
            "elapsed_str": elapsed_str,
            "avg_time_per_video": avg_time,
            "progress": 100 if is_ok else 0,
            "start_cu": start_cu,
            "end_cu": end_cu,
            "used_cu": used_cu,
            "videos": done_vids,
            "video_url": done_vids[0]["url"] if done_vids else None,
            "error_diag": None if is_ok else diagnose_job_error(out)
        })
        threading.Thread(target=check_auth, daemon=True).start()

    with queue_lock:
        job_handlers[jid] = _execute
        job_queue.append(jid)

    _process_queue()
    st_after = active_jobs.get(jid, {})
    is_dispatched = st_after.get("status") in ("starting", "running")
    return {
        "job_id": jid,
        "dispatched": is_dispatched,
        "account_email": st_after.get("account_email"),
        "worker_accounts": st_after.get("worker_accounts", []),
        "queue_pos": 0 if is_dispatched else st_after.get("queue_pos", q_pos),
        "total_jobs": total,
    }


