M2MR_DIR = Path(r"D:\Motion2MixamoRig-main")


def get_m2mr_status() -> dict:
    """Kiểm tra trạng thái thư mục D:\Motion2MixamoRig-main, các file rig .fbx, SMPL-X và các video chuyển động đã render."""
    exists = M2MR_DIR.is_dir()
    smplx_path = M2MR_DIR / "assets" / "body_models" / "smplx" / "SMPLX_NEUTRAL.npz"
    mixamo_dir = M2MR_DIR / "assets" / "mixamo"
    venv_py = M2MR_DIR / ".venv" / "Scripts" / "python.exe"
    outputs_dir = M2MR_DIR / "outputs"

    rigs = []
    if mixamo_dir.is_dir():
        for f in sorted(mixamo_dir.glob("*.fbx")):
            is_bin = False
            try:
                with open(f, "rb") as fh:
                    is_bin = fh.read(18) == b"Kaydara FBX Binary"
            except Exception:
                pass
            rigs.append({
                "name": f.name,
                "path": str(f).replace("\\", "/"),
                "valid_binary": is_bin,
                "size_mb": round(f.stat().st_size / (1024 * 1024), 2),
            })

    motion_clips = []
    if outputs_dir.is_dir():
        for run_d in sorted(outputs_dir.glob("*"), key=lambda p: p.stat().st_mtime if p.exists() else 0, reverse=True)[:24]:
            if not run_d.is_dir():
                continue
            vid_dir = run_d / "videos"
            glb_f = run_d / "mixamo_character.glb"
            skel_f = run_d / "skeleton_motion.npz"
            for vname, vlabel in (
                ("human_skeleton.mp4", "Khung xương 3D"),
                ("side_by_side.mp4", "Gốc | Khung xương 3D"),
                ("mixamo_character.mp4", "Nhân vật 3D Mannequin"),
                ("compare.mp4", "So sánh 2x2"),
            ):
                vf = vid_dir / vname
                if vf.is_file() and vf.stat().st_size > 1000:
                    motion_clips.append({
                        "label": f"🦴 [{run_d.name}] {vlabel}",
                        "path": str(vf).replace("\\", "/"),
                        "type": vname.replace(".mp4", ""),
                        "glb": str(glb_f).replace("\\", "/") if glb_f.is_file() else None,
                        "skeleton_npz": str(skel_f).replace("\\", "/") if skel_f.is_file() else None,
                    })

    # Đặt demo.mp4 ở cuối danh sách để video mới tạo luôn hiển thị đầu tiên
    demo_vid = M2MR_DIR / "docs" / "assets" / "demo.mp4"
    if demo_vid.is_file():
        motion_clips.append({
            "label": "🎬 [Demo M2MR] demo.mp4",
            "path": str(demo_vid).replace("\\", "/"),
            "type": "demo",
            "glb": None,
            "skeleton_npz": None,
        })

    mp_task_path = M2MR_DIR / "assets" / "body_models" / "pose_landmarker_full.task"
    return {
        "ok": exists,
        "root": str(M2MR_DIR).replace("\\", "/"),
        "has_venv": venv_py.is_file(),
        "venv_python": str(venv_py).replace("\\", "/"),
        "has_smplx": smplx_path.is_file() or mp_task_path.is_file(),
        "smplx_path": str(smplx_path).replace("\\", "/"),
        "rigs": rigs,
        "motion_clips": motion_clips,
        "ready_for_extract": bool(exists),
    }


def inspect_v2v_video_preflight(video_path: str, run_pose_scan: bool = True) -> dict:
    """Kiểm tra & nhận diện thông minh video tải lên (Native OpenCV + Local FFprobe + MediaPipe 3D Pose):
    Đo chính xác độ phân giải, thời lượng, FPS gốc, âm thanh và nhận diện số người / vị trí chủ thể / hành động."""
    wp = win_path(video_path)
    if not wp or not os.path.isfile(wp):
        return {"ok": False, "error": "Không tìm thấy file video"}

    w, h, native_fps, dur, n_frames, has_audio = 0, 0, 24.0, 0.0, 0, False
    try:
        import cv2
        cap = cv2.VideoCapture(wp)
        if cap.isOpened():
            w = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH) or 0)
            h = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT) or 0)
            fps_cv = float(cap.get(cv2.CAP_PROP_FPS) or 24.0)
            if 1.0 < fps_cv <= 240.0:
                native_fps = round(fps_cv, 2)
            cnt_cv = int(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
            if cnt_cv > 0:
                n_frames = cnt_cv
                dur = round(cnt_cv / max(native_fps, 1.0), 2)
            cap.release()
    except Exception:
        pass

    # Kiểm tra thêm luồng audio bằng ffprobe nội bộ (hoặc WSL nếu cần)
    try:
        ffprobe_bin = _find_ffprobe()
        if ffprobe_bin and (os.path.isfile(ffprobe_bin) or shutil.which(ffprobe_bin)):
            pr = subprocess.run(
                [
                    ffprobe_bin, "-v", "error",
                    "-show_entries", "stream=codec_type,width,height,r_frame_rate,avg_frame_rate,nb_frames,duration",
                    "-show_entries", "format=duration", "-of", "json", wp,
                ],
                capture_output=True, text=True, timeout=8, encoding="utf-8", errors="ignore"
            )
            if pr.returncode == 0 and pr.stdout.strip():
                pdata = json.loads(pr.stdout)
                streams = pdata.get("streams") or []
                v_st = next((s for s in streams if s.get("codec_type") == "video"), None)
                a_st = next((s for s in streams if s.get("codec_type") == "audio"), None)
                has_audio = a_st is not None
                if v_st:
                    w = int(v_st.get("width") or w)
                    h = int(v_st.get("height") or h)
                    dur_p = float(v_st.get("duration") or (pdata.get("format") or {}).get("duration") or dur)
                    if dur_p > 0:
                        dur = round(dur_p, 2)
    except Exception:
        pass

    if w <= 0 or h <= 0:
        return {"ok": False, "error": "Không thể giải mã khung hình video (hãy dùng định dạng MP4/WebM/MOV hợp lệ)"}

    if n_frames <= 0:
        n_frames = max(1, int(round(dur * native_fps)))
    aspect_str = "9:16" if h > w * 1.15 else ("16:9" if w > h * 1.15 else "1:1")
    fps_note = (
        f"FPS gốc {native_fps:g} -> Tự động đồng bộ 24 FPS (giữ nguyên tốc độ thực {dur:.1f}s)"
        if abs(native_fps - 24.0) > 1.0 else f"Chuẩn {native_fps:g} FPS"
    )
    res_info = {
        "ok": True,
        "path": wp.replace("\\", "/"),
        "width": w,
        "height": h,
        "aspect": aspect_str,
        "native_fps": native_fps,
        "duration": round(dur, 2),
        "n_frames": n_frames,
        "has_audio": has_audio,
        "fps_note": fps_note,
    }
    if run_pose_scan:
        try:
            ai_info = analyze_uploaded_video_intelligence(wp)
            if ai_info.get("ok"):
                res_info["recognition"] = ai_info
                for k_copy in (
                    "detected_person_count",
                    "detected_action_key",
                    "detected_action_label",
                    "suggested_pins",
                    "subjects",
                    "actors",
                    "annotated_preview_b64",
                    "auto_prompt_hint",
                    "motion_timeline",
                ):
                    if k_copy in ai_info:
                        res_info[k_copy] = ai_info[k_copy]
        except Exception:
            pass
    return res_info


class _HybridLandmark:
    __slots__ = ("x", "y", "z", "visibility")

    def __init__(self, x: float, y: float, z: float = 0.0, visibility: float = 0.95):
        self.x = float(x)
        self.y = float(y)
        self.z = float(z)
        self.visibility = float(visibility)


def _build_33_landmarks_from_subject_mask(
    mask_roi, x1_px: int, y1_px: int, x2_px: int, y2_px: int, img_w: int, img_h: int
) -> tuple[list[_HybridLandmark], list[_HybridLandmark]]:
    """Xây dựng bộ 33 khớp chuẩn (Image 0..1 + World 3D mét) từ vùng mask/bbox của chủ thể trong khung hình."""
    import numpy as np

    bw = max(8, x2_px - x1_px)
    bh = max(16, y2_px - y1_px)
    cx = (x1_px + 0.5 * bw) / max(img_w, 1)
    cy = (y1_px + 0.5 * bh) / max(img_h, 1)
    w_norm = bw / max(img_w, 1)
    h_norm = bh / max(img_h, 1)

    # Tìm đỉnh đầu thực tế và 2 bàn tay trái/phải từ mask_roi nếu có
    head_x = cx
    head_y = (y1_px + 0.10 * bh) / max(img_h, 1)
    lh_x = max(0.03, cx - 0.36 * w_norm)
    lh_y = (y1_px + 0.46 * bh) / max(img_h, 1)
    rh_x = min(0.97, cx + 0.36 * w_norm)
    rh_y = (y1_px + 0.46 * bh) / max(img_h, 1)
    la_x = max(0.04, cx - 0.14 * w_norm)
    ra_x = min(0.96, cx + 0.14 * w_norm)

    if mask_roi is not None and mask_roi.size > 0:
        ys_m, xs_m = np.where(mask_roi > 0)
        if len(xs_m) > 12:
            top_cut = np.percentile(ys_m, 12)
            top_xs = xs_m[ys_m <= top_cut]
            if len(top_xs) > 0:
                head_x = (x1_px + float(np.median(top_xs))) / max(img_w, 1)
                head_y = (y1_px + float(np.min(ys_m)) + 0.06 * bh) / max(img_h, 1)

            mid_mask = (ys_m >= 0.16 * bh) & (ys_m <= 0.68 * bh)
            if np.any(mid_mask):
                m_xs = xs_m[mid_mask]
                m_ys = ys_m[mid_mask]
                l_idx = int(np.argmin(m_xs))
                r_idx = int(np.argmax(m_xs))
                rh_x = (x1_px + float(m_xs[l_idx])) / max(img_w, 1)
                rh_y = (y1_px + float(m_ys[l_idx])) / max(img_h, 1)
                lh_x = (x1_px + float(m_xs[r_idx])) / max(img_w, 1)
                lh_y = (y1_px + float(m_ys[r_idx])) / max(img_h, 1)

            bot_mask = ys_m >= 0.78 * bh
            if np.any(bot_mask):
                b_xs = xs_m[bot_mask]
                ra_x = (x1_px + float(np.percentile(b_xs, 22))) / max(img_w, 1)
                la_x = (x1_px + float(np.percentile(b_xs, 78))) / max(img_w, 1)

    sh_y = (y1_px + 0.22 * bh) / max(img_h, 1)
    hip_y = (y1_px + 0.52 * bh) / max(img_h, 1)
    knee_y = (y1_px + 0.74 * bh) / max(img_h, 1)
    ank_y = (y1_px + 0.93 * bh) / max(img_h, 1)
    foot_y = min(0.98, (y1_px + 0.97 * bh) / max(img_h, 1))

    sh_half = max(0.04, min(0.14, 0.24 * w_norm))
    hip_half = max(0.03, min(0.10, 0.17 * w_norm))

    ilm = [_HybridLandmark(cx, cy, 0.0) for _ in range(33)]
    ilm[0] = _HybridLandmark(head_x, head_y, -0.04)
    ilm[7] = _HybridLandmark(head_x + 0.02, head_y, 0.0)
    ilm[8] = _HybridLandmark(head_x - 0.02, head_y, 0.0)
    ilm[11] = _HybridLandmark(cx + sh_half, sh_y, 0.0)     # left_shoulder
    ilm[12] = _HybridLandmark(cx - sh_half, sh_y, 0.0)     # right_shoulder
    ilm[13] = _HybridLandmark(0.5 * (ilm[11].x + lh_x), 0.5 * (sh_y + lh_y) + 0.03, -0.02)  # left_elbow
    ilm[14] = _HybridLandmark(0.5 * (ilm[12].x + rh_x), 0.5 * (sh_y + rh_y) + 0.03, -0.02)  # right_elbow
    ilm[15] = _HybridLandmark(lh_x, lh_y, -0.05)           # left_wrist
    ilm[16] = _HybridLandmark(rh_x, rh_y, -0.05)           # right_wrist
    ilm[17] = _HybridLandmark(lh_x, lh_y + 0.02, -0.06)
    ilm[19] = _HybridLandmark(lh_x, lh_y + 0.02, -0.06)
    ilm[18] = _HybridLandmark(rh_x, rh_y + 0.02, -0.06)
    ilm[20] = _HybridLandmark(rh_x, rh_y + 0.02, -0.06)
    ilm[23] = _HybridLandmark(cx + hip_half, hip_y, 0.0)   # left_hip
    ilm[24] = _HybridLandmark(cx - hip_half, hip_y, 0.0)   # right_hip
    ilm[25] = _HybridLandmark(0.5 * (ilm[23].x + la_x), knee_y, -0.02)  # left_knee
    ilm[26] = _HybridLandmark(0.5 * (ilm[24].x + ra_x), knee_y, -0.02)  # right_knee
    ilm[27] = _HybridLandmark(la_x, ank_y, 0.0)            # left_ankle
    ilm[28] = _HybridLandmark(ra_x, ank_y, 0.0)            # right_ankle
    ilm[29] = _HybridLandmark(la_x, foot_y, -0.06)
    ilm[31] = _HybridLandmark(la_x, foot_y, -0.08)
    ilm[30] = _HybridLandmark(ra_x, foot_y, -0.06)
    ilm[32] = _HybridLandmark(ra_x, foot_y, -0.08)

    # Chuyển đổi sang tọa độ World (gốc tại hông, đơn vị mét, Y hướng xuống theo chuẩn MediaPipe World)
    scale_m = 1.62 / max(h_norm, 0.22)
    wlm = []
    for pt in ilm:
        wx = (pt.x - cx) * scale_m * 0.85
        wy = (pt.y - hip_y) * scale_m
        wz = pt.z * scale_m
        wlm.append(_HybridLandmark(wx, wy, wz, pt.visibility))
    return ilm, wlm


_KEYPOINT_RCNN_MODEL = None
_KEYPOINT_RCNN_DEVICE = None


def _get_keypoint_rcnn_model():
    global _KEYPOINT_RCNN_MODEL, _KEYPOINT_RCNN_DEVICE
    if _KEYPOINT_RCNN_MODEL is not None:
        return _KEYPOINT_RCNN_MODEL, _KEYPOINT_RCNN_DEVICE
    import torch
    from torchvision.models.detection import (
        KeypointRCNN_ResNet50_FPN_Weights,
        keypointrcnn_resnet50_fpn,
    )

    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    is_cpu = str(device) == "cpu"
    model = keypointrcnn_resnet50_fpn(
        weights=KeypointRCNN_ResNet50_FPN_Weights.DEFAULT,
        min_size=384 if is_cpu else 512,
        max_size=512 if is_cpu else 800,
    )
    model.to(device).eval()
    _KEYPOINT_RCNN_MODEL = model
    _KEYPOINT_RCNN_DEVICE = device
    return _KEYPOINT_RCNN_MODEL, _KEYPOINT_RCNN_DEVICE


def _coco17_to_33_landmarks(
    kps_17x3, box_xyxy, img_w: int, img_h: int, kp_scores_17=None
) -> tuple[list[_HybridLandmark], list[_HybridLandmark]]:
    """Chuyển đổi 17 khớp xương chuẩn COCO (Keypoint R-CNN) sang 33 khớp chuẩn MediaPipe (Image 0..1 + World 3D mét).
    Bảo toàn điểm tin cậy thực tế (visibility) từ kp_scores_17 để phân biệt chính xác khớp nằm trong khung hình
    (Cận cảnh / Bán thân / Toàn thân), đồng thời tái tạo phần chân 3D cho World Landmarks để Rig 3D đứng vững trên sàn."""
    import numpy as np

    w_f = float(max(img_w, 1))
    h_f = float(max(img_h, 1))

    def _xyv(idx: int):
        raw_x = float(kps_17x3[idx, 0] / w_f)
        raw_y = float(kps_17x3[idx, 1] / h_f)
        if kp_scores_17 is not None and len(kp_scores_17) > idx:
            logit = float(kp_scores_17[idx])
            vis = 0.98 if (logit >= 2.2 and 0.01 <= raw_x <= 0.99 and 0.01 <= raw_y <= 0.96) else (0.55 if (logit >= 0.8 and raw_y <= 0.98) else 0.12)
        else:
            vis = 0.95 if (float(kps_17x3[idx, 2]) > 0.5 and 0.01 <= raw_y <= 0.95) else 0.20
        return (
            float(np.clip(raw_x, 0.02, 0.98)),
            float(np.clip(raw_y, 0.02, 0.98)),
            vis,
        )

    nose_x, nose_y, nose_v = _xyv(0)
    le_x, le_y, le_v = _xyv(1)
    re_x, re_y, re_v = _xyv(2)
    lear_x, lear_y, lear_v = _xyv(3)
    rear_x, rear_y, rear_v = _xyv(4)
    lsh_x, lsh_y, lsh_v = _xyv(5)
    rsh_x, rsh_y, rsh_v = _xyv(6)
    lelb_x, lelb_y, lelb_v = _xyv(7)
    relb_x, relb_y, relb_v = _xyv(8)
    lwri_x, lwri_y, lwri_v = _xyv(9)
    rwri_x, rwri_y, rwri_v = _xyv(10)
    lhip_x, lhip_y, lhip_v = _xyv(11)
    rhip_x, rhip_y, rhip_v = _xyv(12)
    lknee_x, lknee_y, lknee_v = _xyv(13)
    rknee_x, rknee_y, rknee_v = _xyv(14)
    lank_x, lank_y, lank_v = _xyv(15)
    rank_x, rank_y, rank_v = _xyv(16)

    sh_mid_x = 0.5 * (lsh_x + rsh_x)
    sh_mid_y = 0.5 * (lsh_y + rsh_y)
    hip_mid_x = 0.5 * (lhip_x + rhip_x)
    hip_mid_y = 0.5 * (lhip_y + rhip_y)

    # Nếu hông bị khuất sát mép dưới khung hình (quay cận cảnh ngực/vai), ước lượng vị trí hông 3D
    sh_span = max(0.08, abs(lsh_x - rsh_x))
    hips_cropped = (hip_mid_y <= sh_mid_y + 0.08 or hip_mid_y >= 0.94 or (lhip_v < 0.45 and rhip_v < 0.45))
    if hips_cropped:
        hip_mid_y = sh_mid_y + max(0.24, sh_span * 1.15)
        lhip_y = hip_mid_y
        rhip_y = hip_mid_y
        lhip_x = sh_mid_x + (lsh_x - sh_mid_x) * 0.78
        rhip_x = sh_mid_x + (rsh_x - sh_mid_x) * 0.78
        lhip_v = 0.20
        rhip_v = 0.20

    torso_h = max(0.14, hip_mid_y - sh_mid_y)

    # Kiểm tra chính xác xem đầu gối / cổ chân có nằm trong khung hình thực tế không
    knees_visible = (
        not hips_cropped
        and lknee_v >= 0.50
        and rknee_v >= 0.50
        and lknee_y < 0.94
        and rknee_y < 0.94
        and lknee_y > lhip_y + 0.05
        and rknee_y > rhip_y + 0.05
    )
    ankles_visible = (
        knees_visible
        and lank_v >= 0.50
        and rank_v >= 0.50
        and lank_y < 0.95
        and rank_y < 0.95
        and lank_y > lknee_y + 0.04
        and rank_y > rknee_y + 0.04
    )

    if not knees_visible:
        lknee_x = lhip_x + (lhip_x - hip_mid_x) * 0.08
        rknee_x = rhip_x + (rhip_x - hip_mid_x) * 0.08
        lknee_y = hip_mid_y + torso_h * 0.76
        rknee_y = hip_mid_y + torso_h * 0.76
        lknee_v = 0.12
        rknee_v = 0.12
    if not ankles_visible:
        lank_x = lknee_x
        rank_x = rknee_x
        lank_y = lknee_y + torso_h * 0.74
        rank_y = rknee_y + torso_h * 0.74
        lank_v = 0.10
        rank_v = 0.10

    lfoot_y = lank_y + torso_h * 0.12
    rfoot_y = rank_y + torso_h * 0.12

    # 1. Bộ 33 khớp chuẩn hóa trên mặt phẳng ảnh (0..1) kèm visibility thực tế của từng khớp
    ilm = [_HybridLandmark(hip_mid_x, min(0.95, hip_mid_y), 0.0, 0.90) for _ in range(33)]
    ilm[0] = _HybridLandmark(nose_x, nose_y, -0.04, nose_v)
    ilm[2] = _HybridLandmark(le_x, le_y, -0.03, le_v)
    ilm[5] = _HybridLandmark(re_x, re_y, -0.03, re_v)
    ilm[7] = _HybridLandmark(lear_x, lear_y, 0.0, lear_v)
    ilm[8] = _HybridLandmark(rear_x, rear_y, 0.0, rear_v)
    ilm[11] = _HybridLandmark(lsh_x, lsh_y, 0.0, lsh_v)
    ilm[12] = _HybridLandmark(rsh_x, rsh_y, 0.0, rsh_v)
    ilm[13] = _HybridLandmark(lelb_x, lelb_y, -0.03, lelb_v)
    ilm[14] = _HybridLandmark(relb_x, relb_y, -0.03, relb_v)
    ilm[15] = _HybridLandmark(lwri_x, lwri_y, -0.06, lwri_v)
    ilm[16] = _HybridLandmark(rwri_x, rwri_y, -0.06, rwri_v)
    ilm[17] = _HybridLandmark(lwri_x, min(0.98, lwri_y + 0.02), -0.07, lwri_v)
    ilm[19] = _HybridLandmark(lwri_x, min(0.98, lwri_y + 0.02), -0.07, lwri_v)
    ilm[18] = _HybridLandmark(rwri_x, min(0.98, rwri_y + 0.02), -0.07, rwri_v)
    ilm[20] = _HybridLandmark(rwri_x, min(0.98, rwri_y + 0.02), -0.07, rwri_v)
    ilm[23] = _HybridLandmark(lhip_x, min(0.96, lhip_y), 0.0, lhip_v)
    ilm[24] = _HybridLandmark(rhip_x, min(0.96, rhip_y), 0.0, rhip_v)
    ilm[25] = _HybridLandmark(lknee_x, min(0.97, lknee_y), -0.02, lknee_v)
    ilm[26] = _HybridLandmark(rknee_x, min(0.97, rknee_y), -0.02, rknee_v)
    ilm[27] = _HybridLandmark(lank_x, min(0.98, lank_y), 0.0, lank_v)
    ilm[28] = _HybridLandmark(rank_x, min(0.98, rank_y), 0.0, rank_v)
    ilm[29] = _HybridLandmark(lank_x, min(0.99, lfoot_y), -0.06, lank_v)
    ilm[31] = _HybridLandmark(lank_x, min(0.99, lfoot_y), -0.08, lank_v)
    ilm[30] = _HybridLandmark(rank_x, min(0.99, rfoot_y), -0.06, rank_v)
    ilm[32] = _HybridLandmark(rank_x, min(0.99, rfoot_y), -0.08, rank_v)

    # 2. Bộ 33 khớp trong không gian 3D World (đơn vị mét, tỉ lệ chuẩn theo chiều dài thân trên torso_h)
    raw_pts_3d = [
        (ilm[i].x, ilm[i].y, ilm[i].z) for i in range(33)
    ]
    raw_pts_3d[23] = (lhip_x, lhip_y, 0.0)
    raw_pts_3d[24] = (rhip_x, rhip_y, 0.0)
    raw_pts_3d[25] = (lknee_x, lknee_y, -0.02)
    raw_pts_3d[26] = (rknee_x, rknee_y, -0.02)
    raw_pts_3d[27] = (lank_x, lank_y, 0.0)
    raw_pts_3d[28] = (rank_x, rank_y, 0.0)
    raw_pts_3d[29] = (lank_x, lfoot_y, -0.06)
    raw_pts_3d[31] = (lank_x, lfoot_y, -0.08)
    raw_pts_3d[30] = (rank_x, rfoot_y, -0.06)
    raw_pts_3d[32] = (rank_x, rfoot_y, -0.08)

    scale_m = 0.50 / max(torso_h, 0.14)
    aspect_x = min(1.35, max(0.65, w_f / h_f))
    wlm = []
    for px, py, pz in raw_pts_3d:
        wx = (px - hip_mid_x) * scale_m * aspect_x
        wy = (py - hip_mid_y) * scale_m
        wz = pz * scale_m
        wlm.append(_HybridLandmark(wx, wy, wz, 0.98))
    return ilm, wlm


def _box_iou_xyxy(a, b) -> float:
    ix1 = max(float(a[0]), float(b[0]))
    iy1 = max(float(a[1]), float(b[1]))
    ix2 = min(float(a[2]), float(b[2]))
    iy2 = min(float(a[3]), float(b[3]))
    inter = max(0.0, ix2 - ix1) * max(0.0, iy2 - iy1)
    if inter <= 0.0:
        return 0.0
    area_a = max(1.0, (float(a[2]) - float(a[0])) * (float(a[3]) - float(a[1])))
    area_b = max(1.0, (float(b[2]) - float(b[0])) * (float(b[3]) - float(b[1])))
    return inter / min(area_a, area_b)


def _lerp_pose_landmarks_pair(
    pair_a: tuple[list[_HybridLandmark], list[_HybridLandmark]],
    pair_b: tuple[list[_HybridLandmark], list[_HybridLandmark]],
    alpha: float,
) -> tuple[list[_HybridLandmark], list[_HybridLandmark]]:
    t = float(max(0.0, min(1.0, alpha)))
    inv_t = 1.0 - t
    ilm_a, wlm_a = pair_a
    ilm_b, wlm_b = pair_b
    ilm_out = [
        _HybridLandmark(
            ilm_a[i].x * inv_t + ilm_b[i].x * t,
            ilm_a[i].y * inv_t + ilm_b[i].y * t,
            ilm_a[i].z * inv_t + ilm_b[i].z * t,
            max(ilm_a[i].visibility, ilm_b[i].visibility) if min(ilm_a[i].visibility, ilm_b[i].visibility) >= 0.45 else (ilm_a[i].visibility * inv_t + ilm_b[i].visibility * t),
        )
        for i in range(min(len(ilm_a), len(ilm_b)))
    ]
    wlm_out = [
        _HybridLandmark(
            wlm_a[i].x * inv_t + wlm_b[i].x * t,
            wlm_a[i].y * inv_t + wlm_b[i].y * t,
            wlm_a[i].z * inv_t + wlm_b[i].z * t,
            wlm_a[i].visibility * inv_t + wlm_b[i].visibility * t,
        )
        for i in range(min(len(wlm_a), len(wlm_b)))
    ]
    return ilm_out, wlm_out


def _detect_poses_hybrid(frames_bgr: list, max_poses: int = 4) -> list[list[tuple[list, list]]]:
    """Phân tích giải phẫu học thực tế số lượng người & 17–33 khớp xương (sắp xếp Trái -> Phải) trên chuỗi khung hình:
    - Sử dụng mô hình Deep Learning Keypoint R-CNN ResNet50-FPN (CUDA/CPU) kèm kiểm định điểm tin cậy từng khớp (keypoints_scores).
    - Trên CPU với video dài, lấy mẫu keyframe thông minh + nội suy chuyển động mượt để đạt tốc độ cao và tiết kiệm RAM."""
    import gc
    import cv2
    import numpy as np

    if not frames_bgr:
        return []

    n_total = len(frames_bgr)
    h_orig, w_orig = frames_bgr[0].shape[:2]

    # 1. Phân tích bằng mô hình Deep Learning Keypoint R-CNN ResNet50-FPN
    try:
        import torch

        model, device = _get_keypoint_rcnn_model()
        is_cpu = str(device) == "cpu"
        max_side = 512 if is_cpu else 640
        scale = min(1.0, float(max_side) / float(max(h_orig, w_orig, 1)))
        inf_w = max(64, int(round(w_orig * scale)))
        inf_h = max(64, int(round(h_orig * scale)))

        # Trên CPU khi xử lý video nhiều frame (>16), lấy mẫu keyframe và nội suy các frame ở giữa
        if is_cpu and n_total > 16:
            stride = max(3, min(6, n_total // 40))
            key_indices = list(range(0, n_total, stride))
            if key_indices[-1] != n_total - 1:
                key_indices.append(n_total - 1)
        else:
            key_indices = list(range(n_total))

        key_results: dict[int, list[tuple[list, list]]] = {}
        total_rcnn_people = 0
        batch_size = 8 if not is_cpu else 2

        with torch.no_grad():
            for b_start in range(0, len(key_indices), batch_size):
                batch_k_idxs = key_indices[b_start : b_start + batch_size]
                tensors = []
                for k_idx in batch_k_idxs:
                    frm_bgr = frames_bgr[k_idx]
                    small = (
                        cv2.resize(frm_bgr, (inf_w, inf_h), interpolation=cv2.INTER_AREA)
                        if scale < 0.99
                        else frm_bgr
                    )
                    rgb = cv2.cvtColor(small, cv2.COLOR_BGR2RGB)
                    t = torch.from_numpy(rgb).permute(2, 0, 1).float().div_(255.0).to(device)
                    tensors.append(t)

                outputs = model(tensors)
                for k_idx, out in zip(batch_k_idxs, outputs):
                    scores = out["scores"].detach().cpu().numpy()
                    boxes = out["boxes"].detach().cpu().numpy()
                    keypoints = out["keypoints"].detach().cpu().numpy()
                    kp_scores_all = (
                        out["keypoints_scores"].detach().cpu().numpy()
                        if "keypoints_scores" in out
                        else np.full((len(scores), 17), 5.0, dtype=np.float32)
                    )

                    # Lọc các phát hiện có độ tin cậy cao và có thật các khớp giải phẫu thân trên (đầu, vai, khuỷu tay, cổ tay, hông)
                    candidates = []
                    for idx_det, sc in enumerate(scores):
                        if float(sc) < 0.78:
                            continue
                        bx1, by1, bx2, by2 = boxes[idx_det]
                        bw_det = bx2 - bx1
                        bh_det = by2 - by1
                        if bh_det < inf_h * 0.20 or (bw_det * bh_det) < (inf_w * inf_h * 0.03):
                            continue
                        kp_sc = kp_scores_all[idx_det]
                        valid_upper_kps = int(np.sum(kp_sc[:13] >= 2.5))
                        both_shoulders_ok = bool(kp_sc[5] >= 2.0 and kp_sc[6] >= 2.0)
                        if valid_upper_kps < 5 or not both_shoulders_ok:
                            continue
                        candidates.append((float(sc), boxes[idx_det], keypoints[idx_det], kp_sc))

                    candidates.sort(key=lambda x: x[0], reverse=True)
                    kept = []
                    max_bh = max((c[1][3] - c[1][1] for c in candidates), default=1.0)
                    max_bw = max((c[1][2] - c[1][0] for c in candidates), default=1.0)
                    top_score = candidates[0][0] if candidates else 0.0

                    for sc, box_c, kps_c, kp_sc_c in candidates:
                        bh_c = box_c[3] - box_c[1]
                        bw_c = box_c[2] - box_c[0]
                        if bh_c < max_bh * 0.48 or (bw_c * bh_c) < (max_bw * max_bh * 0.25):
                            continue
                        if kept and top_score >= 0.96 and (kept[0][1][2] - kept[0][1][0]) >= inf_w * 0.45 and sc < 0.94:
                            continue

                        cx_c = 0.5 * (box_c[0] + box_c[2])
                        nose_c = kps_c[0, :2]
                        sh_cx_c = 0.5 * (kps_c[5, 0] + kps_c[6, 0])
                        duplicate = False
                        for _, box_k, kps_k, _ in kept:
                            cx_k = 0.5 * (box_k[0] + box_k[2])
                            nose_k = kps_k[0, :2]
                            sh_cx_k = 0.5 * (kps_k[5, 0] + kps_k[6, 0])
                            nose_dist = float(np.hypot(nose_c[0] - nose_k[0], nose_c[1] - nose_k[1]))
                            if (
                                _box_iou_xyxy(box_c, box_k) > 0.28
                                or abs(cx_c - cx_k) < inf_w * 0.18
                                or abs(sh_cx_c - sh_cx_k) < inf_w * 0.18
                                or nose_dist < max(inf_w, inf_h) * 0.16
                            ):
                                duplicate = True
                                break
                        if not duplicate:
                            kept.append((sc, box_c, kps_c, kp_sc_c))
                        if len(kept) >= max_poses:
                            break

                    paired = []
                    for _, box_k, kps_k, kp_sc_k in kept:
                        ilm, wlm = _coco17_to_33_landmarks(kps_k, box_k, inf_w, inf_h, kp_scores_17=kp_sc_k)
                        cx_norm = 0.5 * (ilm[11].x + ilm[12].x)
                        paired.append((cx_norm, (ilm, wlm)))
                    paired.sort(key=lambda x: x[0])
                    total_rcnn_people += len(paired)
                    key_results[k_idx] = [p[1] for p in paired]
                del outputs, tensors

        gc.collect()
        if total_rcnn_people > 0:
            if len(key_indices) == n_total:
                return [key_results.get(i, []) for i in range(n_total)]
            # Nội suy tuyến tính mượt giữa các keyframe cho toàn bộ n_total khung hình
            rcnn_results: list[list[tuple[list, list]]] = [[] for _ in range(n_total)]
            for pos_k, k_idx in enumerate(key_indices):
                rcnn_results[k_idx] = key_results.get(k_idx, [])
                if pos_k + 1 < len(key_indices):
                    next_k = key_indices[pos_k + 1]
                    span = float(max(1, next_k - k_idx))
                    list_a = key_results.get(k_idx, [])
                    list_b = key_results.get(next_k, [])
                    for f_i in range(k_idx + 1, next_k):
                        alpha = float(f_i - k_idx) / span
                        if list_a and list_b:
                            n_p = min(len(list_a), len(list_b))
                            interp_f = [
                                _lerp_pose_landmarks_pair(list_a[p_i], list_b[p_i], alpha)
                                for p_i in range(n_p)
                            ]
                            if len(list_a) > n_p and alpha < 0.5:
                                interp_f.extend(list_a[n_p:])
                            elif len(list_b) > n_p and alpha >= 0.5:
                                interp_f.extend(list_b[n_p:])
                            rcnn_results[f_i] = interp_f
                        elif list_a:
                            rcnn_results[f_i] = list_a
                        elif list_b:
                            rcnn_results[f_i] = list_b
            return rcnn_results
    except Exception:
        pass

    # 2. Dự phòng MediaPipe PoseLandmarker (nếu môi trường không có PyTorch)
    try:
        import urllib.request
        import mediapipe as mp
        from mediapipe.tasks import python as mp_python
        from mediapipe.tasks.python import vision as mp_vision

        model_path = M2MR_DIR / "assets" / "body_models" / "pose_landmarker_full.task"
        model_path.parent.mkdir(parents=True, exist_ok=True)
        if not model_path.is_file():
            urllib.request.urlretrieve(
                "https://storage.googleapis.com/mediapipe-models/pose_landmarker/pose_landmarker_full/float16/latest/pose_landmarker_full.task",
                str(model_path),
            )
        base_options = mp_python.BaseOptions(model_asset_path=str(model_path))
        options = mp_vision.PoseLandmarkerOptions(
            base_options=base_options,
            running_mode=mp_vision.RunningMode.IMAGE,
            num_poses=max_poses,
            min_pose_detection_confidence=0.60,
            min_pose_presence_confidence=0.60,
        )
        mp_results = []
        total_found = 0
        with mp_vision.PoseLandmarker.create_from_options(options) as landmarker:
            for frm_bgr in frames_bgr:
                rgb = cv2.cvtColor(frm_bgr, cv2.COLOR_BGR2RGB)
                mp_img = mp.Image(image_format=mp.ImageFormat.SRGB, data=rgb)
                res = landmarker.detect(mp_img)
                paired = []
                if res.pose_landmarks and res.pose_world_landmarks:
                    for ilm, wlm in zip(res.pose_landmarks, res.pose_world_landmarks):
                        cx = 0.5 * (ilm[11].x + ilm[12].x)
                        paired.append((cx, (ilm, wlm)))
                    paired.sort(key=lambda x: x[0])
                    total_found += len(paired)
                mp_results.append([p[1] for p in paired])
        if total_found > 0:
            return mp_results
    except Exception:
        pass

    return [[] for _ in frames_bgr]


def _describe_pose_phase_vi(lm: list, t_start: float, t_end: float) -> str:
    """Phân tích tư thế giải phẫu thực tế của nhân vật trong một phân đoạn thời gian (vị trí 2 bàn tay, độ nghiêng vai, hướng mặt, nhịp hông)."""
    nose_x, nose_y = lm[0].x, lm[0].y
    lsh_x, lsh_y = lm[11].x, lm[11].y
    rsh_x, rsh_y = lm[12].x, lm[12].y
    lw_x, lw_y = lm[15].x, lm[15].y
    rw_x, rw_y = lm[16].x, lm[16].y
    lhip_x, lhip_y = lm[23].x, lm[23].y
    rhip_x, rhip_y = lm[24].x, lm[24].y

    sh_y = 0.5 * (lsh_y + rsh_y)
    hip_y = 0.5 * (lhip_y + rhip_y)
    chest_y = sh_y + 0.38 * max(0.12, hip_y - sh_y)

    def _hand_level(hy: float) -> str:
        if hy < nose_y + 0.03:
            return "đưa cao ngang đầu/mặt"
        if hy < sh_y + 0.05:
            return "nâng ngang vai/cổ"
        if hy < chest_y + 0.06:
            return "tạo dáng trước ngực"
        if hy < hip_y - 0.03:
            return "đặt ngang eo/bụng"
        return "hạ tự nhiên cạnh hông"

    lh_desc = _hand_level(lw_y)
    rh_desc = _hand_level(rw_y)
    sh_tilt = lsh_y - rsh_y
    tilt_str = (
        ", nghiêng vai nhịp nhàng sang phải"
        if sh_tilt < -0.035
        else (", nghiêng vai nhịp nhàng sang trái" if sh_tilt > 0.035 else ", giữ trục vai cân đối")
    )
    return (
        f"{t_start:.1f}s–{t_end:.1f}s: Tay phải {rh_desc} ({int(round(rw_x*100))}%, {int(round(rw_y*100))}%), "
        f"tay trái {lh_desc} ({int(round(lw_x*100))}%, {int(round(lw_y*100))}%){tilt_str}"
    )


def _build_motion_timeline_en(samples, dur_s: float, legs_visible: bool = True, subject: str = "") -> list:
    """Dựng timeline động tác tiếng Anh từ chuỗi (t_giây, landmarks33) của 1 người.
    Nhận diện: đi sang trái/phải khung hình, tiến lại/lùi xa máy quay, xoay ngang/quay lưng, ngồi xuống/đứng lên,
    giơ/hạ tay, cử chỉ tay, đứng yên. Trả về list {t0, t1, text} (mốc giây theo video nguồn), đã gộp các đoạn trùng."""
    import math
    if not samples or len(samples) < 2:
        return []
    feats = []
    for t, lm in samples:
        try:
            shx, shy = 0.5 * (lm[11].x + lm[12].x), 0.5 * (lm[11].y + lm[12].y)
            hx, hy = 0.5 * (lm[23].x + lm[24].x), 0.5 * (lm[23].y + lm[24].y)
            torso = max(0.03, math.hypot(hx - shx, hy - shy))
            feats.append({
                "t": float(t), "hx": hx, "hy": hy, "shy": shy, "torso": torso,
                "swr": abs(lm[11].x - lm[12].x) / torso,
                "lw": (lm[15].x, lm[15].y), "rw": (lm[16].x, lm[16].y),
                "nose": float(getattr(lm[0], "visibility", 1.0)),
            })
        except Exception:
            continue
    if len(feats) < 2:
        return []
    swr_sorted = sorted(f["swr"] for f in feats)
    swr_ref = max(0.2, swr_sorted[int(0.8 * (len(swr_sorted) - 1))])  # độ rộng vai khi đối diện máy quay

    def _arms_up(f):
        return (f["lw"][1] < f["shy"], f["rw"][1] < f["shy"])

    def _arm_word(l_on, r_on):
        if l_on and r_on:
            return "both arms"
        return "their left arm" if l_on else "their right arm"

    phrases = []
    for i in range(len(feats) - 1):
        a, b = feats[i], feats[i + 1]
        parts = []
        dx = b["hx"] - a["hx"]
        if abs(dx) > 0.04 and (legs_visible or abs(dx) > 0.08):
            parts.append("walks toward frame " + ("right" if dx > 0 else "left"))
        sc = b["torso"] / a["torso"]
        if sc > 1.12:
            parts.append("steps closer to the camera")
        elif sc < 0.89:
            parts.append("steps back away from the camera")
        fa, fb = a["swr"] / swr_ref, b["swr"] / swr_ref
        if a["nose"] >= 0.5 and b["nose"] < 0.3:
            parts.append("turns away from the camera")
        elif a["nose"] < 0.3 and b["nose"] >= 0.5:
            parts.append("turns back to face the camera")
        elif fa > 0.7 and fb < 0.45:
            parts.append("turns sideways")
        elif fa < 0.45 and fb > 0.7:
            parts.append("turns to face the camera")
        dy = (b["hy"] - a["hy"]) / a["torso"]
        if dy > 0.35:
            parts.append("crouches down")
        elif dy < -0.35:
            parts.append("rises up")
        (la, ra), (lb, rb) = _arms_up(a), _arms_up(b)
        up_new_l, up_new_r = (lb and not la), (rb and not ra)
        down_l, down_r = (la and not lb), (ra and not rb)
        arm_said = False
        if up_new_l or up_new_r:
            parts.append("raises " + _arm_word(up_new_l, up_new_r))
            arm_said = True
        if down_l or down_r:
            parts.append("lowers " + _arm_word(down_l, down_r))
            arm_said = True
        if not arm_said and (lb or rb):
            parts.append("keeps " + _arm_word(lb, rb) + " raised")
            arm_said = True
        wt = (math.hypot(b["lw"][0] - a["lw"][0], b["lw"][1] - a["lw"][1])
              + math.hypot(b["rw"][0] - a["rw"][0], b["rw"][1] - a["rw"][1])) / a["torso"]
        if not arm_said and wt > 0.6:
            parts.append("gestures actively with the arms")
        if not parts:
            parts.append("sways gently in place" if (wt > 0.25 or abs(dx) > 0.015) else "holds still")
        phrases.append(", ".join(parts))

    segs = []
    for i, txt in enumerate(phrases):
        t0 = 0.0 if i == 0 else feats[i]["t"]
        t1 = float(dur_s) if i == len(phrases) - 1 else feats[i + 1]["t"]
        if segs and segs[-1]["text"] == txt:
            segs[-1]["t1"] = t1
        else:
            segs.append({"t0": t0, "t1": t1, "text": txt})
    pref = (subject.strip() + " ") if subject else ""
    return [{"t0": round(s["t0"], 1), "t1": round(s["t1"], 1), "text": pref + s["text"]} for s in segs if s["t1"] - s["t0"] >= 0.2]


def analyze_uploaded_video_intelligence(video_path: str) -> dict:
    """Phân tích chuyên sâu Video tải lên bằng Deep Learning Keypoint R-CNN 17 khớp giải phẫu + Phân tích động học theo thời gian:
    - Đếm chính xác tuyệt đối số người thật trong video (1 người = 1 người, loại bỏ hoàn toàn cơ chế quét/đoán hộp).
    - Phân tích góc máy thực tế (Cận cảnh / Bán thân Medium Shot / Trung cảnh Knee Shot / Toàn thân Full-Body) dựa trên độ hiện diện thực của khớp gối & cổ chân.
    - Phân tích quỹ đạo chuyển động qua 10–12 mốc thời gian để bóc tách rõ từng pha động tác (timeline_phases) và loại hình chuyển động."""
    import cv2
    import numpy as np

    wp = win_path(video_path)
    if not wp or not os.path.isfile(wp):
        return {"ok": False, "error": "File video không tồn tại"}

    is_img = Path(wp).suffix.lower() in {".jpg", ".jpeg", ".png", ".webp", ".bmp"}
    sampled_frames = []
    orig_w, orig_h, dur_s, fps_v = 832, 480, 5.0, 24.0

    if is_img:
        im0 = cv2.imread(wp)
        if im0 is None:
            return {"ok": False, "error": "Không đọc được ảnh"}
        orig_h, orig_w = im0.shape[:2]
        sampled_frames = [(0, im0)]
        dur_s = 5.0
    else:
        cap = cv2.VideoCapture(wp)
        if not cap.isOpened():
            return {"ok": False, "error": "Không mở được video"}
        orig_w = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH) or 832)
        orig_h = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT) or 480)
        fps_v = float(cap.get(cv2.CAP_PROP_FPS) or 24.0)
        if fps_v <= 1.0 or fps_v > 240.0:
            fps_v = 24.0
        total_f = int(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
        dur_s = round(total_f / fps_v, 2) if total_f > 0 else 5.0
        # ~1 khung/giây (10–20 mốc) để timeline động tác đủ chi tiết
        n_samp = max(10, min(20, int(dur_s) + 1))
        sample_fracs = [0.03 + 0.94 * k / (n_samp - 1) for k in range(n_samp)]
        sample_indices = (
            sorted(set(max(0, min(total_f - 1, int(total_f * fr))) for fr in sample_fracs))
            if total_f > 10
            else [0]
        )
        for s_idx in sample_indices:
            cap.set(cv2.CAP_PROP_POS_FRAMES, s_idx)
            ok, frm = cap.read()
            if ok and frm is not None:
                sampled_frames.append((s_idx, frm))
        cap.release()

    if not sampled_frames:
        return {"ok": False, "error": "Không trích xuất được khung hình từ video"}

    hybrid_frames = _detect_poses_hybrid([f[1] for f in sampled_frames], max_poses=4)
    per_frame_poses = [[pair[0] for pair in f_list] for f_list in hybrid_frames]

    # Tính số lượng người chuẩn theo trung vị (consensus median) trên toàn chuỗi thời gian
    non_zero_counts = [len(p) for p in per_frame_poses if len(p) > 0]
    consensus_count = int(round(float(np.median(non_zero_counts)))) if non_zero_counts else 0

    mid_idx = len(sampled_frames) // 2
    best_frame_idx = mid_idx
    best_dist = 999
    for idx_item, poses_in_f in enumerate(per_frame_poses):
        if len(poses_in_f) == consensus_count and abs(idx_item - mid_idx) < best_dist:
            best_frame_idx = idx_item
            best_dist = abs(idx_item - mid_idx)

    rep_frame = sampled_frames[best_frame_idx][1].copy()
    rep_poses = (per_frame_poses[best_frame_idx] if best_frame_idx < len(per_frame_poses) else [])[:consensus_count]

    actor_colors_bgr = [
        (235, 206, 56),   # Actor 1: Cyan-Gold
        (145, 110, 255),  # Actor 2: Coral-Pink
        (120, 235, 110),  # Actor 3: Emerald
        (250, 165, 96),   # Actor 4: Sky-Indigo
    ]
    actor_colors_hex = ["#38ceeb", "#ff6e91", "#6eeb78", "#60a5fa"]

    subjects_summary = []
    suggested_pins = []

    mp_edges = [
        (11, 12), (11, 13), (13, 15), (12, 14), (14, 16),
        (11, 23), (12, 24), (23, 24), (23, 25), (25, 27), (24, 26), (26, 28),
        (0, 11), (0, 12),
    ]

    for a_idx, lm in enumerate(rep_poses):
        actor_num = a_idx + 1
        col_bgr = actor_colors_bgr[a_idx % len(actor_colors_bgr)]
        col_hex = actor_colors_hex[a_idx % len(actor_colors_hex)]

        # Chỉ tính bounding box và vẽ khớp xương trên các khớp thực sự xuất hiện trong khung hình (visibility >= 0.45)
        vis_indices = [idx_k for idx_k in (0, 2, 5, 7, 8, 11, 12, 13, 14, 15, 16, 23, 24, 25, 26, 27, 28) if lm[idx_k].visibility >= 0.45]
        if not vis_indices:
            vis_indices = [0, 11, 12, 13, 14, 15, 16, 23, 24]
        xs = [float(np.clip(lm[idx_k].x, 0.0, 1.0)) for idx_k in vis_indices]
        ys = [float(np.clip(lm[idx_k].y, 0.0, 1.0)) for idx_k in vis_indices]
        x1, y1, x2, y2 = min(xs), min(ys), max(xs), max(ys)

        head_x = float(np.clip(lm[0].x, 0.04, 0.96))
        head_y = float(np.clip(lm[0].y, 0.04, 0.96))
        sh_x = float(np.clip(0.5 * (lm[11].x + lm[12].x), 0.04, 0.96))
        sh_y = float(np.clip(0.5 * (lm[11].y + lm[12].y), 0.04, 0.96))
        torso_x = float(np.clip(0.25 * (lm[11].x + lm[12].x + lm[23].x + lm[24].x), 0.04, 0.96))
        torso_y = float(np.clip(0.25 * (lm[11].y + lm[12].y + lm[23].y + lm[24].y), 0.04, 0.96))
        lhand_x = float(np.clip(lm[15].x, 0.03, 0.97))
        lhand_y = float(np.clip(lm[15].y, 0.03, 0.97))
        rhand_x = float(np.clip(lm[16].x, 0.03, 0.97))
        rhand_y = float(np.clip(lm[16].y, 0.03, 0.97))

        if len(rep_poses) == 1 and 0.22 <= torso_x <= 0.78:
            zone_vi = "Chính Giữa"
        else:
            zone_vi = "Bên Trái" if torso_x < 0.38 else ("Bên Phải" if torso_x > 0.62 else "Chính Giữa")

        # Phân tích cỡ cảnh (Framing) dựa trên sự hiện diện thực tế của mắt cá chân, đầu gối và hông xuyên suốt video
        actor_frames = [pf[a_idx] for pf in per_frame_poses if a_idx < len(pf)]
        ank_vis_ratio = float(np.mean([1.0 if (af[27].visibility >= 0.5 or af[28].visibility >= 0.5) else 0.0 for af in actor_frames])) if actor_frames else 0.0
        knee_vis_ratio = float(np.mean([1.0 if (af[25].visibility >= 0.5 or af[26].visibility >= 0.5) else 0.0 for af in actor_frames])) if actor_frames else 0.0
        hip_vis_ratio = float(np.mean([1.0 if (af[23].visibility >= 0.45 or af[24].visibility >= 0.45) else 0.0 for af in actor_frames])) if actor_frames else 1.0

        if ank_vis_ratio >= 0.45:
            framing_vi = "Toàn thân (Full-Body — từ đầu đến chân)"
            legs_truly_visible = True
        elif knee_vis_ratio >= 0.45:
            framing_vi = "Trung cảnh rộng (Knee Shot — từ đầu đến gối)"
            legs_truly_visible = False
        elif hip_vis_ratio >= 0.40:
            framing_vi = "Bán thân / Trung cảnh (Medium Shot — từ đầu đến hông)"
            legs_truly_visible = False
        else:
            framing_vi = "Cận cảnh (Medium Close-Up — từ đầu đến ngực/eo)"
            legs_truly_visible = False

        # Phân tích động học (Kinematics) thực tế trên toàn chuỗi khung hình
        wrist_travel = 0.0
        hip_path = 0.0
        hip_xs = []
        sh_tilts = []
        hands_raised_cnt = 0
        prev_l = None
        prev_r = None
        prev_hx = None
        for af in actor_frames:
            lwx, lwy = af[15].x, af[15].y
            rwx, rwy = af[16].x, af[16].y
            hx = 0.5 * (af[23].x + af[24].x)
            hy = 0.5 * (af[23].y + af[24].y)
            hip_xs.append(hx)
            sh_tilts.append(abs(af[11].y - af[12].y))
            if lwy < hy - 0.06 or rwy < hy - 0.06:
                hands_raised_cnt += 1
            if prev_l is not None:
                wrist_travel += float(np.hypot(lwx - prev_l[0], lwy - prev_l[1]) + np.hypot(rwx - prev_r[0], rwy - prev_r[1]))
                hip_path += abs(hx - prev_hx)
            prev_l = (lwx, lwy)
            prev_r = (rwx, rwy)
            prev_hx = hx

        net_hip_drift = abs(hip_xs[-1] - hip_xs[0]) if len(hip_xs) >= 2 else 0.0
        hip_range = (max(hip_xs) - min(hip_xs)) if len(hip_xs) >= 2 else 0.0
        hands_raised_ratio = hands_raised_cnt / float(max(len(actor_frames), 1))

        # Phân biệt chuẩn xác giữa Bước đi thực tế (cần thấy rõ chân + di chuyển tịnh tiến một chiều) và Vũ đạo / Cử chỉ tay tại chỗ
        if legs_truly_visible and net_hip_drift > 0.22 and net_hip_drift >= hip_path * 0.65:
            act_vi = "Bước đi / Di chuyển qua khung hình"
            act_code = "catwalk"
        elif wrist_travel >= 0.22 or hands_raised_ratio >= 0.35:
            if not legs_truly_visible:
                act_vi = "Nhảy vũ đạo TikTok / Biểu diễn cử chỉ tay & nhịp vai (Bán thân)"
            else:
                act_vi = "Nhảy vũ đạo sôi động / Cử chỉ tay & đánh nhịp toàn thân"
            act_code = "kpop_dance"
        elif hip_range >= 0.08 or max(sh_tilts, default=0.0) >= 0.04:
            act_vi = "Nhún nhảy theo nhạc / Đánh nhịp vai & hông tại chỗ"
            act_code = "kpop_dance"
        elif abs(lm[11].x - lm[12].x) < 0.07:
            act_vi = "Xoay nghiêng / Ngoái nhìn ống kính"
            act_code = "turn_back_look"
        else:
            act_vi = "Đứng tạo dáng / Biểu cảm tự nhiên trước ống kính"
            act_code = "pose_hip"

        # Phân tích diễn biến chi tiết theo 3 phân đoạn thời gian (Đầu - Giữa - Cuối video)
        timeline_phases = []
        if actor_frames:
            n_af = len(actor_frames)
            seg_indices = [0, n_af // 2, n_af - 1] if n_af >= 3 else list(range(n_af))
            n_segs = len(seg_indices)
            for s_i, f_pos in enumerate(seg_indices):
                t0 = round((s_i / float(n_segs)) * dur_s, 1)
                t1 = round(((s_i + 1) / float(n_segs)) * dur_s, 1)
                timeline_phases.append(_describe_pose_phase_vi(actor_frames[f_pos], t0, t1))

        # Timeline động tác tiếng Anh (đi / xoay / tiến-lùi / ngồi / giơ tay) theo mốc giây thật của video nguồn
        motion_tl_en = []
        if a_idx == 0 and not is_img:
            try:
                tl_samples = [(sampled_frames[fi][0] / fps_v, pf[0]) for fi, pf in enumerate(per_frame_poses) if pf and fi < len(sampled_frames)]
                motion_tl_en = _build_motion_timeline_en(
                    tl_samples, dur_s, legs_visible=legs_truly_visible,
                    subject="" if len(rep_poses) <= 1 else "the leftmost person",
                )
            except Exception:
                motion_tl_en = []

        # Chỉ vẽ các đoạn xương và khớp thực sự nằm trong khung hình (visibility >= 0.45)
        for i_a, i_b in mp_edges:
            if lm[i_a].visibility < 0.45 or lm[i_b].visibility < 0.45:
                continue
            pa = (int(lm[i_a].x * orig_w), int(lm[i_a].y * orig_h))
            pb = (int(lm[i_b].x * orig_w), int(lm[i_b].y * orig_h))
            cv2.line(rep_frame, pa, pb, col_bgr, 3, cv2.LINE_AA)
        for j_idx in (0, 11, 12, 13, 14, 15, 16, 23, 24, 25, 26, 27, 28):
            if lm[j_idx].visibility < 0.45:
                continue
            jp = (int(lm[j_idx].x * orig_w), int(lm[j_idx].y * orig_h))
            cv2.circle(rep_frame, jp, 6, (255, 255, 255), -1, cv2.LINE_AA)
            cv2.circle(rep_frame, jp, 4, col_bgr, -1, cv2.LINE_AA)

        bx1, by1 = max(4, int(x1 * orig_w) - 18), max(4, int(y1 * orig_h) - 28)
        bx2, by2 = min(orig_w - 4, int(x2 * orig_w) + 18), min(orig_h - 4, int(y2 * orig_h) + 18)
        cv2.rectangle(rep_frame, (bx1, by1), (bx2, by2), col_bgr, 2, cv2.LINE_AA)
        label_tag = f"Nhan vat #{actor_num} ({zone_vi})"
        cv2.rectangle(rep_frame, (bx1, max(0, by1 - 24)), (min(orig_w, bx1 + 210), by1), col_bgr, -1)
        cv2.putText(rep_frame, label_tag, (bx1 + 6, max(16, by1 - 6)), cv2.FONT_HERSHEY_SIMPLEX, 0.50, (15, 20, 25), 2, cv2.LINE_AA)

        subjects_summary.append({
            "actor_id": actor_num,
            "actor_index": actor_num,
            "color_hex": col_hex,
            "zone": zone_vi,
            "zone_vi": zone_vi,
            "framing_vi": framing_vi,
            "detected_action_vi": act_vi,
            "action_code": act_code,
            "center_x": round(torso_x, 3),
            "center_y": round(torso_y, 3),
            "head_xy": [round(head_x, 3), round(head_y, 3)],
            "shoulders_xy": [round(sh_x, 3), round(sh_y, 3)],
            "body_xy": [round(torso_x, 3), round(torso_y, 3)],
            "rhand_xy": [round(rhand_x, 3), round(rhand_y, 3)],
            "lhand_xy": [round(lhand_x, 3), round(lhand_y, 3)],
            "bbox": [round(x1, 3), round(y1, 3), round(x2, 3), round(y2, 3)],
            "timeline_phases": timeline_phases,
            "motion_timeline_en": motion_tl_en,
        })

        if actor_num <= 3:
            suggested_pins.append({
                "slot": actor_num,
                "anchor": f"actor{actor_num}_body",
                "x": round(torso_x, 3),
                "y": round(torso_y, 3),
                "head_x": round(head_x, 3),
                "head_y": round(head_y, 3),
                "rhand_x": round(rhand_x, 3),
                "rhand_y": round(rhand_y, 3),
                "lhand_x": round(lhand_x, 3),
                "lhand_y": round(lhand_y, 3),
                "label_vi": f"Nhân vật #{actor_num} ({zone_vi} · {framing_vi})",
            })

    prev_h = 360
    prev_w = max(200, int(round(orig_w * (prev_h / max(orig_h, 1)))))
    rep_small = cv2.resize(rep_frame, (prev_w, prev_h), interpolation=cv2.INTER_AREA)
    ok_enc, buf = cv2.imencode(".jpg", rep_small, [int(cv2.IMWRITE_JPEG_QUALITY), 88])
    b64_preview = f"data:image/jpeg;base64,{base64.b64encode(buf.tobytes()).decode('ascii')}" if ok_enc else ""

    aspect_str = "9:16" if orig_h > orig_w * 1.15 else ("16:9" if orig_w > orig_h * 1.15 else "1:1")
    res_preset = "480x832" if aspect_str == "9:16" else ("640x640" if aspect_str == "1:1" else "832x480")
    main_action_label = subjects_summary[0]["detected_action_vi"] if subjects_summary else "Chuyển động tự nhiên"
    main_framing_label = subjects_summary[0]["framing_vi"] if subjects_summary else ""
    main_phases = subjects_summary[0].get("timeline_phases", []) if subjects_summary else []

    return {
        "ok": True,
        "width": orig_w,
        "height": orig_h,
        "aspect": aspect_str,
        "res_preset": res_preset,
        "duration": dur_s,
        "fps": round(fps_v, 2),
        "detected_person_count": len(subjects_summary),
        "detected_action_label": main_action_label,
        "detected_framing_label": main_framing_label,
        "timeline_phases": main_phases,
        "motion_timeline": (subjects_summary[0].get("motion_timeline_en") or []) if subjects_summary else [],
        "actors": subjects_summary,
        "subjects": subjects_summary,
        "suggested_pins": suggested_pins,
        "annotated_preview_b64": b64_preview,
        "summary_vi": (
            f"Phân tích {len(subjects_summary)} nhân vật trong video ({orig_w}×{orig_h}, {dur_s}s): "
            + ", ".join(f"Nhân vật #{s['actor_index']} ở {s['zone_vi']} — {s['framing_vi']} ({s['detected_action_vi']})" for s in subjects_summary)
            if subjects_summary else f"Video bối cảnh/vật thể ({orig_w}×{orig_h}, {dur_s}s)"
        ),
    }


def _extract_smart_subject_rgba(img_bgr_or_bgra) -> "np.ndarray":
    """Tách nền thông minh thích응 theo dải màu biên từng hàng (Row-Adaptive Border Color Modeling +
    Floodfill & Connected Components + Khử viền halo) giúp tách sạch 100% nền phòng chụp có gradient sáng/tối
    quanh cả phần thân lẫn đôi chân nhân vật."""
    import cv2
    import numpy as np

    if img_bgr_or_bgra is None:
        return np.zeros((64, 64, 4), dtype=np.uint8)
    h, w = img_bgr_or_bgra.shape[:2]
    if img_bgr_or_bgra.ndim == 3 and img_bgr_or_bgra.shape[2] == 4:
        alpha = img_bgr_or_bgra[:, :, 3]
        if int(alpha.min()) < 220:
            return img_bgr_or_bgra.copy()
        bgr = img_bgr_or_bgra[:, :, :3].copy()
    else:
        bgr = img_bgr_or_bgra[:, :, :3].copy()

    rgba = cv2.cvtColor(bgr, cv2.COLOR_BGR2BGRA)
    pad = max(3, min(12, min(h, w) // 20))

    # Kiểm tra độ đồng nhất của viền trái/phải và góc trên để nhận diện ảnh nhân vật/đạo cụ trên nền studio/đơn sắc
    left_strip = np.median(bgr[:, :pad, :].astype(np.float32), axis=1)      # (h, 3)
    right_strip = np.median(bgr[:, w - pad:, :].astype(np.float32), axis=1)  # (h, 3)
    top_strip = bgr[:pad, :, :].reshape(-1, 3).astype(np.float32)

    # Làm mượt dải màu nền theo chiều dọc để thích ứng với bóng đổ sàn studio ở phần chân
    k_vert = max(5, (h // 10) | 1)
    left_smooth = cv2.GaussianBlur(left_strip.reshape(h, 1, 3), (1, k_vert), 0).reshape(h, 3)
    right_smooth = cv2.GaussianBlur(right_strip.reshape(h, 1, 3), (1, k_vert), 0).reshape(h, 3)

    lr_diff = float(np.median(np.linalg.norm(left_smooth - right_smooth, axis=1)))
    left_grad_std = float(np.mean(np.std(np.diff(left_smooth, axis=0), axis=0)))
    right_grad_std = float(np.mean(np.std(np.diff(right_smooth, axis=0), axis=0)))

    # Nếu biên trái & biên phải tương đồng hoặc chuyển sắc mượt (ảnh thẻ / studio / nền phẳng)
    if lr_diff < 52.0 and max(left_grad_std, right_grad_std) < 8.5:
        xs = np.linspace(0.0, 1.0, w, dtype=np.float32)[None, :, None]  # (1, w, 3)
        bg_model = left_smooth[:, None, :] * (1.0 - xs) + right_smooth[:, None, :] * xs  # (h, w, 3)
        bg_u8 = np.clip(bg_model, 0, 255).astype(np.uint8)

        lab_img = cv2.cvtColor(bgr, cv2.COLOR_BGR2LAB).astype(np.float32)
        lab_bg = cv2.cvtColor(bg_u8, cv2.COLOR_BGR2LAB).astype(np.float32)
        ycc_img = cv2.cvtColor(bgr, cv2.COLOR_BGR2YCrCb).astype(np.float32)
        ycc_bg = cv2.cvtColor(bg_u8, cv2.COLOR_BGR2YCrCb).astype(np.float32)

        # Phân tách Sắc độ (Chroma LAB a,b + YCrCb Cr) và Độ sáng (Luminance L):
        # Bóng đổ trên sàn studio chỉ làm giảm L (~15..30) nhưng giữ nguyên Chroma (chroma_score < 3.6),
        # trong khi da chân/tay có nắng chiếu cùng độ sáng L với tường nhưng lệch sắc độ ấm (chroma_score >= 6.0).
        d_l = np.abs(lab_img[:, :, 0] - lab_bg[:, :, 0])
        d_ab = np.hypot(lab_img[:, :, 1] - lab_bg[:, :, 1], lab_img[:, :, 2] - lab_bg[:, :, 2])
        d_cr = np.abs(ycc_img[:, :, 1] - ycc_bg[:, :, 1])
        chroma_score = np.maximum(d_ab, d_cr * 0.85)

        bg_cand = ((chroma_score < 3.6) & (d_l < 34.0)).astype(np.uint8)
        border_seed = np.zeros((h, w), dtype=np.uint8)
        border_seed[:, :2] = 1
        border_seed[:, w - 2:] = 1
        border_seed[:2, :] = 1
        border_seed = border_seed & ((chroma_score < 6.0) & (d_l < 45.0)).astype(np.uint8)

        # 1. Loại bỏ toàn bộ vùng nền thông với mép khung hình
        union_bg = np.where((bg_cand > 0) | (border_seed > 0), 1, 0).astype(np.uint8)
        num_lbl, labels = cv2.connectedComponents(union_bg, connectivity=8)
        border_labels = np.unique(labels[border_seed > 0])
        border_labels = border_labels[border_labels > 0]
        is_bg = np.isin(labels, border_labels)

        # 2. Loại bỏ các hốc nền khép kín bên trong (giữa 2 chân hoặc hốc khuỷu tay chống hông)
        inner_bg_cand = ((~is_bg) & (chroma_score < 2.6) & (d_l < 18.0)).astype(np.uint8)
        inner_bg_cand[:int(h * 0.22), :] = 0  # Bảo vệ tuyệt đối vùng mặt/mắt
        if np.any(inner_bg_cand):
            n_in, lbl_in, stats_in, _ = cv2.connectedComponentsWithStats(inner_bg_cand, connectivity=8)
            for idx_in in range(1, n_in):
                if stats_in[idx_in, cv2.CC_STAT_AREA] >= 65:
                    is_bg |= (lbl_in == idx_in)

        fg_mask = np.where(is_bg, 0, 255).astype(np.uint8)

        # Lấp các lỗ thủng nhỏ bên trong chủ thể và giữ lại thành phần liên thông lớn nhất (nhân vật chính)
        kernel_close = cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (5, 5))
        fg_mask = cv2.morphologyEx(fg_mask, cv2.MORPH_CLOSE, kernel_close, iterations=2)
        num_fg, fg_labels, stats, _ = cv2.connectedComponentsWithStats(fg_mask, connectivity=8)
        if num_fg > 1:
            areas = stats[1:, cv2.CC_STAT_AREA]
            max_area = int(np.max(areas)) if len(areas) else 0
            keep = np.zeros_like(fg_mask)
            for lbl_i in range(1, num_fg):
                if stats[lbl_i, cv2.CC_STAT_AREA] >= max(64, int(max_area * 0.08)):
                    keep[fg_labels == lbl_i] = 255
            fg_mask = keep

        # Co nhẹ 1px ở biên rồi làm mượt Alpha + khử ám màu nền ở viền
        fg_eroded = cv2.erode(fg_mask, np.ones((3, 3), np.uint8), iterations=1)
        fg_alpha = cv2.GaussianBlur(fg_eroded, (3, 3), 0)

        edge_band = (fg_alpha > 8) & (fg_alpha < 245)
        if np.any(edge_band):
            inner_bgr = cv2.erode(bgr, np.ones((3, 3), np.uint8), iterations=2)
            rgba_bgr = rgba[:, :, :3]
            rgba_bgr[edge_band] = inner_bgr[edge_band]
            rgba[:, :, :3] = rgba_bgr

        rgba[:, :, 3] = fg_alpha
        return rgba

    # Fallback cho ảnh có nền phức tạp: Floodfill từ 4 góc
    top_med = np.median(top_strip, axis=0)
    top_std = float(np.mean(np.std(top_strip, axis=0)))
    if top_std < 42.0:
        ff_mask = np.zeros((h + 2, w + 2), dtype=np.uint8)
        tol = (32, 32, 32)
        flags = 4 | (255 << 8) | cv2.FLOODFILL_MASK_ONLY | cv2.FLOODFILL_FIXED_RANGE
        work = bgr.copy()
        for sx, sy in ((1, 1), (w - 2, 1), (1, h - 2), (w - 2, h - 2), (w // 2, 1)):
            if 0 <= sx < w and 0 <= sy < h:
                diff = float(np.linalg.norm(work[sy, sx].astype(np.float32) - top_med))
                if diff < 55.0:
                    try:
                        cv2.floodFill(work, ff_mask, (sx, sy), 0, tol, tol, flags)
                    except Exception:
                        pass
        bg_region = ff_mask[1:-1, 1:-1]
        fg_alpha = np.where(bg_region > 0, 0, 255).astype(np.uint8)
        fg_alpha = cv2.GaussianBlur(fg_alpha, (3, 3), 0)
        rgba[:, :, 3] = fg_alpha
    return rgba


def _build_character_puppet_rig(cutout_rgba: "np.ndarray") -> dict | None:
    """Phân tích giải phẫu 2D từ ảnh nhân vật đã tách nền (cutout_rgba) để tạo bộ Rig Con Rối Khớp Xương
    (Articulated Character Puppet Rig) gồm:
      - Khớp chuẩn 2D trên ảnh gốc (head, neck, l/r_shoulder, l/r_elbow, l/r_wrist, l/r_hip, l/r_knee, l/r_ankle)
      - Lớp thân chính đã khử cánh tay thừa, xóa túi xách treo ngoài hông & tự động inpaint vùng bàn tay đặt đè lên váy (body_base_rgba)
      - 4 đoạn cánh tay rời có khớp xoay tròn mượt (l_upper, l_fore, r_upper, r_fore) lọc chuẩn màu da/ống tay
    Nhờ đó khi gắn lên Khung Xương 3D, nhân vật thật sẽ thay thế hoàn toàn khung xương và cử động tay/vai/thân/chân mượt mà!"""
    import cv2
    import numpy as np

    if cutout_rgba is None or cutout_rgba.ndim != 3 or cutout_rgba.shape[2] != 4:
        return None
    h, w = cutout_rgba.shape[:2]
    if h < 48 or w < 32:
        return None

    alpha = cutout_rgba[:, :, 3]
    ys, xs = np.where(alpha > 32)
    if len(xs) < 120:
        return None

    x_min, x_max = int(xs.min()), int(xs.max())
    y_min, y_max = int(ys.min()), int(ys.max())
    subj_w = max(16.0, float(x_max - x_min))
    subj_h = max(32.0, float(y_max - y_min))
    cx_subj = 0.5 * (x_min + x_max)

    bgr_clean = cutout_rgba[:, :, :3].copy()
    a_f = (alpha.astype(np.float32) / 255.0)[:, :, None]
    neutral_bg = np.full_like(bgr_clean, 215, dtype=np.uint8)
    comp_for_pose = np.clip(bgr_clean.astype(np.float32) * a_f + neutral_bg.astype(np.float32) * (1.0 - a_f), 0, 255).astype(np.uint8)

    pts = {}
    try:
        det = _detect_poses_hybrid([comp_for_pose], max_poses=1)
        if det and det[0]:
            ilm, _ = det[0][0]
            def _px(idx_lm: int) -> np.ndarray:
                return np.array([float(ilm[idx_lm].x) * w, float(ilm[idx_lm].y) * h], dtype=np.float32)

            pts["head"] = _px(0)
            pts["l_shoulder"] = _px(11)
            pts["r_shoulder"] = _px(12)
            pts["neck"] = 0.5 * (pts["l_shoulder"] + pts["r_shoulder"]) + np.array([0.0, -0.025 * subj_h], dtype=np.float32)
            pts["l_elbow"] = _px(13)
            pts["r_elbow"] = _px(14)
            pts["l_wrist"] = _px(15)
            pts["r_wrist"] = _px(16)
            pts["l_hip"] = _px(23)
            pts["r_hip"] = _px(24)
            pts["l_knee"] = _px(25)
            pts["r_knee"] = _px(26)
            pts["l_ankle"] = _px(27)
            pts["r_ankle"] = _px(28)
    except Exception:
        pts = {}

    if "l_shoulder" not in pts or "r_shoulder" not in pts:
        pts = {
            "head": np.array([cx_subj, y_min + 0.11 * subj_h], dtype=np.float32),
            "neck": np.array([cx_subj, y_min + 0.18 * subj_h], dtype=np.float32),
            "l_shoulder": np.array([cx_subj + 0.16 * subj_w, y_min + 0.21 * subj_h], dtype=np.float32),
            "r_shoulder": np.array([cx_subj - 0.16 * subj_w, y_min + 0.21 * subj_h], dtype=np.float32),
            "l_elbow": np.array([cx_subj + 0.23 * subj_w, y_min + 0.36 * subj_h], dtype=np.float32),
            "r_elbow": np.array([cx_subj - 0.23 * subj_w, y_min + 0.36 * subj_h], dtype=np.float32),
            "l_wrist": np.array([cx_subj + 0.20 * subj_w, y_min + 0.48 * subj_h], dtype=np.float32),
            "r_wrist": np.array([cx_subj - 0.20 * subj_w, y_min + 0.48 * subj_h], dtype=np.float32),
            "l_hip": np.array([cx_subj + 0.11 * subj_w, y_min + 0.50 * subj_h], dtype=np.float32),
            "r_hip": np.array([cx_subj - 0.11 * subj_w, y_min + 0.50 * subj_h], dtype=np.float32),
            "l_knee": np.array([cx_subj + 0.10 * subj_w, y_min + 0.73 * subj_h], dtype=np.float32),
            "r_knee": np.array([cx_subj - 0.10 * subj_w, y_min + 0.73 * subj_h], dtype=np.float32),
            "l_ankle": np.array([cx_subj + 0.09 * subj_w, y_min + 0.94 * subj_h], dtype=np.float32),
            "r_ankle": np.array([cx_subj - 0.09 * subj_w, y_min + 0.94 * subj_h], dtype=np.float32),
        }

    # Chuẩn hóa thứ tự ngang của hông, đầu gối, cổ chân đồng nhất với chiều vai (l_shoulder vs r_shoulder)
    # để lưới cơ thể không bao giờ bị xoắn chéo khi người mẫu bắt chéo chân trong ảnh gốc
    sh_sign = 1.0 if pts["l_shoulder"][0] >= pts["r_shoulder"][0] else -1.0
    sh_width = max(24.0, float(np.linalg.norm(pts["l_shoulder"] - pts["r_shoulder"])))
    for pair_l, pair_r, min_span_ratio in (("l_hip", "r_hip", 0.58), ("l_knee", "r_knee", 0.44), ("l_ankle", "r_ankle", 0.38)):
        mid_p = 0.5 * (pts[pair_l] + pts[pair_r])
        cur_span = abs(float(pts[pair_l][0] - pts[pair_r][0]))
        half_span = 0.5 * max(cur_span, sh_width * min_span_ratio)
        pts[pair_l] = np.array([mid_p[0] + sh_sign * half_span, mid_p[1]], dtype=np.float32)
        pts[pair_r] = np.array([mid_p[0] - sh_sign * half_span, mid_p[1]], dtype=np.float32)

    arm_radius = max(9, int(round(sh_width * 0.26)))

    # Lấy mẫu màu trang phục thân chính (ngực/bụng) để phân biệt với màu da cánh tay và túi xách
    sh_mid_y = int(round(0.5 * (pts["l_shoulder"][1] + pts["r_shoulder"][1])))
    hip_mid_y = int(round(0.5 * (pts["l_hip"][1] + pts["r_hip"][1])))
    torso_cx = int(round(0.25 * (pts["l_shoulder"][0] + pts["r_shoulder"][0] + pts["l_hip"][0] + pts["r_hip"][0])))
    ty0 = max(0, min(h - 1, sh_mid_y + int(0.18 * (hip_mid_y - sh_mid_y))))
    ty1 = max(ty0 + 4, min(h, sh_mid_y + int(0.68 * (hip_mid_y - sh_mid_y))))
    tx0 = max(0, torso_cx - max(6, int(sh_width * 0.16)))
    tx1 = min(w, torso_cx + max(6, int(sh_width * 0.16)))
    torso_patch = bgr_clean[ty0:ty1, tx0:tx1]
    torso_valid = alpha[ty0:ty1, tx0:tx1] > 180
    dress_med_bgr = np.median(torso_patch[torso_valid].astype(np.float32), axis=0) if np.any(torso_valid) else np.array([60.0, 40.0, 120.0], dtype=np.float32)

    # Lấy mẫu màu da từ vùng cổ + bắp tay thực tế (bao gồm cả vùng da sáng nắng và da trong bóng râm)
    neck_y = int(round(pts["neck"][1]))
    neck_x = int(round(pts["neck"][0]))
    ny0, ny1 = max(0, neck_y - int(sh_width * 0.20)), min(h, neck_y + int(sh_width * 0.15))
    nx0, nx1 = max(0, neck_x - int(sh_width * 0.16)), min(w, neck_x + int(sh_width * 0.16))
    neck_patch = bgr_clean[ny0:ny1, nx0:nx1]
    neck_valid = alpha[ny0:ny1, nx0:nx1] > 180
    skin_med_bgr = np.median(neck_patch[neck_valid].astype(np.float32), axis=0) if np.any(neck_valid) else np.array([165.0, 185.0, 215.0], dtype=np.float32)
    skin_dress_dist = float(np.linalg.norm(skin_med_bgr - dress_med_bgr))

    def _extract_clean_limb_rgba(p_start: np.ndarray, p_end: np.ndarray, extend_end: float = 0.0, radius: int = 12) -> tuple["np.ndarray", "np.ndarray", np.ndarray, int]:
        """Trích xuất lớp RGBA mượt mà của một đoạn cánh tay dọc theo trục p_start -> p_end
        bằng ống trụ giải phẫu thuôn mượt (Smooth Tapered Capsule) kết hợp khử dây túi/váy lấn vào da."""
        vec = p_end - p_start
        seg_len = max(1.0, float(np.linalg.norm(vec)))
        p_tip = p_end + (vec / seg_len) * (seg_len * extend_end) if extend_end > 0 else p_end.copy()

        # Tạo ống trụ cánh tay thuôn mượt (không dùng mặt nạ cắt răng cưa theo mắt xích dây túi)
        cap_mask = np.zeros((h, w), dtype=np.uint8)
        r_start = max(6, int(round(radius * 0.78)))
        r_end = max(5, int(round(radius * (0.64 if extend_end > 0 else 0.70))))
        n_steps = max(12, int(round(seg_len / 3.0)))
        for s_i in range(n_steps + 1):
            t_s = float(s_i) / float(n_steps)
            pt_s = p_start * (1.0 - t_s) + p_tip * t_s
            rad_s = int(round(r_start * (1.0 - t_s) + r_end * t_s))
            cv2.circle(cap_mask, (int(round(pt_s[0])), int(round(pt_s[1]))), rad_s, 255, -1, cv2.LINE_AA)

        limb_alpha = cv2.bitwise_and(alpha, cv2.GaussianBlur(cap_mask, (5, 5), 0))
        limb_rgba = cutout_rgba.copy()
        limb_rgba[:, :, 3] = limb_alpha

        # Khử mượt phần dây túi xách hoặc góc váy đỏ đô lấn vào bên trong ống trụ cánh tay (giữ nguyên biên tròn mượt của cánh tay)
        arm_px = limb_alpha > 32
        valid_px_count = int(np.count_nonzero(arm_px))
        if valid_px_count > 40:
            arm_bgr = limb_rgba[:, :, :3].astype(np.float32)
            arm_luma = 0.114 * arm_bgr[:, :, 0] + 0.587 * arm_bgr[:, :, 1] + 0.299 * arm_bgr[:, :, 2]
            dist_dress = np.linalg.norm(arm_bgr - dress_med_bgr[None, None, :], axis=2)
            good_skin = arm_px & (arm_luma > 95.0) & (dist_dress > 58.0)
            valid_px_count = int(np.count_nonzero(good_skin))
            if valid_px_count > 30:
                med_arm_skin = np.median(arm_bgr[good_skin], axis=0)
                bad_px = arm_px & ((arm_luma < 92.0) | (dist_dress <= 58.0) | (np.linalg.norm(arm_bgr - med_arm_skin[None, None, :], axis=2) > 68.0))
                if np.any(bad_px):
                    bad_u8 = cv2.dilate(bad_px.astype(np.uint8) * 255, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (5, 5)), iterations=1)
                    ys_b, xs_b = np.where(arm_px)
                    y0_b, y1_b = max(0, int(ys_b.min()) - 2), min(h, int(ys_b.max()) + 3)
                    x0_b, x1_b = max(0, int(xs_b.min()) - 2), min(w, int(xs_b.max()) + 3)
                    for ry in range(y0_b, y1_b):
                        row_bad = bad_u8[ry, x0_b:x1_b] > 0
                        if not np.any(row_bad):
                            continue
                        row_good = good_skin[ry, x0_b:x1_b] & (~row_bad)
                        fill_c = np.median(arm_bgr[ry, x0_b:x1_b][row_good], axis=0) if np.count_nonzero(row_good) >= 3 else med_arm_skin
                        arm_bgr[ry, x0_b:x1_b][row_bad] = fill_c
                    sub_u8 = np.clip(arm_bgr[y0_b:y1_b, x0_b:x1_b], 0, 255).astype(np.uint8)
                    sub_blur = cv2.GaussianBlur(sub_u8, (5, 5), 0)
                    bm = (cv2.GaussianBlur(bad_u8[y0_b:y1_b, x0_b:x1_b], (5, 5), 0).astype(np.float32) / 255.0)[:, :, None]
                    limb_rgba[y0_b:y1_b, x0_b:x1_b, :3] = np.clip(sub_u8.astype(np.float32) * (1.0 - bm) + sub_blur.astype(np.float32) * bm, 0, 255).astype(np.uint8)

        return limb_rgba, cap_mask, p_tip, valid_px_count

    l_upper_rgba, l_up_mask, _, l_up_cnt = _extract_clean_limb_rgba(pts["l_shoulder"], pts["l_elbow"], extend_end=0.0, radius=arm_radius)
    l_fore_rgba, l_fo_mask, l_tip, l_fo_cnt = _extract_clean_limb_rgba(pts["l_elbow"], pts["l_wrist"], extend_end=0.36, radius=int(round(arm_radius * 0.92)))
    r_upper_rgba, r_up_mask, _, r_up_cnt = _extract_clean_limb_rgba(pts["r_shoulder"], pts["r_elbow"], extend_end=0.0, radius=arm_radius)
    r_fore_rgba, r_fo_mask, r_tip, r_fo_cnt = _extract_clean_limb_rgba(pts["r_elbow"], pts["r_wrist"], extend_end=0.36, radius=int(round(arm_radius * 0.92)))
    pts["l_hand_tip"] = l_tip
    pts["r_hand_tip"] = r_tip

    r_upper_src_a, r_upper_src_b = pts["r_shoulder"].copy(), pts["r_elbow"].copy()
    l_upper_src_a, l_upper_src_b = pts["l_shoulder"].copy(), pts["l_elbow"].copy()
    r_fore_src_a, r_fore_src_b = pts["r_elbow"].copy(), pts["r_hand_tip"].copy()
    l_fore_src_a, l_fore_src_b = pts["l_elbow"].copy(), pts["l_hand_tip"].copy()

    if l_up_cnt > r_up_cnt * 1.35 and l_up_cnt > 120:
        r_upper_rgba = l_upper_rgba
        r_upper_src_a, r_upper_src_b = l_upper_src_a, l_upper_src_b
    elif r_up_cnt > l_up_cnt * 1.35 and r_up_cnt > 120:
        l_upper_rgba = r_upper_rgba
        l_upper_src_a, l_upper_src_b = r_upper_src_a, r_upper_src_b

    if l_fo_cnt > r_fo_cnt * 1.35 and l_fo_cnt > 100:
        r_fore_rgba = l_fore_rgba
        r_fore_src_a, r_fore_src_b = l_fore_src_a, l_fore_src_b
    elif r_fo_cnt > l_fo_cnt * 1.35 and r_fo_cnt > 100:
        l_fore_rgba = r_fore_rgba
        l_fore_src_a, l_fore_src_b = r_fore_src_a, r_fore_src_b

    # Xây dựng đa giác bảo vệ phần Đầu/Tóc + Thân Váy + Chân (cắt sát dây vai đầm để không thừa mấu bắp vai tĩnh)
    l_sh_x, r_sh_x = float(pts["l_shoulder"][0]), float(pts["r_shoulder"][0])
    l_hip_x, r_hip_x = float(pts["l_hip"][0]), float(pts["r_hip"][0])
    knee_mid_y = int(round(0.5 * (pts["l_knee"][1] + pts["r_knee"][1])))
    neck_top_y = max(0, int(round(pts["neck"][1] - 0.04 * subj_h)))

    body_poly = np.array([
        [int(round(l_sh_x + sh_sign * 0.12 * sh_width)), y_min],
        [int(round(r_sh_x - sh_sign * 0.22 * sh_width)), y_min],
        [int(round(r_sh_x - sh_sign * 0.16 * sh_width)), neck_top_y],
        [int(round(r_sh_x + sh_sign * 0.02 * sh_width)), sh_mid_y],
        [int(round(r_hip_x - sh_sign * 0.14 * sh_width)), hip_mid_y],
        [int(round(r_hip_x - sh_sign * 0.20 * sh_width)), knee_mid_y],
        [int(round(pts["r_ankle"][0] - sh_sign * 0.35 * sh_width)), int(round(y_max))],
        [int(round(pts["l_ankle"][0] + sh_sign * 0.35 * sh_width)), int(round(y_max))],
        [int(round(l_hip_x + sh_sign * 0.20 * sh_width)), knee_mid_y],
        [int(round(l_hip_x + sh_sign * 0.14 * sh_width)), hip_mid_y],
        [int(round(l_sh_x - sh_sign * 0.06 * sh_width)), sh_mid_y],
        [int(round(l_sh_x + sh_sign * 0.06 * sh_width)), neck_top_y],
    ], dtype=np.int32)
    torso_protect = np.zeros((h, w), dtype=np.uint8)
    cv2.fillPoly(torso_protect, [body_poly], 255)

    body_base_rgba = cutout_rgba.copy()
    outside_torso = cv2.bitwise_not(torso_protect)
    outside_torso[min(h, knee_mid_y):, :] = 0
    rem_blur = cv2.GaussianBlur(outside_torso, (7, 7), 0).astype(np.float32) / 255.0
    body_base_rgba[:, :, 3] = np.clip(body_base_rgba[:, :, 3].astype(np.float32) * (1.0 - rem_blur), 0, 255).astype(np.uint8)

    # Trong vùng thân váy (từ dưới ngực tới đùi trên), bất kỳ pixel nào không phải màu váy (bàn tay đặt lên đầm, dây túi xách, khe sáng tay)
    # đều được lấp mượt bằng màu đầm cùng hàng ngang để thân váy liền lạc 100%
    if skin_dress_dist > 45.0:
        hand_zone_y0 = max(0, int(round(sh_mid_y + 0.22 * (hip_mid_y - sh_mid_y))))
        hand_zone_y1 = min(h, int(round(hip_mid_y + 0.42 * (knee_mid_y - hip_mid_y))))
        if hand_zone_y1 > hand_zone_y0 + 8:
            sub_bgr = body_base_rgba[hand_zone_y0:hand_zone_y1, :, :3].astype(np.float32)
            sub_a = body_base_rgba[hand_zone_y0:hand_zone_y1, :, 3]
            d_d = np.linalg.norm(sub_bgr - dress_med_bgr[None, None, :], axis=2)
            non_dress_on_torso = (sub_a > 80) & (d_d > 52.0)
            hand_mask_u8 = cv2.dilate(non_dress_on_torso.astype(np.uint8) * 255, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (9, 9)), iterations=1)
            for ry in range(hand_zone_y1 - hand_zone_y0):
                row_m = hand_mask_u8[ry] > 0
                if not np.any(row_m):
                    continue
                dress_cols = (sub_a[ry] > 180) & (~row_m) & (d_d[ry] <= 52.0)
                if np.count_nonzero(dress_cols) >= 5:
                    fill_c = np.median(sub_bgr[ry, dress_cols], axis=0)
                else:
                    fill_c = dress_med_bgr
                sub_bgr[ry, row_m] = fill_c
            sub_bgr_u8 = np.clip(sub_bgr, 0, 255).astype(np.uint8)
            sub_bgr_u8 = cv2.GaussianBlur(sub_bgr_u8, (5, 5), 0)
            blend_m = (cv2.GaussianBlur(hand_mask_u8, (7, 7), 0).astype(np.float32) / 255.0)[:, :, None]
            orig_sub = body_base_rgba[hand_zone_y0:hand_zone_y1, :, :3].astype(np.float32)
            body_base_rgba[hand_zone_y0:hand_zone_y1, :, :3] = np.clip(orig_sub * (1.0 - blend_m) + sub_bgr_u8.astype(np.float32) * blend_m, 0, 255).astype(np.uint8)
            # Làm đầy alpha ở sát biên eo nơi cẳng tay từng cắt qua đầm để không còn vệt khuyết trắng
            for ry in range(hand_zone_y1 - hand_zone_y0):
                valid_x = np.where((sub_a[ry] > 180) & (d_d[ry] <= 60.0))[0]
                if len(valid_x) >= 12:
                    x_left_edge, x_right_edge = int(valid_x.min()), int(valid_x.max())
                    sub_a[ry, x_left_edge:x_right_edge + 1] = np.maximum(sub_a[ry, x_left_edge:x_right_edge + 1], 255)
            body_base_rgba[hand_zone_y0:hand_zone_y1, :, 3] = sub_a

    return {
        "w": w,
        "h": h,
        "bbox": (x_min, y_min, x_max, y_max),
        "pts": pts,
        "arm_radius": arm_radius,
        "full_cutout_rgba": cutout_rgba,
        "body_base_rgba": body_base_rgba,
        "l_upper_rgba": l_upper_rgba,
        "l_fore_rgba": l_fore_rgba,
        "r_upper_rgba": r_upper_rgba,
        "r_fore_rgba": r_fore_rgba,
        "r_upper_src": (r_upper_src_a, r_upper_src_b),
        "l_upper_src": (l_upper_src_a, l_upper_src_b),
        "r_fore_src": (r_fore_src_a, r_fore_src_b),
        "l_fore_src": (l_fore_src_a, l_fore_src_b),
    }


def _alpha_blend_rgba_onto_bgr(dst_bgr: "np.ndarray", src_rgba: "np.ndarray") -> None:
    """Trộn mượt một lớp RGBA có cùng kích thước (H, W, 4) lên khung hình BGR tại chỗ."""
    import numpy as np

    a = src_rgba[:, :, 3]
    ys, xs = np.where(a > 4)
    if len(xs) == 0:
        return
    x0, x1 = int(xs.min()), int(xs.max()) + 1
    y0, y1 = int(ys.min()), int(ys.max()) + 1
    sub_rgba = src_rgba[y0:y1, x0:x1]
    alpha_f = (sub_rgba[:, :, 3:4].astype(np.float32)) / 255.0
    roi = dst_bgr[y0:y1, x0:x1].astype(np.float32)
    dst_bgr[y0:y1, x0:x1] = np.clip(roi * (1.0 - alpha_f) + sub_rgba[:, :, :3].astype(np.float32) * alpha_f, 0, 255).astype(np.uint8)


def _warp_limb_segment_rgba(
    dst_bgr: "np.ndarray",
    limb_rgba: "np.ndarray",
    src_a: "np.ndarray",
    src_b: "np.ndarray",
    dst_a: "np.ndarray",
    dst_b: "np.ndarray",
    src_radius: float,
) -> None:
    """Biến đổi tương tự (Similarity / Affine Transform) một đoạn cánh tay từ (src_a -> src_b)
    sang vị trí khớp xương đích (dst_a -> dst_b) với đầu khớp bo tròn tự nhiên."""
    import cv2
    import numpy as np

    h_d, w_d = dst_bgr.shape[:2]
    v_src = src_b - src_a
    v_dst = dst_b - dst_a
    len_src = float(np.linalg.norm(v_src))
    len_dst = float(np.linalg.norm(v_dst))
    if len_src < 4.0 or len_dst < 4.0:
        return

    u_src = v_src / len_src
    n_src = np.array([-u_src[1], u_src[0]], dtype=np.float32)
    u_dst = v_dst / len_dst
    n_dst = np.array([-u_dst[1], u_dst[0]], dtype=np.float32)

    scale_len = len_dst / len_src
    scale_thick = float(np.clip(scale_len, 0.72 * scale_len, 1.25 * scale_len))

    p_src = np.array([
        src_a,
        src_b,
        src_a + n_src * src_radius,
    ], dtype=np.float32)
    p_dst = np.array([
        dst_a,
        dst_b,
        dst_a + n_dst * (src_radius * scale_thick),
    ], dtype=np.float32)

    M = cv2.getAffineTransform(p_src, p_dst)
    warped = cv2.warpAffine(
        limb_rgba, M, (w_d, h_d),
        flags=cv2.INTER_LINEAR,
        borderMode=cv2.BORDER_CONSTANT,
        borderValue=(0, 0, 0, 0),
    )
    _alpha_blend_rgba_onto_bgr(dst_bgr, warped)


def _warp_character_puppet_to_skeleton(
    canvas_bgr: "np.ndarray",
    puppet_rig: dict,
    target_px_map: dict[str, tuple[float, float]],
    scale_mult: float = 1.0,
) -> tuple[int, int, int, int]:
    """Biến hình & gắn trực tiếp Nhân Vật Thật (Ribbon-Quad Body Mesh + Articulated Arms) vào đúng vị trí
    các khớp xương 2D của Khung Xương trên từng khung hình video (thay thế hoàn toàn khung xương que)."""
    import cv2
    import numpy as np

    h_c, w_c = canvas_bgr.shape[:2]
    src_pts = puppet_rig["pts"]
    src_w, src_h = puppet_rig["w"], puppet_rig["h"]

    def _g(name: str, fallback: tuple[float, float]) -> np.ndarray:
        p = target_px_map.get(name, fallback)
        return np.array([float(p[0]), float(p[1])], dtype=np.float32)

    t_head = _g("head", (w_c * 0.5, h_c * 0.24))
    t_l_sh = _g("left_shoulder", (w_c * 0.56, h_c * 0.36))
    t_r_sh = _g("right_shoulder", (w_c * 0.44, h_c * 0.36))
    t_neck = _g("neck", (0.5 * (t_l_sh[0] + t_r_sh[0]), 0.5 * (t_l_sh[1] + t_r_sh[1]) - 12.0))
    t_l_el = _g("left_elbow", (t_l_sh[0] + 24.0, t_l_sh[1] + 55.0))
    t_r_el = _g("right_elbow", (t_r_sh[0] - 24.0, t_r_sh[1] + 55.0))
    t_l_wr = _g("left_wrist", (t_l_el[0] + 12.0, t_l_el[1] + 50.0))
    t_r_wr = _g("right_wrist", (t_r_el[0] - 12.0, t_r_el[1] + 50.0))
    t_l_hip = _g("left_hip", (w_c * 0.54, h_c * 0.62))
    t_r_hip = _g("right_hip", (w_c * 0.46, h_c * 0.62))
    t_l_kn = _g("left_knee", (t_l_hip[0], t_l_hip[1] + 95.0))
    t_r_kn = _g("right_knee", (t_r_hip[0], t_r_hip[1] + 95.0))
    t_l_ank = _g("left_ankle", (t_l_kn[0], t_l_kn[1] + 95.0))
    t_r_ank = _g("right_ankle", (t_r_kn[0], t_r_kn[1] + 95.0))

    chest_c = 0.5 * (0.5 * (t_l_sh + t_r_sh) + 0.5 * (t_l_hip + t_r_hip))
    if abs(scale_mult - 1.0) > 1e-3:
        for arr in (t_head, t_neck, t_l_sh, t_r_sh, t_l_el, t_r_el, t_l_wr, t_r_wr, t_l_hip, t_r_hip, t_l_kn, t_r_kn, t_l_ank, t_r_ank):
            arr[:] = chest_c + (arr - chest_c) * scale_mult

    src_sh_sign = 1.0 if (src_pts["l_shoulder"][0] >= src_pts["r_shoulder"][0]) else -1.0
    dst_sh_vec = t_l_sh - t_r_sh
    if (dst_sh_vec[0] * src_sh_sign) < 16.0:
        sh_mid = 0.5 * (t_l_sh + t_r_sh)
        half_w = max(18.0, 0.5 * float(np.linalg.norm(dst_sh_vec)))
        t_l_sh = np.array([sh_mid[0] + src_sh_sign * half_w, t_l_sh[1]], dtype=np.float32)
        t_r_sh = np.array([sh_mid[0] - src_sh_sign * half_w, t_r_sh[1]], dtype=np.float32)

    s_sh_mid = 0.5 * (src_pts["l_shoulder"] + src_pts["r_shoulder"])
    s_hip_mid = 0.5 * (src_pts["l_hip"] + src_pts["r_hip"])
    s_kn_mid = 0.5 * (src_pts["l_knee"] + src_pts["r_knee"])
    s_ank_mid = 0.5 * (src_pts["l_ankle"] + src_pts["r_ankle"])

    t_sh_mid = 0.5 * (t_l_sh + t_r_sh)
    t_hip_mid = 0.5 * (t_l_hip + t_r_hip)

    src_torso_len = max(24.0, float(np.linalg.norm(s_hip_mid - s_sh_mid)))
    dst_torso_len = max(24.0, float(np.linalg.norm(t_hip_mid - t_sh_mid)))
    src_sh_w = max(20.0, float(np.linalg.norm(src_pts["l_shoulder"] - src_pts["r_shoulder"])))
    dst_sh_w = max(20.0, float(np.linalg.norm(t_l_sh - t_r_sh)))

    body_scale = float(np.clip(0.55 * (dst_torso_len / src_torso_len) + 0.45 * (dst_sh_w / src_sh_w), 0.35, 2.8))

    # Đảm bảo hông có độ rộng tỷ lệ thuận với vai và chiều dài thân (không bị phình to hay bóp méo váy)
    hip_half_vec_s = 0.5 * (src_pts["l_hip"] - src_pts["r_hip"])
    hip_half_vec_d = hip_half_vec_s * body_scale
    t_l_hip = t_hip_mid + hip_half_vec_d
    t_r_hip = t_hip_mid - hip_half_vec_d

    # Nếu là góc máy Trung cảnh / Bán thân (hông nằm thấp hoặc cổ chân chạm đáy khung hình),
    # chiếu thẳng trục chân xuống dưới theo đúng tỷ lệ giải phẫu gốc để tà váy & đùi không bị dồn cục hay rách tam giác ở đáy!
    t_kn_mid_raw = 0.5 * (t_l_kn + t_r_kn)
    t_ank_mid_raw = 0.5 * (t_l_ank + t_r_ank)
    is_medium_shot = (t_hip_mid[1] > h_c * 0.56) or (max(t_l_ank[1], t_r_ank[1]) > h_c * 0.92)
    if is_medium_shot:
        t_kn_mid = t_hip_mid + (s_kn_mid - s_hip_mid) * body_scale
        t_ank_mid = t_hip_mid + (s_ank_mid - s_hip_mid) * body_scale
    else:
        t_kn_mid = t_kn_mid_raw
        t_ank_mid = t_ank_mid_raw

    kn_half_vec_s = 0.5 * (src_pts["l_knee"] - src_pts["r_knee"])
    kn_half_vec_d = kn_half_vec_s * body_scale
    t_l_kn = t_kn_mid + kn_half_vec_d
    t_r_kn = t_kn_mid - kn_half_vec_d

    ank_half_vec_s = 0.5 * (src_pts["l_ankle"] - src_pts["r_ankle"])
    ank_half_vec_d = ank_half_vec_s * body_scale
    t_l_ank = t_ank_mid + ank_half_vec_d
    t_r_ank = t_ank_mid - ank_half_vec_d

    # 1. Vùng Đầu & Mái Tóc: biến đổi cứng đồng dạng (Similarity) từ cổ -> đầu
    s_neck = src_pts["neck"]
    s_head = src_pts["head"]
    s_head_vec = s_head - s_neck
    s_head_dist = max(12.0, float(np.linalg.norm(s_head_vec)))
    head_scale = body_scale
    d_head_dir = t_head - t_neck
    d_head_norm = float(np.linalg.norm(d_head_dir))
    if d_head_norm < 4.0:
        d_head_unit = np.array([0.0, -1.0], dtype=np.float32)
    else:
        d_head_unit = d_head_dir / d_head_norm
    d_head_unit = np.array([float(np.clip(d_head_unit[0], -0.38, 0.38)), -max(0.88, abs(float(d_head_unit[1])))], dtype=np.float32)
    d_head_unit /= max(1e-6, float(np.linalg.norm(d_head_unit)))
    d_head_right = np.array([-d_head_unit[1], d_head_unit[0]], dtype=np.float32) * src_sh_sign

    s_head_up = np.array([0.0, -s_head_dist], dtype=np.float32)
    s_head_r = np.array([s_head_dist, 0.0], dtype=np.float32) * src_sh_sign

    def _map_head_pt(dx_mult: float, dy_mult: float) -> tuple[np.ndarray, np.ndarray]:
        sp = s_neck + s_head_r * dx_mult + s_head_up * dy_mult
        dp = t_neck + (d_head_right * dx_mult + d_head_unit * dy_mult) * (s_head_dist * head_scale)
        return sp, dp

    h_tl_s, h_tl_d = _map_head_pt(-1.45, 2.35)
    h_tr_s, h_tr_d = _map_head_pt(1.45, 2.35)
    h_ml_s, h_ml_d = _map_head_pt(-1.45, 0.25)
    h_mr_s, h_mr_d = _map_head_pt(1.45, 0.25)

    # Lưới Ribbon-Quad 21 đỉnh (4 cột đồng nhất từ Vai -> Hông -> Đầu Gối -> Cổ Chân) không bao giờ bị rách hay lật tam giác
    sh_out_s = (src_pts["l_shoulder"] - src_pts["r_shoulder"]) * 0.55
    sh_out_d = (t_l_sh - t_r_sh) * 0.55
    hip_out_s = (src_pts["l_hip"] - src_pts["r_hip"]) * 0.65
    hip_out_d = (t_l_hip - t_r_hip) * 0.65
    kn_out_s = (src_pts["l_knee"] - src_pts["r_knee"]) * 0.75
    kn_out_d = (t_l_kn - t_r_kn) * 0.75
    ank_out_s = (src_pts["l_ankle"] - src_pts["r_ankle"]) * 0.85
    ank_out_d = (t_l_ank - t_r_ank) * 0.85

    foot_drop_s = np.array([0.0, max(18.0, (src_h - max(src_pts["l_ankle"][1], src_pts["r_ankle"][1])) + 10.0)], dtype=np.float32)
    foot_drop_d = foot_drop_s * body_scale

    ctrl_src = np.array([
        h_tl_s,                                         # 0
        h_tr_s,                                         # 1
        h_ml_s,                                         # 2
        s_neck,                                         # 3
        h_mr_s,                                         # 4
        src_pts["r_shoulder"] - sh_out_s,               # 5
        src_pts["r_shoulder"],                          # 6
        src_pts["l_shoulder"],                          # 7
        src_pts["l_shoulder"] + sh_out_s,               # 8
        src_pts["r_hip"] - hip_out_s,                   # 9
        src_pts["r_hip"],                               # 10
        src_pts["l_hip"],                               # 11
        src_pts["l_hip"] + hip_out_s,                   # 12
        src_pts["r_knee"] - kn_out_s,                   # 13
        src_pts["r_knee"],                              # 14
        src_pts["l_knee"],                              # 15
        src_pts["l_knee"] + kn_out_s,                   # 16
        src_pts["r_ankle"] - ank_out_s + foot_drop_s,   # 17
        src_pts["r_ankle"] + foot_drop_s,               # 18
        src_pts["l_ankle"] + foot_drop_s,               # 19
        src_pts["l_ankle"] + ank_out_s + foot_drop_s,   # 20
    ], dtype=np.float32)

    ctrl_dst = np.array([
        h_tl_d,                                         # 0
        h_tr_d,                                         # 1
        h_ml_d,                                         # 2
        t_neck,                                         # 3
        h_mr_d,                                         # 4
        t_r_sh - sh_out_d,                              # 5
        t_r_sh,                                         # 6
        t_l_sh,                                         # 7
        t_l_sh + sh_out_d,                              # 8
        t_r_hip - hip_out_d,                            # 9
        t_r_hip,                                        # 10
        t_l_hip,                                        # 11
        t_l_hip + hip_out_d,                            # 12
        t_r_kn - kn_out_d,                              # 13
        t_r_kn,                                         # 14
        t_l_kn,                                         # 15
        t_l_kn + kn_out_d,                              # 16
        t_r_ank - ank_out_d + foot_drop_d,              # 17
        t_r_ank + foot_drop_d,                          # 18
        t_l_ank + foot_drop_d,                          # 19
        t_l_ank + ank_out_d + foot_drop_d,              # 20
    ], dtype=np.float32)

    tris = [
        # Đầu & mái tóc
        (0, 1, 3), (0, 3, 2), (1, 4, 3),
        # Cổ & vai
        (2, 3, 6), (2, 6, 5), (3, 7, 6), (3, 4, 7), (4, 8, 7),
        # Ngực, eo & hông (3 dải tứ giác liền mạch)
        (5, 6, 10), (5, 10, 9),
        (6, 7, 11), (6, 11, 10),
        (7, 8, 12), (7, 12, 11),
        # Hông xuống Đầu gối (3 dải tứ giác liền mạch, không khe hở)
        (9, 10, 14), (9, 14, 13),
        (10, 11, 15), (10, 15, 14),
        (11, 12, 16), (11, 16, 15),
        # Đầu gối xuống Bàn chân (3 dải tứ giác liền mạch)
        (13, 14, 18), (13, 18, 17),
        (14, 15, 19), (14, 19, 18),
        (15, 16, 20), (15, 20, 19),
    ]

    warped_body = np.zeros((h_c, w_c, 4), dtype=np.uint8)
    body_src_img = puppet_rig["body_base_rgba"]

    for i0, i1, i2 in tris:
        st = np.array([ctrl_src[i0], ctrl_src[i1], ctrl_src[i2]], dtype=np.float32)
        dt = np.array([ctrl_dst[i0], ctrl_dst[i1], ctrl_dst[i2]], dtype=np.float32)

        area_s = abs((st[1, 0] - st[0, 0]) * (st[2, 1] - st[0, 1]) - (st[2, 0] - st[0, 0]) * (st[1, 1] - st[0, 1]))
        area_d = abs((dt[1, 0] - dt[0, 0]) * (dt[2, 1] - dt[0, 1]) - (dt[2, 0] - dt[0, 0]) * (dt[1, 1] - dt[0, 1]))
        if area_s < 8.0 or area_d < 8.0:
            continue

        rx_s, ry_s, rw_s, rh_s = cv2.boundingRect(st)
        rx_d, ry_d, rw_d, rh_d = cv2.boundingRect(dt)

        x0_d = max(0, rx_d)
        y0_d = max(0, ry_d)
        x1_d = min(w_c, rx_d + rw_d)
        y1_d = min(h_c, ry_d + rh_d)
        if x1_d <= x0_d or y1_d <= y0_d:
            continue

        x0_s = max(0, rx_s - 2)
        y0_s = max(0, ry_s - 2)
        x1_s = min(src_w, rx_s + rw_s + 2)
        y1_s = min(src_h, ry_s + rh_s + 2)
        if x1_s <= x0_s or y1_s <= y0_s:
            continue

        patch_src = body_src_img[y0_s:y1_s, x0_s:x1_s]
        if int(patch_src[:, :, 3].max()) < 4:
            continue

        st_local = st - np.array([[x0_s, y0_s]], dtype=np.float32)
        dt_local = dt - np.array([[x0_d, y0_d]], dtype=np.float32)
        M_tri = cv2.getAffineTransform(st_local, dt_local)
        sub_w, sub_h = x1_d - x0_d, y1_d - y0_d

        warped_patch = cv2.warpAffine(
            patch_src, M_tri, (sub_w, sub_h),
            flags=cv2.INTER_LINEAR,
            borderMode=cv2.BORDER_CONSTANT,
            borderValue=(0, 0, 0, 0),
        )
        tri_mask = np.zeros((sub_h, sub_w), dtype=np.uint8)
        cv2.fillConvexPoly(tri_mask, np.round(dt_local).astype(np.int32), 255, lineType=cv2.LINE_AA)

        dst_roi = warped_body[y0_d:y1_d, x0_d:x1_d]
        sel = tri_mask > 0
        dst_roi[sel] = warped_patch[sel]

    # 2. Vẽ lớp Thân + Đầu + Chân lên khung hình nền
    _alpha_blend_rgba_onto_bgr(canvas_bgr, warped_body)

    # 3. Vẽ 4 đoạn Cánh Tay Cử Động (Bắp tay + Cẳng tay & Bàn tay) bám chính xác theo khớp Vai - Khuỷu - Cổ Tay
    arm_rad = float(puppet_rig["arm_radius"])
    r_hand_target = _g("right_hand", (t_r_wr[0] + 0.35 * (t_r_wr[0] - t_r_el[0]), t_r_wr[1] + 0.35 * (t_r_wr[1] - t_r_el[1])))
    l_hand_target = _g("left_hand", (t_l_wr[0] + 0.35 * (t_l_wr[0] - t_l_el[0]), t_l_wr[1] + 0.35 * (t_l_wr[1] - t_l_el[1])))
    r_tip_dst = t_r_wr + 0.36 * (t_r_wr - t_r_el)
    l_tip_dst = t_l_wr + 0.36 * (t_l_wr - t_l_el)
    if float(np.linalg.norm(r_hand_target - t_r_wr)) > 4.0:
        r_tip_dst = t_r_wr + 1.15 * (r_hand_target - t_r_wr)
    if float(np.linalg.norm(l_hand_target - t_l_wr)) > 4.0:
        l_tip_dst = t_l_wr + 1.15 * (l_hand_target - t_l_wr)

    r_up_a, r_up_b = puppet_rig.get("r_upper_src", (src_pts["r_shoulder"], src_pts["r_elbow"]))
    l_up_a, l_up_b = puppet_rig.get("l_upper_src", (src_pts["l_shoulder"], src_pts["l_elbow"]))
    r_fo_a, r_fo_b = puppet_rig.get("r_fore_src", (src_pts["r_elbow"], src_pts["r_hand_tip"]))
    l_fo_a, l_fo_b = puppet_rig.get("l_fore_src", (src_pts["l_elbow"], src_pts["l_hand_tip"]))

    _warp_limb_segment_rgba(canvas_bgr, puppet_rig["r_upper_rgba"], r_up_a, r_up_b, t_r_sh, t_r_el, arm_rad)
    _warp_limb_segment_rgba(canvas_bgr, puppet_rig["r_fore_rgba"], r_fo_a, r_fo_b, t_r_el, r_tip_dst, arm_rad * 0.92)
    _warp_limb_segment_rgba(canvas_bgr, puppet_rig["l_upper_rgba"], l_up_a, l_up_b, t_l_sh, t_l_el, arm_rad)
    _warp_limb_segment_rgba(canvas_bgr, puppet_rig["l_fore_rgba"], l_fo_a, l_fo_b, t_l_el, l_tip_dst, arm_rad * 0.92)

    all_x = ctrl_dst[:, 0]
    all_y = ctrl_dst[:, 1]
    bx1 = int(np.clip(np.min(all_x), 0, w_c - 1))
    by1 = int(np.clip(np.min(all_y), 0, h_c - 1))
    bx2 = int(np.clip(np.max(all_x), 0, w_c - 1))
    by2 = int(np.clip(np.max(all_y), 0, h_c - 1))
    return bx1, by1, bx2, by2


def _prepare_pinned_ref_assets(ref_pins: list | None, panel_w: int, height: int) -> dict:
    """Chuẩn bị danh sách hình ảnh tham chiếu đã ghim vị trí (<Picture 1..9>) để kết xuất trực tiếp
    nhân vật cử động theo Khung Xương 3D (hoặc đạo cụ/bối cảnh) trên từng khung hình."""
    import cv2
    import numpy as np

    pin_palette_bgr = [
        (235, 206, 56),   # P1: Cyan-Gold
        (145, 110, 255),  # P2: Pink-Coral
        (120, 235, 110),  # P3: Emerald
        (80, 190, 255),   # P4: Amber-Gold
        (250, 140, 180),  # P5: Purple
        (180, 230, 80),   # P6: Teal
        (110, 140, 255),  # P7: Orange-Red
        (235, 175, 95),   # P8: Sky Blue
        (190, 245, 160),  # P9: Mint
    ]
    result = {
        "bg_image_bgr": None,
        "bg_pin": None,
        "pins": [],
        "actor_offsets": {},  # actor_idx (1..3) -> (norm_x, norm_y)
        "actor_rigs": {},     # actor_idx_0_based (0..2) -> pin_dict with puppet_rig
    }
    if not ref_pins or not isinstance(ref_pins, list):
        return result

    try:
        from scripts.blocking_storyboard import find_local_ref_image
    except Exception:
        find_local_ref_image = None

    # Ảnh nhân vật đầu tiên không gắn khớp ("fixed") sẽ được nâng thành Thân #1 để THAY THẾ khung xương
    # (thay vì dán thành ô ảnh nhỏ cạnh khung xương) khi chưa có ảnh nào gắn vào thân nhân vật.
    _has_body_pin = any(
        isinstance(it, dict) and it.get("enabled") is not False
        and re.match(r"^actor\d_body$", str(it.get("anchor") or "").strip().lower())
        for it in ref_pins[:9]
    )
    _promote_done = False
    for idx, item in enumerate(ref_pins[:9]):
        if not isinstance(item, dict) or item.get("enabled") is False:
            continue
        slot = int(item.get("slot") or (idx + 1))
        name = str(item.get("name") or f"Picture_{slot}.png").strip()
        anchor = str(item.get("anchor") or ("actor1_body" if slot == 1 else "fixed")).strip().lower()
        _promoted = False
        if not _has_body_pin and not _promote_done and anchor in ("fixed", ""):
            anchor = "actor1_body"
            _promote_done = True
            _promoted = True
        px_norm = float(np.clip(float(item.get("x") if item.get("x") is not None else (0.35 if slot == 1 else 0.65)), 0.04, 0.96))
        py_norm = float(np.clip(float(item.get("y") if item.get("y") is not None else 0.48), 0.04, 0.96))
        scale = float(np.clip(float(item.get("scale") or 1.0), 0.4, 2.5))

        raw_img = None
        data_uri = str(item.get("data") or "").strip()
        if data_uri:
            try:
                b64 = data_uri.split(",", 1)[1] if "," in data_uri else data_uri
                arr = np.frombuffer(base64.b64decode(b64), dtype=np.uint8)
                raw_img = cv2.imdecode(arr, cv2.IMREAD_UNCHANGED)
            except Exception:
                raw_img = None
        if raw_img is None:
            p_str = str(item.get("path") or item.get("url") or "").strip()
            if p_str:
                cand_paths = [win_path(p_str), str(SCRIPT_DIR / p_str.lstrip("/\\"))]
                for cp in cand_paths:
                    if cp and os.path.isfile(cp):
                        raw_img = cv2.imread(cp, cv2.IMREAD_UNCHANGED)
                        if raw_img is not None:
                            break
            if raw_img is None and find_local_ref_image is not None:
                lp = find_local_ref_image(name, clean_for_h3=True) or find_local_ref_image(name, clean_for_h3=False)
                if lp and lp.is_file():
                    raw_img = cv2.imread(str(lp), cv2.IMREAD_UNCHANGED)

        # Ghi nhận tọa độ ghim của Actor 1 / 2 / 3 để đặt vị trí đứng 3D cho Khung Xương
        for a_num in (1, 2, 3):
            if anchor.startswith(f"actor{a_num}_") and not _promoted:
                if a_num not in result["actor_offsets"] or anchor == f"actor{a_num}_body":
                    result["actor_offsets"][a_num] = (px_norm, py_norm)

        if raw_img is None:
            continue

        col_bgr = pin_palette_bgr[(slot - 1) % len(pin_palette_bgr)]
        if anchor == "background":
            bgr_bg = raw_img[:, :, :3] if raw_img.ndim == 3 else cv2.cvtColor(raw_img, cv2.COLOR_GRAY2BGR)
            ih, iw = bgr_bg.shape[:2]
            sc_bg = max(panel_w / max(iw, 1), height / max(ih, 1))
            nw, nh = max(panel_w, int(round(iw * sc_bg))), max(height, int(round(ih * sc_bg)))
            resized_bg = cv2.resize(bgr_bg, (nw, nh), interpolation=cv2.INTER_AREA)
            x0 = (nw - panel_w) // 2
            y0 = (nh - height) // 2
            crop_bg = resized_bg[y0:y0 + height, x0:x0 + panel_w].copy()
            result["bg_image_bgr"] = crop_bg
            result["bg_pin"] = {
                "slot": slot,
                "name": name,
                "anchor": "background",
                "x": px_norm,
                "y": py_norm,
            }
            continue

        cutout_rgba = _extract_smart_subject_rgba(raw_img)
        puppet_rig = None
        m_body = re.match(r"^actor(\d+)_(body|head)$", anchor)
        if m_body:
            act_0 = max(0, min(2, int(m_body.group(1)) - 1))
            part_type = m_body.group(2)
            if part_type == "body" or act_0 not in result["actor_rigs"]:
                puppet_rig = _build_character_puppet_rig(cutout_rgba)

        pin_entry = {
            "slot": slot,
            "tag": f"<Picture {slot}>",
            "short_tag": f"P{slot}",
            "name": name,
            "anchor": anchor,
            "x": px_norm,
            "y": py_norm,
            "scale": scale,
            "color_bgr": col_bgr,
            "cutout_rgba": cutout_rgba,
            "puppet_rig": puppet_rig,
        }
        result["pins"].append(pin_entry)
        if m_body and puppet_rig is not None:
            act_0 = max(0, min(2, int(m_body.group(1)) - 1))
            if m_body.group(2) == "body" or act_0 not in result["actor_rigs"]:
                result["actor_rigs"][act_0] = pin_entry
    return result


def _overlay_rgba_sprite(canvas_bgr: "np.ndarray", sprite_rgba: "np.ndarray", cx: int, cy: int, target_w: int, target_h: int) -> tuple[int, int, int, int]:
    """Vẽ ảnh RGBA có kênh Alpha mượt lên khung hình BGR tại tâm (cx, cy)."""
    import cv2
    import numpy as np

    h_c, w_c = canvas_bgr.shape[:2]
    sh, sw = sprite_rgba.shape[:2]
    if sw <= 0 or sh <= 0 or target_w <= 4 or target_h <= 4:
        return cx, cy, cx, cy
    sc = min(target_w / float(sw), target_h / float(sh))
    nw = max(8, int(round(sw * sc)))
    nh = max(8, int(round(sh * sc)))
    resized = cv2.resize(sprite_rgba, (nw, nh), interpolation=cv2.INTER_AREA)

    x1 = cx - nw // 2
    y1 = cy - nh // 2
    x2 = x1 + nw
    y2 = y1 + nh

    cx1, cy1 = max(0, x1), max(0, y1)
    cx2, cy2 = min(w_c, x2), min(h_c, y2)
    if cx2 <= cx1 or cy2 <= cy1:
        return cx, cy, cx, cy

    sub_sp = resized[cy1 - y1:cy2 - y1, cx1 - x1:cx2 - x1]
    alpha = (sub_sp[:, :, 3:4].astype(np.float32)) / 255.0
    roi = canvas_bgr[cy1:cy2, cx1:cx2].astype(np.float32)
    blended = roi * (1.0 - alpha) + sub_sp[:, :, :3].astype(np.float32) * alpha
    canvas_bgr[cy1:cy2, cx1:cx2] = np.clip(blended, 0, 255).astype(np.uint8)
    return cx1, cy1, cx2, cy2


def _render_pinned_refs_on_frame(
    frame: "np.ndarray",
    actors_pos_list: list[dict],
    cam,
    prepared_pins: dict,
    pin_render_mode: str = "joint_attach",
    actors_2d_override: list[dict] | None = None,
) -> list[dict]:
    """Kết xuất Nhân Vật Thật đã gắn Rig Khớp Xương (thay thế hoàn toàn khung xương que bằng ảnh người cử động)
    cùng các đạo cụ tay/đầu (<Picture 1..9>) trên từng khung hình video."""
    import cv2
    import numpy as np

    h_f, w_f = frame.shape[:2]
    pins_list = prepared_pins.get("pins") or []
    actor_rigs = prepared_pins.get("actor_rigs") or {}
    mode_clean = str(pin_render_mode or "joint_attach").strip().lower()

    # Chiếu toàn bộ các khớp của từng Actor sang 2D trên khung hình hiện tại (hoặc dùng 2D trực tiếp từ video gốc)
    actors_2d = []
    if actors_2d_override and len(actors_2d_override) > 0:
        actors_2d = actors_2d_override
    else:
        for a_i, pos_d in enumerate(actors_pos_list):
            names = list(pos_d.keys())
            uv = cam.project(np.stack([pos_d[n] for n in names]))
            px_map = {n: (float(uv[i, 0]), float(uv[i, 1])) for i, n in enumerate(names)}
            ys_all = [p[1] for p in px_map.values()]
            skel_h = max(48, int(round((max(ys_all) - min(ys_all)) if ys_all else 160)))
            actors_2d.append({"px": px_map, "skel_h": skel_h})

    frame_pin_coords = []
    if not pins_list:
        return frame_pin_coords

    # Bước 1: Nếu chế độ không phải clean_skeleton, vẽ Nhân Vật Thật đã gắn Rig khớp xương cho từng Actor
    rendered_rig_slots = set()
    if mode_clean != "clean_skeleton" and actors_2d:
        for act_idx, rig_pin in sorted(actor_rigs.items()):
            if act_idx < len(actors_2d) and rig_pin.get("puppet_rig") is not None:
                px_map = actors_2d[act_idx]["px"]
                _warp_character_puppet_to_skeleton(
                    frame,
                    rig_pin["puppet_rig"],
                    px_map,
                    scale_mult=float(rig_pin.get("scale") or 1.0),
                )
                rendered_rig_slots.add(rig_pin["slot"])
                sp_xy = px_map.get("spine2") or px_map.get("pelvis") or (w_f * 0.5, h_f * 0.5)
                frame_pin_coords.append({
                    "slot": rig_pin["slot"],
                    "anchor": rig_pin["anchor"],
                    "x": round(float(sp_xy[0]) / float(max(w_f, 1)), 3),
                    "y": round(float(sp_xy[1]) / float(max(h_f, 1)), 3),
                })

    # Bước 2: Vẽ các đạo cụ gắn vào Tay Phải / Tay Trái / Đầu riêng biệt hoặc vị trí cố định
    for pin in pins_list:
        slot = pin["slot"]
        if slot in rendered_rig_slots:
            continue
        short_tag = pin["short_tag"]
        anchor = pin["anchor"]
        col_bgr = pin["color_bgr"]
        scale = pin["scale"]
        sprite = pin["cutout_rgba"]

        target_x = int(round(pin["x"] * w_f))
        target_y = int(round(pin["y"] * h_f))
        joint_xy = None
        base_size = int(round(min(w_f, h_f) * 0.18 * scale))

        if anchor.startswith("actor") and actors_2d:
            m_act = re.match(r"^actor(\d+)_(\w+)$", anchor)
            if m_act:
                act_idx = min(len(actors_2d) - 1, max(0, int(m_act.group(1)) - 1))
                part = m_act.group(2)
                px_map = actors_2d[act_idx]["px"]
                skel_h = actors_2d[act_idx]["skel_h"]
                if part == "head":
                    pt_h = px_map.get("head")
                    if pt_h is not None:
                        joint_xy = (int(round(pt_h[0])), int(round(pt_h[1])))
                    base_size = int(round(skel_h * 0.34 * scale))
                elif part == "rhand":
                    pt_rh = px_map.get("right_hand") or px_map.get("right_wrist")
                    if pt_rh is not None:
                        joint_xy = (int(round(pt_rh[0])), int(round(pt_rh[1])))
                    base_size = int(round(skel_h * 0.26 * scale))
                elif part == "lhand":
                    pt_lh = px_map.get("left_hand") or px_map.get("left_wrist")
                    if pt_lh is not None:
                        joint_xy = (int(round(pt_lh[0])), int(round(pt_lh[1])))
                    base_size = int(round(skel_h * 0.26 * scale))
                else:
                    pt_b = px_map.get("spine2") or px_map.get("pelvis")
                    if pt_b is not None:
                        joint_xy = (int(round(pt_b[0])), int(round(pt_b[1])))
                    base_size = int(round(skel_h * 0.45 * scale))

        base_size = max(32, min(int(min(w_f, h_f) * 0.55), base_size))

        if joint_xy is not None:
            jx, jy = joint_xy
            draw_cx = jx
            draw_cy = jy - (base_size // 6 if anchor.endswith("_head") else 0)
        else:
            draw_cx = int(np.clip(target_x, base_size // 2 + 6, w_f - base_size // 2 - 6))
            draw_cy = int(np.clip(target_y, base_size // 2 + 18, h_f - base_size // 2 - 6))
            jx, jy = draw_cx, draw_cy

        frame_pin_coords.append({
            "slot": slot,
            "anchor": anchor,
            "x": round(jx / float(max(w_f, 1)), 3),
            "y": round(jy / float(max(h_f, 1)), 3),
        })

        if mode_clean == "clean_skeleton":
            continue

        _overlay_rgba_sprite(frame, sprite, draw_cx, draw_cy, base_size, base_size)

    return frame_pin_coords


def _draw_custom_colored_skeleton(
    img: "np.ndarray",
    pos: dict[str, "np.ndarray"],
    edges: list[tuple[str, str]],
    cam,
    actor_idx: int = 0,
    thickness: int = 3,
) -> None:
    """Vẽ khung xương 3D 24 khớp với bảng màu phân biệt rõ từng nhân vật (Actor 1, Actor 2, Actor 3) và Trái/Phải."""
    import cv2
    import numpy as np

    palettes = [
        {"left": (232, 155, 76), "right": (90, 90, 224), "torso": (76, 200, 230), "joint": (245, 245, 245)},
        {"left": (130, 235, 110), "right": (180, 105, 255), "torso": (80, 225, 195), "joint": (255, 240, 245)},
        {"left": (255, 190, 70), "right": (245, 110, 145), "torso": (195, 140, 255), "joint": (240, 255, 245)},
    ]
    pal = palettes[actor_idx % len(palettes)]
    names = list(pos.keys())
    uv = cam.project(np.stack([pos[n] for n in names]))
    px = {n: (int(round(uv[i, 0])), int(round(uv[i, 1]))) for i, n in enumerate(names)}
    for a, b in edges:
        if a in px and b in px:
            tok = f"{a}_{b}".lower()
            col = pal["left"] if "left" in tok else (pal["right"] if "right" in tok else pal["torso"])
            cv2.line(img, px[a], px[b], col, thickness, cv2.LINE_AA)
    for p in px.values():
        cv2.circle(img, p, 3, pal["joint"], -1, cv2.LINE_AA)


def create_v2v_side_by_side_compare(orig_video_path: str, swapped_video_path: str) -> tuple[str | None, str]:
    """Áp dụng kỹ thuật ghép bảng so sánh (Before / After Compare) từ Motion2MixamoRig/videos.py:
    Đặt <Video 1> (Gốc) bên trái và Video H3 V2V bên phải, cân chỉnh cùng chiều cao 720p, giữ nguyên âm thanh."""
    w_orig = win_path(orig_video_path)
    w_swap = win_path(swapped_video_path)
    if not w_orig or not os.path.isfile(w_orig):
        return None, "Không tìm thấy Video Gốc (<Video 1>)"
    if not w_swap or not os.path.isfile(w_swap):
        return None, "Không tìm thấy Video V2V đã render"

    out_dir = Path(w_swap).parent
    out_file = out_dir / f"Compare_V2V_{Path(w_swap).stem}_{int(time.time())}.mp4"
    ffmpeg_bin = _find_ffmpeg()
    filter_complex = (
        "[0:v]fps=24,scale=-2:720:flags=lanczos,setsar=1[v0];"
        "[1:v]fps=24,scale=-2:720:flags=lanczos,setsar=1[v1];"
        "[v0][v1]hstack=inputs=2[vout]"
    )
    try:
        pr = subprocess.run(
            [
                ffmpeg_bin, "-y", "-i", w_orig, "-i", w_swap,
                "-filter_complex", filter_complex,
                "-map", "[vout]", "-map", "1:a:0?",
                "-c:v", "libx264", "-crf", "18", "-preset", "fast", "-pix_fmt", "yuv420p",
                "-c:a", "aac", "-b:a", "192k", "-shortest", str(out_file),
            ],
            capture_output=True, text=True, timeout=300, encoding="utf-8", errors="ignore"
        )
        if pr.returncode == 0 and out_file.exists() and out_file.stat().st_size > 1000:
            record_h3_video(str(out_file), title=f"🌗 [So Sánh Gốc vs V2V] {Path(w_swap).name}")
            return str(out_file), "Đã tạo video so sánh Gốc vs V2V (Side-by-Side) thành công!"
    except Exception as e:
        return None, f"Lỗi FFmpeg khi ghép so sánh: {e}"
    return None, "Không thể ghép video so sánh"


def extract_m2mr_from_real_video_mediapipe(
    src_win: str,
    run_out_dir: Path,
    jid: str = "",
    ref_pins: list | None = None,
    pin_render_mode: str = "joint_attach",
    camera_azimuth: float = 0.0,
    camera_elevation: float = 7.0,
) -> dict:
    """Trích xuất trực tiếp Khung Xương 3D 24 Khớp (SMPL-X) Hỗ Trợ Đa Nhân Vật (1–4 người) + Mannequin 3D + file .GLB
    từ Video/Ảnh người thật bằng MediaPipe 3D Pose Landmarker + bộ render phối cảnh 3D của D:\\Motion2MixamoRig-main,
    đồng thời hỗ trợ gắn Hình Ảnh Tham Chiếu Ghim Vị Trí (<Picture 1..9>) bám theo khớp xương!"""
    import math
    import sys
    import urllib.request
    import numpy as np
    import cv2

    m2mr_path_str = str(M2MR_DIR)
    if M2MR_DIR.is_dir() and m2mr_path_str not in sys.path:
        sys.path.insert(0, m2mr_path_str)

    from motion2mixamorig.mixamo.render import (
        DARK_THEME,
        GRID_THEME,
        Ground,
        build_perspective_camera,
        ground_backdrop,
        draw_shadow,
        draw_mesh,
        label_panel,
    )
    from motion2mixamorig.mixamo.retarget import HUMAN_EDGES
    from motion2mixamorig.extract import SMPL_JOINT_NAMES

    is_img = Path(src_win).suffix.lower() in {".jpg", ".jpeg", ".png", ".webp", ".bmp"}
    raw_frames_bgr = []
    target_fps = 24.0

    if is_img:
        img0 = cv2.imread(src_win)
        if img0 is None:
            return {"ok": False, "error": "Không đọc được file ảnh đầu vào."}
        orig_h, orig_w = img0.shape[:2]
        raw_frames_bgr = [img0] * 72
    else:
        cap = cv2.VideoCapture(src_win)
        if not cap.isOpened():
            return {"ok": False, "error": "Không mở được file video đầu vào."}
        src_fps = float(cap.get(cv2.CAP_PROP_FPS) or 24.0)
        if src_fps <= 1.0 or src_fps > 120.0:
            src_fps = 24.0
        orig_w = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH) or 480)
        orig_h = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT) or 832)
        step = max(1.0, src_fps / 24.0)
        target_fps = round(src_fps / step, 2) if step > 1.05 else round(src_fps, 2)
        idx_f = 0
        next_take = 0.0
        while True:
            ok, frm = cap.read()
            if not ok or frm is None:
                break
            if idx_f + 1e-3 >= next_take:
                raw_frames_bgr.append(frm)
                next_take += step
                if len(raw_frames_bgr) >= 720:
                    break
            idx_f += 1
        cap.release()

    if not raw_frames_bgr:
        return {"ok": False, "error": "Video không có khung hình hợp lệ."}

    if orig_h > orig_w * 1.12:
        render_w, render_h = 480, 832
    elif orig_w > orig_h * 1.12:
        render_w, render_h = 832, 480
    else:
        render_w, render_h = 640, 640

    n_frames = len(raw_frames_bgr)
    max_poses = 3

    def _landmarks_to_smpl24(wlm, ilm) -> tuple[np.ndarray, np.ndarray]:
        hip_2d_x = 0.5 * (ilm[23].x + ilm[24].x)
        sh_2d_y = 0.5 * (ilm[11].y + ilm[12].y)
        hip_2d_y = 0.5 * (ilm[23].y + ilm[24].y)
        torso_2d = max(0.14, abs(hip_2d_y - sh_2d_y))
        root_tx = float((hip_2d_x - 0.5) * 1.25)
        root_tz = float(np.clip((torso_2d - 0.26) * 1.8, -0.45, 0.45))

        def _pt(idx_lm: int) -> np.ndarray:
            p = wlm[idx_lm]
            return np.array([float(p.x) + root_tx, float(-p.y), float(-p.z) + root_tz], dtype=np.float64)

        def _uvv(idx_lm: int) -> np.ndarray:
            p = ilm[idx_lm]
            v = float(getattr(p, "visibility", 0.9))
            return np.array([float(p.x), float(p.y), v], dtype=np.float64)

        l_hip, r_hip = _pt(23), _pt(24)
        pelvis = 0.5 * (l_hip + r_hip)
        l_sh, r_sh = _pt(11), _pt(12)
        sh_mid = 0.5 * (l_sh + r_sh)
        spine1 = pelvis + 0.28 * (sh_mid - pelvis)
        spine2 = pelvis + 0.56 * (sh_mid - pelvis)
        spine3 = pelvis + 0.84 * (sh_mid - pelvis)
        neck = sh_mid + np.array([0.0, 0.055, 0.0])
        ear_mid = 0.5 * (_pt(7) + _pt(8))
        nose_p = _pt(0)
        head = 0.65 * ear_mid + 0.35 * nose_p + np.array([0.0, 0.045, 0.0])
        l_collar = spine3 + 0.42 * (l_sh - spine3)
        r_collar = spine3 + 0.42 * (r_sh - spine3)
        l_elbow, r_elbow = _pt(13), _pt(14)
        l_wrist, r_wrist = _pt(15), _pt(16)
        l_hand = 0.5 * (_pt(17) + _pt(19))
        r_hand = 0.5 * (_pt(18) + _pt(20))
        l_knee, r_knee = _pt(25), _pt(26)
        l_ankle, r_ankle = _pt(27), _pt(28)
        l_foot = 0.45 * _pt(29) + 0.55 * _pt(31)
        r_foot = 0.45 * _pt(30) + 0.55 * _pt(32)

        jmap = {
            "pelvis": pelvis, "left_hip": l_hip, "right_hip": r_hip,
            "spine1": spine1, "left_knee": l_knee, "right_knee": r_knee,
            "spine2": spine2, "left_ankle": l_ankle, "right_ankle": r_ankle,
            "spine3": spine3, "left_foot": l_foot, "right_foot": r_foot,
            "neck": neck, "left_collar": l_collar, "right_collar": r_collar,
            "head": head, "left_shoulder": l_sh, "right_shoulder": r_sh,
            "left_elbow": l_elbow, "right_elbow": r_elbow,
            "left_wrist": l_wrist, "right_wrist": r_wrist,
            "left_hand": l_hand, "right_hand": r_hand,
        }

        # Tọa độ 2D chuẩn hóa (0..1) trên khung hình video gốc để giữ đúng tỷ lệ Trung cảnh / Toàn thân
        u_l_hip, u_r_hip = _uvv(23), _uvv(24)
        u_pelvis = 0.5 * (u_l_hip + u_r_hip)
        u_l_sh, u_r_sh = _uvv(11), _uvv(12)
        u_sh_mid = 0.5 * (u_l_sh + u_r_sh)
        u_spine1 = u_pelvis + 0.28 * (u_sh_mid - u_pelvis)
        u_spine2 = u_pelvis + 0.56 * (u_sh_mid - u_pelvis)
        u_spine3 = u_pelvis + 0.84 * (u_sh_mid - u_pelvis)
        u_neck = u_sh_mid.copy()
        u_neck[1] -= 0.065 * torso_2d
        u_head = _uvv(0)
        u_l_col = u_spine3 + 0.42 * (u_l_sh - u_spine3)
        u_r_col = u_spine3 + 0.42 * (u_r_sh - u_spine3)
        u_l_el, u_r_el = _uvv(13), _uvv(14)
        u_l_wr, u_r_wr = _uvv(15), _uvv(16)
        u_l_hd = u_l_wr.copy()
        u_l_hd[:2] = u_l_wr[:2] + 0.30 * (u_l_wr[:2] - u_l_el[:2])
        u_r_hd = u_r_wr.copy()
        u_r_hd[:2] = u_r_wr[:2] + 0.30 * (u_r_wr[:2] - u_r_el[:2])
        u_l_kn, u_r_kn = _uvv(25), _uvv(26)
        u_l_ank, u_r_ank = _uvv(27), _uvv(28)

        # Nếu là góc máy Trung cảnh / Bán thân (đầu gối/cổ chân nằm ngoài khung hình dưới hoặc độ tin cậy thấp),
        # ngoại suy mượt vị trí đầu gối & cổ chân xuống phía dưới hông theo tỷ lệ thân người thật
        if u_l_kn[2] < 0.42 or u_r_kn[2] < 0.42 or (hip_2d_y > 0.72 and max(u_l_kn[1], u_r_kn[1]) > 0.88):
            u_l_kn = np.array([u_l_hip[0], u_l_hip[1] + torso_2d * 0.96, 0.85], dtype=np.float64)
            u_r_kn = np.array([u_r_hip[0], u_r_hip[1] + torso_2d * 0.96, 0.85], dtype=np.float64)
            u_l_ank = np.array([u_l_hip[0], u_l_hip[1] + torso_2d * 1.88, 0.85], dtype=np.float64)
            u_r_ank = np.array([u_r_hip[0], u_r_hip[1] + torso_2d * 1.88, 0.85], dtype=np.float64)
        elif u_l_ank[2] < 0.42 or u_r_ank[2] < 0.42:
            u_l_ank = np.array([u_l_kn[0], u_l_kn[1] + torso_2d * 0.92, 0.85], dtype=np.float64)
            u_r_ank = np.array([u_r_kn[0], u_r_kn[1] + torso_2d * 0.92, 0.85], dtype=np.float64)

        u_l_ft = u_l_ank.copy()
        u_l_ft[1] += 0.08 * torso_2d
        u_r_ft = u_r_ank.copy()
        u_r_ft[1] += 0.08 * torso_2d

        umap = {
            "pelvis": u_pelvis, "left_hip": u_l_hip, "right_hip": u_r_hip,
            "spine1": u_spine1, "left_knee": u_l_kn, "right_knee": u_r_kn,
            "spine2": u_spine2, "left_ankle": u_l_ank, "right_ankle": u_r_ank,
            "spine3": u_spine3, "left_foot": u_l_ft, "right_foot": u_r_ft,
            "neck": u_neck, "left_collar": u_l_col, "right_collar": u_r_col,
            "head": u_head, "left_shoulder": u_l_sh, "right_shoulder": u_r_sh,
            "left_elbow": u_l_el, "right_elbow": u_r_el,
            "left_wrist": u_l_wr, "right_wrist": u_r_wr,
            "left_hand": u_l_hd, "right_hand": u_r_hd,
        }

        cur_j3d = np.zeros((len(SMPL_JOINT_NAMES), 3), dtype=np.float32)
        cur_j2d = np.zeros((len(SMPL_JOINT_NAMES), 3), dtype=np.float32)
        for ji, jname in enumerate(SMPL_JOINT_NAMES):
            cur_j3d[ji] = jmap[jname]
            cur_j2d[ji] = umap[jname]
        return cur_j3d, cur_j2d

    if jid and jid in active_jobs:
        active_jobs[jid]["progress"] = 22
        active_jobs[jid]["stage_label"] = f"🦴 [Hybrid 3D Pose] Đang nhận diện & bóc tách khớp xương 3D ({n_frames} frames)..."

    detected_all = _detect_poses_hybrid(raw_frames_bgr, max_poses=max_poses)
    per_frame_detected: list[list[tuple[np.ndarray, np.ndarray]]] = []
    person_counts = []

    for fi, frame_actors in enumerate(detected_all):
        if jid and jid in active_jobs and fi % 12 == 0:
            pct = 25 + int(35 * (fi / max(n_frames, 1)))
            active_jobs[jid]["progress"] = pct
            active_jobs[jid]["stage_label"] = f"🦴 [Hybrid 3D Pose] Đang quy đổi khớp xương SMPL-24 ({fi+1}/{n_frames} frames)..."

        actors_this_frame = []
        for ilm, wlm in frame_actors:
            actors_this_frame.append(_landmarks_to_smpl24(wlm, ilm))
        person_counts.append(len(actors_this_frame))
        per_frame_detected.append(actors_this_frame)

    # Xác định số lượng người thực sự xuất hiện ổn định trong video (1..3)
    non_zero_counts = [c for c in person_counts if c > 0]
    active_actor_count = int(round(float(np.median(non_zero_counts)))) if non_zero_counts else 1
    active_actor_count = max(1, min(max_poses, active_actor_count))

    actors_joints_3d = np.zeros((active_actor_count, n_frames, len(SMPL_JOINT_NAMES), 3), dtype=np.float32)
    actors_joints_2d = np.zeros((active_actor_count, n_frames, len(SMPL_JOINT_NAMES), 3), dtype=np.float32)
    last_valid_3d: list[np.ndarray | None] = [None] * active_actor_count
    last_valid_2d: list[np.ndarray | None] = [None] * active_actor_count

    # Theo dõi danh tính từng người qua các frame (ghép theo tâm thân gần nhất + vận tốc),
    # thay vì xếp Trái -> Phải mỗi frame (tránh tráo màu/ảnh ghim khi 2 người đi chéo qua nhau).
    _pel_i = SMPL_JOINT_NAMES.index("pelvis")
    _nk_i = SMPL_JOINT_NAMES.index("neck")

    def _trk_feat(j2_arr: np.ndarray) -> np.ndarray:
        return np.array([
            0.5 * (float(j2_arr[_pel_i, 0]) + float(j2_arr[_nk_i, 0])),
            0.5 * (float(j2_arr[_pel_i, 1]) + float(j2_arr[_nk_i, 1])),
            abs(float(j2_arr[_pel_i, 1]) - float(j2_arr[_nk_i, 1])),
        ], dtype=np.float64)

    trk_xy: list[np.ndarray | None] = [None] * active_actor_count
    trk_vel: list[np.ndarray] = [np.zeros(3) for _ in range(active_actor_count)]
    trk_lost = [0] * active_actor_count
    track_swaps_fixed = 0

    for fi in range(n_frames):
        det_list = per_frame_detected[fi]
        assign: list[int | None] = [None] * active_actor_count
        if det_list:
            feats = [_trk_feat(dj[1]) for dj in det_list]
            pairs = []
            for a_i in range(active_actor_count):
                if trk_xy[a_i] is None:
                    continue
                pred = trk_xy[a_i] + trk_vel[a_i] * min(trk_lost[a_i] + 1, 6)
                for d_i, ft in enumerate(feats):
                    c = float(np.hypot(ft[0] - pred[0], ft[1] - pred[1])) + 0.6 * abs(ft[2] - pred[2])
                    pairs.append((c, a_i, d_i))
            pairs.sort(key=lambda t: t[0])
            used_d: set = set()
            for c, a_i, d_i in pairs:
                if assign[a_i] is not None or d_i in used_d:
                    continue
                if c > (0.22 + 0.03 * min(trk_lost[a_i], 10)):
                    continue
                assign[a_i] = d_i
                used_d.add(d_i)
            free_d = [d_i for d_i in range(len(det_list)) if d_i not in used_d]  # vẫn theo thứ tự Trái -> Phải
            for a_i in range(active_actor_count):
                if assign[a_i] is None and free_d and (trk_xy[a_i] is None or trk_lost[a_i] > 18):
                    assign[a_i] = free_d.pop(0)
            if any(assign[a_i] is not None and assign[a_i] != a_i for a_i in range(active_actor_count)):
                track_swaps_fixed += 1
        for a_i in range(active_actor_count):
            d_sel = assign[a_i]
            if d_sel is not None:
                j3, j2 = det_list[d_sel]
                ft_new = _trk_feat(j2)
                if trk_xy[a_i] is not None:
                    trk_vel[a_i] = 0.6 * trk_vel[a_i] + 0.4 * ((ft_new - trk_xy[a_i]) / float(trk_lost[a_i] + 1))
                trk_xy[a_i] = ft_new
                trk_lost[a_i] = 0
                # Nếu khớp khuỷu tay / cổ tay bị che khuất tạm thời (vis < 0.45), giữ vị trí hợp lệ gần nhất để tay không bị giật
                if last_valid_2d[a_i] is not None:
                    prev_j2 = last_valid_2d[a_i]
                    prev_j3 = last_valid_3d[a_i]
                    for ji in range(len(SMPL_JOINT_NAMES)):
                        if j2[ji, 2] < 0.45 and prev_j2[ji, 2] >= 0.45:
                            j2[ji, :2] = prev_j2[ji, :2]
                            j3[ji, :] = prev_j3[ji, :]
                actors_joints_3d[a_i, fi] = j3
                actors_joints_2d[a_i, fi] = j2
                last_valid_3d[a_i] = j3.copy()
                last_valid_2d[a_i] = j2.copy()
            elif last_valid_3d[a_i] is not None:
                trk_lost[a_i] += 1
                actors_joints_3d[a_i, fi] = last_valid_3d[a_i]
                actors_joints_2d[a_i, fi] = last_valid_2d[a_i]
            else:
                actors_joints_3d[a_i, fi, :, 1] = 0.85
                actors_joints_2d[a_i, fi, :, 0] = 0.5
                actors_joints_2d[a_i, fi, :, 1] = 0.5

    # Điền ngược (backward fill) cho các frame đầu nếu frame đầu bị khuất khớp
    for a_i in range(active_actor_count):
        for ji in range(len(SMPL_JOINT_NAMES)):
            valid_f = [f_idx for f_idx in range(n_frames) if actors_joints_2d[a_i, f_idx, ji, 2] >= 0.45]
            if valid_f and valid_f[0] > 0:
                first_v = valid_f[0]
                actors_joints_2d[a_i, :first_v, ji, :2] = actors_joints_2d[a_i, first_v, ji, :2]
                actors_joints_3d[a_i, :first_v, ji, :] = actors_joints_3d[a_i, first_v, ji, :]

    try:
        from scipy.ndimage import gaussian_filter1d
        if n_frames >= 5:
            for a_i in range(active_actor_count):
                actors_joints_3d[a_i] = gaussian_filter1d(actors_joints_3d[a_i], sigma=1.15, axis=0)
                actors_joints_2d[a_i, :, :, :2] = gaussian_filter1d(actors_joints_2d[a_i, :, :, :2], sigma=1.35, axis=0)
    except Exception:
        pass

    foot_indices = [SMPL_JOINT_NAMES.index(k) for k in ("left_ankle", "right_ankle", "left_foot", "right_foot")]
    for a_i in range(active_actor_count):
        for fi in range(n_frames):
            min_fy = float(np.min(actors_joints_3d[a_i, fi, foot_indices, 1]))
            actors_joints_3d[a_i, fi, :, 1] -= min_fy

    joints_3d_arr = actors_joints_3d[0]
    actors_frames_pos: list[list[dict[str, np.ndarray]]] = []
    for fi in range(n_frames):
        f_actors = []
        for a_i in range(active_actor_count):
            pos_d = {jname: actors_joints_3d[a_i, fi, ji].astype(np.float64) for ji, jname in enumerate(SMPL_JOINT_NAMES)}
            f_actors.append(pos_d)
        actors_frames_pos.append(f_actors)

    def _build_limb_frustum(a: np.ndarray, b: np.ndarray, ra: float, rb: float, sides: int = 10) -> tuple[np.ndarray, np.ndarray]:
        axis = b - a
        length = float(np.linalg.norm(axis))
        axis = np.array([0.0, 1.0, 0.0]) if length < 1e-6 else axis / length
        ref = np.array([0.0, 0.0, 1.0]) if abs(axis[2]) < 0.9 else np.array([1.0, 0.0, 0.0])
        u = np.cross(axis, ref)
        u = u / max(float(np.linalg.norm(u)), 1e-8)
        v = np.cross(axis, u)
        angles = np.linspace(0.0, 2.0 * math.pi, sides, endpoint=False)
        ca, sa = np.cos(angles)[:, None], np.sin(angles)[:, None]
        ring_a = a[None, :] + ra * (ca * u[None, :] + sa * v[None, :])
        ring_b = b[None, :] + rb * (ca * u[None, :] + sa * v[None, :])
        cap_a = a - axis * (ra * 0.35)
        cap_b = b + axis * (rb * 0.35)
        verts = np.vstack([ring_a, ring_b, cap_a[None, :], cap_b[None, :]])
        center = 0.5 * (a + b)
        tris = []
        idx_ca, idx_cb = 2 * sides, 2 * sides + 1
        for i in range(sides):
            j = (i + 1) % sides
            tris.append([i, j, sides + j])
            tris.append([i, sides + j, sides + i])
            tris.append([idx_ca, j, i])
            tris.append([idx_cb, sides + i, sides + j])
        faces = np.asarray(tris, dtype=np.int32)
        p0, p1, p2 = verts[faces[:, 0]], verts[faces[:, 1]], verts[faces[:, 2]]
        normals = np.cross(p1 - p0, p2 - p0)
        mids = (p0 + p1 + p2) / 3.0 - center[None, :]
        flip = np.sum(normals * mids, axis=1) < 0.0
        faces[flip, 1], faces[flip, 2] = faces[flip, 2].copy(), faces[flip, 1].copy()
        return verts, faces

    def _build_mannequin_meshes(pos: dict[str, np.ndarray], actor_idx: int = 0):
        tint_shift = actor_idx * 25
        parts = [
            (pos["pelvis"], pos["spine1"], 0.115, 0.105, np.array([195, max(130, 175 - tint_shift), min(220, 140 + tint_shift)], dtype=np.float64)),
            (pos["spine1"], pos["spine3"], 0.105, 0.135, np.array([210, max(140, 185 - tint_shift), min(225, 145 + tint_shift)], dtype=np.float64)),
            (pos["spine3"], pos["neck"], 0.125, 0.052, np.array([195, 175, 140], dtype=np.float64)),
            (pos["neck"], pos["head"], 0.075, 0.088, np.array([225, 205, 175], dtype=np.float64)),
            (pos["left_shoulder"], pos["left_elbow"], 0.045, 0.038, np.array([215, 180, 125], dtype=np.float64)),
            (pos["left_elbow"], pos["left_wrist"], 0.036, 0.028, np.array([215, 180, 125], dtype=np.float64)),
            (pos["left_wrist"], pos["left_hand"], 0.030, 0.022, np.array([225, 200, 165], dtype=np.float64)),
            (pos["right_shoulder"], pos["right_elbow"], 0.045, 0.038, np.array([165, 165, 220], dtype=np.float64)),
            (pos["right_elbow"], pos["right_wrist"], 0.036, 0.028, np.array([165, 165, 220], dtype=np.float64)),
            (pos["right_wrist"], pos["right_hand"], 0.030, 0.022, np.array([225, 200, 165], dtype=np.float64)),
            (pos["left_hip"], pos["left_knee"], 0.068, 0.048, np.array([205, 175, 130], dtype=np.float64)),
            (pos["left_knee"], pos["left_ankle"], 0.046, 0.034, np.array([205, 175, 130], dtype=np.float64)),
            (pos["left_ankle"], pos["left_foot"], 0.036, 0.030, np.array([180, 160, 135], dtype=np.float64)),
            (pos["right_hip"], pos["right_knee"], 0.068, 0.048, np.array([160, 165, 210], dtype=np.float64)),
            (pos["right_knee"], pos["right_ankle"], 0.046, 0.034, np.array([160, 165, 210], dtype=np.float64)),
            (pos["right_ankle"], pos["right_foot"], 0.036, 0.030, np.array([180, 160, 135], dtype=np.float64)),
        ]
        v_list, f_list, c_list = [], [], []
        for a, b, ra, rb, col in parts:
            v, f = _build_limb_frustum(a, b, ra, rb, sides=10)
            v_list.append(v)
            f_list.append(f)
            c_list.append(col)
        return v_list, f_list, c_list

    run_out_dir.mkdir(parents=True, exist_ok=True)
    vid_dir = run_out_dir / "videos"
    vid_dir.mkdir(parents=True, exist_ok=True)

    npz_path = run_out_dir / "skeleton_motion.npz"
    np.savez_compressed(
        npz_path,
        joints_3d=joints_3d_arr,
        all_actors_joints_3d=actors_joints_3d,
        joint_names=np.array(SMPL_JOINT_NAMES),
        fps=np.float32(target_fps),
        timestamps=np.arange(n_frames, dtype=np.float64) / float(target_fps),
        root_translation=joints_3d_arr[:, 0, :],
        root_orientation=np.zeros((n_frames, 3), dtype=np.float32),
    )

    glb_path = run_out_dir / "mixamo_character.glb"
    try:
        import trimesh
        mid_actors = actors_frames_pos[n_frames // 2]
        meshes = []
        for a_i, mid_pos in enumerate(mid_actors):
            v_list, f_list, c_list = _build_mannequin_meshes(mid_pos, actor_idx=a_i)
            for v, f, col_bgr in zip(v_list, f_list, c_list):
                m = trimesh.Trimesh(vertices=v, faces=f, process=False)
                rgba = np.array([int(col_bgr[2]), int(col_bgr[1]), int(col_bgr[0]), 255], dtype=np.uint8)
                m.visual.face_colors = np.tile(rgba, (len(f), 1))
                meshes.append(m)
        combined = trimesh.util.concatenate(meshes)
        combined.export(str(glb_path))
    except Exception:
        pass

    axes = {
        "right": np.array([1.0, 0.0, 0.0]),
        "up": np.array([0.0, 1.0, 0.0]),
        "forward": np.array([0.0, 0.0, 1.0]),
    }
    all_pts = actors_joints_3d.reshape(-1, 3)
    pad_pts = np.vstack([
        all_pts,
        all_pts + np.array([0.32, 0.38, 0.32]),
        all_pts - np.array([0.32, 0.20, 0.32]),
    ])
    ground = Ground(
        y=0.0,
        cx=float(0.5 * (all_pts[:, 0].min() + all_pts[:, 0].max())),
        cz=float(0.5 * (all_pts[:, 2].min() + all_pts[:, 2].max())),
    )
    # Góc máy mới (#2): khung xương gần như dẹt nên chỉ cho xoay nhỏ ±35° và nâng máy tối đa 40°
    try:
        cam_az = max(-35.0, min(35.0, float(camera_azimuth or 0.0)))
    except Exception:
        cam_az = 0.0
    try:
        cam_el = max(0.0, min(40.0, float(7.0 if camera_elevation is None else camera_elevation)))
    except Exception:
        cam_el = 7.0
    angle_changed = abs(cam_az) > 0.5 or abs(cam_el - 7.0) > 0.5
    cam = build_perspective_camera(
        axes, pad_pts, render_w, render_h,
        fov_deg=28.0, azimuth_deg=cam_az, elevation_deg=cam_el, fill=0.74,
    )
    bg_dark = ground_backdrop(cam, ground, render_w, render_h, theme=DARK_THEME)
    bg_grid = ground_backdrop(cam, ground, render_w, render_h, theme=GRID_THEME)

    prepared_pins = _prepare_pinned_ref_assets(ref_pins, render_w, render_h)
    actor_rigs_map = prepared_pins.get("actor_rigs") or {}
    mode_clean = str(pin_render_mode or "joint_attach").strip().lower()
    has_rigged_char = bool(actor_rigs_map and mode_clean != "clean_skeleton")

    if prepared_pins.get("bg_image_bgr") is not None:
        if has_rigged_char:
            bg_dark = prepared_pins["bg_image_bgr"].copy()
        else:
            bg_dark = cv2.addWeighted(prepared_pins["bg_image_bgr"], 0.88, bg_dark, 0.12, 0)
        bg_grid = cv2.addWeighted(prepared_pins["bg_image_bgr"], 0.78, bg_grid, 0.22, 0)

    # Nếu người dùng chủ động kéo ghim nhân vật sang vị trí (x, y) khác trên sân khấu, dịch chuyển nhẹ tọa độ 2D theo ghim
    spine2_idx = SMPL_JOINT_NAMES.index("spine2")
    actor_2d_shifts: dict[int, tuple[float, float]] = {}
    for a_i in range(active_actor_count):
        off_xy = prepared_pins.get("actor_offsets", {}).get(a_i + 1)
        if off_xy is not None:
            med_sx = float(np.median(actors_joints_2d[a_i, :, spine2_idx, 0]))
            med_sy = float(np.median(actors_joints_2d[a_i, :, spine2_idx, 1]))
            dx_n = float(off_xy[0]) - med_sx
            dy_n = float(off_xy[1]) - med_sy
            if abs(dx_n) > 0.08 or abs(dy_n) > 0.08:
                actor_2d_shifts[a_i] = (dx_n * render_w, dy_n * render_h)
            else:
                actor_2d_shifts[a_i] = (0.0, 0.0)
        else:
            actor_2d_shifts[a_i] = (0.0, 0.0)

    skel_mp4 = vid_dir / "human_skeleton.mp4"
    man_mp4 = vid_dir / "mixamo_character.mp4"
    sbs_mp4 = vid_dir / "side_by_side.mp4"

    ffmpeg_bin = _find_ffmpeg()

    def _open_writer(out_p: Path, w_px: int, h_px: int):
        cmd_w = [
            ffmpeg_bin, "-y", "-loglevel", "error",
            "-f", "rawvideo", "-pix_fmt", "bgr24",
            "-s", f"{w_px}x{h_px}", "-r", str(target_fps),
            "-i", "-",
        ]
        if not is_img:
            cmd_w += ["-i", src_win, "-map", "0:v:0", "-map", "1:a:0?", "-c:a", "aac", "-shortest"]
        cmd_w += [
            "-c:v", "libx264", "-pix_fmt", "yuv420p", "-crf", "18",
            "-preset", "veryfast", "-movflags", "+faststart",
            str(out_p),
        ]
        return subprocess.Popen(cmd_w, stdin=subprocess.PIPE)

    p_skel = _open_writer(skel_mp4, render_w, render_h)
    p_man = _open_writer(man_mp4, render_w, render_h)
    p_sbs = _open_writer(sbs_mp4, render_w * 2, render_h)

    for fi in range(n_frames):
        if jid and jid in active_jobs and fi % 15 == 0:
            pct = 62 + int(34 * (fi / max(n_frames, 1)))
            active_jobs[jid]["progress"] = pct
            active_jobs[jid]["stage_label"] = f"🎬 [MediaPipe 3D] Đang kết xuất {active_actor_count} Nhân Vật & Khung Xương ({fi+1}/{n_frames} frames)..."

        f_actors = actors_frames_pos[fi]
        pts_all_f = actors_joints_3d[:, fi, :, :].reshape(-1, 3)

        # Xây dựng bản đồ khớp 2D chuẩn xác theo khung hình thực tế cho từng Actor
        f_actors_2d = []
        for a_i in range(active_actor_count):
            sx_shift, sy_shift = actor_2d_shifts.get(a_i, (0.0, 0.0))
            px_map_2d = {}
            for ji, jname in enumerate(SMPL_JOINT_NAMES):
                ux = float(actors_joints_2d[a_i, fi, ji, 0]) * render_w + sx_shift
                uy = float(actors_joints_2d[a_i, fi, ji, 1]) * render_h + sy_shift
                px_map_2d[jname] = (ux, uy)
            ys_vis = [p[1] for p in px_map_2d.values()]
            skel_h_2d = max(64, int(round((max(ys_vis) - min(ys_vis)) if ys_vis else render_h * 0.65)))
            f_actors_2d.append({"px": px_map_2d, "skel_h": skel_h_2d})

        f_skel = bg_dark.copy()
        if not has_rigged_char:
            draw_shadow(f_skel, cam, pts_all_f, ground, theme=DARK_THEME)
        for a_i, pos in enumerate(f_actors):
            # Nếu Actor này đã có Ảnh Nhân Vật gắn Rig, thay thế hoàn toàn khung xương bằng nhân vật thật!
            if a_i in actor_rigs_map and mode_clean != "clean_skeleton":
                continue
            _draw_custom_colored_skeleton(f_skel, pos, HUMAN_EDGES, cam, actor_idx=a_i, thickness=3)
        _render_pinned_refs_on_frame(
            f_skel, f_actors, cam, prepared_pins,
            pin_render_mode=pin_render_mode,
            actors_2d_override=(None if angle_changed else f_actors_2d),
        )
        if mode_clean == "skeleton_overlay":
            for a_i, pos in enumerate(f_actors):
                _draw_custom_colored_skeleton(f_skel, pos, HUMAN_EDGES, cam, actor_idx=a_i, thickness=2)

        f_man = bg_grid.copy()
        draw_shadow(f_man, cam, pts_all_f, ground, theme=GRID_THEME)
        for a_i, pos in enumerate(f_actors):
            v_list, f_list, c_list = _build_mannequin_meshes(pos, actor_idx=a_i)
            draw_mesh(f_man, v_list, f_list, c_list, cam, ambient=0.36)
            _draw_custom_colored_skeleton(f_man, pos, HUMAN_EDGES, cam, actor_idx=a_i, thickness=2)

        orig_resized = cv2.resize(raw_frames_bgr[fi], (render_w, render_h), interpolation=cv2.INTER_AREA)
        f_sbs_left = orig_resized.copy()
        label_panel(f_sbs_left, "Original Video")
        f_sbs_right = f_skel.copy()
        label_panel(f_sbs_right, "Character + Bg Rig" if has_rigged_char else f"3D Skeleton ({active_actor_count} Actor{'s' if active_actor_count > 1 else ''})")
        f_sbs = np.hstack([f_sbs_left, f_sbs_right])

        if p_skel.stdin:
            p_skel.stdin.write(f_skel.tobytes())
        if p_man.stdin:
            p_man.stdin.write(f_man.tobytes())
        if p_sbs.stdin:
            p_sbs.stdin.write(f_sbs.tobytes())

    for pr in (p_skel, p_man, p_sbs):
        if pr.stdin:
            pr.stdin.close()
        pr.wait()

    ts = int(time.time())
    stem_clean = re.sub(r"[^a-zA-Z0-9_-]+", "_", Path(src_win).stem[:28]).strip("_") or "extract3d"
    studio_skel = SCRIPT_DIR / "output" / f"Extract3D_{ts}_{stem_clean}_skeleton.mp4"
    studio_skel.parent.mkdir(parents=True, exist_ok=True)
    if skel_mp4.is_file():
        shutil.copy2(skel_mp4, studio_skel)

    actors_summary = []
    if n_frames > 0:
        mid_idx = n_frames // 2
        for a_i in range(active_actor_count):
            def _norm_xy(jname: str) -> list[float]:
                ji = SMPL_JOINT_NAMES.index(jname)
                return [
                    round(float(np.clip(actors_joints_2d[a_i, mid_idx, ji, 0], 0.04, 0.96)), 3),
                    round(float(np.clip(actors_joints_2d[a_i, mid_idx, ji, 1], 0.04, 0.96)), 3),
                ]
            body_xy = _norm_xy("spine2")
            head_xy = _norm_xy("head")
            rh_xy = _norm_xy("right_hand")
            lh_xy = _norm_xy("left_hand")
            zone_vi = "Bên Trái" if body_xy[0] < 0.38 else ("Bên Phải" if body_xy[0] > 0.62 else "Chính Giữa")
            actors_summary.append({
                "actor_id": a_i + 1,
                "zone": zone_vi,
                "zone_vi": zone_vi,
                "head_xy": head_xy,
                "body_xy": body_xy,
                "rhand_xy": rh_xy,
                "lhand_xy": lh_xy,
            })

    compiled_v2v_prompt = ""
    if isinstance(ref_pins, list) and len(ref_pins) > 0:
        pin_clauses = []
        bg_clause = ""
        # Ảnh nhân vật đầu tiên đang "fixed" (khi chưa có ảnh gắn vào thân) = nhân vật thay khung xương #1
        _has_body_p = any(isinstance(rp, dict) and re.match(r"^actor\d_body$", str(rp.get("anchor") or "").lower()) for rp in ref_pins)
        _promo_p = False
        for idx_p, rp in enumerate(ref_pins):
            if not isinstance(rp, dict):
                continue
            p_num = int(rp.get("slot") or rp.get("pic_index") or (idx_p + 1))
            anc = str(rp.get("anchor") or "actor1_body").lower()
            _is_promo = False
            if not _has_body_p and not _promo_p and anc in ("fixed", ""):
                anc = "actor1_body"
                _promo_p = True
                _is_promo = True
            px_pct = int(round(float(rp.get("x", 0.5)) * 100))
            py_pct = int(round(float(rp.get("y", 0.5)) * 100))
            zone_str = "on the left side of the frame" if px_pct < 38 else ("on the right side of the frame" if px_pct > 62 else "in the center of the frame")
            if _is_promo:
                zone_str = "the main figure"
            if anc == "background":
                bg_clause = f"The whole background is the environment from <Picture {p_num}>, with its lighting and atmosphere."
            elif anc.startswith("actor") and "_body" in anc:
                a_num = anc.replace("actor", "").split("_")[0]
                pin_clauses.append(
                    f"Skeleton #{a_num} ({zone_str}) in <Video 1> is only a pose guide: replace it entirely with the full-body character from <Picture {p_num}> "
                    f"(exact face, hairstyle, skin tone and outfit), at the same position, size and pose as the skeleton"
                )
            elif anc.startswith("actor") and "_head" in anc:
                a_num = anc.replace("actor", "").split("_")[0]
                pin_clauses.append(
                    f"Lock the face and hairstyle of Character #{a_num} in <Video 1> strictly to <Picture {p_num}>"
                )
            elif anc.startswith("actor") and ("_rhand" in anc or "_lhand" in anc):
                a_num = anc.replace("actor", "").split("_")[0]
                hand_str = "right hand" if "_rhand" in anc else "left hand"
                pin_clauses.append(
                    f"Attach the prop/accessory from <Picture {p_num}> to the {hand_str} of Character #{a_num} in <Video 1>"
                )
            else:
                pin_clauses.append(
                    f"Place the subject from <Picture {p_num}> at coordinates ({px_pct}%, {py_pct}%) in <Video 1>"
                )
        parts_p = []
        if pin_clauses:
            parts_p.append(". ".join(pin_clauses) + ".")
        parts_p.append(
            "The character performs the exact body movements, arm gestures, posture and timing shown in <Video 1>."
        )
        if bg_clause:
            parts_p.append(bg_clause)
        parts_p.append(
            "Refine into seamless photorealistic 8K live-action video with natural human anatomy, fluid arm and hand articulation, realistic fabric physics and cinematic lighting."
        )
        parts_p.append("Never show <Picture N> itself as an inset photo, thumbnail, card, frame, sticker, badge or label anywhere in the video; no skeleton lines, joint dots, boxes or text remain.")
        compiled_v2v_prompt = "\n\n".join(parts_p)
    else:
        compiled_v2v_prompt = (
            "Render the character in <Video 1> with the exact appearance shown in <Picture 1>.\n\n"
            "Strictly preserve the exact face, facial structure, skin tone, hair and outfit from <Picture 1>.\n"
            "The character performs the exact same body movements, posture, gestures and timing guided by <Video 1>.\n"
            "Produce photorealistic 8K live-action human anatomy, natural fabric movement and cinematic lighting."
        )

    return {
        "ok": skel_mp4.is_file(),
        "skeleton_mp4": str(skel_mp4).replace("\\", "/"),
        "studio_skel": str(studio_skel).replace("\\", "/") if studio_skel.is_file() else str(skel_mp4).replace("\\", "/"),
        "mannequin_mp4": str(man_mp4).replace("\\", "/") if man_mp4.is_file() else None,
        "sbs_mp4": str(sbs_mp4).replace("\\", "/"),
        "glb_path": str(glb_path).replace("\\", "/") if glb_path.is_file() else None,
        "npz_path": str(npz_path).replace("\\", "/"),
        "frames": n_frames,
        "fps": target_fps,
        "actor_count": active_actor_count,
        "detected_person_count": active_actor_count,
        "actors_summary": actors_summary,
        "compiled_v2v_prompt": compiled_v2v_prompt,
        "camera_azimuth": cam_az,
        "camera_elevation": cam_el,
        "angle_changed": angle_changed,
        "track_reorders": track_swaps_fixed,
    }


def compute_v2v_pose_follow_score(src_path: str, out_path: str, src_start: float = 0.0,
                                  src_len: float = 0.0, n_samples: int = 16) -> dict:
    """#8 Chấm điểm mức độ video kết quả bám theo động tác của video nguồn (chỉ chấm, KHÔNG tự tạo lại).
    So sánh hướng 10 đoạn xương (tay, chân, vai, thân) 2D của người chính trên các khung hình cùng mốc thời gian.
    Điểm chỉ mang tính tương đối (khung xương 2D, nhân vật khác vóc dáng vẫn bị lệch nhẹ)."""
    import math
    import cv2
    import numpy as np

    s_p, o_p = win_path(src_path or ""), win_path(out_path or "")
    if not s_p or not os.path.isfile(s_p):
        return {"ok": False, "error": "Không tìm thấy video nguồn (người thật)"}
    if not o_p or not os.path.isfile(o_p):
        return {"ok": False, "error": "Không tìm thấy video kết quả để chấm"}

    def _dur(pth: str) -> float:
        cap = cv2.VideoCapture(pth)
        fps = float(cap.get(cv2.CAP_PROP_FPS) or 0.0)
        nfr = float(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0.0)
        cap.release()
        return (nfr / fps) if fps > 0 and nfr > 0 else 0.0

    def _grab(pth: str, times: list) -> list:
        cap = cv2.VideoCapture(pth)
        frames, size = [], None
        for t in times:
            cap.set(cv2.CAP_PROP_POS_MSEC, max(0.0, float(t)) * 1000.0)
            ok, frm = cap.read()
            if not ok or frm is None:
                frames.append(None)
                continue
            if size is None:
                h0, w0 = frm.shape[:2]
                sc = min(1.0, 640.0 / float(max(h0, w0, 1)))
                size = (max(64, int(w0 * sc)), max(64, int(h0 * sc)))
            frames.append(cv2.resize(frm, size, interpolation=cv2.INTER_AREA))
        cap.release()
        return frames

    d_src, d_out = _dur(s_p), _dur(o_p)
    if d_src <= 0 or d_out <= 0:
        return {"ok": False, "error": "Không đọc được thời lượng video"}
    w0 = max(0.0, min(float(src_start or 0.0), max(0.0, d_src - 0.5)))
    wl = float(src_len or 0.0)
    if wl <= 0 or w0 + wl > d_src + 0.05:
        wl = d_src - w0
    n = max(6, min(32, int(n_samples or 16)))
    fracs = [(i + 0.5) / n for i in range(n)]
    src_times = [w0 + f * wl for f in fracs]
    out_times = [f * d_out for f in fracs]
    src_frames = _grab(s_p, src_times)
    out_frames = _grab(o_p, out_times)

    def _detect(frames: list) -> list:
        valid = [f for f in frames if f is not None]
        if not valid:
            return [[] for _ in frames]
        det = _detect_poses_hybrid(valid, max_poses=3)
        res, k = [], 0
        for f in frames:
            if f is None:
                res.append([])
            else:
                res.append(det[k] if k < len(det) else [])
                k += 1
        return res

    det_s = _detect(src_frames)
    det_o = _detect(out_frames)
    bones = [(11, 13), (13, 15), (12, 14), (14, 16), (23, 25), (25, 27), (24, 26), (26, 28), (11, 12), (11, 23)]

    def _main_person(dets: list, frm):
        if not dets or frm is None:
            return None
        h_f, w_f = frm.shape[:2]
        best, best_area = None, -1.0
        for ilm, _wlm in dets:
            xs = [float(p.x) * w_f for p in ilm]
            ys = [float(p.y) * h_f for p in ilm]
            area = (max(xs) - min(xs)) * (max(ys) - min(ys))
            if area > best_area:
                best_area = area
                best = [(float(p.x) * w_f, float(p.y) * h_f, float(getattr(p, "visibility", 0.9))) for p in ilm]
        return best

    per_frame = []
    for i in range(n):
        ps = _main_person(det_s[i], src_frames[i])
        po = _main_person(det_o[i], out_frames[i])
        if ps is None:
            continue  # nguồn không thấy người -> bỏ qua frame này
        if po is None:
            per_frame.append({"t": round(out_times[i], 1), "score": 0.0, "note": "không thấy người"})
            continue
        errs = []
        for a, b in bones:
            if min(ps[a][2], ps[b][2], po[a][2], po[b][2]) < 0.4:
                continue
            vs = (ps[b][0] - ps[a][0], ps[b][1] - ps[a][1])
            vo = (po[b][0] - po[a][0], po[b][1] - po[a][1])
            ns, no = math.hypot(*vs), math.hypot(*vo)
            if ns < 1e-3 or no < 1e-3:
                continue
            cosv = max(-1.0, min(1.0, (vs[0] * vo[0] + vs[1] * vo[1]) / (ns * no)))
            errs.append(math.degrees(math.acos(cosv)))
        if len(errs) < 3:
            continue
        sc = float(np.mean([max(0.0, 1.0 - e / 90.0) for e in errs])) * 100.0
        per_frame.append({"t": round(out_times[i], 1), "score": round(sc, 1), "mean_err_deg": round(float(np.mean(errs)), 1)})

    if not per_frame:
        return {"ok": False, "error": "Không nhận diện được người trong video nguồn để so sánh"}
    overall = float(np.mean([p["score"] for p in per_frame]))
    verdict = "Bám tốt" if overall >= 80 else ("Tạm được" if overall >= 65 else "Lệch nhiều – nên cân nhắc tạo lại")
    worst = sorted(per_frame, key=lambda p: p["score"])[:3]
    return {
        "ok": True,
        "score": round(overall, 1),
        "verdict": verdict,
        "frames_scored": len(per_frame),
        "worst": worst,
        "per_frame": per_frame,
        "source": s_p.replace("\\", "/"),
        "output": o_p.replace("\\", "/"),
        "src_window": [round(w0, 2), round(w0 + wl, 2)],
    }


def pick_skeleton_video_for_style(ext_res: dict, skel_style: str):
    """Chọn video khung xương theo kiểu hiển thị; nếu file Mannequin không tồn tại thì lùi về khung xương studio.
    Trả về (path|None, style_thực_tế)."""
    style = str(skel_style or "joint_attach").strip().lower()
    if not isinstance(ext_res, dict):
        return None, style
    cands = []
    if style == "mannequin":
        cands.append(("mannequin", ext_res.get("mannequin_mp4")))
    cands.append((style if style != "mannequin" else "clean_skeleton", ext_res.get("studio_skel")))
    cands.append((style if style != "mannequin" else "clean_skeleton", ext_res.get("skeleton_mp4")))
    for st, pth in cands:
        if pth and os.path.isfile(win_path(pth)):
            return pth, st
    return None, style


# Câu lệnh nối vào prompt chế độ Audio Sync: báo cho H3 biết <Audio 1> là âm thanh tham chiếu để khớp khẩu hình.
AUDIO_SYNC_PROMPT_CLAUSE = (
    "The character from <Picture 1> speaks/sings exactly the words heard in <Audio 1>, with natural lip-sync "
    "matching the timing, rhythm and voice of <Audio 1>; the video soundtrack is <Audio 1>."
)


SKELETON_STYLE_PROMPT_CLAUSE = {
    "mannequin": "<Video 1> shows a grey 3D mannequin performing the motion; replace the mannequin entirely with the real character, do not keep any mannequin, grid or grey body surface.",
    "clean_skeleton": "<Video 1> shows a clean stick-figure skeleton on a plain background; use it only as motion guidance and render a fully realistic character, no visible bones or lines.",
}

# Màu thân khung xương của từng nhân vật (khớp với palettes trong _draw_custom_colored_skeleton)
SKELETON_ACTOR_TORSO_COLOR_EN = ["yellow", "lime-green", "pink"]


def skeleton_camera_angle_clause(azimuth: float, elevation: float) -> str:
    """Câu prompt (EN) mô tả góc máy mới khi người dùng xoay góc máy của video khung xương (#2)."""
    try:
        az = float(azimuth or 0.0)
        el = float(7.0 if elevation is None else elevation)
    except Exception:
        return ""
    parts = []
    if abs(az) > 0.5:
        parts.append(f"rotated about {abs(az):.0f} degrees to the {'right' if az > 0 else 'left'} around the subject")
    if el > 12.0:
        parts.append(f"raised to a high angle looking down about {el:.0f} degrees")
    if not parts:
        return ""
    return ("Camera angle: <Video 1> was re-rendered from a new viewpoint (" + " and ".join(parts) +
            "). Keep this exact camera angle and perspective for the whole shot.")


def skeleton_multi_actor_color_clause(actor_count: int, ref_pins: list | None) -> str:
    """Câu prompt (EN) gán màu khung xương -> <Picture N> cho từng người (#6). Chỉ dùng khi có >= 2 người."""
    try:
        n = int(actor_count or 0)
    except Exception:
        n = 0
    if n < 2:
        return ""
    slot_by_actor: dict[int, int] = {}
    for idx_p, rp in enumerate(ref_pins or []):
        if not isinstance(rp, dict) or rp.get("enabled") is False:
            continue
        anc = str(rp.get("anchor") or "").lower()
        m = re.match(r"actor(\d)_(body|head)", anc)
        if not m:
            continue
        a_num = int(m.group(1))
        if 1 <= a_num <= n and a_num not in slot_by_actor:
            try:
                slot_by_actor[a_num] = int(rp.get("slot") or rp.get("pic_index") or (idx_p + 1))
            except Exception:
                slot_by_actor[a_num] = idx_p + 1
    items = []
    for a_num in range(1, min(n, len(SKELETON_ACTOR_TORSO_COLOR_EN)) + 1):
        col = SKELETON_ACTOR_TORSO_COLOR_EN[a_num - 1]
        if a_num in slot_by_actor:
            items.append(f"the skeleton with the {col} torso is the person from <Picture {slot_by_actor[a_num]}>")
        else:
            items.append(f"the skeleton with the {col} torso is person #{a_num}")
    if not items:
        return ""
    return ("Multi-person mapping (identity stays fixed for the whole video, even when people cross paths): " +
            "; ".join(items) + ".")


def run_m2mr_extract_job(
    source_path: str,
    rig_name: str = "",
    skeleton_npz: str = "",
    device: str = "cpu",
    ref_pins: list | None = None,
    pin_render_mode: str = "joint_attach",
) -> dict:
    """Chạy trích xuất khung xương 3D 24 khớp (hỗ trợ đa người + ghim ảnh tham chiếu) & xuất file .GLB + 3 video từ Video người thật."""
    st = get_m2mr_status()
    if not st["ok"]:
        return {"ok": False, "error": "Không tìm thấy thư mục D:\\Motion2MixamoRig-main"}

    src_win = win_path(source_path)
    if not src_win or not os.path.isfile(src_win):
        return {"ok": False, "error": "File video/ảnh đầu vào không tồn tại"}

    smplx_npz_file = M2MR_DIR / "assets" / "body_models" / "smplx" / "SMPLX_NEUTRAL.npz"
    use_full_cli = bool(st["has_venv"] and smplx_npz_file.is_file() and len(st["rigs"]) > 0 and not ref_pins)

    jid = f"m2mr_{uuid.uuid4().hex[:6]}"
    clean_stem = re.sub(r"[^a-zA-Z0-9_-]+", "_", Path(src_win).stem[:30]).strip("_") or "video"
    run_out_dir = M2MR_DIR / "outputs" / f"extract_{time.strftime('%Y%m%d_%H%M%S')}_{clean_stem}"
    run_out_dir.mkdir(parents=True, exist_ok=True)
    prog_jsonl = run_out_dir / "progress.jsonl"

    active_jobs[jid] = {
        "id": jid,
        "status": "running",
        "stage": "extract",
        "queue_pos": 1,
        "stage_label": f"🦴 [3D Pose Extractor] Đang bóc tách khung xương 3D 24 khớp từ {Path(src_win).name}...",
        "output": str(run_out_dir).replace("\\", "/"),
        "gpu": "MediaPipe 3D + M2MR" if not use_full_cli else f"Local ({device.upper()})",
        "seed": "24-Joint SMPL 3D",
        "started_at": time.strftime("%H:%M:%S"),
        "log": f"Bắt đầu trích xuất khung xương 3D từ {Path(src_win).name}...",
        "progress": 12,
        "videos": [],
        "video_url": None,
        "prompt": f"[Trích xuất Khung Xương 3D] Source: {Path(src_win).name}",
        "error_diag": None,
    }

    def _bg():
        t0 = time.time()
        out_log = ""
        if use_full_cli:
            rig_path = M2MR_DIR / "assets" / "mixamo" / rig_name if rig_name else Path(win_path(st["rigs"][0]["path"]))
            if not rig_path.is_file():
                rig_path = Path(win_path(st["rigs"][0]["path"]))
            py_exe = str(M2MR_DIR / ".venv" / "Scripts" / "python.exe")
            is_img = Path(src_win).suffix.lower() in {".jpg", ".jpeg", ".png", ".webp", ".bmp"}
            cmd = [
                py_exe, "-m", "motion2mixamorig.cli", "run",
                "--image" if is_img else "--video", src_win,
                "--rig", str(rig_path),
                "--device", device,
                "--output-dir", str(run_out_dir),
                "--progress-jsonl", str(prog_jsonl),
            ]
            if skeleton_npz and os.path.isfile(win_path(skeleton_npz)):
                cmd += ["--skeleton", win_path(skeleton_npz)]

            proc = subprocess.Popen(
                cmd,
                cwd=str(M2MR_DIR),
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                encoding="utf-8",
                errors="replace",
            )
            while proc.poll() is None:
                time.sleep(1.5)
                if prog_jsonl.is_file():
                    try:
                        lines = [ln.strip() for ln in prog_jsonl.read_text(encoding="utf-8").splitlines() if ln.strip()]
                        if lines:
                            last_ev = json.loads(lines[-1])
                            pct = int(float(last_ev.get("progress") or 0.15) * 100)
                            msg = last_ev.get("message") or "Đang xử lý..."
                            active_jobs[jid]["progress"] = max(10, min(95, pct))
                            active_jobs[jid]["stage_label"] = f"🦴 [Motion2Mixamo 3D] {msg} ({pct}%)"
                    except Exception:
                        pass
            out_log = proc.stdout.read() if proc.stdout else ""
        else:
            try:
                res_mp = extract_m2mr_from_real_video_mediapipe(
                    src_win, run_out_dir, jid=jid, ref_pins=ref_pins, pin_render_mode=pin_render_mode
                )
                out_log = json.dumps(res_mp, ensure_ascii=False, indent=2)
            except Exception as exc:
                out_log = f"Lỗi trích xuất MediaPipe 3D: {exc}"

        vids_found = []
        vid_sub = run_out_dir / "videos"
        if vid_sub.is_dir():
            for vf in sorted(vid_sub.glob("*.mp4")):
                if vf.stat().st_size > 1000:
                    wp = str(vf)
                    record_h3_video(wp, title=f"🦴 [Trích Xuất 3D] {vf.name} ({Path(src_win).stem})")
                    vids_found.append({
                        "id": vf.stem,
                        "title": f"🦴 {vf.name}",
                        "path": wp.replace("\\", "/"),
                        "url": f"/api/video?path={urllib.parse.quote(wp)}",
                        "completed_at": time.strftime("%H:%M:%S"),
                        "size_mb": round(vf.stat().st_size / (1024 * 1024), 2),
                    })
        is_ok = len(vids_found) > 0 or (run_out_dir / "mixamo_character.glb").is_file()
        el = int(time.time() - t0)
        active_jobs[jid].update({
            "log": out_log,
            "status": "completed" if is_ok else "failed",
            "stage": "completed" if is_ok else "failed",
            "stage_label": (
                f"🎉 Hoàn tất trích xuất Khung Xương 3D (.GLB & {len(vids_found)} video chuyển động)!"
                if is_ok else f"❌ Trích xuất 3D gặp lỗi: {out_log[:180]}"
            ),
            "finished_at": time.strftime("%H:%M:%S (%d/%m/%Y)"),
            "elapsed_seconds": el,
            "elapsed_str": f"{el // 60}p {el % 60}s",
            "progress": 100 if is_ok else 0,
            "videos": vids_found,
            "video_url": vids_found[0]["url"] if vids_found else None,
        })

    threading.Thread(target=_bg, daemon=True).start()
    return {"ok": True, "job_id": jid, "output_dir": str(run_out_dir).replace("\\", "/")}


def generate_m2mr_motion_from_prompt(
    prompt: str,
    duration_s: float = 5.0,
    width: int = 832,
    height: int = 480,
    style: str = "skeleton",
    fps: int = 24,
    camera_azimuth: float = 0.0,
    camera_elevation: float = 8.0,
    camera_orbit: bool = False,
    camera_mode: str = "auto_multicam",
    auto_expand_long: bool = True,
    speed_mult: float = 1.0,
    sway_mult: float = 1.0,
    actor_count: int = 1,
    ref_pins: list | None = None,
    pin_render_mode: str = "joint_attach",
) -> dict:
    """Biên dịch Prompt hành động của người dùng thành chuyển động 24 khớp xương 3D (SMPL-X)
    + Mannequin 3D (hỗ trợ 1-3 nhân vật đồng thời + Ghim Vị Trí Ảnh Tham Chiếu <Picture 1..9> trực tiếp vào khớp xương/khung hình)
    và xuất ra .mp4 + skeleton_motion.npz.
    Hỗ trợ:
      - 1 đến 3 khung xương 3D (Multi-Actor 3D Skeletons) với mã màu riêng biệt và định vị không gian theo ghim tọa độ
      - 22 động tác hình thể khác biệt + biến thiên bất đối xứng Trái/Phải theo pha
      - Tự động mở rộng kịch bản liên hoàn (Choreography Progression) khi chọn thời lượng dài (8s, 10s, 15s, 30s)
      - Quỹ đạo không gian 3D liên tục (Continuous 3D Root Trajectory)
      - Đạo diễn đa góc máy tự động (Multi-Cam Cuts / Smooth Dolly Tracking / 360 Orbit / Fixed)
      - Ghim ảnh tham chiếu (Reference Image Pinning) vào từng bộ phận khớp xương / vị trí cố định / phông nền
    """
    import math
    import re
    import sys
    import numpy as np
    import cv2

    m2mr_path_str = str(M2MR_DIR)
    if M2MR_DIR.is_dir() and m2mr_path_str not in sys.path:
        sys.path.insert(0, m2mr_path_str)

    from motion2mixamorig.mixamo.render import (
        DARK_THEME,
        GRID_THEME,
        Ground,
        build_perspective_camera,
        ground_backdrop,
        draw_shadow,
        draw_skeleton,
        draw_mesh,
        label_panel,
    )
    from motion2mixamorig.mixamo.retarget import HUMAN_EDGES
    from motion2mixamorig.extract import SMPL_JOINT_NAMES

    raw_prompt = (prompt or "").strip() or "Đi catwalk từ xa lại gần, chống hông tạo dáng rồi xoay người 360 độ"
    duration_s = max(2.0, min(60.0, float(duration_s or 5.0)))
    fps = max(16, min(30, int(fps or 24)))
    width = max(320, min(1280, int(width or 832)))
    height = max(320, min(1280, int(height or 480)))
    width += width % 2
    height += height % 2
    speed_mult = max(0.4, min(2.0, float(speed_mult or 1.0)))
    sway_mult = max(0.3, min(2.0, float(sway_mult or 1.0)))
    actor_count = max(1, min(3, int(actor_count or 1)))
    # Tự động nâng số lượng khung xương nếu trong ref_pins có ghim vào actor2 / actor3 hoặc prompt nhắc tới 2-3 người
    tl_init = raw_prompt.lower()
    if actor_count == 1:
        if any(k in tl_init for k in ("3 người", "ba người", "nhóm 3", "3 cô gái", "3 nhân vật")):
            actor_count = 3
        elif any(k in tl_init for k in ("2 người", "hai người", "cặp đôi", "song ca", "nhảy đôi", "2 cô gái", "2 nhân vật")):
            actor_count = 2
    if isinstance(ref_pins, list):
        for rp in ref_pins:
            if isinstance(rp, dict):
                anc = str(rp.get("anchor") or "").lower()
                if anc.startswith("actor3"):
                    actor_count = max(actor_count, 3)
                elif anc.startswith("actor2"):
                    actor_count = max(actor_count, 2)
    n_frames = max(24, int(round(duration_s * fps)))

    # Tách prompt thành chuỗi các pha hành động nối tiếp nhau
    clauses = [
        c.strip()
        for c in re.split(r"(?:,|;|->|→|\brồi\b|\bsau đó\b|\btiếp theo\b|\bxong\b|\bvà\s+chuyển\s+sang\b)", raw_prompt, flags=re.IGNORECASE)
        if c.strip()
    ]
    if not clauses:
        clauses = [raw_prompt]

    def _classify_clause(text: str) -> str:
        t = text.lower()
        if any(k in t for k in ("ngoái nhìn", "nhìn qua vai", "quay lưng nhìn", "look back", "over shoulder")):
            return "turn_back_look"
        if any(k in t for k in ("xoay 360", "xoay vòng", "quay vòng", "xoay người", "quay người", "spin", "pirouette")):
            return "spin360"
        if any(k in t for k in ("vuốt tóc", "chải tóc", "hất tóc", "hair flip", "touch hair")):
            return "hair_flip"
        if any(k in t for k in ("hôn gió", "blow kiss", "thả tim", "flying kiss", "kiss")):
            return "blow_kiss"
        if any(k in t for k in ("3 dáng", "ba dáng", "đổi dáng liên", "nhiều dáng", "chụp ảnh", "photoshoot", "model pose")):
            return "pose_3model"
        if any(k in t for k in ("uốn sóng", "body wave", "sóng cơ thể", "uốn người", "lượn sóng")):
            return "body_wave"
        if any(k in t for k in ("kpop", "k-pop", "idol", "nhảy idol", "vũ đạo nhóm")):
            return "kpop_dance"
        if any(k in t for k in ("sexy", "uốn éo", "lắc hông", "quyến rũ", "twerk", "gợi cảm")):
            return "sexy_dance"
        if any(k in t for k in ("bước ngang", "sang ngang", "nhún ngang", "sidestep", "side step", "trái phải")):
            return "sidestep"
        if any(k in t for k in ("đi vòng", "vòng cung", "dạo vòng", "circle walk", "around")):
            return "walk_circle"
        if any(k in t for k in ("đá cao", "high kick", "xoay đá", "roundhouse", "tung cước")):
            return "high_kick"
        if any(k in t for k in ("võ", "đấm", "đá", "kick", "punch", "boxing", "kungfu", "chiến đấu")):
            return "martial"
        if any(k in t for k in ("nhảy lên", "bật nhảy", "ăn mừng", "cheer", "jump")):
            return "jump_cheer"
        if any(k in t for k in ("nhảy", "hiphop", "vũ đạo", "dance", "sôi động", "shuffle", "street")):
            return "dance_hiphop"
        if any(k in t for k in ("quỳ", "kneel", "hạ gối", "quỳ 1 gối")):
            return "kneel_pose"
        if any(k in t for k in ("ngồi", "sit", "hạ người", "squat pose")):
            return "sit_pose"
        if any(k in t for k in ("vươn vai", "uốn lưng", "ưỡn ngực", "stretch", "arch", "đứng dậy")):
            return "stretch"
        if any(k in t for k in ("chạy", "run", "sprint", "lao tới")):
            return "run"
        if any(k in t for k in ("quay lưng bước", "đi ra xa", "bước đi xa", "rời đi")):
            return "walk_away"
        if any(k in t for k in ("catwalk", "đi bộ", "bước tới", "lại gần", "đi tới", "bước đi", "walk", "dạo")):
            return "catwalk"
        if any(k in t for k in ("vẫy tay", "chào", "wave", "hello", "hi ")):
            return "wave"
        if any(k in t for k in ("cúi chào", "cúi đầu", "bow")):
            return "bow"
        if any(k in t for k in ("chống hông", "tạo dáng", "khoe dáng", "người mẫu", "pose", "đứng")):
            return "pose_hip"
        return "catwalk"

    phase_types = [_classify_clause(c) for c in clauses]

    # Ma trận đạo diễn tự động nối tiếp kịch bản (Choreography Progression Graph)
    # Khi video dài (8s, 10s, 15s, 30s) mà người dùng chỉ nhập ngắn (1-3 ý), tự động biên đạo thêm các pha nối tiếp hợp logic
    NEXT_FLOW_MAP = {
        "catwalk": ["pose_hip", "hair_flip", "spin360", "pose_3model", "turn_back_look", "walk_away", "blow_kiss"],
        "pose_hip": ["hair_flip", "pose_3model", "spin360", "blow_kiss", "walk_circle", "turn_back_look"],
        "pose_3model": ["spin360", "hair_flip", "walk_circle", "blow_kiss", "turn_back_look", "catwalk"],
        "hair_flip": ["blow_kiss", "pose_3model", "sexy_dance", "spin360", "turn_back_look"],
        "blow_kiss": ["wave", "spin360", "walk_away", "pose_hip", "sexy_dance"],
        "turn_back_look": ["catwalk", "sexy_dance", "spin360", "pose_hip", "blow_kiss"],
        "walk_away": ["turn_back_look", "spin360", "catwalk", "pose_hip"],
        "walk_circle": ["pose_3model", "hair_flip", "spin360", "sexy_dance", "pose_hip"],
        "spin360": ["pose_3model", "sexy_dance", "hair_flip", "blow_kiss", "catwalk", "kpop_dance"],
        "sexy_dance": ["body_wave", "hair_flip", "spin360", "pose_3model", "kpop_dance", "blow_kiss"],
        "body_wave": ["sexy_dance", "kpop_dance", "spin360", "hair_flip", "sidestep"],
        "kpop_dance": ["sidestep", "spin360", "body_wave", "dance_hiphop", "jump_cheer", "pose_3model"],
        "dance_hiphop": ["sidestep", "kpop_dance", "spin360", "jump_cheer", "body_wave"],
        "sidestep": ["kpop_dance", "dance_hiphop", "spin360", "sexy_dance", "pose_hip"],
        "martial": ["high_kick", "spin360", "kneel_pose", "jump_cheer", "run"],
        "high_kick": ["martial", "spin360", "kneel_pose", "pose_hip"],
        "kneel_pose": ["stretch", "pose_hip", "spin360", "catwalk"],
        "sit_pose": ["stretch", "pose_hip", "hair_flip", "wave"],
        "stretch": ["pose_hip", "catwalk", "hair_flip", "spin360"],
        "run": ["jump_cheer", "spin360", "martial", "pose_hip"],
        "jump_cheer": ["wave", "spin360", "kpop_dance", "pose_3model", "bow"],
        "wave": ["blow_kiss", "pose_hip", "catwalk", "spin360", "bow"],
        "bow": ["wave", "pose_hip", "catwalk"],
    }

    # Mục tiêu mỗi pha kéo dài khoảng ~2.6 giây để video dài luôn biến hóa liên tục, không bị lặp nhàm chán
    target_min_phases = max(len(phase_types), int(round(duration_s / 2.6))) if auto_expand_long else len(phase_types)
    target_min_phases = min(14, max(1, target_min_phases))
    step_seed = sum(ord(ch) for ch in raw_prompt) % 7
    while len(phase_types) < target_min_phases:
        last_act = phase_types[-1]
        candidates = NEXT_FLOW_MAP.get(last_act, ["pose_hip", "spin360", "hair_flip", "catwalk"])
        recent = set(phase_types[-2:])
        filtered = [c for c in candidates if c not in recent] or candidates
        chosen = filtered[(len(phase_types) + step_seed) % len(filtered)]
        phase_types.append(chosen)

    n_phases = len(phase_types)

    def _rot_x(a: float) -> np.ndarray:
        c, s = math.cos(a), math.sin(a)
        return np.array([[1.0, 0.0, 0.0], [0.0, c, -s], [0.0, s, c]], dtype=np.float64)

    def _rot_y(a: float) -> np.ndarray:
        c, s = math.cos(a), math.sin(a)
        return np.array([[c, 0.0, s], [0.0, 1.0, 0.0], [-s, 0.0, c]], dtype=np.float64)

    def _rot_z(a: float) -> np.ndarray:
        c, s = math.cos(a), math.sin(a)
        return np.array([[c, -s, 0.0], [s, c, 0.0], [0.0, 0.0, 1.0]], dtype=np.float64)

    def _euler(rx: float, ry: float, rz: float) -> np.ndarray:
        return _rot_y(ry) @ _rot_x(rx) @ _rot_z(rz)

    def _pose_params_for_action(act: str, u: float, t_sec: float, phase_idx: int = 0) -> dict:
        """Trả về góc xoay khớp (radian) và vận tốc dịch chuyển liên tục (vx, vz, vyaw) cho 22 hành động."""
        w = 2.0 * math.pi * t_sec * speed_mult
        side_sign = -1.0 if (phase_idx % 2 == 1) else 1.0
        p = {
            "vx": 0.0, "vz": 0.0, "vyaw": 0.0,
            "ox": 0.0, "dy": 0.0, "oz": 0.0, "oyaw": 0.0,
            "pelvis_tilt": (0.0, 0.0, 0.0),
            "spine": (0.0, 0.0, 0.0),
            "head": (0.0, 0.0, 0.0),
            "l_arm": (0.0, 0.0, -0.18),
            "l_fore": (0.15, 0.0, 0.0),
            "r_arm": (0.0, 0.0, 0.18),
            "r_fore": (0.15, 0.0, 0.0),
            "l_leg": (0.0, 0.0, 0.03),
            "l_knee": 0.05,
            "r_leg": (0.0, 0.0, -0.03),
            "r_knee": 0.05,
        }
        if act == "catwalk":
            cyc = w * 1.15
            s = math.sin(cyc)
            c = math.cos(cyc)
            p["vz"] = 0.36 * speed_mult
            p["dy"] = -0.025 * abs(c)
            p["ox"] = 0.038 * s
            p["pelvis_tilt"] = (0.04, -0.15 * s, 0.12 * s)
            p["spine"] = (-0.03, 0.11 * s, -0.07 * s)
            p["head"] = (0.02 * math.sin(w * 0.5), -0.06 * s, 0.03 * s)
            p["l_leg"] = (-0.54 * s, 0.0, 0.02)
            p["l_knee"] = max(0.05, 0.74 * max(0.0, -s))
            p["r_leg"] = (0.54 * s, 0.0, -0.02)
            p["r_knee"] = max(0.05, 0.74 * max(0.0, s))
            p["l_arm"] = (0.36 * s, 0.0, -0.16)
            p["l_fore"] = (-0.28 - 0.15 * max(0.0, -s), 0.0, 0.0)
            p["r_arm"] = (-0.36 * s, 0.0, 0.16)
            p["r_fore"] = (-0.28 - 0.15 * max(0.0, s), 0.0, 0.0)
        elif act == "walk_circle":
            cyc = w * 1.15
            s = math.sin(cyc)
            p["vz"] = 0.28 * math.cos(math.pi * (u - 0.3)) * speed_mult
            p["vx"] = 0.26 * math.sin(math.pi * u) * side_sign * speed_mult
            p["oyaw"] = 0.48 * math.sin(math.pi * u) * side_sign
            p["dy"] = -0.022 * abs(math.cos(cyc))
            p["pelvis_tilt"] = (0.03, -0.13 * s, 0.10 * s)
            p["spine"] = (-0.03, 0.09 * s, -0.06 * side_sign)
            p["head"] = (0.02, -0.18 * side_sign, 0.03 * s)
            p["l_leg"] = (-0.48 * s, 0.0, 0.03)
            p["l_knee"] = max(0.05, 0.68 * max(0.0, -s))
            p["r_leg"] = (0.48 * s, 0.0, -0.03)
            p["r_knee"] = max(0.05, 0.68 * max(0.0, s))
            p["l_arm"] = (0.32 * s, 0.0, -0.20)
            p["r_arm"] = (-0.32 * s, 0.0, 0.20)
        elif act == "sidestep":
            cyc = w * 1.35
            s = math.sin(cyc)
            c = math.cos(cyc)
            p["ox"] = 0.24 * s
            p["dy"] = -0.045 * abs(c)
            p["oyaw"] = 0.16 * s
            p["pelvis_tilt"] = (0.04, -0.10 * s, 0.14 * s)
            p["spine"] = (-0.04, 0.08 * s, -0.09 * s)
            p["head"] = (0.03 * c, -0.08 * s, 0.05 * s)
            p["l_arm"] = (-0.35 + 0.25 * c, 0.18, -0.45 - 0.25 * max(0.0, s))
            p["l_fore"] = (-0.85, 0.0, 0.35)
            p["r_arm"] = (-0.35 - 0.25 * c, -0.18, 0.45 + 0.25 * max(0.0, -s))
            p["r_fore"] = (-0.85, 0.0, -0.35)
            p["l_leg"] = (-0.22 * abs(s), 0.0, 0.08 + 0.14 * max(0.0, s))
            p["l_knee"] = 0.18 + 0.35 * abs(c)
            p["r_leg"] = (-0.22 * abs(s), 0.0, -0.08 - 0.14 * max(0.0, -s))
            p["r_knee"] = 0.18 + 0.35 * abs(c)
        elif act == "walk_away":
            cyc = w * 1.1
            s = math.sin(cyc)
            turn_in = min(1.0, u * 3.5)
            p["oyaw"] = math.pi * (0.5 - 0.5 * math.cos(math.pi * turn_in))
            p["vz"] = -0.32 * speed_mult
            p["dy"] = -0.02 * abs(math.cos(cyc))
            p["pelvis_tilt"] = (0.03, -0.11 * s, 0.09 * s)
            p["spine"] = (0.0, 0.08 * s, -0.05 * s)
            look_back = max(0.0, math.sin(math.pi * max(0.0, (u - 0.35) / 0.65)))
            p["head"] = (0.04 * look_back, -0.52 * look_back * side_sign, 0.05 * look_back)
            p["l_leg"] = (-0.48 * s, 0.0, 0.02)
            p["l_knee"] = max(0.05, 0.65 * max(0.0, -s))
            p["r_leg"] = (0.48 * s, 0.0, -0.02)
            p["r_knee"] = max(0.05, 0.65 * max(0.0, s))
            p["l_arm"] = (0.32 * s, 0.0, -0.16)
            p["r_arm"] = (-0.32 * s, 0.0, 0.16)
        elif act == "turn_back_look":
            arc = math.sin(math.pi * u)
            sway = math.sin(w * 0.9)
            p["oyaw"] = (2.35 * side_sign) * arc
            p["ox"] = 0.04 * sway
            p["pelvis_tilt"] = (-0.04, 0.14 * arc * side_sign, 0.11 * arc)
            p["spine"] = (-0.08 * arc, 0.28 * arc * side_sign, -0.08 * arc)
            p["head"] = (0.06 * arc, 0.46 * arc * side_sign, -0.08 * arc)
            p["l_arm"] = (0.18, 0.22, -0.64)
            p["l_fore"] = (-0.82, 0.0, 0.78)
            p["r_arm"] = (-0.38 * arc, -0.15, 0.42 + 0.55 * arc)
            p["r_fore"] = (-0.88 * arc, 0.0, -0.55 * arc)
            p["l_leg"] = (-0.08, 0.0, 0.06)
            p["r_leg"] = (0.16 * arc, -0.10, -0.09)
            p["r_knee"] = 0.34 * arc + 0.05
        elif act == "run":
            cyc = w * 1.9
            s = math.sin(cyc)
            p["vz"] = 0.52 * speed_mult
            p["dy"] = 0.045 * abs(s) - 0.03
            p["pelvis_tilt"] = (0.14, -0.16 * s, 0.08 * s)
            p["spine"] = (0.18, 0.14 * s, -0.06 * s)
            p["l_leg"] = (-0.82 * s, 0.0, 0.03)
            p["l_knee"] = 0.25 + 0.95 * max(0.0, -s)
            p["r_leg"] = (0.82 * s, 0.0, -0.03)
            p["r_knee"] = 0.25 + 0.95 * max(0.0, s)
            p["l_arm"] = (0.65 * s, 0.0, -0.22)
            p["l_fore"] = (-1.15, 0.0, 0.0)
            p["r_arm"] = (-0.65 * s, 0.0, 0.22)
            p["r_fore"] = (-1.15, 0.0, 0.0)
        elif act == "spin360":
            ease = 0.5 - 0.5 * math.cos(math.pi * u)
            p["oyaw"] = 2.0 * math.pi * ease * side_sign
            step = math.sin(4.0 * math.pi * u)
            p["dy"] = -0.018 * abs(step)
            p["pelvis_tilt"] = (0.0, 0.0, 0.06 * step)
            p["spine"] = (-0.05, 0.12 * math.sin(math.pi * u) * side_sign, 0.0)
            p["head"] = (0.0, 0.22 * math.sin(2.0 * math.pi * u) * side_sign, 0.04)
            flare = math.sin(math.pi * u)
            p["l_arm"] = (-0.15, 0.0, -0.35 - 0.55 * flare)
            p["l_fore"] = (-0.35, 0.0, 0.20 * flare)
            p["r_arm"] = (-0.15, 0.0, 0.35 + 0.55 * flare)
            p["r_fore"] = (-0.35, 0.0, -0.20 * flare)
            p["l_leg"] = (-0.22 * step, 0.0, 0.05)
            p["l_knee"] = max(0.05, 0.35 * max(0.0, -step))
            p["r_leg"] = (0.22 * step, 0.0, -0.05)
            p["r_knee"] = max(0.05, 0.35 * max(0.0, step))
        elif act == "pose_hip":
            sway = math.sin(w * 0.75)
            p["ox"] = 0.045 * sway * side_sign
            p["oyaw"] = 0.22 * side_sign * math.sin(math.pi * u)
            p["pelvis_tilt"] = (-0.04, 0.12 * sway, 0.13 * side_sign)
            p["spine"] = (-0.06, -0.08 * sway, -0.09 * side_sign)
            p["head"] = (0.04, 0.15 * sway, -0.08 * side_sign)
            p["l_arm"] = (0.18, 0.25, -0.68)
            p["l_fore"] = (-0.85, 0.0, 0.82)
            p["r_arm"] = (-0.22 + 0.12 * sway, -0.15, 0.58)
            p["r_fore"] = (-0.75, 0.0, -0.72)
            p["l_leg"] = (-0.08, 0.0, 0.06)
            p["l_knee"] = 0.04
            p["r_leg"] = (0.14, -0.12, -0.09)
            p["r_knee"] = 0.32
        elif act == "pose_3model":
            sub = u * 3.0
            sub_idx = min(2, int(sub))
            sub_u = sub - sub_idx
            pulse = math.sin(math.pi * sub_u)
            if sub_idx == 0:
                p["oyaw"] = -0.35 * side_sign
                p["ox"] = -0.04 * side_sign
                p["pelvis_tilt"] = (-0.05, -0.14 * side_sign, 0.14 * side_sign)
                p["spine"] = (-0.07, 0.10 * side_sign, -0.10 * side_sign)
                p["head"] = (0.04, 0.18 * side_sign, -0.07 * side_sign)
                p["l_arm"] = (0.18, 0.25, -0.68)
                p["l_fore"] = (-0.85, 0.0, 0.82)
                p["r_arm"] = (-0.75 * pulse - 0.25, -0.25, 0.45)
                p["r_fore"] = (-1.15 * pulse - 0.35, 0.0, -0.45)
                p["r_knee"] = 0.32
            elif sub_idx == 1:
                p["oyaw"] = 0.38 * side_sign
                p["ox"] = 0.05 * side_sign
                p["pelvis_tilt"] = (-0.06, 0.16 * side_sign, -0.15 * side_sign)
                p["spine"] = (-0.11, -0.12 * side_sign, 0.11 * side_sign)
                p["head"] = (-0.06, -0.16 * side_sign, 0.09 * side_sign)
                p["l_arm"] = (-0.55, 0.22, -1.22)
                p["l_fore"] = (-1.18, 0.0, 0.92)
                p["r_arm"] = (0.18, -0.25, 0.66)
                p["r_fore"] = (-0.84, 0.0, -0.80)
                p["l_knee"] = 0.34
            else:
                p["oyaw"] = 0.08 * side_sign
                p["pelvis_tilt"] = (-0.05, 0.0, 0.12 * side_sign)
                p["spine"] = (-0.12, 0.0, -0.08 * side_sign)
                p["head"] = (-0.04, 0.08 * side_sign, -0.05)
                p["l_arm"] = (0.15, 0.22, -0.62)
                p["l_fore"] = (-0.82, 0.0, 0.76)
                p["r_arm"] = (0.15, -0.22, 0.62)
                p["r_fore"] = (-0.82, 0.0, -0.76)
                p["r_leg"] = (0.15, -0.10, -0.11)
                p["r_knee"] = 0.28
        elif act == "hair_flip":
            lift = math.sin(math.pi * u)
            sway = math.sin(w * 0.9)
            p["ox"] = 0.04 * sway
            p["oyaw"] = 0.20 * sway
            p["pelvis_tilt"] = (-0.05, 0.12 * sway, 0.13)
            p["spine"] = (-0.12 * lift, -0.08 * sway, -0.08)
            p["head"] = (-0.16 * lift, 0.18 * sway, 0.12 * lift)
            p["l_arm"] = (-0.58 * lift, 0.25, -0.35 - 1.05 * lift)
            p["l_fore"] = (-1.22 * lift - 0.15, 0.0, 0.95 * lift)
            p["r_arm"] = (-0.48 * lift, -0.22, 0.35 + 0.95 * lift)
            p["r_fore"] = (-1.15 * lift - 0.15, 0.0, -0.88 * lift)
            p["l_leg"] = (-0.06, 0.0, 0.05)
            p["r_leg"] = (0.12, -0.08, -0.08)
            p["r_knee"] = 0.26
        elif act == "blow_kiss":
            touch = max(0.0, math.sin(math.pi * min(1.0, u * 1.6)))
            send = max(0.0, math.sin(math.pi * max(0.0, (u - 0.35) / 0.65)))
            p["ox"] = 0.035 * math.sin(w * 0.8)
            p["pelvis_tilt"] = (-0.04, 0.10 * send, 0.11)
            p["spine"] = (0.08 * send - 0.05 * touch, -0.08 * send, -0.07)
            p["head"] = (0.06 * send, 0.12 * send, 0.08 * touch)
            p["l_arm"] = (0.16, 0.22, -0.62)
            p["l_fore"] = (-0.82, 0.0, 0.78)
            p["r_arm"] = (-0.95 * touch - 0.72 * send, -0.35 * touch, 0.35 + 0.45 * send)
            p["r_fore"] = (-1.32 * touch - 0.25 * send, 0.0, -0.55 * touch)
            p["r_leg"] = (0.14, 0.0, -0.07)
            p["r_knee"] = 0.24
        elif act == "body_wave":
            w_wave = w * 1.35
            s_chest = math.sin(w_wave)
            s_pelvis = math.sin(w_wave - 1.05)
            s_knee = math.sin(w_wave - 1.95)
            p["ox"] = 0.055 * math.sin(w_wave * 0.5)
            p["oz"] = 0.065 * s_pelvis
            p["dy"] = -0.055 * (0.5 + 0.5 * s_knee)
            p["oyaw"] = 0.32 * math.cos(w_wave * 0.5)
            p["pelvis_tilt"] = (0.22 * s_pelvis, 0.14 * s_chest, 0.12 * s_pelvis)
            p["spine"] = (-0.26 * s_chest, -0.12 * s_pelvis, -0.09 * s_chest)
            p["head"] = (0.14 * s_chest, 0.08 * s_pelvis, 0.06 * s_chest)
            p["l_arm"] = (-0.35 + 0.25 * s_chest, 0.18, -0.75 - 0.35 * max(0.0, s_chest))
            p["l_fore"] = (-0.85, 0.0, 0.65)
            p["r_arm"] = (-0.35 - 0.25 * s_chest, -0.18, 0.75 + 0.35 * max(0.0, -s_chest))
            p["r_fore"] = (-0.85, 0.0, -0.65)
            p["l_leg"] = (-0.24 * (0.5 + 0.5 * s_knee), 0.0, 0.06)
            p["l_knee"] = 0.38 * (0.5 + 0.5 * s_knee) + 0.06
            p["r_leg"] = (-0.24 * (0.5 + 0.5 * s_knee), 0.0, -0.06)
            p["r_knee"] = 0.38 * (0.5 + 0.5 * s_knee) + 0.06
        elif act == "kpop_dance":
            s1 = math.sin(w * 1.65)
            c1 = math.cos(w * 1.65)
            s2 = math.sin(w * 3.3)
            p["ox"] = 0.12 * s1
            p["dy"] = -0.05 * abs(s2)
            p["oyaw"] = 0.36 * s1
            p["pelvis_tilt"] = (0.06 * s2, -0.20 * s1, 0.16 * c1)
            p["spine"] = (-0.08 * abs(s2), 0.18 * s1, -0.12 * c1)
            p["head"] = (0.06 * s2, -0.16 * s1, 0.09 * c1)
            p["l_arm"] = (-0.75 + 0.45 * c1, 0.28, -1.05 - 0.35 * max(0.0, s1))
            p["l_fore"] = (-1.15 + 0.35 * s1, 0.0, 0.65)
            p["r_arm"] = (-0.75 - 0.45 * c1, -0.28, 1.05 + 0.35 * max(0.0, -s1))
            p["r_fore"] = (-1.15 - 0.35 * s1, 0.0, -0.65)
            p["l_leg"] = (-0.28 * max(0.0, s1), 0.0, 0.09 + 0.08 * max(0.0, c1))
            p["l_knee"] = 0.22 + 0.38 * max(0.0, s1)
            p["r_leg"] = (-0.28 * max(0.0, -s1), 0.0, -0.09 - 0.08 * max(0.0, -c1))
            p["r_knee"] = 0.22 + 0.38 * max(0.0, -s1)
        elif act == "sexy_dance":
            s1 = math.sin(w * 1.1)
            c1 = math.cos(w * 1.1)
            s2 = math.sin(w * 2.2)
            p["ox"] = 0.075 * s1
            p["dy"] = -0.035 * (0.5 + 0.5 * s2)
            p["oyaw"] = 0.28 * c1 * side_sign
            p["pelvis_tilt"] = (0.09 * c1, 0.22 * s1, 0.16 * s1)
            p["spine"] = (-0.11 * c1, -0.14 * s1, -0.12 * s1)
            p["head"] = (0.06 * s1, -0.12 * c1, 0.09 * s1)
            p["l_arm"] = (-0.55 + 0.15 * s1, 0.2, -1.25)
            p["l_fore"] = (-1.15, 0.0, 0.95)
            p["r_arm"] = (0.15 * c1, 0.2, 0.55 + 0.15 * s1)
            p["r_fore"] = (-0.75, 0.0, -0.55)
            p["l_leg"] = (-0.18 * s1, 0.0, 0.07)
            p["l_knee"] = 0.18 + 0.18 * max(0.0, -s1)
            p["r_leg"] = (0.18 * s1, 0.0, -0.07)
            p["r_knee"] = 0.18 + 0.18 * max(0.0, s1)
        elif act == "dance_hiphop":
            s1 = math.sin(w * 1.5)
            s2 = math.sin(w * 3.0)
            p["ox"] = 0.11 * s1
            p["dy"] = -0.055 * abs(s2)
            p["oyaw"] = 0.32 * s1
            p["pelvis_tilt"] = (0.08 * s2, -0.18 * s1, 0.12 * s1)
            p["spine"] = (0.10 * s2, 0.15 * s1, -0.08 * s1)
            p["head"] = (0.08 * s2, -0.10 * s1, 0.06 * s1)
            p["l_arm"] = (-0.65 - 0.45 * s1, 0.2, -0.85 - 0.35 * s2)
            p["l_fore"] = (-0.95 + 0.35 * s2, 0.0, 0.35)
            p["r_arm"] = (-0.65 + 0.45 * s1, -0.2, 0.85 + 0.35 * s2)
            p["r_fore"] = (-0.95 - 0.35 * s2, 0.0, -0.35)
            p["l_leg"] = (-0.32 * max(0.0, s1), 0.0, 0.09 + 0.08 * max(0.0, s1))
            p["l_knee"] = 0.24 + 0.42 * max(0.0, s1)
            p["r_leg"] = (-0.32 * max(0.0, -s1), 0.0, -0.09 - 0.08 * max(0.0, -s1))
            p["r_knee"] = 0.24 + 0.42 * max(0.0, -s1)
        elif act == "wave":
            sway = math.sin(w * 0.8)
            wave_osc = math.sin(w * 2.8)
            p["ox"] = 0.03 * sway
            p["pelvis_tilt"] = (0.0, 0.06 * sway, 0.07 * sway)
            p["spine"] = (-0.04, -0.05 * sway, -0.05 * sway)
            p["head"] = (0.03, 0.08 * sway, 0.06)
            p["l_arm"] = (0.12, 0.2, -0.55)
            p["l_fore"] = (-0.68, 0.0, 0.65)
            p["r_arm"] = (-0.35, 0.0, 1.42)
            p["r_fore"] = (-0.75, 0.0, -0.35 + 0.42 * wave_osc)
            p["l_leg"] = (0.0, 0.0, 0.05)
            p["r_leg"] = (0.08, 0.0, -0.07)
            p["r_knee"] = 0.16
        elif act == "high_kick":
            kick = max(0.0, math.sin(math.pi * u))
            p["dy"] = -0.04 * kick
            p["oyaw"] = -0.55 * kick * side_sign
            p["pelvis_tilt"] = (-0.18 * kick, 0.28 * kick * side_sign, -0.22 * kick)
            p["spine"] = (-0.22 * kick, -0.25 * kick * side_sign, -0.24 * kick)
            p["l_arm"] = (-0.85 * kick, 0.25, -0.55)
            p["l_fore"] = (-1.05, 0.0, 0.25)
            p["r_arm"] = (-0.65 * kick, -0.25, 0.75)
            p["r_fore"] = (-0.95, 0.0, -0.25)
            p["l_leg"] = (-0.15 * kick, 0.0, 0.10)
            p["l_knee"] = 0.22
            p["r_leg"] = (-1.48 * kick, 0.0, -0.14 - 0.42 * kick)
            p["r_knee"] = 0.10 * kick + 0.22 * (1.0 - kick)
        elif act == "martial":
            s1 = math.sin(w * 1.6)
            kick = max(0.0, math.sin(w * 0.9 - 0.4))
            p["dy"] = -0.05
            p["oyaw"] = -0.35 + 0.45 * s1
            p["pelvis_tilt"] = (0.08, 0.25 * s1, -0.12 * kick)
            p["spine"] = (0.12, -0.28 * s1, -0.18 * kick)
            punch_l = max(0.0, s1)
            punch_r = max(0.0, -s1)
            p["l_arm"] = (-1.15 - 0.35 * punch_l, 0.25, -0.32)
            p["l_fore"] = (-1.35 * (1.0 - 0.85 * punch_l), 0.0, 0.15)
            p["r_arm"] = (-1.15 - 0.35 * punch_r, -0.25, 0.32)
            p["r_fore"] = (-1.35 * (1.0 - 0.85 * punch_r), 0.0, -0.15)
            p["l_leg"] = (-0.25, 0.0, 0.12)
            p["l_knee"] = 0.28
            p["r_leg"] = (-1.15 * kick + 0.18 * (1.0 - kick), 0.0, -0.12 - 0.32 * kick)
            p["r_knee"] = 0.25 * (1.0 - kick) + 0.12 * kick
        elif act == "jump_cheer":
            cyc = (u * 2.0) % 1.0
            jump = max(0.0, math.sin(math.pi * cyc))
            squat = max(0.0, -math.sin(2.0 * math.pi * cyc))
            p["dy"] = 0.26 * (jump ** 1.4) - 0.11 * squat
            p["spine"] = (-0.12 * jump + 0.18 * squat, 0.0, 0.0)
            p["l_arm"] = (-0.25, 0.0, -0.35 - 1.25 * jump)
            p["l_fore"] = (-0.25, 0.0, 0.0)
            p["r_arm"] = (-0.25, 0.0, 0.35 + 1.25 * jump)
            p["r_fore"] = (-0.25, 0.0, 0.0)
            p["l_leg"] = (-0.55 * squat - 0.25 * jump, 0.0, 0.06 + 0.08 * jump)
            p["l_knee"] = 0.95 * squat + 0.35 * jump
            p["r_leg"] = (-0.55 * squat - 0.25 * jump, 0.0, -0.06 - 0.08 * jump)
            p["r_knee"] = 0.95 * squat + 0.35 * jump
        elif act == "kneel_pose":
            kn = math.sin(math.pi * min(1.0, u * 1.25)) if n_phases == 1 else math.sin(math.pi * u)
            p["dy"] = -0.36 * kn
            p["spine"] = (-0.06 * kn, 0.12 * kn * side_sign, 0.0)
            p["head"] = (-0.08 * kn, 0.15 * kn * side_sign, 0.0)
            p["l_leg"] = (-1.35 * kn, 0.0, 0.06)
            p["l_knee"] = 1.45 * kn
            p["r_leg"] = (0.25 * kn, 0.0, -0.05)
            p["r_knee"] = 1.55 * kn
            p["l_arm"] = (-0.45 * kn, 0.15, -0.35)
            p["l_fore"] = (-0.55 * kn, 0.0, 0.25)
            p["r_arm"] = (0.15, -0.22, 0.62 * kn + 0.18)
            p["r_fore"] = (-0.82 * kn, 0.0, -0.72 * kn)
        elif act == "sit_pose":
            sit = math.sin(math.pi * min(1.0, u * 1.3)) if n_phases == 1 else (0.5 - 0.5 * math.cos(math.pi * u))
            p["dy"] = -0.32 * sit
            p["oz"] = -0.08 * sit
            p["spine"] = (0.08 * sit, 0.06 * math.sin(w * 0.7), 0.0)
            p["l_leg"] = (-1.28 * sit, 0.0, 0.05)
            p["l_knee"] = 1.35 * sit
            p["r_leg"] = (-1.28 * sit, 0.0, -0.05)
            p["r_knee"] = 1.35 * sit
            p["l_arm"] = (-0.35 * sit, 0.0, -0.18)
            p["l_fore"] = (-0.45 * sit, 0.0, 0.18 * sit)
            p["r_arm"] = (-0.35 * sit, 0.0, 0.18)
            p["r_fore"] = (-0.45 * sit, 0.0, -0.18 * sit)
        elif act == "stretch":
            arch = math.sin(math.pi * u)
            p["spine"] = (-0.22 * arch, 0.08 * math.sin(w * 0.6), 0.0)
            p["head"] = (-0.18 * arch, 0.0, 0.0)
            p["l_arm"] = (-0.35 * arch, 0.0, -0.25 - 1.25 * arch)
            p["l_fore"] = (-0.35 * arch, 0.0, 0.22 * arch)
            p["r_arm"] = (-0.35 * arch, 0.0, 0.25 + 1.25 * arch)
            p["r_fore"] = (-0.35 * arch, 0.0, -0.22 * arch)
        elif act == "bow":
            bow = math.sin(math.pi * u)
            p["spine"] = (0.65 * bow, 0.0, 0.0)
            p["head"] = (0.25 * bow, 0.0, 0.0)
            p["r_arm"] = (-0.45 * bow, 0.35 * bow, 0.25)
            p["r_fore"] = (-0.95 * bow, 0.0, -0.65 * bow)
        if abs(sway_mult - 1.0) > 1e-3:
            p["ox"] = p["ox"] * sway_mult
            p["pelvis_tilt"] = tuple(x * sway_mult for x in p["pelvis_tilt"])
            p["spine"] = tuple(x * sway_mult for x in p["spine"])
        return p

    def _lerp_pose(p1: dict, p2: dict, a: float) -> dict:
        out = {}
        for k in p1:
            v1, v2 = p1[k], p2[k]
            if isinstance(v1, tuple):
                out[k] = tuple((1.0 - a) * x + a * y for x, y in zip(v1, v2))
            else:
                out[k] = (1.0 - a) * v1 + a * v2
        return out

    def _fk_human(pose: dict) -> dict[str, np.ndarray]:
        """Tính tọa độ 3D (mét, Y-up) của đủ 24 khớp SMPL từ pose parameters."""
        R_root = _rot_y(pose["yaw"]) @ _euler(*pose["pelvis_tilt"])
        pelvis = np.array([pose["dx"], 0.94 + pose["dy"], pose["dz"]], dtype=np.float64)

        R_sp1 = R_root @ _euler(*(x * 0.35 for x in pose["spine"]))
        R_sp2 = R_sp1 @ _euler(*(x * 0.35 for x in pose["spine"]))
        R_sp3 = R_sp2 @ _euler(*(x * 0.30 for x in pose["spine"]))
        R_neck = R_sp3 @ _euler(*(x * 0.45 for x in pose["head"]))
        R_head = R_neck @ _euler(*(x * 0.55 for x in pose["head"]))

        spine1 = pelvis + R_root @ np.array([0.0, 0.11, 0.0])
        spine2 = spine1 + R_sp1 @ np.array([0.0, 0.13, 0.0])
        spine3 = spine2 + R_sp2 @ np.array([0.0, 0.13, 0.0])
        neck = spine3 + R_sp3 @ np.array([0.0, 0.10, 0.0])
        head = neck + R_neck @ np.array([0.0, 0.19, 0.02])

        l_collar = spine3 + R_sp3 @ np.array([0.06, 0.05, 0.0])
        r_collar = spine3 + R_sp3 @ np.array([-0.06, 0.05, 0.0])
        l_shoulder = l_collar + R_sp3 @ np.array([0.11, 0.01, 0.0])
        r_shoulder = r_collar + R_sp3 @ np.array([-0.11, 0.01, 0.0])

        R_la = R_sp3 @ _euler(*pose["l_arm"])
        l_elbow = l_shoulder + R_la @ np.array([0.0, -0.27, 0.0])
        R_lf = R_la @ _euler(*pose["l_fore"])
        l_wrist = l_elbow + R_lf @ np.array([0.0, -0.25, 0.0])
        l_hand = l_wrist + R_lf @ np.array([0.0, -0.09, 0.02])

        R_ra = R_sp3 @ _euler(*pose["r_arm"])
        r_elbow = r_shoulder + R_ra @ np.array([0.0, -0.27, 0.0])
        R_rf = R_ra @ _euler(*pose["r_fore"])
        r_wrist = r_elbow + R_rf @ np.array([0.0, -0.25, 0.0])
        r_hand = r_wrist + R_rf @ np.array([0.0, -0.09, 0.02])

        l_hip = pelvis + R_root @ np.array([0.095, -0.05, 0.0])
        r_hip = pelvis + R_root @ np.array([-0.095, -0.05, 0.0])

        R_ll = _rot_y(pose["yaw"]) @ _euler(*pose["l_leg"])
        l_knee = l_hip + R_ll @ np.array([0.0, -0.42, 0.0])
        R_lk = R_ll @ _rot_x(pose["l_knee"])
        l_ankle = l_knee + R_lk @ np.array([0.0, -0.41, 0.0])
        l_foot = l_ankle + _rot_y(pose["yaw"]) @ np.array([0.0, -0.05, 0.13])

        R_rl = _rot_y(pose["yaw"]) @ _euler(*pose["r_leg"])
        r_knee = r_hip + R_rl @ np.array([0.0, -0.42, 0.0])
        R_rk = R_rl @ _rot_x(pose["r_knee"])
        r_ankle = r_knee + R_rk @ np.array([0.0, -0.41, 0.0])
        r_foot = r_ankle + _rot_y(pose["yaw"]) @ np.array([0.0, -0.05, 0.13])

        pos = {
            "pelvis": pelvis,
            "left_hip": l_hip,
            "right_hip": r_hip,
            "spine1": spine1,
            "left_knee": l_knee,
            "right_knee": r_knee,
            "spine2": spine2,
            "left_ankle": l_ankle,
            "right_ankle": r_ankle,
            "spine3": spine3,
            "left_foot": l_foot,
            "right_foot": r_foot,
            "neck": neck,
            "left_collar": l_collar,
            "right_collar": r_collar,
            "head": head,
            "left_shoulder": l_shoulder,
            "right_shoulder": r_shoulder,
            "left_elbow": l_elbow,
            "right_elbow": r_elbow,
            "left_wrist": l_wrist,
            "right_wrist": r_wrist,
            "left_hand": l_hand,
            "right_hand": r_hand,
        }
        # Giữ bàn chân luôn chạm sàn (không lún xuống dưới y=0.0)
        min_y = min(float(pos["left_foot"][1]), float(pos["right_foot"][1]), float(pos["left_ankle"][1]), float(pos["right_ankle"][1]))
        if min_y < 0.0:
            lift = -min_y
            for k in pos:
                pos[k][1] += lift
        return pos

    # Tạo toàn bộ chuỗi khung hình 3D với tích phân quỹ đạo không gian liên tục (Continuous 3D Root Trajectory) cho 1..3 nhân vật
    default_x_slots = [0.0] if actor_count == 1 else ([-0.44, 0.44] if actor_count == 2 else [-0.58, 0.0, 0.58])
    actor_init_x = list(default_x_slots)
    actor_init_z = [-0.45 if phase_types[0] in ("catwalk", "run") else 0.0 for _ in range(actor_count)]

    if isinstance(ref_pins, list):
        for rp in ref_pins:
            if not isinstance(rp, dict):
                continue
            anc = str(rp.get("anchor") or "").lower()
            for a_i in range(actor_count):
                if anc in (f"actor{a_i+1}_body", f"actor{a_i+1}_head"):
                    try:
                        px = float(rp.get("x", 0.5))
                        py = float(rp.get("y", 0.5))
                        actor_init_x[a_i] = (px - 0.5) * 1.45
                        actor_init_z[a_i] += (py - 0.52) * 0.65
                    except Exception:
                        pass

    actors_frames_pos: list[list[dict[str, np.ndarray]]] = [[] for _ in range(n_frames)]
    actors_joints_3d = np.zeros((actor_count, n_frames, len(SMPL_JOINT_NAMES), 3), dtype=np.float32)
    frame_phase_indices: list[int] = [0] * n_frames

    dt = 1.0 / float(fps)
    for a_i in range(actor_count):
        world_x = float(actor_init_x[a_i])
        world_z = float(actor_init_z[a_i])
        world_yaw = 0.0
        phase_shift = a_i * 0.14  # Độ lệch nhịp tự nhiên giữa các nhân vật khi nhảy nhóm / catwalk đôi

        for fi in range(n_frames):
            u_global = fi / max(n_frames - 1, 1)
            t_sec = fi / float(fps) + phase_shift
            scaled = u_global * n_phases
            idx = min(int(scaled), n_phases - 1)
            u_local = scaled - idx
            if a_i == 0:
                frame_phase_indices[fi] = idx

            pose = _pose_params_for_action(phase_types[idx], u_local, t_sec, idx + a_i)
            if idx + 1 < n_phases and u_local > 0.78:
                blend = (u_local - 0.78) / 0.22
                blend = 0.5 - 0.5 * math.cos(math.pi * blend)
                next_pose = _pose_params_for_action(phase_types[idx + 1], 0.0, t_sec, idx + 1 + a_i)
                pose = _lerp_pose(pose, next_pose, blend)

            min_x_bound = float(actor_init_x[a_i]) - (0.65 if actor_count == 1 else 0.34)
            max_x_bound = float(actor_init_x[a_i]) + (0.65 if actor_count == 1 else 0.34)
            world_x = max(min_x_bound, min(max_x_bound, world_x + pose["vx"] * dt))
            world_z = max(-0.62, min(0.62, world_z + pose["vz"] * dt))
            world_yaw += pose["vyaw"] * dt

            pose["dx"] = world_x + pose["ox"] * (1.0 if actor_count == 1 else 0.72)
            pose["dz"] = world_z + pose["oz"]
            pose["yaw"] = world_yaw + pose["oyaw"]

            pos = _fk_human(pose)
            actors_frames_pos[fi].append(pos)
            for ji, jname in enumerate(SMPL_JOINT_NAMES):
                actors_joints_3d[a_i, fi, ji] = pos[jname]

    frames_pos = [actors_frames_pos[fi][0] for fi in range(n_frames)]
    joints_3d_arr = actors_joints_3d[0]

    # Hàm tạo lưới Mannequin 3D có khối (Lambert-shaded) gắn theo khớp xương
    def _build_limb_frustum(a: np.ndarray, b: np.ndarray, ra: float, rb: float, sides: int = 10) -> tuple[np.ndarray, np.ndarray]:
        axis = b - a
        length = float(np.linalg.norm(axis))
        if length < 1e-6:
            axis = np.array([0.0, 1.0, 0.0])
        else:
            axis = axis / length
        ref = np.array([0.0, 0.0, 1.0]) if abs(axis[2]) < 0.9 else np.array([1.0, 0.0, 0.0])
        u = np.cross(axis, ref)
        u = u / max(float(np.linalg.norm(u)), 1e-8)
        v = np.cross(axis, u)
        angles = np.linspace(0.0, 2.0 * math.pi, sides, endpoint=False)
        ca, sa = np.cos(angles)[:, None], np.sin(angles)[:, None]
        ring_a = a[None, :] + ra * (ca * u[None, :] + sa * v[None, :])
        ring_b = b[None, :] + rb * (ca * u[None, :] + sa * v[None, :])
        cap_a = a - axis * (ra * 0.35)
        cap_b = b + axis * (rb * 0.35)
        verts = np.vstack([ring_a, ring_b, cap_a[None, :], cap_b[None, :]])
        center = 0.5 * (a + b)
        tris = []
        idx_ca = 2 * sides
        idx_cb = 2 * sides + 1
        for i in range(sides):
            j = (i + 1) % sides
            tris.append([i, j, sides + j])
            tris.append([i, sides + j, sides + i])
            tris.append([idx_ca, j, i])
            tris.append([idx_cb, sides + i, sides + j])
        faces = np.asarray(tris, dtype=np.int32)
        p0, p1, p2 = verts[faces[:, 0]], verts[faces[:, 1]], verts[faces[:, 2]]
        normals = np.cross(p1 - p0, p2 - p0)
        mids = (p0 + p1 + p2) / 3.0 - center[None, :]
        flip = np.sum(normals * mids, axis=1) < 0.0
        faces[flip, 1], faces[flip, 2] = faces[flip, 2].copy(), faces[flip, 1].copy()
        return verts, faces

    def _build_mannequin_meshes(pos: dict[str, np.ndarray], actor_idx: int = 0):
        torso_tints = [
            np.array([210, 185, 145], dtype=np.float64),
            np.array([215, 155, 185], dtype=np.float64),
            np.array([150, 210, 175], dtype=np.float64),
        ]
        t_col = torso_tints[actor_idx % len(torso_tints)]
        parts = [
            (pos["pelvis"], pos["spine1"], 0.125, 0.115, t_col * 0.92),
            (pos["spine1"], pos["spine3"], 0.115, 0.145, t_col),
            (pos["spine3"], pos["neck"], 0.135, 0.055, t_col * 0.92),
            (pos["neck"], pos["head"], 0.078, 0.092, np.array([225, 205, 175], dtype=np.float64)),
            (pos["left_shoulder"], pos["left_elbow"], 0.048, 0.040, np.array([215, 180, 125], dtype=np.float64)),
            (pos["left_elbow"], pos["left_wrist"], 0.039, 0.030, np.array([215, 180, 125], dtype=np.float64)),
            (pos["left_wrist"], pos["left_hand"], 0.032, 0.024, np.array([225, 200, 165], dtype=np.float64)),
            (pos["right_shoulder"], pos["right_elbow"], 0.048, 0.040, np.array([165, 165, 220], dtype=np.float64)),
            (pos["right_elbow"], pos["right_wrist"], 0.039, 0.030, np.array([165, 165, 220], dtype=np.float64)),
            (pos["right_wrist"], pos["right_hand"], 0.032, 0.024, np.array([225, 200, 165], dtype=np.float64)),
            (pos["left_hip"], pos["left_knee"], 0.072, 0.052, np.array([205, 175, 130], dtype=np.float64)),
            (pos["left_knee"], pos["left_ankle"], 0.050, 0.036, np.array([205, 175, 130], dtype=np.float64)),
            (pos["left_ankle"], pos["left_foot"], 0.038, 0.032, np.array([180, 160, 135], dtype=np.float64)),
            (pos["right_hip"], pos["right_knee"], 0.072, 0.052, np.array([160, 165, 210], dtype=np.float64)),
            (pos["right_knee"], pos["right_ankle"], 0.050, 0.036, np.array([160, 165, 210], dtype=np.float64)),
            (pos["right_ankle"], pos["right_foot"], 0.038, 0.032, np.array([180, 160, 135], dtype=np.float64)),
        ]
        v_list, f_list, c_list = [], [], []
        for a, b, ra, rb, col in parts:
            v, f = _build_limb_frustum(a, b, ra, rb, sides=10)
            v_list.append(v)
            f_list.append(f)
            c_list.append(col)
        return v_list, f_list, c_list

    # Xây dựng Hệ thống Đạo diễn Đa Góc Quay 3D (Multi-Angle Cinema Camera Director) & Mặt sàn lưới 3D
    axes = {
        "right": np.array([1.0, 0.0, 0.0]),
        "up": np.array([0.0, 1.0, 0.0]),
        "forward": np.array([0.0, 0.0, 1.0]),
    }
    all_pts = actors_joints_3d.reshape(-1, 3)
    pad_pts = np.vstack([
        all_pts,
        all_pts + np.array([0.32, 0.42, 0.32]),
        all_pts - np.array([0.32, 0.22, 0.32]),
    ])
    tl = raw_prompt.lower()
    base_az_deg = float(camera_azimuth) if camera_azimuth is not None else (22.0 if "nghiêng" in tl else 0.0)
    el_deg = float(camera_elevation) if camera_elevation is not None else 8.0
    ground = Ground(
        y=0.0,
        cx=float(0.5 * (all_pts[:, 0].min() + all_pts[:, 0].max())),
        cz=float(0.5 * (all_pts[:, 2].min() + all_pts[:, 2].max())),
    )

    is_sbs = (style == "side_by_side")
    panel_w = (width // 2) if is_sbs else width
    panel_w -= panel_w % 2
    out_w = (panel_w * 2) if is_sbs else width

    eff_cam_mode = "orbit" if camera_orbit else str(camera_mode or "auto_multicam").strip().lower()
    if eff_cam_mode not in ("auto_multicam", "dolly_follow", "orbit", "fixed"):
        eff_cam_mode = "auto_multicam"

    CINEMA_SHOT_PRESETS = [
        {"label": "Cam 1: Chính diện Toàn cảnh (0°)", "az": base_az_deg + 0.0,  "el": el_deg,        "fov": 28.0, "fill": 0.74},
        {"label": "Cam 2: Chéo 3/4 Trái Trung cảnh (-32°)", "az": base_az_deg - 32.0, "el": el_deg - 2.0,  "fov": 26.5, "fill": 0.76},
        {"label": "Cam 3: Góc Thấp Tôn Dáng Hero (+28°)",   "az": base_az_deg + 28.0, "el": max(-4.0, el_deg - 10.0), "fov": 26.0, "fill": 0.75},
        {"label": "Cam 4: Góc Nghiêng Điện Ảnh (-56°)",     "az": base_az_deg - 56.0, "el": el_deg + 1.0,  "fov": 27.5, "fill": 0.74},
        {"label": "Cam 5: Cận Trung Cảnh Phải (+20°)",      "az": base_az_deg + 20.0, "el": el_deg - 2.0,  "fov": 25.5, "fill": 0.76},
        {"label": "Cam 6: Góc Cao Sân Khấu (-22°)",         "az": base_az_deg - 22.0, "el": el_deg + 11.0, "fov": 28.0, "fill": 0.74},
    ]

    prepared_pins = _prepare_pinned_ref_assets(ref_pins, panel_w, height)
    bg_pin_bgr = prepared_pins.get("bg_image_bgr")
    actor_rigs_map = prepared_pins.get("actor_rigs") or {}
    mode_clean = str(pin_render_mode or "joint_attach").strip().lower()
    has_rigged_char = bool(actor_rigs_map and mode_clean != "clean_skeleton")

    phase_cam_cache: dict[int, tuple] = {}
    camera_shots_used: list[str] = []

    if eff_cam_mode == "auto_multicam":
        for p_idx in range(n_phases):
            shot = CINEMA_SHOT_PRESETS[p_idx % len(CINEMA_SHOT_PRESETS)]
            camera_shots_used.append(shot["label"])
            p_frames = [i for i, ph in enumerate(frame_phase_indices) if ph == p_idx]
            if p_frames:
                sub_pts = actors_joints_3d[:, p_frames[0]:p_frames[-1] + 1, :, :].reshape(-1, 3)
            else:
                sub_pts = all_pts
            sub_pad = np.vstack([
                sub_pts,
                sub_pts + np.array([0.34, 0.42, 0.34]),
                sub_pts - np.array([0.34, 0.22, 0.34]),
            ])
            c_p = build_perspective_camera(
                axes, sub_pad, panel_w, height,
                fov_deg=shot["fov"], azimuth_deg=shot["az"], elevation_deg=shot["el"], fill=shot["fill"],
            )
            bg_d = ground_backdrop(c_p, ground, panel_w, height, theme=DARK_THEME)
            bg_g = ground_backdrop(c_p, ground, panel_w, height, theme=GRID_THEME) if style != "skeleton" else bg_d
            if bg_pin_bgr is not None:
                bg_d = bg_pin_bgr.copy() if has_rigged_char else cv2.addWeighted(bg_pin_bgr, 0.88, bg_d, 0.12, 0)
                bg_g = cv2.addWeighted(bg_pin_bgr, 0.78, bg_g, 0.22, 0)
            phase_cam_cache[p_idx] = (c_p, bg_d, bg_g, shot["label"])
    elif eff_cam_mode == "fixed":
        camera_shots_used = [f"Góc cố định ({base_az_deg:.0f}°)"]
    elif eff_cam_mode == "dolly_follow":
        camera_shots_used = ["Dolly & Crane Bám Sát Đa Góc Liên Tục"]
    else:
        camera_shots_used = ["Orbit Xoay 360° Quanh Nhân Vật"]

    cam_static = build_perspective_camera(
        axes, pad_pts, panel_w, height,
        fov_deg=28.0, azimuth_deg=base_az_deg, elevation_deg=el_deg, fill=0.74,
    )
    bg_dark_static = ground_backdrop(cam_static, ground, panel_w, height, theme=DARK_THEME) if eff_cam_mode == "fixed" else None
    bg_grid_static = ground_backdrop(cam_static, ground, panel_w, height, theme=GRID_THEME) if eff_cam_mode == "fixed" else None
    if bg_pin_bgr is not None and eff_cam_mode == "fixed":
        bg_dark_static = bg_pin_bgr.copy() if has_rigged_char else cv2.addWeighted(bg_pin_bgr, 0.88, bg_dark_static, 0.12, 0)
        bg_grid_static = cv2.addWeighted(bg_pin_bgr, 0.78, bg_grid_static, 0.22, 0)

    slug = re.sub(r"[^a-zA-Z0-9_-]+", "_", raw_prompt[:32]).strip("_") or "motion3d"
    ts = int(time.time())
    out_dir = M2MR_DIR / "outputs" / f"prompt_{ts}_{slug}"
    out_dir.mkdir(parents=True, exist_ok=True)
    vid_dir = out_dir / "videos"
    vid_dir.mkdir(parents=True, exist_ok=True)

    npz_path = out_dir / "skeleton_motion.npz"
    np.savez_compressed(
        npz_path,
        joints_3d=joints_3d_arr,
        all_actors_joints_3d=actors_joints_3d,
        joint_names=np.array(SMPL_JOINT_NAMES),
        fps=np.float32(fps),
        timestamps=np.arange(n_frames, dtype=np.float64) / float(fps),
        root_translation=joints_3d_arr[:, 0, :],
        root_orientation=np.zeros((n_frames, 3), dtype=np.float32),
    )

    out_mp4 = vid_dir / ("human_skeleton.mp4" if style == "skeleton" else "mixamo_character.mp4")
    studio_out_mp4 = SCRIPT_DIR / "output" / f"Motion3D_{ts}_{slug}.mp4"
    studio_out_mp4.parent.mkdir(parents=True, exist_ok=True)

    ffmpeg_bin = _find_ffmpeg()
    cmd = [
        ffmpeg_bin, "-y", "-loglevel", "error",
        "-f", "rawvideo", "-pix_fmt", "bgr24",
        "-s", f"{out_w}x{height}", "-r", str(fps),
        "-i", "-",
        "-c:v", "libx264", "-pix_fmt", "yuv420p", "-crf", "18",
        "-preset", "veryfast", "-movflags", "+faststart",
        str(out_mp4),
    ]
    proc = subprocess.Popen(cmd, stdin=subprocess.PIPE)
    assert proc.stdin is not None
    dolly_cache = None
    first_cam = cam_static
    for fi in range(n_frames):
        f_actors = actors_frames_pos[fi]
        pts_frame = actors_joints_3d[:, fi, :, :].reshape(-1, 3)
        p_idx = frame_phase_indices[fi]
        if eff_cam_mode == "auto_multicam" and p_idx in phase_cam_cache:
            cam, bg_dark, bg_grid, _ = phase_cam_cache[p_idx]
        elif eff_cam_mode == "dolly_follow":
            if dolly_cache is None or fi % 2 == 0:
                u_f = fi / max(n_frames - 1, 1)
                az_cur = base_az_deg + 36.0 * math.sin(2.0 * math.pi * u_f * max(1.0, n_phases * 0.45))
                el_cur = el_deg + 7.0 * math.cos(2.0 * math.pi * u_f * max(1.0, n_phases * 0.35))
                fill_cur = 0.85 + 0.04 * math.sin(2.0 * math.pi * u_f * max(1.0, n_phases * 0.5))
                w0 = max(0, fi - 14)
                w1 = min(n_frames, fi + 15)
                win_pts = actors_joints_3d[:, w0:w1, :, :].reshape(-1, 3)
                win_pad = np.vstack([
                    win_pts,
                    win_pts + np.array([0.22, 0.18, 0.22]),
                    win_pts - np.array([0.22, 0.08, 0.22]),
                ])
                cam_d = build_perspective_camera(
                    axes, win_pad, panel_w, height,
                    fov_deg=26.5, azimuth_deg=az_cur, elevation_deg=el_cur, fill=fill_cur,
                )
                bg_d = ground_backdrop(cam_d, ground, panel_w, height, theme=DARK_THEME)
                bg_g = ground_backdrop(cam_d, ground, panel_w, height, theme=GRID_THEME) if style != "skeleton" else bg_d
                if bg_pin_bgr is not None:
                    bg_d = bg_pin_bgr.copy() if has_rigged_char else cv2.addWeighted(bg_pin_bgr, 0.88, bg_d, 0.12, 0)
                    bg_g = cv2.addWeighted(bg_pin_bgr, 0.78, bg_g, 0.22, 0)
                dolly_cache = (cam_d, bg_d, bg_g)
            cam, bg_dark, bg_grid = dolly_cache
        elif eff_cam_mode == "orbit":
            az_cur = base_az_deg + 360.0 * (fi / max(n_frames - 1, 1))
            cam = build_perspective_camera(
                axes, pad_pts, panel_w, height,
                fov_deg=28.0, azimuth_deg=az_cur, elevation_deg=el_deg, fill=0.84,
            )
            bg_dark = ground_backdrop(cam, ground, panel_w, height, theme=DARK_THEME)
            bg_grid = ground_backdrop(cam, ground, panel_w, height, theme=GRID_THEME) if style != "skeleton" else bg_dark
            if bg_pin_bgr is not None:
                bg_dark = bg_pin_bgr.copy() if has_rigged_char else cv2.addWeighted(bg_pin_bgr, 0.88, bg_dark, 0.12, 0)
                bg_grid = cv2.addWeighted(bg_pin_bgr, 0.78, bg_grid, 0.22, 0)
        else:
            cam = cam_static
            bg_dark = bg_dark_static
            bg_grid = bg_grid_static

        if fi == 0:
            first_cam = cam

        if is_sbs:
            left_f = bg_dark.copy()
            if not has_rigged_char:
                draw_shadow(left_f, cam, pts_frame, ground, theme=DARK_THEME)
            for a_i, pos_a in enumerate(f_actors):
                if a_i in actor_rigs_map and mode_clean != "clean_skeleton":
                    continue
                _draw_custom_colored_skeleton(left_f, pos_a, HUMAN_EDGES, cam, actor_idx=a_i, thickness=3)
            _render_pinned_refs_on_frame(left_f, f_actors, cam, prepared_pins, pin_render_mode=pin_render_mode)
            label_panel(left_f, "Character + Bg Rig" if has_rigged_char else f"3D Skeleton ({actor_count} Actor{'s' if actor_count > 1 else ''})")

            right_f = bg_grid.copy()
            draw_shadow(right_f, cam, pts_frame, ground, theme=GRID_THEME)
            for a_i, pos_a in enumerate(f_actors):
                v_list, f_list, c_list = _build_mannequin_meshes(pos_a, actor_idx=a_i)
                draw_mesh(right_f, v_list, f_list, c_list, cam, ambient=0.36)
                _draw_custom_colored_skeleton(right_f, pos_a, HUMAN_EDGES, cam, actor_idx=a_i, thickness=2)
            label_panel(right_f, "3D Mannequin + Rig")

            frame = np.hstack([left_f, right_f])
        elif style == "skeleton":
            frame = bg_dark.copy()
            if not has_rigged_char:
                draw_shadow(frame, cam, pts_frame, ground, theme=DARK_THEME)
            for a_i, pos_a in enumerate(f_actors):
                if a_i in actor_rigs_map and mode_clean != "clean_skeleton":
                    continue
                _draw_custom_colored_skeleton(frame, pos_a, HUMAN_EDGES, cam, actor_idx=a_i, thickness=3)
            _render_pinned_refs_on_frame(frame, f_actors, cam, prepared_pins, pin_render_mode=pin_render_mode)
            if mode_clean == "skeleton_overlay":
                for a_i, pos_a in enumerate(f_actors):
                    _draw_custom_colored_skeleton(frame, pos_a, HUMAN_EDGES, cam, actor_idx=a_i, thickness=2)
        else:
            frame = bg_grid.copy()
            draw_shadow(frame, cam, pts_frame, ground, theme=GRID_THEME)
            for a_i, pos_a in enumerate(f_actors):
                v_list, f_list, c_list = _build_mannequin_meshes(pos_a, actor_idx=a_i)
                draw_mesh(frame, v_list, f_list, c_list, cam, ambient=0.36)
                _draw_custom_colored_skeleton(frame, pos_a, HUMAN_EDGES, cam, actor_idx=a_i, thickness=2)
            _render_pinned_refs_on_frame(frame, f_actors, cam, prepared_pins, pin_render_mode=pin_render_mode)
        proc.stdin.write(frame.tobytes())
    proc.stdin.close()
    if proc.wait() != 0 or not out_mp4.is_file():
        return {"ok": False, "error": "Không thể xuất video 3D bằng FFmpeg."}

    # Tính tọa độ 2D chuẩn hóa (0..1) của từng nhân vật tại khung hình đầu để UI hiển thị Ghim Vị Trí chính xác
    actors_summary = []
    try:
        f0_actors = actors_frames_pos[0]
        for a_i, pos_a in enumerate(f0_actors):
            pts3 = np.array([
                pos_a["head"],
                pos_a["spine2"],
                pos_a["right_hand"],
                pos_a["left_hand"],
            ], dtype=np.float64)
            uv = first_cam.project(pts3)
            zone_lbl = "Chính Giữa" if actor_count == 1 else ("Bên Trái" if a_i == 0 else ("Bên Phải" if a_i == actor_count - 1 else "Chính Giữa"))
            actors_summary.append({
                "actor_id": a_i + 1,
                "zone": zone_lbl,
                "head_xy": [round(float(uv[0, 0]) / max(panel_w, 1), 3), round(float(uv[0, 1]) / max(height, 1), 3)],
                "body_xy": [round(float(uv[1, 0]) / max(panel_w, 1), 3), round(float(uv[1, 1]) / max(height, 1), 3)],
                "rhand_xy": [round(float(uv[2, 0]) / max(panel_w, 1), 3), round(float(uv[2, 1]) / max(height, 1), 3)],
                "lhand_xy": [round(float(uv[3, 0]) / max(panel_w, 1), 3), round(float(uv[3, 1]) / max(height, 1), 3)],
            })
    except Exception:
        pass

    # Tự động sinh câu lệnh V2V không gian theo danh sách Ghim Vị Trí Ảnh Tham Chiếu (ref_pins)
    compiled_v2v_prompt = ""
    if isinstance(ref_pins, list) and len(ref_pins) > 0:
        pin_clauses = []
        bg_clause = ""
        for idx_p, rp in enumerate(ref_pins):
            if not isinstance(rp, dict):
                continue
            p_num = int(rp.get("pic_index") or (idx_p + 1))
            anc = str(rp.get("anchor") or "actor1_body").lower()
            px_pct = int(round(float(rp.get("x", 0.5)) * 100))
            py_pct = int(round(float(rp.get("y", 0.5)) * 100))
            zone_str = "bên trái khung hình" if px_pct < 38 else ("bên phải khung hình" if px_pct > 62 else "chính giữa khung hình")
            if anc == "background":
                bg_clause = f"Đặt toàn bộ bối cảnh trong không gian của <Picture {p_num}>."
            elif anc.startswith("actor") and "_body" in anc:
                a_num = anc.replace("actor", "").split("_")[0]
                pin_clauses.append(
                    f"Ánh xạ toàn bộ nhân vật (khuôn mặt, vóc dáng, trang phục) từ <Picture {p_num}> vào Khung Xương #{a_num} đang ở {zone_str} (tọa độ ghim ~{px_pct}%, {py_pct}%)"
                )
            elif anc.startswith("actor") and "_head" in anc:
                a_num = anc.replace("actor", "").split("_")[0]
                pin_clauses.append(
                    f"Gắn diện mạo khuôn mặt và kiểu tóc từ <Picture {p_num}> vào khớp Đầu của Khung Xương #{a_num}"
                )
            elif anc.startswith("actor") and ("_rhand" in anc or "_lhand" in anc):
                a_num = anc.replace("actor", "").split("_")[0]
                hand_str = "tay phải" if "_rhand" in anc else "tay trái"
                pin_clauses.append(
                    f"Cho Khung Xương #{a_num} cầm/đeo đạo cụ từ <Picture {p_num}> gắn chặt theo chuyển động khớp {hand_str}"
                )
            else:
                pin_clauses.append(
                    f"Đặt đối tượng từ <Picture {p_num}> tại vị trí ghim ({px_pct}%, {py_pct}% — {zone_str})"
                )
        parts_prompt = []
        if pin_clauses:
            parts_prompt.append(". ".join(pin_clauses) + ".")
        parts_prompt.append(f"Thực hiện chuỗi chuyển động chính xác theo quỹ đạo video khung xương 3D: {raw_prompt}.")
        if bg_clause:
            parts_prompt.append(bg_clause)
        else:
            parts_prompt.append("Xóa bỏ hoàn toàn các vạch xương 3D, tái tạo da thịt, vải vóc và ánh sáng điện ảnh 8K chân thực.")
        compiled_v2v_prompt = " ".join(parts_prompt)

    shutil.copy2(out_mp4, studio_out_mp4)
    win_path = str(out_mp4)
    record_h3_video(str(studio_out_mp4), title=f"🦴 [Khung Xương 3D] {raw_prompt[:55]}")
    return {
        "ok": True,
        "path": win_path.replace("\\", "/"),
        "studio_path": str(studio_out_mp4).replace("\\", "/"),
        "npz_path": str(npz_path).replace("\\", "/"),
        "url": f"/api/video?path={urllib.parse.quote(win_path)}",
        "duration": duration_s,
        "fps": fps,
        "width": out_w,
        "height": height,
        "phases": phase_types,
        "camera_mode": eff_cam_mode,
        "camera_shots": camera_shots_used,
        "prompt": raw_prompt,
        "style": style,
        "actor_count": actor_count,
        "actors_summary": actors_summary,
        "compiled_v2v_prompt": compiled_v2v_prompt,
    }

