import urllib.request
import urllib.error

GEMINI_WEB_DIR = Path(r"D:\gemini-web-to-api-main")
GEMINI_COOKIE_CFG_FILE = SCRIPT_DIR / ".gemini_cookie_config.json"
_gemini_proc = None
_gemini_proc_lock = threading.Lock()


def normalize_gemini_cookie_input(raw_cookie: str, psid: str = "", psidts: str = "") -> str:
    """Chấp nhận Netscape HTTP Cookie File (cookies.txt), Cookie header gốc, JSON từ Cookie-Editor/EditThisCookie, hoặc 2 trường __Secure-1PSID / __Secure-1PSIDTS."""
    raw_cookie = (raw_cookie or "").strip()
    psid = (psid or "").strip()
    psidts = (psidts or "").strip()

    cookie_map = {}

    # 1. Hỗ trợ định dạng Netscape HTTP Cookie File (cookies.txt)
    if "# Netscape HTTP Cookie File" in raw_cookie or "\tTRUE\t" in raw_cookie or "\tFALSE\t" in raw_cookie:
        for ln in raw_cookie.splitlines():
            s = ln.strip()
            if not s or (s.startswith("#") and not s.startswith("#HttpOnly_")):
                continue
            if s.startswith("#HttpOnly_"):
                s = s[len("#HttpOnly_"):].strip()
            cols = s.split("\t")
            if len(cols) < 7:
                cols = s.split()
            if len(cols) >= 7:
                domain = cols[0].strip().lower()
                if "google.com" not in domain and domain != "":
                    continue
                c_name = cols[5].strip()
                c_val = cols[6].strip()
                if c_name:
                    cookie_map[c_name] = c_val
        if psid:
            cookie_map["__Secure-1PSID"] = psid
        if psidts:
            cookie_map["__Secure-1PSIDTS"] = psidts
        if cookie_map:
            return "; ".join(f"{k}={v}" for k, v in cookie_map.items() if k)

    # 2. Hỗ trợ định dạng JSON từ tiện ích Cookie-Editor / EditThisCookie
    if raw_cookie.startswith("[") or raw_cookie.startswith("{"):
        try:
            parsed = json.loads(raw_cookie)
            if isinstance(parsed, dict):
                parsed = [parsed]
            if isinstance(parsed, list):
                pairs = []
                for item in parsed:
                    if isinstance(item, dict) and item.get("name") and item.get("value") is not None:
                        pairs.append(f"{str(item['name']).strip()}={str(item['value']).strip()}")
                if pairs:
                    raw_cookie = "; ".join(pairs)
        except Exception:
            pass

    # 3. Hỗ trợ định dạng Cookie Header chuẩn (name=val; name2=val2)
    if raw_cookie.lower().startswith("cookie:"):
        raw_cookie = raw_cookie[7:].strip()

    for part in raw_cookie.replace("\r", " ").replace("\n", ";").split(";"):
        p = part.strip()
        if "=" in p and "\t" not in p:
            k, v = p.split("=", 1)
            cookie_map[k.strip()] = v.strip()

    if psid:
        cookie_map["__Secure-1PSID"] = psid
    if psidts:
        cookie_map["__Secure-1PSIDTS"] = psidts

    if not cookie_map and raw_cookie:
        return raw_cookie
    return "; ".join(f"{k}={v}" for k, v in cookie_map.items() if k)


def load_gemini_cookie_config() -> dict:
    cfg = {
        "api_url": "http://127.0.0.1:4981/openai/v1",
        "cookies": "",
        "psid": "",
        "psidts": "",
        "auth_user": "",
        "default_model": "gemini-2.5-flash",
        "gemini_api_key": "",
    }
    if GEMINI_COOKIE_CFG_FILE.is_file():
        try:
            saved = json.loads(GEMINI_COOKIE_CFG_FILE.read_text(encoding="utf-8"))
            if isinstance(saved, dict):
                cfg.update(saved)
        except Exception:
            pass
    if not cfg.get("gemini_api_key") and os.environ.get("GEMINI_API_KEY"):
        cfg["gemini_api_key"] = os.environ.get("GEMINI_API_KEY", "").strip()

    env_file = GEMINI_WEB_DIR / ".env"
    if not cfg.get("cookies") and env_file.is_file():
        try:
            for ln in env_file.read_text(encoding="utf-8", errors="ignore").splitlines():
                s = ln.strip()
                if not s or s.startswith("#") or "=" not in s:
                    continue
                k, v = s.split("=", 1)
                k = k.strip()
                v = v.strip().strip('"').strip("'")
                if k == "GEMINI_COOKIES" and v:
                    cfg["cookies"] = v
                elif k == "GEMINI_AUTH_USER" and v:
                    cfg["auth_user"] = v
                elif k == "PORT" and v:
                    cfg["api_url"] = f"http://127.0.0.1:{v}/openai/v1"
        except Exception:
            pass

    ck = cfg.get("cookies", "")
    if ck:
        for part in ck.split(";"):
            if "=" in part:
                k, v = part.strip().split("=", 1)
                if k.strip() == "__Secure-1PSID":
                    cfg["psid"] = v.strip()
                elif k.strip() == "__Secure-1PSIDTS":
                    cfg["psidts"] = v.strip()
    return cfg


def save_gemini_cookie_config(new_data: dict) -> dict:
    cfg = load_gemini_cookie_config()
    raw_ck = new_data.get("cookies", cfg.get("cookies", ""))
    psid = new_data.get("psid", "")
    psidts = new_data.get("psidts", "")
    merged_ck = normalize_gemini_cookie_input(raw_ck, psid, psidts)

    if merged_ck:
        cfg["cookies"] = merged_ck
    if "auth_user" in new_data:
        cfg["auth_user"] = str(new_data.get("auth_user") or "").strip()
    if new_data.get("api_url"):
        u = str(new_data["api_url"]).strip().rstrip("/")
        if not u.endswith("/openai/v1") and not u.endswith("/v1"):
            u = u + "/openai/v1"
        cfg["api_url"] = u
    if new_data.get("default_model"):
        cfg["default_model"] = str(new_data["default_model"]).strip()
    if "gemini_api_key" in new_data:
        cfg["gemini_api_key"] = str(new_data.get("gemini_api_key") or "").strip()

    try:
        GEMINI_COOKIE_CFG_FILE.write_text(json.dumps(cfg, ensure_ascii=False, indent=2), encoding="utf-8")
    except Exception:
        pass

    # Đồng bộ sang D:\gemini-web-to-api-main\.env
    if GEMINI_WEB_DIR.is_dir() and cfg.get("cookies"):
        try:
            port = "4981"
            m_port = re.search(r":(\d+)/", cfg.get("api_url", "") + "/")
            if m_port:
                port = m_port.group(1)
            env_lines = [
                f"PORT={port}",
                "LOG_LEVEL=info",
                "APP_ENV=production",
                "RATE_LIMIT_ENABLED=false",
                "RATE_LIMIT_WINDOW_MS=60000",
                "RATE_LIMIT_MAX_REQUESTS=60",
                f'GEMINI_COOKIES="{cfg["cookies"]}"',
                f'GEMINI_AUTH_USER="{cfg.get("auth_user", "")}"',
                "GEMINI_REFRESH_INTERVAL=15",
                "GEMINI_MAX_RETRIES=3",
                "GEMINI_TEMPORARY=false",
            ]
            (GEMINI_WEB_DIR / ".env").write_text("\n".join(env_lines) + "\n", encoding="utf-8")
        except Exception:
            pass
    return cfg


GEMINI_WEB_LOG_FILE = SCRIPT_DIR / ".gemini_web_api.log"


def _inspect_gemini_web_log_for_error() -> str:
    """Đọc log khởi chạy của gemini-web-to-api.exe để phát hiện tức thì lỗi Cookie Die / Hết Hạn (401)."""
    if not GEMINI_WEB_LOG_FILE.is_file():
        return ""
    try:
        txt = GEMINI_WEB_LOG_FILE.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return ""
    if not txt:
        return ""
    if "Rotation failed" in txt or '"status":401' in txt or "invalid __Secure-1PSID" in txt:
        return "🔴 COOKIE ĐÃ DIE HOẶC HẾT HẠN (Lỗi 401): Mã __Secure-1PSID / __Secure-1PSIDTS không còn hiệu lực (do phiên Gemini bị đăng xuất hoặc bạn đang mở sẵn tab gemini.google.com khiến trình duyệt tự xoay vòng làm chết Cookie cũ). Hãy vào gemini.google.com nhấn F5, xuất Cookie mới, ĐÓNG tab Gemini đi rồi dán lại vào đây!"
    if "GEMINI_COOKIES is invalid or expired" in txt or "SNlM0e not found" in txt:
        return "🔴 COOKIE ĐÃ HẾT HẠN (Expired): Phiên đăng nhập Gemini của Cookie này đã hết hạn. Vui lòng mở gemini.google.com, F5 tải lại trang, lấy Cookie mới và dán lại!"
    if "cannot select models" in txt:
        return "🔴 TÀI KHOẢN GEMINI BỊ HẠN CHẾ: Cookie hợp lệ nhưng tài khoản Google này chưa bật quyền truy cập Gemini Web."
    if "Gemini provider initialization failed" in txt:
        return "🔴 COOKIE LỖI / HẾT HẠN: Không thể xác thực với máy chủ Google Gemini. Vui lòng lấy lại Cookie mới!"
    return ""


def ensure_gemini_web_server(restart: bool = False) -> tuple[bool, str]:
    r"""Đảm bảo tiến trình D:\gemini-web-to-api-main đang chạy và trả về trạng thái."""
    global _gemini_proc
    cfg = load_gemini_cookie_config()
    api_url = cfg.get("api_url", "http://127.0.0.1:4981/openai/v1").rstrip("/")

    if not restart:
        try:
            req = urllib.request.Request(f"{api_url}/models", method="GET")
            with urllib.request.urlopen(req, timeout=2.5) as resp:
                if resp.status == 200:
                    data = json.loads(resp.read().decode("utf-8", errors="ignore"))
                    if isinstance(data, dict) and isinstance(data.get("data"), list) and len(data["data"]) > 0:
                        return True, "🟢 KẾT NỐI HOẠT ĐỘNG TỐT (COOKIE LIVE): Đã kết nối Gemini Cookie API thành công!"
        except Exception:
            pass

    raw_ck = cfg.get("cookies", "")
    if not raw_ck:
        return False, "⚪ CHƯA CÀI ĐẶT COOKIE: Vui lòng bấm nút 🍪 Cookie và dán Cookie từ trang gemini.google.com."
    if "__Secure-1PSID" not in raw_ck or "__Secure-1PSIDTS" not in raw_ck:
        return False, "🟡 COOKIE THIẾU DỮ LIỆU: Đoạn Cookie bạn dán thiếu __Secure-1PSID hoặc __Secure-1PSIDTS. Hãy xuất toàn bộ Cookie của trang gemini.google.com!"

    if not GEMINI_WEB_DIR.is_dir():
        return False, f"Không tìm thấy thư mục {GEMINI_WEB_DIR}"

    with _gemini_proc_lock:
        if not restart:
            try:
                req = urllib.request.Request(f"{api_url}/models", method="GET")
                with urllib.request.urlopen(req, timeout=2.5) as resp:
                    if resp.status == 200:
                        data = json.loads(resp.read().decode("utf-8", errors="ignore"))
                        if isinstance(data, dict) and isinstance(data.get("data"), list) and len(data["data"]) > 0:
                            return True, "🟢 KẾT NỐI HOẠT ĐỘNG TỐT (COOKIE LIVE): Đã kết nối Gemini Cookie API thành công!"
            except Exception:
                pass
            # Nếu lần khởi chạy trước đã ghi nhận Cookie Die/Hết hạn và chưa thay Cookie mới thì báo ngay không treo 15s
            prev_err = _inspect_gemini_web_log_for_error()
            if prev_err and _gemini_proc is not None and _gemini_proc.poll() is None:
                return False, prev_err

        if _gemini_proc is not None:
            try:
                _gemini_proc.terminate()
                _gemini_proc.wait(timeout=2)
            except Exception:
                pass
            _gemini_proc = None

        # Dọn các tiến trình gemini-web-to-api.exe cũ bị treo chiếm cổng 4981
        if os.name == "nt":
            try:
                subprocess.run(
                    ["taskkill", "/F", "/IM", "gemini-web-to-api.exe"],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    creationflags=subprocess.CREATE_NO_WINDOW,
                    timeout=3,
                )
                time.sleep(0.35)
            except Exception:
                pass

        try:
            GEMINI_WEB_LOG_FILE.write_text("", encoding="utf-8")
        except Exception:
            pass

        # Khởi chạy gemini-web-to-api.exe (ghi log ra GEMINI_WEB_LOG_FILE để bắt lỗi 401 tức thì)
        exe_path = GEMINI_WEB_DIR / ("gemini-web-to-api.exe" if os.name == "nt" else "gemini-web-to-api")
        cmd = [str(exe_path)] if exe_path.is_file() else ["go", "run", "cmd/server/main.go"]
        env = os.environ.copy()
        port = "4981"
        m_port = re.search(r":(\d+)/", api_url + "/")
        if m_port:
            port = m_port.group(1)
        env["PORT"] = port
        env["GEMINI_COOKIES"] = cfg.get("cookies", "")
        env["GEMINI_AUTH_USER"] = cfg.get("auth_user", "")
        env["GEMINI_REFRESH_INTERVAL"] = "15"
        env["RATE_LIMIT_ENABLED"] = "false"

        try:
            creationflags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
            log_fh = open(GEMINI_WEB_LOG_FILE, "w", encoding="utf-8", errors="ignore")
            _gemini_proc = subprocess.Popen(
                cmd,
                cwd=str(GEMINI_WEB_DIR),
                env=env,
                stdout=log_fh,
                stderr=subprocess.STDOUT,
                creationflags=creationflags,
            )
        except Exception as e:
            return False, f"Không thể khởi chạy gemini-web-to-api: {e}"

        # Kiểm tra liên tục mỗi 0.4s: nếu thành công (/models có data) hoặc báo lỗi 401 trong log thì trả kết quả NGAY LẬP TỨC!
        for _ in range(25):
            time.sleep(0.4)
            err_log = _inspect_gemini_web_log_for_error()
            if err_log:
                return False, err_log
            try:
                req = urllib.request.Request(f"{api_url}/models", method="GET")
                with urllib.request.urlopen(req, timeout=2.0) as resp:
                    if resp.status == 200:
                        data = json.loads(resp.read().decode("utf-8", errors="ignore"))
                        if isinstance(data, dict) and isinstance(data.get("data"), list) and len(data["data"]) > 0:
                            return True, "🟢 KẾT NỐI HOẠT ĐỘNG TỐT (COOKIE LIVE): Đã xác thực thành công với đủ 4 Model Gemini!"
            except Exception:
                pass

    err_after = _inspect_gemini_web_log_for_error()
    if err_after:
        return False, err_after
    return False, "🔴 COOKIE ĐÃ DIE HOẶC HẾT HẠN: Không thể lấy token SNlM0e từ Gemini Web. Hãy mở gemini.google.com nhấn F5, xuất lại Cookie mới rồi dán vào!"


def get_gemini_web_status(auto_start: bool = True) -> dict:
    cfg = load_gemini_cookie_config()
    api_url = cfg.get("api_url", "http://127.0.0.1:4981/openai/v1").rstrip("/")
    raw_ck = cfg.get("cookies", "")
    has_psid = "__Secure-1PSID" in raw_ck
    has_psidts = "__Secure-1PSIDTS" in raw_ck
    has_cookies = bool(raw_ck and has_psid and has_psidts)
    models = []
    connected = False
    err_msg = ""

    for candidate_prefix in [api_url, api_url.replace("/openai/v1", "/v1")]:
        try:
            req = urllib.request.Request(f"{candidate_prefix}/models", method="GET")
            with urllib.request.urlopen(req, timeout=2.5) as resp:
                data = json.loads(resp.read().decode("utf-8", errors="ignore"))
                if isinstance(data, dict) and isinstance(data.get("data"), list) and len(data["data"]) > 0:
                    models = data["data"]
                    connected = True
                    api_url = candidate_prefix
                    break
        except Exception as e:
            err_msg = str(e)

    if not connected:
        if not raw_ck:
            cookie_state = "missing"
            err_msg = "⚪ CHƯA CÀI ĐẶT COOKIE: Hãy bấm nút 🍪 Cookie và dán Cookie từ trang gemini.google.com."
        elif not (has_psid and has_psidts):
            cookie_state = "incomplete"
            err_msg = "🟡 COOKIE THIẾU TRƯỜNG BẮT BUỘC: Đoạn Cookie vừa dán thiếu __Secure-1PSID hoặc __Secure-1PSIDTS. Hãy xuất toàn bộ Cookie của trang gemini.google.com!"
        elif auto_start:
            ok_start, msg_start = ensure_gemini_web_server(restart=False)
            if ok_start:
                try:
                    req = urllib.request.Request(f"{api_url}/models", method="GET")
                    with urllib.request.urlopen(req, timeout=3.0) as resp:
                        data = json.loads(resp.read().decode("utf-8", errors="ignore"))
                        if isinstance(data, dict) and isinstance(data.get("data"), list) and len(data["data"]) > 0:
                            models = data["data"]
                            connected = True
                            err_msg = ""
                except Exception as e:
                    err_msg = str(e)
            else:
                err_msg = msg_start
        else:
            err_msg = _inspect_gemini_web_log_for_error() or "🔴 COOKIE ĐÃ DIE HOẶC HẾT HẠN: Vui lòng lấy lại Cookie mới từ gemini.google.com!"

    if connected:
        cookie_state = "live"
        status_msg = "🟢 KẾT NỐI HOẠT ĐỘNG TỐT (COOKIE LIVE): Đã xác thực Gemini thành công — Sẵn sàng đủ 4 Model (3.5 Flash-Lite, 3.8 Flash, 3.1 Pro, 4 Argon)!"
    else:
        if not raw_ck:
            cookie_state = "missing"
        elif not (has_psid and has_psidts):
            cookie_state = "incomplete"
        else:
            cookie_state = "expired"
        status_msg = err_msg or "🔴 COOKIE ĐÃ DIE HOẶC HẾT HẠN: Vui lòng lấy lại Cookie mới từ gemini.google.com!"

    # Luôn đảm bảo đủ 4 model chuẩn của gemini-web-to-api (kể cả gemini-4-argon "4 Argon")
    core_models = [
        {"id": "gemini-3.5-flash-lite", "object": "model", "owned_by": "google", "display_name": "3.5 Flash-Lite"},
        {"id": "gemini-3.8-flash", "object": "model", "owned_by": "google", "display_name": "3.8 Flash"},
        {"id": "gemini-3.1-pro", "object": "model", "owned_by": "google", "display_name": "3.1 Pro"},
        {"id": "gemini-4-argon", "object": "model", "owned_by": "google", "display_name": "4 Argon"},
    ]
    if not isinstance(models, list):
        models = []
    existing_ids = {str(m.get("id", "")).strip() for m in models if isinstance(m, dict)}
    for cm in core_models:
        if cm["id"] not in existing_ids:
            models.append(cm)

    masked_psid = ""
    if cfg.get("psid"):
        p = cfg["psid"]
        masked_psid = (p[:10] + "..." + p[-6:]) if len(p) > 20 else "Đã lưu"

    return {
        "ok": True,
        "connected": connected,
        "cookie_state": cookie_state,
        "has_cookies": has_cookies,
        "masked_psid": masked_psid,
        "auth_user": cfg.get("auth_user", ""),
        "api_url": api_url,
        "default_model": cfg.get("default_model", "gemini-3.1-pro"),
        "models": models,
        "message": status_msg,
    }


def _extract_json_block(text: str) -> dict:
    text = (text or "").strip()
    m = re.search(r"```(?:json)?\s*(\{[\s\S]*?\})\s*```", text, re.IGNORECASE)
    if m:
        try:
            return json.loads(m.group(1))
        except Exception:
            pass
    start = text.find("{")
    end = text.rfind("}")
    if start != -1 and end != -1 and end > start:
        candidate = text[start:end + 1]
        try:
            return json.loads(candidate)
        except Exception:
            # Sửa lỗi trailing comma phổ biến của LLM
            cleaned = re.sub(r",\s*([\}\]])", r"\1", candidate)
            return json.loads(cleaned)
    raise ValueError("Phản hồi từ Gemini không chứa khối JSON hợp lệ")


def build_longshot_with_gemini(script_text: str, model: str = "gemini-3.1-pro", shot_count: int = 0, shot_seconds: int = 8, images_data: list = None, adult_mode: bool = False) -> dict:
    r"""Gọi Gemini Cookie API (/openai/v1/chat/completions) kèm nhận diện ảnh tham chiếu đã tải lên (nếu có) để dựng trọn bộ JSON Long Shot + Prompt tạo ảnh tham chiếu."""
    images_data = images_data or []
    uploaded_count = len(images_data)
    try:
        from scripts.blocking_storyboard import parse_h3_three_tier_director_script
        if parse_h3_three_tier_director_script(script_text):
            return _build_longshot_smart_fallback(script_text, shot_count, shot_seconds, uploaded_count, adult_mode)
    except Exception:
        pass
    st = get_gemini_web_status(auto_start=True)
    if not st.get("connected"):
        return _build_longshot_smart_fallback(script_text, shot_count, shot_seconds, uploaded_count, adult_mode)

    api_url = st["api_url"].rstrip("/")
    avail_ids = [m.get("id") for m in st.get("models", []) if m.get("id")]
    chosen_model = model if (model in avail_ids or not avail_ids) else avail_ids[0]

    shot_rule = (
        f"Break the story into EXACTLY {shot_count} sequential shots (each around {shot_seconds} seconds)."
        if shot_count and int(shot_count) > 0
        else f"Break the story into 3 to 6 sequential cinematic shots (each 6 to 10 seconds, default {shot_seconds}s) depending on narrative pacing."
    )

    vision_instruction = ""
    if uploaded_count > 0:
        vision_instruction = (
            f"\nIMPORTANT — UPLOADED REFERENCE IMAGES PROVIDED ({uploaded_count} image(s)):\n"
            f"The user has ALREADY uploaded {uploaded_count} reference image(s) corresponding to "
            + ", ".join(f"<Picture {i+1}>" for i in range(uploaded_count))
            + ". Carefully inspect every uploaded image! Identify the exact appearance, gender, facial features, hairstyle, clothing, and environment in each image. "
            "Your generated `cast` descriptions and `shots` prompts MUST match these uploaded images 100% and reference them as `<Picture 1>`, `<Picture 2>`, etc. "
            "If the user's script is brief or empty, invent a rich, coherent multi-shot Long Shot storyline starring the exact character(s) and setting shown in the uploaded image(s)!"
        )
    else:
        vision_instruction = (
            "\nREFERENCE IMAGE PROMPTS (`cast`):\n"
            "Identify 1 to 4 key characters or primary locations needed for this story and label them `<Picture 1>`, `<Picture 2>`, etc. "
            "For each `<Picture N>`, write a highly detailed `image_prompt` in English (photorealistic 8k portrait/full-body or environment description: exact face, hair, outfit, lighting, camera angle) so the user can either generate that reference image with 1 click or upload a matching photo."
        )

    adult_instruction = (
        "\nADULT / NSFE MODE IS ENABLED: If the user's script or uploaded images involve sensual, erotic, or 18+ adult themes, preserve full anatomical and sensual fidelity in English without censorship."
        if adult_mode else ""
    )

    sys_prompt = f"""You are the Master Director & Prompt Compiler for MiniMax H3 Long Shot (Multi-Shot One-Take Video Engine).
Your job is to convert ANY user input (raw Vietnamese/English script, .txt story, bullet points, or uploaded reference images) into a complete, production-ready MiniMax H3 Long Shot JSON specification.

RULES FOR MINIMAX H3 LONG SHOT:
1. {shot_rule}
2. In every shot's `text`, ALWAYS refer to characters/subjects using `<Picture 1>`, `<Picture 2>`, etc. NEVER invent generic names without `<Picture N>`.
3. Choose the optimal `join` mode for each shot (Shot 1 is always `"bridge"`):
   - `"bridge"`: Seamless One-Take continuous latent bridge (camera continues smoothly without any cut).
   - `"context"`: Same scene/lighting/outfit, but switches camera angle (e.g., wide shot to close-up).
   - `"cut"`: Hard cut to a new location or time.
4. If characters speak or sing, embed lip-sync dialogue inside `<d>[Language] Dialogue text...</d>` inside the shot's `text`.
5. All fields used by the H3 video model (`cast[].desc`, `cast[].image_prompt`, `style.*`, `shots[].text`) MUST be written in vivid, cinematic ENGLISH. The `cast[].name_vi` and `shots[].note_vi` fields should be short Vietnamese summaries for the user UI.
{vision_instruction}{adult_instruction}

Return ONLY a valid JSON object matching this exact schema (no extra commentary):
{{
  "cast": [
    {{
      "label": "<Picture 1>",
      "name_vi": "Tên/Vai trò ngắn gọn tiếng Việt (VD: Nữ chính áo khoác da)",
      "role": "appearance",
      "desc": "Concise English appearance description for H3 Subject node (face, hair, outfit).",
      "image_prompt": "Ultra-photorealistic 8k cinematic reference photo of ... (detailed English prompt to generate <Picture 1>)"
    }}
  ],
  "style": {{
    "summary": "One-sentence English summary of the entire multi-shot sequence.",
    "retention": "Strict identity and outfit preservation rules for <Picture 1>, <Picture 2> across all shots.",
    "style_line": "Live-action photorealistic 8k cinema, lens, lighting, color grading.",
    "soundscape": "Continuous synchronized environmental sound effects, footsteps, ambience.",
    "music": "Background music style or N/A"
  }},
  "shots": [
    {{
      "id": "s1",
      "seconds": {shot_seconds},
      "join": "bridge",
      "note_vi": "Tóm tắt cảnh 1 bằng tiếng Việt",
      "text": "Detailed English H3 shot prompt starting with camera framing, <Picture 1> action, lighting, and optional <d>dialogue</d>."
    }}
  ]
}}"""

    user_text = (script_text or "").strip()
    if not user_text:
        if uploaded_count > 0:
            user_text = f"Hãy quan sát kỹ {uploaded_count} ảnh tham chiếu đã tải lên (<Picture 1>..), nhận diện nhân vật/bối cảnh và tự động sáng tạo một kịch bản phim dài Long Shot liền mạch, hấp dẫn, khớp 100% với hình ảnh."
        else:
            user_text = "Hãy sáng tạo một kịch bản phim dài Long Shot điện ảnh ấn tượng (4 phân cảnh liền mạch)."

    content_parts = [{"type": "text", "text": f"{sys_prompt}\n\n=== USER SCRIPT / REQUEST ===\n{user_text}"}]
    for idx, img_item in enumerate(images_data[:9]):
        data_uri = str(img_item.get("data") or "").strip()
        if data_uri.startswith("data:image/"):
            content_parts.append({
                "type": "image_url",
                "image_url": {"url": data_uri}
            })

    payload = {
        "model": chosen_model,
        "messages": [
            {
                "role": "user",
                "content": content_parts if len(content_parts) > 1 else content_parts[0]["text"],
            }
        ],
        "stream": False,
    }

    try:
        req_bytes = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        req = urllib.request.Request(
            f"{api_url}/chat/completions",
            data=req_bytes,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=180) as resp:
            resp_json = json.loads(resp.read().decode("utf-8", errors="ignore"))
        raw_reply = resp_json["choices"][0]["message"]["content"]
        parsed = _extract_json_block(raw_reply)
    except Exception:
        return _build_longshot_smart_fallback(script_text, shot_count, shot_seconds, uploaded_count, adult_mode)

    # Chuẩn hóa dữ liệu trả về
    cast_out = []
    for idx, c in enumerate(parsed.get("cast") or []):
        if not isinstance(c, dict):
            continue
        lbl = f"<Picture {idx + 1}>"
        cast_out.append({
            "label": lbl,
            "name_vi": str(c.get("name_vi") or f"Nhân vật / Bối cảnh #{idx + 1}").strip(),
            "role": str(c.get("role") or "appearance").strip(),
            "desc": str(c.get("desc") or f"Reference subject {idx + 1}").strip(),
            "image_prompt": str(c.get("image_prompt") or c.get("desc") or "").strip(),
        })

    if not cast_out:
        cast_out.append({
            "label": "<Picture 1>",
            "name_vi": "Nhân vật chính (<Picture 1>)",
            "role": "appearance",
            "desc": "Main character in <Picture 1> with consistent facial identity and outfit.",
            "image_prompt": "Ultra-photorealistic 8k cinematic portrait and upper body shot of the main character, natural lighting, sharp focus.",
        })

    shots_out = []
    for idx, sh in enumerate(parsed.get("shots") or []):
        if not isinstance(sh, dict):
            continue
        sec = int(sh.get("seconds") or shot_seconds or 8)
        sec = max(5, min(15, sec))
        jn = str(sh.get("join") or "bridge").strip().lower()
        if jn not in ("bridge", "context", "cut"):
            jn = "bridge"
        if idx == 0:
            jn = "bridge"
        txt = str(sh.get("text") or "").strip()
        if txt and "<Picture " not in txt:
            txt = f"<Picture 1> {txt}"
        shots_out.append({
            "id": f"s{idx + 1}",
            "seconds": sec,
            "join": jn,
            "note_vi": str(sh.get("note_vi") or f"Phân cảnh {idx + 1}").strip(),
            "text": txt,
        })

    style_in = parsed.get("style") if isinstance(parsed.get("style"), dict) else {}
    style_out = {
        "summary": str(style_in.get("summary") or "Continuous multi-shot cinematic video maintaining strict character identity across all shots.").strip(),
        "retention": str(style_in.get("retention") or "Strictly preserve exact facial structure, hairstyle, skin tone and outfit of <Picture 1> across every shot transition.").strip(),
        "style_line": str(style_in.get("style_line") or "Live-action photorealistic 8k cinema, natural skin texture, smooth fluid camera movement.").strip(),
        "soundscape": str(style_in.get("soundscape") or "Natural synchronized environmental audio matching each shot.").strip(),
        "music": str(style_in.get("music") or "N/A").strip(),
    }

    return {
        "ok": True,
        "model": chosen_model,
        "used_vision_count": uploaded_count,
        "cast": cast_out,
        "style": style_out,
        "shots": shots_out,
    }


def _build_continuum_smart_fallback(
    script_text: str,
    chunks: int = 3,
    chunk_seconds: float = 10.0,
    uploaded_count: int = 1,
    adult_mode: bool = False,
) -> dict:
    """Bộ dựng kịch bản [Chunk 1]..[Chunk N] thông minh chuẩn H3 Continuum V3.9 (@R1..@R9) khi không có kết nối Gemini API."""
    chunks = max(2, min(16, int(chunks or 3)))
    chunk_seconds = max(4.0, min(15.0, float(chunk_seconds or 10.0)))
    raw = (script_text or "").strip()
    ref_tags = [f"@R{i+1}" for i in range(max(1, min(9, uploaded_count or 1)))]
    main_ref = ref_tags[0]
    sec_ref = ref_tags[1] if len(ref_tags) >= 2 else None

    # Nếu người dùng đã viết sẵn [Chunk N] hoặc phân tách bằng dòng
    existing_blocks = [
        b.strip()
        for b in re.split(r"(?:^|\n)\s*\[Chunk\s+\d+\]\s*", raw, flags=re.IGNORECASE)
        if b.strip()
    ]
    if len(existing_blocks) < 2 and raw:
        lines = [ln.strip() for ln in re.split(r"\n+|===+", raw) if ln.strip()]
        if len(lines) >= 2:
            existing_blocks = lines

    chunk_items = []
    for idx in range(chunks):
        c_num = idx + 1
        src_line = existing_blocks[idx] if idx < len(existing_blocks) else (existing_blocks[-1] if existing_blocks else "performs fluid cinematic motion with expressive natural micro-expressions")
        src_line = re.sub(r"<Picture\s+(\d)>", r"@R\1", src_line, flags=re.IGNORECASE)
        if c_num == 1:
            txt = (
                f"Medium-wide cinematic tracking shot in 8k photorealistic live-action. "
                f"{main_ref} appears with exact facial identity, hairstyle, skin texture, and signature wardrobe preserved"
                + (f", alongside {sec_ref} in the same environment" if sec_ref else "")
                + f". {src_line}. Soft directional cinema lighting, crisp ambient soundscape and realistic foley."
            )
            note_vi = f"Chunk 1 (0s–{chunk_seconds:g}s): Mở màn & thiết lập nhân vật {main_ref}"
        else:
            txt = (
                f"Continuation of Chunk {c_num - 1} in the same continuous take. "
                f"{main_ref} maintains identical facial features, hairstyle, and wardrobe from Chunk {c_num - 1}"
                + (f" with {sec_ref}" if sec_ref else "")
                + f". {src_line}. Smooth camera progression, consistent lighting and continuous synchronized ambient audio."
            )
            note_vi = f"Chunk {c_num} ({(c_num-1)*chunk_seconds:g}s–{c_num*chunk_seconds:g}s): Nối tiếp liền mạch từ Chunk {c_num - 1}"
        chunk_items.append({
            "chunk": c_num,
            "note_vi": note_vi,
            "text": txt,
        })

    r_chunks = {f"r{i+1}": f"1-{chunks}" for i in range(max(1, min(9, uploaded_count or 1)))}
    sequence_prompt = "\n\n".join(f"[Chunk {c['chunk']}]\n{c['text']}" for c in chunk_items)
    return {
        "ok": True,
        "model": "h3-v39-compiler",
        "chunks": chunks,
        "chunk_seconds": chunk_seconds,
        "reference_use": "All chunks",
        "r_chunks": r_chunks,
        "chunk_items": chunk_items,
        "sequence_prompt": sequence_prompt,
    }


def build_continuum_with_gemini(
    script_text: str,
    model: str = "gemini-3.1-pro",
    chunks: int = 3,
    chunk_seconds: float = 10.0,
    images_data: list = None,
    adult_mode: bool = False,
) -> dict:
    """Biên dịch kịch bản chuẩn ComfyUI-H3-Continuum V3.9.8 ([Chunk 1]..[Chunk N] + định tuyến @R1..@R9 + Continuation of Chunk N-1)."""
    images_data = images_data or []
    uploaded_count = len(images_data)
    chunks = max(2, min(16, int(chunks or 3)))
    chunk_seconds = max(4.0, min(15.0, float(chunk_seconds or 10.0)))

    st = get_gemini_web_status(auto_start=True)
    if not st.get("connected"):
        return _build_continuum_smart_fallback(script_text, chunks, chunk_seconds, uploaded_count, adult_mode)

    api_url = st["api_url"].rstrip("/")
    avail_ids = [m.get("id") for m in st.get("models", []) if m.get("id")]
    chosen_model = model if (model in avail_ids or not avail_ids) else avail_ids[0]

    ref_list_str = ", ".join(f"@R{i+1}" for i in range(max(1, uploaded_count)))
    adult_instruction = (
        "\nADULT / 18+ MODE IS ENABLED: Preserve full anatomical, sensual, and uncensored fidelity in English if the script or images involve adult themes."
        if adult_mode else ""
    )

    sys_prompt = f"""You are the Official Prompt Compiler for ComfyUI-H3-Continuum V3.9.8 (MiniMax H3 Multi-Chunk Seamless Video Engine).
Convert the user's idea/script and uploaded reference images ({ref_list_str}) into a {chunks}-chunk V3.9 Timeline prompt (`[Chunk 1]` .. `[Chunk {chunks}]`, {chunk_seconds:g}s per chunk).

STRICT V3.9 PROMPT WRITING RULES (from write-h3-v39-reference-prompts):
1. Use `@R1`, `@R2`, ..., `@R9` to refer to uploaded reference images (`@R1` = Image 1, `@R2` = Image 2, etc.). NEVER use `<Picture 1>` — always use `@R1`.
2. Write EXACTLY {chunks} chunks. Each chunk is {chunk_seconds:g} seconds long.
3. Chunk 1 establishes `@R1` (and any other active `@Rk` in Chunk 1): exact facial identity, hairstyle, wardrobe, environment, camera framing, action, and soundscape.
4. Every subsequent chunk (`Chunk K` where K >= 2) MUST start with:
   `Continuation of Chunk {{K-1}} in the same continuous take.` (or `Continuation of Chunk {{K-1}}...`)
   and explicitly reiterate the active `@R1`..`@Rk` subject identity, wardrobe, lighting, and spatial continuity.
5. NO EARLY SPOILERS: In Chunk K, only describe actions, props, and subjects that appear DURING Chunk K. Do NOT mention future events or subjects that only enter in Chunk K+1.
6. If a character speaks or sings, wrap spoken dialogue in `<d>[Language] spoken line</d>`.
7. Determine `r_chunks` routing for each `@R1`..`@R{max(1, uploaded_count)}` (e.g. `"1-{chunks}"` if active in all chunks, or `"2-{chunks}"` if introduced in Chunk 2).{adult_instruction}

Return ONLY a valid JSON object matching this exact schema:
{{
  "reference_use": "All chunks",
  "r_chunks": {{
    "r1": "1-{chunks}"
  }},
  "chunk_items": [
    {{
      "chunk": 1,
      "note_vi": "Tóm tắt ngắn gọn Chunk 1 bằng tiếng Việt",
      "text": "Detailed English V3.9 prompt for [Chunk 1] using @R1..."
    }}
  ]
}}"""

    user_text = (script_text or "").strip() or f"Hãy quan sát {uploaded_count or 1} ảnh tham chiếu ({ref_list_str}) và biên dịch kịch bản {chunks} Chunks ({chunk_seconds:g}s/chunk) liền mạch chuẩn H3 Continuum V3.9."
    content_parts = [{"type": "text", "text": f"{sys_prompt}\n\n=== USER SCRIPT / REQUEST ===\n{user_text}"}]
    for img_item in images_data[:9]:
        data_uri = str(img_item.get("data") or "").strip()
        if data_uri.startswith("data:image/"):
            content_parts.append({"type": "image_url", "image_url": {"url": data_uri}})

    payload = {
        "model": chosen_model,
        "messages": [{"role": "user", "content": content_parts if len(content_parts) > 1 else content_parts[0]["text"]}],
        "stream": False,
    }
    try:
        req_bytes = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        req = urllib.request.Request(
            f"{api_url}/chat/completions",
            data=req_bytes,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=180) as resp:
            resp_json = json.loads(resp.read().decode("utf-8", errors="ignore"))
        raw_reply = resp_json["choices"][0]["message"]["content"]
        parsed = _extract_json_block(raw_reply)
    except Exception:
        return _build_continuum_smart_fallback(script_text, chunks, chunk_seconds, uploaded_count, adult_mode)

    chunk_items = []
    for idx, item in enumerate(parsed.get("chunk_items") or parsed.get("chunks") or []):
        if not isinstance(item, dict):
            continue
        c_num = idx + 1
        txt = str(item.get("text") or item.get("prompt") or "").strip()
        txt = re.sub(r"<Picture\s+(\d)>", r"@R\1", txt, flags=re.IGNORECASE)
        if txt and "@R" not in txt:
            txt = f"@R1 {txt}"
        if c_num >= 2 and not txt.lower().startswith("continuation of chunk"):
            txt = f"Continuation of Chunk {c_num - 1} in the same continuous take. {txt}"
        chunk_items.append({
            "chunk": c_num,
            "note_vi": str(item.get("note_vi") or f"Chunk {c_num}").strip(),
            "text": txt,
        })

    if not chunk_items:
        return _build_continuum_smart_fallback(script_text, chunks, chunk_seconds, uploaded_count, adult_mode)

    r_chunks = parsed.get("r_chunks") if isinstance(parsed.get("r_chunks"), dict) else {f"r{i+1}": f"1-{len(chunk_items)}" for i in range(max(1, uploaded_count))}
    ref_use = str(parsed.get("reference_use") or "All chunks")
    if ref_use not in ("All chunks", "Per chunk"):
        ref_use = "All chunks"
    sequence_prompt = "\n\n".join(f"[Chunk {c['chunk']}]\n{c['text']}" for c in chunk_items)
    return {
        "ok": True,
        "model": chosen_model,
        "chunks": len(chunk_items),
        "chunk_seconds": chunk_seconds,
        "reference_use": ref_use,
        "r_chunks": r_chunks,
        "chunk_items": chunk_items,
        "sequence_prompt": sequence_prompt,
    }


def _catmull_rom_point(pts: list, t: float) -> tuple:
    """Nội suy đường cong mượt Catmull-Rom qua danh sách điểm [(x, y, z), ...] với t thuộc [0.0, 1.0]."""
    n = len(pts)
    if n == 0:
        return (0.0, 0.0, 1.7)
    if n == 1:
        return tuple(float(v) for v in pts[0])
    t = max(0.0, min(1.0, float(t)))
    seg_f = t * (n - 1)
    idx = min(n - 2, int(seg_f))
    u = seg_f - idx
    p0 = pts[max(0, idx - 1)]
    p1 = pts[idx]
    p2 = pts[min(n - 1, idx + 1)]
    p3 = pts[min(n - 1, idx + 2)]
    u2 = u * u
    u3 = u2 * u
    out = []
    for k in range(3):
        v0, v1, v2, v3 = float(p0[k]), float(p1[k]), float(p2[k]), float(p3[k])
        val = 0.5 * (
            (2.0 * v1)
            + (-v0 + v2) * u
            + (2.0 * v0 - 5.0 * v1 + 4.0 * v2 - v3) * u2
            + (-v0 + 3.0 * v1 - 3.0 * v2 + v3) * u3
        )
        out.append(val)
    return (out[0], out[1], out[2])


def render_cam01_previs_mp4(scene_data: dict) -> dict:
    """
    Kết xuất Video Mẫu Đường Đi Máy Quay 3D Toàn Thân (Full-Body Minimalist 3D Previs):
    - Nhân vật chính (Ảnh 1, 2, 3...): Hình trụ Toàn Thân (2 chân + thân + 2 tay + đầu cầu tỉ lệ chuẩn, màu xám/xanh/tím tối giản).
    - Người phụ / Đám đông: Hình trụ Toàn Thân màu trắng kem tối giản.
    - Đạo cụ 3D (Ghế sofa, bàn trà, quầy bar, ghế, cột nhà, cửa) & Tường phẳng.
    - Hỗ trợ nhiều góc quay (Multi-Shot) hoặc 1 cú máy liền mạch (One-Take).
    """
    import math
    import cv2
    import numpy as np

    scene_data = scene_data or {}
    previs_dur = max(2.0, min(15.0, float(scene_data.get("duration") or 5.0)))
    h3_target_dur = max(previs_dur, min(15.0, float(scene_data.get("h3_duration") or (previs_dur + 1.0))))
    fps = 24
    total_frames = max(24, int(round(previs_dur * fps)))

    aspect = str(scene_data.get("aspect") or "16:9").strip()
    if aspect == "9:16":
        w, h = 768, 1376
    elif aspect == "1:1":
        w, h = 1024, 1024
    else:
        w, h = 1280, 720

    default_fov_mm = float(scene_data.get("fov_mm") or 32.0)
    framing_mode = str(scene_data.get("framing") or "full_body").strip()
    show_ceiling = bool(scene_data.get("show_ceiling", True))
    ceiling_h = float(scene_data.get("ceiling_height") or 3.2)
    look_mode = str(scene_data.get("look_mode") or "dolly_blend").strip()
    ease_mode = str(scene_data.get("ease_mode") or "ease_out").strip()

    walls = scene_data.get("walls") or []
    props = scene_data.get("props") or []
    actors = scene_data.get("actors") or []
    shots_raw = scene_data.get("shots") or []
    waypoints_raw = scene_data.get("waypoints") or []

    if not shots_raw:
        if not waypoints_raw:
            waypoints_raw = [
                {"x": -3.2, "y": 2.4, "z": 1.35},
                {"x": -0.4, "y": 1.2, "z": 1.35},
                {"x": 2.4, "y": 0.8, "z": 1.35},
                {"x": 0.8, "y": -1.4, "z": 1.35},
                {"x": 0.0, "y": -2.5, "z": 1.32},
            ]
        shots_raw = [{
            "name": "Góc quay 1",
            "waypoints": waypoints_raw,
            "fov_mm": default_fov_mm,
            "framing": framing_mode,
            "look_mode": look_mode,
        }]

    # Locate Hero actor (<Picture 1>)
    hero_actor = None
    for ac in actors:
        if str(ac.get("role") or "").startswith("hero"):
            hero_actor = ac
            break
    if not hero_actor and actors:
        hero_actor = actors[0]

    out_dir = SCRIPT_DIR / "output" / "previs"
    out_dir.mkdir(parents=True, exist_ok=True)
    ts_str = time.strftime("%Y%m%d_%H%M%S")
    uid = uuid.uuid4().hex[:5]
    raw_tmp_mp4 = out_dir / f"cam01_raw_{ts_str}_{uid}.mp4"
    final_mp4 = out_dir / f"cam01_previs_{ts_str}_{uid}.mp4"

    fourcc = cv2.VideoWriter_fourcc(*"mp4v")
    writer = cv2.VideoWriter(str(raw_tmp_mp4), fourcc, float(fps), (w, h))

    def _project_3d(pt_world, cam_pos, right_v, up_v, fwd_v, focal_px):
        dx = pt_world[0] - cam_pos[0]
        dy = pt_world[1] - cam_pos[1]
        dz = pt_world[2] - cam_pos[2]
        cx = dx * right_v[0] + dy * right_v[1] + dz * right_v[2]
        cy = dx * up_v[0] + dy * up_v[1] + dz * up_v[2]
        cz = dx * fwd_v[0] + dy * fwd_v[1] + dz * fwd_v[2]
        if cz <= 0.25:
            return None
        sx = int(round(w * 0.5 + (cx / cz) * focal_px))
        sy = int(round(h * 0.5 - (cy / cz) * focal_px))
        return (sx, sy, cz)

    def _clip_line_3d(p1_w, p2_w, cam_pos, right_v, up_v, fwd_v, focal_px):
        def _to_cam(pw):
            dx, dy, dz = pw[0] - cam_pos[0], pw[1] - cam_pos[1], pw[2] - cam_pos[2]
            return [
                dx * right_v[0] + dy * right_v[1] + dz * right_v[2],
                dx * up_v[0] + dy * up_v[1] + dz * up_v[2],
                dx * fwd_v[0] + dy * fwd_v[1] + dz * fwd_v[2],
            ]
        c1, c2 = _to_cam(p1_w), _to_cam(p2_w)
        near_z = 0.25
        if c1[2] < near_z and c2[2] < near_z:
            return None
        if c1[2] < near_z:
            t_clip = (near_z - c1[2]) / (c2[2] - c1[2] + 1e-8)
            c1 = [c1[i] + t_clip * (c2[i] - c1[i]) for i in range(3)]
        elif c2[2] < near_z:
            t_clip = (near_z - c2[2]) / (c1[2] - c2[2] + 1e-8)
            c2 = [c2[i] + t_clip * (c1[i] - c2[i]) for i in range(3)]
        s1 = (int(round(w * 0.5 + (c1[0] / c1[2]) * focal_px)), int(round(h * 0.5 - (c1[1] / c1[2]) * focal_px)), c1[2])
        s2 = (int(round(w * 0.5 + (c2[0] / c2[2]) * focal_px)), int(round(h * 0.5 - (c2[1] / c2[2]) * focal_px)), c2[2])
        return s1, s2

    def _draw_capsule_3d(frame_img, p_a, p_b, rad_px, sh_bgr, hi_bgr):
        """Vẽ ống trụ 3D có đổ bóng mượt nối từ điểm màn hình p_a đến p_b."""
        x1, y1 = p_a[0], p_a[1]
        x2, y2 = p_b[0], p_b[1]
        r = max(2, int(round(rad_px)))
        dx, dy = x2 - x1, y2 - y1
        seg_l = math.hypot(dx, dy)
        if seg_l < 1.0:
            cv2.circle(frame_img, (x1, y1), r, hi_bgr, -1, lineType=cv2.LINE_AA)
            return
        nx, ny = -dy / seg_l, dx / seg_l
        n_strips = max(4, min(16, r))
        for s_i in range(n_strips):
            u0 = -1.0 + 2.0 * (s_i / n_strips)
            u1 = -1.0 + 2.0 * ((s_i + 1) / n_strips)
            um = 0.5 * (u0 + u1)
            lit = max(0.0, math.cos((um + 0.25) * 1.35))
            col_s = tuple(int(round(sh_bgr[c] + (hi_bgr[c] - sh_bgr[c]) * lit)) for c in range(3))
            pts = np.array([
                [int(round(x1 + nx * u0 * r)), int(round(y1 + ny * u0 * r))],
                [int(round(x1 + nx * u1 * r)), int(round(y1 + ny * u1 * r))],
                [int(round(x2 + nx * u1 * r)), int(round(y2 + ny * u1 * r))],
                [int(round(x2 + nx * u0 * r)), int(round(y2 + ny * u0 * r))],
            ], dtype=np.int32)
            cv2.fillPoly(frame_img, [pts], col_s, lineType=cv2.LINE_AA)
        mid_bgr = tuple(int(round(0.35 * sh_bgr[c] + 0.65 * hi_bgr[c])) for c in range(3))
        cv2.circle(frame_img, (x1, y1), r, mid_bgr, -1, lineType=cv2.LINE_AA)
        cv2.circle(frame_img, (x2, y2), r, hi_bgr, -1, lineType=cv2.LINE_AA)

    n_shots = max(1, len(shots_raw))
    shot_durs = [max(0.5, float(sh.get("duration") or (previs_dur / n_shots))) for sh in shots_raw]
    total_shot_dur = max(0.5, sum(shot_durs))

    # ===== #1: Động tác THẬT (khung xương .npz bóc từ video / tạo từ chữ) cho nhân vật chính trong cảnh Cam01 =====
    _motion_cache: dict = {}
    _MOT_EDGES = [
        ("pelvis", "left_hip"), ("left_hip", "left_knee"), ("left_knee", "left_ankle"), ("left_ankle", "left_foot"),
        ("pelvis", "right_hip"), ("right_hip", "right_knee"), ("right_knee", "right_ankle"), ("right_ankle", "right_foot"),
        ("pelvis", "spine1"), ("spine1", "spine2"), ("spine2", "spine3"), ("spine3", "neck"), ("neck", "head"),
        ("spine3", "left_collar"), ("left_collar", "left_shoulder"), ("left_shoulder", "left_elbow"),
        ("left_elbow", "left_wrist"), ("left_wrist", "left_hand"),
        ("spine3", "right_collar"), ("right_collar", "right_shoulder"), ("right_shoulder", "right_elbow"),
        ("right_elbow", "right_wrist"), ("right_wrist", "right_hand"),
    ]
    _MOT_RAD = {"pelvis": 0.11, "spine": 0.12, "neck": 0.05, "collar": 0.06, "shoulder": 0.05, "elbow": 0.04,
                "wrist": 0.03, "hip": 0.07, "knee": 0.055, "ankle": 0.04}

    def _load_motion_npz(pth: str):
        pth = str(pth or "").strip()
        if not pth:
            return None
        if pth in _motion_cache:
            return _motion_cache[pth]
        res_m = None
        try:
            z = np.load(win_path(pth), allow_pickle=False)
            names_m = [str(x) for x in z["joint_names"]]
            if "all_actors_joints_3d" in z.files:
                arr = np.asarray(z["all_actors_joints_3d"], dtype=np.float64)
            else:
                arr = np.asarray(z["joints_3d"], dtype=np.float64)[None]
            fps_m = float(z["fps"]) if "fps" in z.files else 24.0
            need = {"pelvis", "head", "left_foot", "right_foot", "left_ankle", "right_ankle"}
            if arr.ndim == 4 and arr.shape[1] >= 2 and need.issubset(set(names_m)):
                pel_i = names_m.index("pelvis")
                feet_i = [names_m.index(k) for k in ("left_ankle", "right_ankle", "left_foot", "right_foot")]
                head_i = names_m.index("head")
                actors_m = []
                for a_m in range(arr.shape[0]):
                    A = arr[a_m].copy()
                    A[:, :, 1] -= A[:, feet_i, 1].min(axis=1, keepdims=True)
                    p0 = A[0, pel_i].copy()
                    A[:, :, 0] -= p0[0]
                    A[:, :, 2] -= p0[2]
                    h_med = float(np.median(A[:, head_i, 1]))
                    if h_med > 0.2:
                        actors_m.append({"J": A, "head_h": h_med})
                if actors_m:
                    res_m = {"actors": actors_m, "names": names_m, "fps": max(1.0, fps_m)}
        except Exception as e_m:
            print(f"[Cam01] Không nạp được động tác {pth}: {e_m}")
        _motion_cache[pth] = res_m
        return res_m

    scene_motion_npz = str(scene_data.get("motion_npz") or "").strip()
    motion_scope = str(scene_data.get("motion_scope") or "heroes").strip().lower()
    motion_used = {"count": 0}

    def _actor_motion(ac_m: dict, role_m: str):
        own = str(ac_m.get("motion_npz") or "").strip()
        pth = own or scene_motion_npz
        if not pth:
            return None
        if not own and motion_scope != "all" and not role_m.startswith("hero"):
            return None
        mot = _load_motion_npz(pth)
        if not mot:
            return None
        if role_m == "hero2":
            k = 1
        elif role_m == "hero3":
            k = 2
        else:
            k = max(0, int(ac_m.get("motion_actor") or ac_m.get("pic_idx") or 1) - 1) if role_m.startswith("hero") else 0
        return mot, mot["actors"][k % len(mot["actors"])]

    def _draw_motion_actor(frame_img, mot, act_m, ax_m, ay_m, sxv, syv, fxv, fyv, height_mm, f_i,
                           cam_pos_m, right_m, up_m, fwd_m, focal_m, sh_c, hi_c, lsh_c, lhi_c):
        names_m = mot["names"]
        J = act_m["J"]
        fi_m = min(J.shape[0] - 1, int(round(f_i / float(fps) * mot["fps"])))
        sc_m = (height_mm * 0.93) / max(0.2, act_m["head_h"])
        pts_w = {}
        for ji_m, nm in enumerate(names_m):
            lx, ly, lz = J[fi_m, ji_m]
            lx, lz = lx * sc_m, lz * sc_m
            pts_w[nm] = (ax_m + lx * sxv + lz * fxv, ay_m + lx * syv + lz * fyv, ly * sc_m)
        segs = []
        for a_n, b_n in _MOT_EDGES:
            if a_n not in pts_w or b_n not in pts_w:
                continue
            pa = _project_3d(pts_w[a_n], cam_pos_m, right_m, up_m, fwd_m, focal_m)
            pb = _project_3d(pts_w[b_n], cam_pos_m, right_m, up_m, fwd_m, focal_m)
            if not pa or not pb:
                continue
            key = next((k for k in _MOT_RAD if k in a_n), "spine")
            is_leg = any(k in a_n for k in ("hip", "knee", "ankle")) and a_n != "pelvis"
            segs.append((0.5 * (pa[2] + pb[2]), pa, pb, _MOT_RAD[key], is_leg))
        segs.sort(key=lambda s: s[0], reverse=True)
        for depth_s, pa, pb, r_m, is_leg in segs:
            rad = max(2.0, (r_m / max(0.5, depth_s)) * focal_m)
            if is_leg:
                _draw_capsule_3d(frame_img, pa, pb, rad, lsh_c, lhi_c)
            else:
                _draw_capsule_3d(frame_img, pa, pb, rad, sh_c, hi_c)
        if "head" in pts_w:
            ph = _project_3d(pts_w["head"], cam_pos_m, right_m, up_m, fwd_m, focal_m)
            if ph:
                hr = max(3, int(round((0.105 / max(0.5, ph[2])) * focal_m)))
                cv2.circle(frame_img, (ph[0], ph[1]), hr, (158, 186, 218), -1, lineType=cv2.LINE_AA)
                cv2.circle(frame_img, (ph[0] - max(1, hr // 4), ph[1] - max(1, hr // 4)), max(2, int(hr * 0.52)),
                           (190, 216, 242), -1, lineType=cv2.LINE_AA)
        motion_used["count"] += 1

    for f_idx in range(total_frames):
        global_u = f_idx / max(1, total_frames - 1)
        t_cur = global_u * total_shot_dur
        shot_idx = 0
        local_raw_u = 0.0
        for s_i, s_d in enumerate(shot_durs):
            if t_cur <= s_d or s_i == n_shots - 1:
                shot_idx = s_i
                local_raw_u = max(0.0, min(1.0, t_cur / max(0.1, s_d)))
                break
            t_cur -= s_d
        cur_shot = shots_raw[shot_idx]

        cur_wps = cur_shot.get("waypoints") or waypoints_raw
        if not cur_wps:
            cur_wps = [{"x": 0.0, "y": 2.2, "z": 1.35}, {"x": 0.0, "y": -2.5, "z": 1.32}]

        cur_fov = float(cur_shot.get("fov_mm") or default_fov_mm or 32.0)
        cur_framing = str(cur_shot.get("framing") or framing_mode or "full_body").strip()
        cur_look = str(cur_shot.get("look_mode") or look_mode or "dolly_blend").strip()

        # Select target actor for this specific shot (e.g., Shot 3 cuts to Sect Elder hero_2!)
        target_id = str(cur_shot.get("target_actor_id") or "").strip()
        focus_actor = next((a for a in actors if str(a.get("id") or "") == target_id), None) or hero_actor
        focus_pose = str((focus_actor or {}).get("pose") or "stand")
        is_focus_kneel = (focus_pose == "kneel")

        # Target Z height by framing & pose:
        if cur_framing == "closeup":
            target_z_aim = 0.96 if is_focus_kneel else 1.48
            default_cam_z = 1.05 if is_focus_kneel else 1.50
            min_standoff = 1.20
        elif cur_framing == "medium":
            target_z_aim = 0.78 if is_focus_kneel else 1.16
            default_cam_z = 1.08 if is_focus_kneel else 1.38
            min_standoff = 1.65
        else:
            target_z_aim = 0.65 if is_focus_kneel else 0.80
            default_cam_z = 1.15 if is_focus_kneel else 1.22
            min_standoff = 2.35
            cur_fov = min(cur_fov, 30.0)

        fov_rad = 2.0 * math.atan(18.0 / max(18.0, min(105.0, cur_fov)))
        focal_px = (w * 0.5) / math.tan(fov_rad * 0.5)

        wp_tuples = [
            (float(p.get("x", 0.0)), float(p.get("y", 0.0)), float(p.get("z", default_cam_z)))
            for p in cur_wps
        ]

        if ease_mode == "ease_in_out":
            u = local_raw_u * local_raw_u * (3.0 - 2.0 * local_raw_u)
        elif ease_mode == "ease_out":
            u = max(0.0, min(1.0, local_raw_u + 0.10 * math.sin(local_raw_u * math.pi)))
        else:
            u = local_raw_u

        cam_pos = list(_catmull_rom_point(wp_tuples, u))
        ahead_pos = _catmull_rom_point(wp_tuples, min(1.0, u + 0.08))

        # Dynamic focus actor position at current time
        hx_w = float(focus_actor.get("x", 0.0)) if focus_actor else 0.0
        hy_w = float(focus_actor.get("y", -3.0)) if focus_actor else -3.0
        if focus_actor and isinstance(focus_actor.get("walk_to"), dict):
            w_start = float(focus_actor.get("walk_start_u") or 0.0)
            eff_u = max(0.0, min(1.0, (global_u - w_start) / max(0.05, 1.0 - w_start))) if global_u >= w_start else 0.0
            wtx = float(focus_actor["walk_to"].get("x", hx_w))
            wty = float(focus_actor["walk_to"].get("y", hy_w))
            hx_w = hx_w + (wtx - hx_w) * eff_u
            hy_w = hy_w + (wty - hy_w) * eff_u
        elif focus_actor and isinstance(focus_actor.get("path"), list) and len(focus_actor["path"]) >= 2:
            hp_tuples = [(float(p.get("x", hx_w)), float(p.get("y", hy_w)), 0.0) for p in focus_actor["path"]]
            hp_now = _catmull_rom_point(hp_tuples, global_u)
            hx_w, hy_w = hp_now[0], hp_now[1]

        # Enforce minimum standoff distance from Focus Actor at all times
        dist_to_hero = math.hypot(cam_pos[0] - hx_w, cam_pos[1] - hy_w)
        if dist_to_hero < min_standoff and dist_to_hero > 1e-3:
            cam_pos[0] = hx_w + ((cam_pos[0] - hx_w) / dist_to_hero) * min_standoff
            cam_pos[1] = hy_w + ((cam_pos[1] - hy_w) / dist_to_hero) * min_standoff

        hero_pos = (hx_w, hy_w, target_z_aim)

        tx_path = ahead_pos[0] - cam_pos[0]
        ty_path = ahead_pos[1] - cam_pos[1]
        tz_path = (target_z_aim - cam_pos[2]) * 0.85
        path_len = math.hypot(tx_path, ty_path)
        if path_len < 1e-3:
            tx_path, ty_path, tz_path = hero_pos[0] - cam_pos[0], hero_pos[1] - cam_pos[1], hero_pos[2] - cam_pos[2]
            path_len = max(1e-3, math.hypot(tx_path, ty_path))
        dir_path = (tx_path / path_len, ty_path / path_len, tz_path / max(1.5, path_len))

        hx, hy, hz = hero_pos[0] - cam_pos[0], hero_pos[1] - cam_pos[1], hero_pos[2] - cam_pos[2]
        h_len = max(1e-3, math.sqrt(hx * hx + hy * hy + hz * hz))
        dir_hero = (hx / h_len, hy / h_len, hz / h_len)

        if cur_look == "lock_hero":
            blend_w = 1.0
        elif cur_look == "tangent":
            blend_w = 0.15
        else:
            blend_w = max(0.35, min(1.0, (u - 0.35) / 0.55)) if u > 0.35 else 0.35 + u * 0.25

        fx = dir_path[0] * (1.0 - blend_w) + dir_hero[0] * blend_w
        fy = dir_path[1] * (1.0 - blend_w) + dir_hero[1] * blend_w
        fz = dir_path[2] * (1.0 - blend_w) + dir_hero[2] * blend_w
        f_norm = max(1e-5, math.sqrt(fx * fx + fy * fy + fz * fz))
        fwd_v = (fx / f_norm, fy / f_norm, fz / f_norm)

        rx, ry = fwd_v[1], -fwd_v[0]
        r_norm = max(1e-5, math.hypot(rx, ry))
        right_v = (rx / r_norm, ry / r_norm, 0.0)
        up_v = (
            right_v[1] * fwd_v[2],
            -right_v[0] * fwd_v[2],
            right_v[0] * fwd_v[1] - right_v[1] * fwd_v[0],
        )

        # Base frame: clean minimalist room/courtyard background
        frame = np.full((h, w, 3), (224, 234, 240), dtype=np.uint8)
        horizon_y = int(round(h * 0.5 - (fwd_v[2] / max(0.2, math.hypot(fwd_v[0], fwd_v[1]))) * focal_px * 0.65))
        horizon_y = max(int(h * 0.15), min(int(h * 0.72), horizon_y))
        frame[horizon_y:, :] = (196, 208, 218)
        if show_ceiling:
            ceil_y = max(0, int(round(horizon_y - h * 0.34)))
            frame[:ceil_y, :] = (236, 242, 246)

        # Draw subtle 3D floor perspective grid
        for gx in range(-10, 11, 1):
            seg = _clip_line_3d((gx, -9.0, 0.0), (gx, 6.0, 0.0), cam_pos, right_v, up_v, fwd_v, focal_px)
            if seg:
                cv2.line(frame, (seg[0][0], seg[0][1]), (seg[1][0], seg[1][1]), (182, 194, 204), 1, lineType=cv2.LINE_AA)
        for gy in range(-9, 7, 1):
            seg = _clip_line_3d((-10.0, gy, 0.0), (10.0, gy, 0.0), cam_pos, right_v, up_v, fwd_v, focal_px)
            if seg:
                cv2.line(frame, (seg[0][0], seg[0][1]), (seg[1][0], seg[1][1]), (182, 194, 204), 1, lineType=cv2.LINE_AA)

        draw_queue = []

        def _queue_box_3d(bx, by, bw, bd, z0, z1, pang_rad, side_bgr, top_bgr):
            ca_b, sa_b = math.cos(pang_rad), math.sin(pang_rad)
            hw_b, hd_b = bw * 0.5, bd * 0.5
            c_loc = [(-hw_b, -hd_b), (hw_b, -hd_b), (hw_b, hd_b), (-hw_b, hd_b)]
            c_w = [(bx + lx * ca_b - ly * sa_b, by + lx * sa_b + ly * ca_b) for (lx, ly) in c_loc]
            for fi in range(4):
                c_a = c_w[fi]
                c_b = c_w[(fi + 1) % 4]
                b_s = _clip_line_3d((c_a[0], c_a[1], z0), (c_b[0], c_b[1], z0), cam_pos, right_v, up_v, fwd_v, focal_px)
                t_s = _clip_line_3d((c_a[0], c_a[1], z1), (c_b[0], c_b[1], z1), cam_pos, right_v, up_v, fwd_v, focal_px)
                if b_s and t_s:
                    az = 0.25 * (b_s[0][2] + b_s[1][2] + t_s[0][2] + t_s[1][2])
                    poly = np.array([[b_s[0][0], b_s[0][1]], [b_s[1][0], b_s[1][1]], [t_s[1][0], t_s[1][1]], [t_s[0][0], t_s[0][1]]], dtype=np.int32)
                    sh_f = (-10 if fi % 2 == 1 else 6)
                    col_f = tuple(max(40, min(250, side_bgr[c] + sh_f)) for c in range(3))
                    draw_queue.append((az, "wall", (poly, col_f)))
            top_pts = [_project_3d((cx_w, cy_w, z1), cam_pos, right_v, up_v, fwd_v, focal_px) for (cx_w, cy_w) in c_w]
            if all(top_pts):
                az_top = sum(tp[2] for tp in top_pts) * 0.25 - 0.02
                poly_top = np.array([[tp[0], tp[1]] for tp in top_pts], dtype=np.int32)
                draw_queue.append((az_top, "wall", (poly_top, top_bgr)))

        # 1. Queue minimalist walls / counters
        for w_item in walls:
            x1, y1 = float(w_item.get("x1", -8.0)), float(w_item.get("y1", -6.0))
            x2, y2 = float(w_item.get("x2", 8.0)), float(w_item.get("y2", -6.0))
            wh = float(w_item.get("h") or (1.05 if w_item.get("type") == "counter" else ceiling_h))
            w_type = str(w_item.get("type") or "wall")
            seg_len = max(0.1, math.hypot(x2 - x1, y2 - y1))
            n_sub = max(1, min(12, int(math.ceil(seg_len / 1.5))))
            for s_i in range(n_sub):
                t0, t1 = s_i / n_sub, (s_i + 1) / n_sub
                sx0, sy0 = x1 + (x2 - x1) * t0, y1 + (y2 - y1) * t0
                sx1, sy1 = x1 + (x2 - x1) * t1, y1 + (y2 - y1) * t1
                bot_seg = _clip_line_3d((sx0, sy0, 0.0), (sx1, sy1, 0.0), cam_pos, right_v, up_v, fwd_v, focal_px)
                top_seg = _clip_line_3d((sx0, sy0, wh), (sx1, sy1, wh), cam_pos, right_v, up_v, fwd_v, focal_px)
                if not bot_seg or not top_seg:
                    continue
                avg_z = 0.25 * (bot_seg[0][2] + bot_seg[1][2] + top_seg[0][2] + top_seg[1][2])
                poly = np.array([
                    [bot_seg[0][0], bot_seg[0][1]],
                    [bot_seg[1][0], bot_seg[1][1]],
                    [top_seg[1][0], top_seg[1][1]],
                    [top_seg[0][0], top_seg[0][1]],
                ], dtype=np.int32)
                ang = math.atan2(y2 - y1, x2 - x1)
                shade = int(12 * math.cos(ang))
                if w_type == "counter":
                    col_bgr = (max(135, 168 + shade), max(148, 182 + shade), max(160, 196 + shade))
                else:
                    col_bgr = (max(175, 208 + shade), max(185, 218 + shade), max(195, 226 + shade))
                draw_queue.append((avg_z, "wall", (poly, col_bgr)))

        # 2. Queue Rich 3D Props (Monument, Arch Gate, Sofa, Table with 4 legs, Tree, Car, Stage, Red Carpet, Stairs, etc.)
        for pr in props:
            px, py = float(pr.get("x", 0.0)), float(pr.get("y", -2.5))
            pw = float(pr.get("w") or 1.4)
            pd = float(pr.get("d") or 0.8)
            ph = float(pr.get("h") or 0.78)
            ptype = str(pr.get("type") or "table").lower()
            pang = math.radians(float(pr.get("angle") or 0.0))
            ca_p, sa_p = math.cos(pang), math.sin(pang)

            if ptype == "monument":
                # Dark stone spiritual-root testing monument: stepped stone pedestal + dark slate obelisk stele
                _queue_box_3d(px, py, pw * 1.35, pd * 1.35, 0.0, 0.30, pang, (118, 126, 136), (138, 146, 156))
                _queue_box_3d(px, py, pw, pd, 0.30, ph * 0.86, pang, (68, 74, 84), (84, 90, 102))
                _queue_box_3d(px, py, pw * 0.72, pd * 0.72, ph * 0.86, ph, pang, (54, 60, 70), (72, 78, 90))
            elif ptype == "arch_gate":
                # Ancient sect hall / gateway: left & right pillars + upper roof beam
                pil_w = max(0.35, pw * 0.16)
                for side_g in (-1.0, 1.0):
                    gx_p = px + (pw * 0.40 * side_g) * ca_p
                    gy_p = py + (pw * 0.40 * side_g) * sa_p
                    _queue_box_3d(gx_p, gy_p, pil_w, pd, 0.0, ph * 0.78, pang, (110, 122, 142), (128, 140, 160))
                _queue_box_3d(px, py, pw * 1.12, pd * 1.25, ph * 0.78, ph, pang, (92, 104, 124), (112, 124, 145))
            elif ptype in ("table", "round_table", "bench"):
                _queue_box_3d(px, py, pw, pd, max(0.35, ph - 0.08), ph, pang, (132, 158, 185), (152, 178, 204))
                for lx_s in (-pw * 0.42, pw * 0.42):
                    for ly_s in (-pd * 0.42, pd * 0.42):
                        wx_l = px + lx_s * ca_p - ly_s * sa_p
                        wy_l = py + lx_s * sa_p + ly_s * ca_p
                        _queue_box_3d(wx_l, wy_l, 0.09, 0.09, 0.0, max(0.35, ph - 0.08), pang, (112, 132, 152), (122, 142, 162))
            elif ptype in ("sofa", "chair", "bed"):
                _queue_box_3d(px, py, pw, pd, 0.0, ph * 0.52, pang, (138, 154, 172), (158, 175, 192))
                bx_s = px - (-pd * 0.36) * sa_p
                by_s = py + (-pd * 0.36) * ca_p
                _queue_box_3d(bx_s, by_s, pw, pd * 0.28, ph * 0.52, ph, pang, (124, 140, 158), (146, 162, 180))
            elif ptype == "tree":
                _queue_box_3d(px, py, 0.24, 0.24, 0.0, ph * 0.48, pang, (92, 118, 148), (105, 132, 162))
                p_can = _project_3d((px, py, ph * 0.75), cam_pos, right_v, up_v, fwd_v, focal_px)
                if p_can and p_can[2] > 0.5:
                    r_can = max(6, int(round((max(pw, 0.9) * 0.52 / p_can[2]) * focal_px)))
                    draw_queue.append((p_can[2] - 0.05, "sphere", (p_can[0], p_can[1], r_can, (118, 172, 132), (148, 202, 162))))
            elif ptype in ("car", "motorbike"):
                _queue_box_3d(px, py, pw, pd, 0.12, ph * 0.58, pang, (128, 142, 162), (148, 164, 184))
                _queue_box_3d(px, py, pw * 0.82, pd * 0.55, ph * 0.58, ph, pang, (155, 175, 192), (175, 195, 212))
            elif ptype == "red_carpet":
                _queue_box_3d(px, py, pw, pd, 0.0, 0.04, pang, (95, 92, 185), (108, 105, 205))
            elif ptype == "stairs":
                for st_i in range(4):
                    frac0, frac1 = st_i / 4.0, (st_i + 1) / 4.0
                    sy_off = -pd * 0.5 + pd * (frac0 + frac1) * 0.5
                    wx_st = px - sy_off * sa_p
                    wy_st = py + sy_off * ca_p
                    _queue_box_3d(wx_st, wy_st, pw, pd * 0.25, 0.0, ph * frac1, pang, (152, 166, 180), (174, 188, 202))
            elif ptype in ("light_stand", "street_lamp"):
                _queue_box_3d(px, py, 0.14, 0.14, 0.0, ph * 0.92, pang, (110, 120, 130), (130, 140, 150))
                p_bulb = _project_3d((px, py, ph), cam_pos, right_v, up_v, fwd_v, focal_px)
                if p_bulb and p_bulb[2] > 0.5:
                    r_b = max(4, int(round((0.18 / p_bulb[2]) * focal_px)))
                    draw_queue.append((p_bulb[2] - 0.03, "sphere", (p_bulb[0], p_bulb[1], r_b, (150, 215, 245), (200, 245, 255))))
            else:
                _queue_box_3d(px, py, pw, pd, 0.0, ph, pang, (152, 168, 184), (172, 188, 202))

        # 3. Queue Full-Body 3D Actors (Supporting Stand, Sit, Kneel, Reach, Wave, Talk, Walk with walk_start_u!)
        for ac in actors:
            ax = float(ac.get("x", 0.0))
            ay = float(ac.get("y", 0.0))
            pose_mode = str(ac.get("pose") or "stand")
            act_mode = str(ac.get("action") or ("kneel" if pose_mode == "kneel" else ("sit" if pose_mode == "sit" else "stand")))
            is_walking = False
            if isinstance(ac.get("walk_to"), dict):
                w_start = float(ac.get("walk_start_u") or 0.0)
                if global_u >= w_start:
                    eff_u = max(0.0, min(1.0, (global_u - w_start) / max(0.05, 1.0 - w_start)))
                    wtx = float(ac["walk_to"].get("x", ax))
                    wty = float(ac["walk_to"].get("y", ay))
                    ax = ax + (wtx - ax) * eff_u
                    ay = ay + (wty - ay) * eff_u
                    is_walking = (eff_u > 0.01 and eff_u < 0.99)
            else:
                a_path = ac.get("path") or []
                if isinstance(a_path, list) and len(a_path) >= 2:
                    ap_tuples = [(float(p.get("x", ax)), float(p.get("y", ay)), 0.0) for p in a_path]
                    ap_now = _catmull_rom_point(ap_tuples, global_u)
                    ax, ay = ap_now[0], ap_now[1]
                    is_walking = True

            dx_cam, dy_cam = ax - cam_pos[0], ay - cam_pos[1]
            dist_cam = math.hypot(dx_cam, dy_cam)
            min_actor_clear = 2.25 if cur_framing == "full_body" else 1.20
            if dist_cam < min_actor_clear and dist_cam > 1e-4:
                ax = cam_pos[0] + (dx_cam / dist_cam) * min_actor_clear
                ay = cam_pos[1] + (dy_cam / dist_cam) * min_actor_clear

            role = str(ac.get("role") or "crowd")
            height_m = float(ac.get("height") or (1.18 if pose_mode == "kneel" else (1.32 if pose_mode == "sit" else 1.72)))
            p_center = _project_3d((ax, ay, height_m * 0.5), cam_pos, right_v, up_v, fwd_v, focal_px)
            if not p_center or p_center[2] <= 0.85:
                continue
            draw_queue.append((p_center[2], "actor", (ac, ax, ay, role, pose_mode, act_mode, height_m, is_walking, global_u, shot_idx, local_raw_u)))

        draw_queue.sort(key=lambda item: item[0], reverse=True)

        for _, kind, payload in draw_queue:
            if kind == "wall":
                poly, col_bgr = payload
                cv2.fillPoly(frame, [poly], col_bgr, lineType=cv2.LINE_AA)
                cv2.polylines(frame, [poly], True, (145, 156, 166), 1, lineType=cv2.LINE_AA)
            elif kind == "sphere":
                sx_c, sy_c, rad_c, col_base, col_hi = payload
                cv2.circle(frame, (sx_c, sy_c), rad_c, col_base, -1, lineType=cv2.LINE_AA)
                cv2.circle(frame, (sx_c - max(1, rad_c // 4), sy_c - max(1, rad_c // 4)), max(2, int(rad_c * 0.55)), col_hi, -1, lineType=cv2.LINE_AA)
            elif kind == "actor":
                ac, ax, ay, role, pose_mode, act_mode, height_m, is_walking, cur_u, cur_shot_idx, cur_shot_u = payload
                p_foot_c = _project_3d((ax, ay, 0.0), cam_pos, right_v, up_v, fwd_v, focal_px)
                if not p_foot_c:
                    continue
                cz = max(1.95 if cur_framing == "full_body" else 1.25, p_foot_c[2])

                pic_idx = int(ac.get("pic_idx") or 1)
                if role.startswith("hero"):
                    if pic_idx == 2 or role == "hero2":
                        sh_bgr, hi_bgr = (128, 92, 68), (205, 162, 130)
                        leg_sh, leg_hi = (98, 70, 52), (165, 128, 102)
                    elif pic_idx >= 3 or role == "hero3":
                        sh_bgr, hi_bgr = (68, 62, 118), (132, 118, 195)
                        leg_sh, leg_hi = (48, 42, 90), (105, 92, 155)
                    else:
                        sh_bgr, hi_bgr = (92, 88, 82), (168, 162, 152)
                        leg_sh, leg_hi = (72, 68, 64), (135, 130, 122)
                else:
                    sh_bgr, hi_bgr = (196, 202, 208), (250, 252, 254)
                    leg_sh, leg_hi = (176, 182, 188), (232, 236, 240)

                ang_rad = math.radians(float(ac.get("angle") or 90.0))
                sx_v = -math.sin(ang_rad)
                sy_v = math.cos(ang_rad)
                fx_v = math.cos(ang_rad)
                fy_v = math.sin(ang_rad)

                sh_rad_px = max(4, int(round((0.22 / cz) * focal_px)))
                cv2.ellipse(
                    frame,
                    (p_foot_c[0], p_foot_c[1]),
                    (int(sh_rad_px * 1.15), max(3, int(sh_rad_px * 0.38))),
                    0, 0, 360,
                    (158, 168, 176), -1, lineType=cv2.LINE_AA
                )

                _mot_pair = _actor_motion(ac, role)
                if _mot_pair is not None:
                    _draw_motion_actor(frame, _mot_pair[0], _mot_pair[1], ax, ay, sx_v, sy_v, fx_v, fy_v,
                                       height_m if pose_mode not in ("sit", "kneel") else 1.72, f_idx,
                                       cam_pos, right_v, up_v, fwd_v, focal_px, sh_bgr, hi_bgr, leg_sh, leg_hi)
                    continue

                if pose_mode == "kneel":
                    hip_z = 0.36
                    shoulder_z = 0.84
                    neck_z = 0.90
                    head_z = 1.02
                elif pose_mode == "sit":
                    hip_z = height_m * 0.42
                    shoulder_z = height_m * 0.81
                    neck_z = height_m * 0.85
                    head_z = height_m * 0.92
                else:
                    hip_z = height_m * 0.48
                    shoulder_z = height_m * 0.81
                    neck_z = height_m * 0.85
                    head_z = height_m * 0.92

                stride = math.sin(cur_u * math.pi * 8.0) * 0.14 if is_walking else 0.0
                sit_fwd = 0.22 if pose_mode == "sit" else (0.14 if pose_mode == "kneel" else 0.0)

                # Left & Right Legs + Knees/Shoes
                for side_s in (-1.0, 1.0):
                    hip_w = (ax + sx_v * 0.095 * side_s, ay + sy_v * 0.095 * side_s, hip_z)
                    if pose_mode == "kneel":
                        knee_w = (
                            ax + sx_v * 0.095 * side_s + fx_v * 0.15,
                            ay + sy_v * 0.095 * side_s + fy_v * 0.15,
                            0.05,
                        )
                        foot_back_w = (
                            ax + sx_v * 0.095 * side_s - fx_v * 0.18,
                            ay + sy_v * 0.095 * side_s - fy_v * 0.18,
                            0.04,
                        )
                        p_hip = _project_3d(hip_w, cam_pos, right_v, up_v, fwd_v, focal_px)
                        p_knee = _project_3d(knee_w, cam_pos, right_v, up_v, fwd_v, focal_px)
                        p_fb = _project_3d(foot_back_w, cam_pos, right_v, up_v, fwd_v, focal_px)
                        leg_px = max(2, (0.068 / cz) * focal_px)
                        if p_hip and p_knee:
                            _draw_capsule_3d(frame, p_hip, p_knee, leg_px, leg_sh, leg_hi)
                        if p_knee and p_fb:
                            _draw_capsule_3d(frame, p_knee, p_fb, leg_px * 0.9, leg_sh, leg_hi)
                    else:
                        ankle_w = (
                            ax + sx_v * 0.095 * side_s + fx_v * (sit_fwd + stride * side_s),
                            ay + sy_v * 0.095 * side_s + fy_v * (sit_fwd + stride * side_s),
                            0.04,
                        )
                        p_hip = _project_3d(hip_w, cam_pos, right_v, up_v, fwd_v, focal_px)
                        p_ank = _project_3d(ankle_w, cam_pos, right_v, up_v, fwd_v, focal_px)
                        if p_hip and p_ank:
                            leg_px = max(2, (0.068 / cz) * focal_px)
                            _draw_capsule_3d(frame, p_hip, p_ank, leg_px, leg_sh, leg_hi)
                            cv2.circle(frame, (p_ank[0], p_ank[1]), max(2, int(leg_px * 1.1)), (65, 65, 70), -1, lineType=cv2.LINE_AA)

                # Torso Cylinder
                p_hip_c = _project_3d((ax, ay, hip_z), cam_pos, right_v, up_v, fwd_v, focal_px)
                p_sh_c = _project_3d((ax, ay, shoulder_z), cam_pos, right_v, up_v, fwd_v, focal_px)
                if p_hip_c and p_sh_c:
                    torso_px = max(4, (0.165 / cz) * focal_px)
                    _draw_capsule_3d(frame, p_hip_c, p_sh_c, torso_px, sh_bgr, hi_bgr)

                # Left & Right Arms (wave, reach toward monument, talk, drink, walk)
                for side_s in (-1.0, 1.0):
                    sh_w = (ax + sx_v * 0.19 * side_s, ay + sy_v * 0.19 * side_s, shoulder_z - 0.03)
                    if act_mode == "wave" and side_s > 0:
                        wave_sway = math.sin(cur_u * math.pi * 6.0) * 0.08
                        hand_w = (ax + sx_v * (0.28 + wave_sway), ay + sy_v * (0.28 + wave_sway), head_z + 0.08)
                    elif act_mode == "reach" and side_s > 0 and (n_shots == 1 or cur_shot_idx == 1):
                        reach_amt = math.sin(cur_shot_u * math.pi)
                        hand_w = (
                            ax + sx_v * 0.14 + fx_v * (0.16 + 0.28 * reach_amt),
                            ay + sy_v * 0.14 + fy_v * (0.16 + 0.28 * reach_amt),
                            hip_z + 0.12 + 0.42 * reach_amt,
                        )
                    elif act_mode in ("talk", "drink") and side_s > 0:
                        hand_w = (ax + sx_v * 0.18 + fx_v * 0.18, ay + sy_v * 0.18 + fy_v * 0.18, shoulder_z - 0.10)
                    else:
                        hand_w = (
                            ax + sx_v * 0.20 * side_s + fx_v * (0.12 if pose_mode in ("sit", "kneel") else -stride * 0.5 * side_s),
                            ay + sy_v * 0.20 * side_s + fy_v * (0.12 if pose_mode in ("sit", "kneel") else -stride * 0.5 * side_s),
                            hip_z + 0.04,
                        )
                    p_sh_s = _project_3d(sh_w, cam_pos, right_v, up_v, fwd_v, focal_px)
                    p_hd_s = _project_3d(hand_w, cam_pos, right_v, up_v, fwd_v, focal_px)
                    if p_sh_s and p_hd_s:
                        arm_px = max(2, (0.048 / cz) * focal_px)
                        _draw_capsule_3d(frame, p_sh_s, p_hd_s, arm_px, sh_bgr, hi_bgr)

                # Properly proportioned 3D Sphere Head
                p_neck = _project_3d((ax, ay, neck_z), cam_pos, right_v, up_v, fwd_v, focal_px)
                p_head = _project_3d((ax, ay, head_z), cam_pos, right_v, up_v, focal_px) if False else _project_3d((ax, ay, head_z), cam_pos, right_v, up_v, fwd_v, focal_px)
                if p_neck and p_head:
                    head_rad = max(3, int(round((0.102 / cz) * focal_px)))
                    hx_c, hy_c = p_head[0], p_head[1]
                    head_base = (158, 186, 218) if role.startswith("hero") else (154, 184, 224)
                    head_hi = (190, 216, 242)
                    cv2.circle(frame, (hx_c, hy_c), head_rad, head_base, -1, lineType=cv2.LINE_AA)
                    cv2.circle(
                        frame,
                        (hx_c - max(1, head_rad // 4), hy_c - max(1, head_rad // 4)),
                        max(2, int(head_rad * 0.52)),
                        head_hi, -1, lineType=cv2.LINE_AA
                    )

        writer.write(frame)

    writer.release()

    ff_bin = _find_ffmpeg()
    try:
        subprocess.run(
            [
                ff_bin, "-y", "-i", str(raw_tmp_mp4),
                "-f", "lavfi", "-i", "anullsrc=channel_layout=stereo:sample_rate=44100",
                "-c:v", "libx264", "-preset", "fast", "-crf", "18", "-pix_fmt", "yuv420p",
                "-c:a", "aac", "-shortest",
                str(final_mp4),
            ],
            check=True, capture_output=True, timeout=45,
        )
        raw_tmp_mp4.unlink(missing_ok=True)
    except Exception:
        if raw_tmp_mp4.is_file():
            shutil.move(str(raw_tmp_mp4), str(final_mp4))

    raw_script = str(scene_data.get("original_script") or "").strip()
    hero_desc = str(scene_data.get("hero_desc") or "the main character in <Picture 1> standing naturally full-body with a confident expression").strip()
    scene_desc = str(scene_data.get("scene_desc") or "warm atmospheric interior referenced from <Picture 2>").strip()
    hold_sec = max(0.0, round(h3_target_dur - previs_dur, 1))
    crowd_cnt = sum(1 for a in actors if not str(a.get("role") or "").startswith("hero"))
    prop_labels_en = ", ".join(str(p.get("label") or p.get("type") or "") for p in props[:8] if p)

    # If the user provided a structured multi-shot screenplay (with timecodes, [Shot N], integrated_multimodal_description:, or SETTING:/CHARACTERS:), preserve its full multi-shot structure and dialogue!
    import re as _re_pr
    if raw_script and (
        _re_pr.search(r"\d{1,2}:\d{2}\s*[-–—to]+\s*\d{1,2}:\d{2}", raw_script)
        or "SETTING:" in raw_script
        or "CHARACTERS:" in raw_script
        or "integrated_multimodal_description:" in raw_script
        or "[Shot" in raw_script
        or len(raw_script) >= 80
    ):
        enhanced_script = raw_script.strip()
        # Wrap quoted Mandarin/Vietnamese/English dialogue with <d>...</d> if not already wrapped so MiniMax H3 performs accurate lip-sync
        if "<d>" not in enhanced_script:
            enhanced_script = _re_pr.sub(
                r"(says in (?:Chinese Mandarin|Mandarin|Vietnamese|English)\s*:\s*)['\"]([^'\"]+)['\"]",
                r"\1<d>[\2]</d>",
                enhanced_script,
                flags=_re_pr.IGNORECASE,
            )
            enhanced_script = _re_pr.sub(
                r"(shouting\s*\[(?:Vietnamese|Mandarin|Chinese|English)\]\s*)([^;.\n!]+!?)?",
                lambda m: f"{m.group(1)}<d>[{m.group(2).strip()}]</d>" if m.group(2) else m.group(0),
                enhanced_script,
                flags=_re_pr.IGNORECASE,
            )
        hero_actors = [a for a in actors if str(a.get("role") or "").startswith("hero")]
        pic_refs = []
        for idx_h, ha in enumerate(hero_actors[:4], start=1):
            p_num = int(ha.get("pic_idx") or idx_h)
            lbl_h = str(ha.get("label") or f"Character {p_num}").split("(")[0].strip()
            ref_item = f"<Picture {p_num}> ({lbl_h})"
            if ref_item not in pic_refs:
                pic_refs.append(ref_item)
        if not pic_refs:
            pic_refs = ["<Picture 1> (primary character)"]
        refs_str = ", ".join(pic_refs)
        body_script = _re_pr.sub(r"^integrated_multimodal_description\s*:\s*", "", enhanced_script, flags=_re_pr.IGNORECASE).strip()
        compiled_prompt = (
            f"For the target video, at 0.00 seconds into the target video, {refs_str}, and <Video 1> ({previs_dur:g}s multi-shot 3D camera blocking & spatial reference) are referenced. "
            f"integrated_multimodal_description: Strictly follow the 3D spatial layout, character blocking, and multi-shot camera cuts of <Video 1> while executing this screenplay: {body_script}"
        )
    elif hold_sec > 0.1:
        compiled_prompt = (
            f"For the target video, at 0.00 seconds into the target video, <Picture 1> (main character), <Picture 2> (environment reference), and <Video 1> (camera trajectory and full-body spatial blocking reference) are referenced.\n\n"
            f"integrated_multimodal_description: [Shot 1] Live-action photorealistic footage in {scene_desc}"
            f"{f' featuring {prop_labels_en}' if prop_labels_en else ''}. Continuous single take ({h3_target_dur:g}s total). "
            f"From 0.00s to {previs_dur:.2f}s, strictly follow the exact camera movement path and full-body spatial blocking of <Video 1>: "
            f"transform all minimalist white figures in <Video 1> into realistic full-body people naturally interacting in the scene, and transform the grey target figure into {hero_desc} (<Picture 1>), preserving the exact facial identity and full-body outfit of <Picture 1>. "
            f"From {previs_dur:.2f}s to {h3_target_dur:.2f}s (final {hold_sec:g}s hold), the camera holds steady on <Picture 1> as {hero_desc}, holding natural facial expression and lifelike movements.\n\n"
            f"overall_soundscape: Realistic ambient room acoustics, footsteps, and natural atmosphere matching the camera movement.\n\n"
            f"non_diegetic_music: N/A"
        )
    else:
        compiled_prompt = (
            f"For the target video, at 0.00 seconds into the target video, <Picture 1> (main character), <Picture 2> (environment reference), and <Video 1> (camera trajectory and full-body spatial blocking reference) are referenced.\n\n"
            f"integrated_multimodal_description: [Shot 1] Live-action photorealistic footage in {scene_desc}"
            f"{f' featuring {prop_labels_en}' if prop_labels_en else ''}. Continuous single take ({previs_dur:g}s). "
            f"Strictly follow the exact camera movement trajectory and full-body blocking guided by <Video 1>, stopping at {hero_desc} (<Picture 1>). "
            f"Transform all minimalist figures into realistic full-body people and the grey figure into <Picture 1> with exact facial identity.\n\n"
            f"overall_soundscape: Realistic ambient room and crowd soundscape.\n\n"
            f"non_diegetic_music: N/A"
        )

    return {
        "ok": True,
        "path": str(final_mp4),
        "filename": final_mp4.name,
        "duration": previs_dur,
        "h3_duration": h3_target_dur,
        "hold_seconds": hold_sec,
        "width": w,
        "height": h,
        "crowd_count": crowd_cnt,
        "waypoints_count": len(waypoints_raw),
        "compiled_prompt": compiled_prompt,
        "motion_used": int(motion_used.get("count", 0)),
    }


def _call_gemini_for_cam01_scene(idea: str, model: str = "gemini-3.1-pro", api_key: str = "") -> dict | None:
    """
    Gọi Gemini Cookie API nội bộ (127.0.0.1:4981: gemini-3.1-pro, gemini-3.8-flash, gemini-4-argon, gemini-3.5-flash-lite)
    để bóc tách kịch bản phức tạp thành sơ đồ 3D (walls, props, actors, multi-shot timecoded shots).
    """
    if not idea or len(idea.strip()) < 10:
        return None

    cfg = load_gemini_cookie_config()
    eff_key = (api_key or cfg.get("gemini_api_key") or os.environ.get("GEMINI_API_KEY") or "").strip()

    sys_instruction = """You are a 3D Film Blocking & Camera Previs Director. Analyze the user's screenplay/prompt and output ONLY a valid JSON object representing the 3D floor plan, props, characters, and multi-shot camera trajectories.

COORDINATE SYSTEM (in meters):
- X: left (-) to right (+), range [-7.0, +7.0]. Center is X=0.
- Y: back of scene is negative (e.g. Y=-5.5 for back wall, Y=-3.0 for center monument/stage), front toward camera is positive (Y=+1.0 to +3.5).
- Z: height above floor in meters (floor Z=0.0, eye-level camera Z=1.24, high crane camera Z=2.30).

ALLOWED PROP TYPES (`props[].type`):
"monument" (stone testing obelisk/stele), "arch_gate" (ancient sect hall/gateway), "stage" (stone platform/stage), "pillar" (stone column), "sofa", "table", "round_table", "chair", "bed", "tv_screen", "bookshelf", "piano", "counter", "red_carpet", "light_stand", "car", "motorbike", "tree", "street_lamp", "bench", "fence", "door", "window", "stairs".

ALLOWED ACTOR POSES (`actors[].pose`):
- "stand" (height 1.72)
- "sit" (height 1.32)
- "kneel" (kneeling on floor, height 1.18)

ALLOWED ACTOR ACTIONS (`actors[].action`):
- "stand", "sit", "kneel", "reach" (lifting hand toward object), "walk", "wave", "talk", "drink".
- CRITICAL POSE RULE: Only use `"pose": "kneel"` if the character is explicitly kneeling in prayer/ceremony throughout the scene. For combat, action, crouching/landing, hunting, or standing scenes, ALWAYS use `"pose": "stand"` and `"action": "walk"` or `"reach"` with `"height": 1.70`!
- If an actor walks/moves in the frame, include `"walk_to": {"x": 0.0, "y": -1.2}` and `"walk_start_u": 0.15` (fraction of total duration when movement begins).

MULTI-SHOT CAMERA CUTS (`shots`):
- If the prompt has timecoded shots (e.g. `00:00-00:03`, `00:03-00:07`) or `[Shot 1]`, `[Shot 2]`..., create one entry in `shots` for EACH shot with exact `duration` in seconds, `name` (in Vietnamese summarizing the shot), `target_actor_id` (the `id` of the actor the camera focuses on in that shot!), `framing` ("full_body" | "medium" | "closeup"), `fov_mm` (24 for wide, 35 for medium, 48 for closeup), `look_mode` ("lock_hero" or "dolly_blend"), and 2 to 3 `waypoints` `[{"x": ..., "y": ..., "z": ...}]`.

Return ONLY valid JSON matching this schema:
{
  "scene_name_vi": "Tên bối cảnh tiếng Việt",
  "duration": 15.0,
  "h3_duration": 15.0,
  "hero_desc": "Concise English description of main characters (<Picture 1>, <Picture 2>, etc.)",
  "scene_desc": "Concise English description of environment",
  "walls": [{"x1": -7.5, "y1": -5.8, "x2": 7.5, "y2": -5.8, "h": 3.5, "type": "wall"}],
  "props": [{"id": "p_1", "type": "street_lamp", "label": "Đèn Lồng Đá", "x": -2.5, "y": -3.0, "w": 0.5, "d": 0.5, "h": 2.6, "angle": 0}],
  "actors": [
    {"id": "hero_1", "role": "hero", "pic_idx": 1, "label": "Nhân vật chính (Ảnh 1)", "x": 0.0, "y": -2.1, "angle": 90, "pose": "stand", "action": "walk", "height": 1.70, "radius": 0.25, "walk_to": {"x": 0.0, "y": -1.1}, "walk_start_u": 0.15}
  ],
  "shots": [
    {"id": "shot_1", "name": "Shot 1: Toàn cảnh theo chân", "duration": 3.0, "target_actor_id": "hero_1", "fov_mm": 24, "framing": "full_body", "look_mode": "lock_hero", "ease_mode": "ease_out", "waypoints": [{"x": -0.4, "y": 1.2, "z": 0.95}, {"x": 0.1, "y": 0.2, "z": 1.15}]}
  ]
}"""

    # Gọi Local Gemini Cookie API (gemini-web-to-api trên 127.0.0.1:4981/openai/v1) với 4 model: gemini-3.1-pro / gemini-3.8-flash / gemini-4-argon / gemini-3.5-flash-lite
    try:
        st = get_gemini_web_status(auto_start=True)
        if st.get("connected"):
            api_url = st["api_url"].rstrip("/")
            req_model = (model or cfg.get("default_model") or "gemini-3.1-pro").strip()
            candidate_models = [req_model]
            for fb_m in ("gemini-3.8-flash", "gemini-3.1-pro", "gemini-3.5-flash-lite"):
                if fb_m not in candidate_models:
                    candidate_models.append(fb_m)
            for chosen_model in candidate_models[:2]:
                try:
                    payload = {
                        "model": chosen_model,
                        "messages": [{"role": "user", "content": f"{sys_instruction}\n\n=== USER PROMPT ===\n{idea}"}],
                        "stream": False,
                    }
                    req = urllib.request.Request(
                        f"{api_url}/chat/completions",
                        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
                        headers={"Content-Type": "application/json"},
                        method="POST",
                    )
                    with urllib.request.urlopen(req, timeout=30) as resp:
                        resp_json = json.loads(resp.read().decode("utf-8", errors="ignore"))
                    raw_reply = resp_json["choices"][0]["message"]["content"]
                    parsed = _extract_json_block(raw_reply)
                    if isinstance(parsed, dict) and parsed.get("actors") and parsed.get("shots"):
                        parsed["_ai_source"] = f"Gemini Cookie API ({chosen_model})"
                        return parsed
                except Exception:
                    continue
    except Exception:
        pass

    return None


def _deep_parse_structured_screenplay(idea: str) -> dict | None:
    """
    Bộ Phân Tích Kịch Bản Đa Phân Cảnh & Timecode Chuyên Sâu (Deep Screenplay & Timecode Analyzer):
    Xử lý chuẩn xác các prompt điện ảnh / hoạt hình 3D phức tạp có cấu trúc SETTING, CHARACTERS,
    mốc thời gian 00:00-00:03, 00:03-00:07..., hoặc cấu trúc [Shot 1], [Shot 2], integrated_multimodal_description.
    """
    import re as _re
    text = (idea or "").strip()
    lower = text.lower()

    tc_matches = list(_re.finditer(r"(\d{1,2}):(\d{2})\s*[-–—to]+\s*(\d{1,2}):(\d{2})\s*:\s*([^\n]+)", text))
    shot_tag_matches = list(_re.finditer(r"\[Shot\s*(\d+)\]\s*([^\[\n]+(?:\n(?!\[Shot\s*\d+\]|overall_soundscape:|non_diegetic_music:)[^\n]+)*)", text, flags=_re.IGNORECASE))
    is_xianxia_or_sect = any(k in lower for k in [
        "xianxia", "cultivation", "sect", "spiritual-root", "testing monument", "stone monument",
        "disciple", "lam phong", "trieu hao", "thanh van", "tông môn", "tu tiên", "linh căn",
        "bia đá", "đệ tử", "trưởng lão",
    ])
    is_ancient_village_or_lantern = any(k in lower for k in [
        "lantern-lit", "stone street", "village of", "vong hoa", "ancient village", "wooden stall",
        "female hunter", "suong", "sương", "moss-rock hound", "phố đá", "đèn lồng", "ngôi làng", "cổ trấn", "thợ săn",
    ])
    has_structured_sections = any(k in text for k in ["SETTING:", "CHARACTERS:", "CAMERA AND EDITING:", "integrated_multimodal_description:"])

    if not tc_matches and not shot_tag_matches and not is_xianxia_or_sect and not is_ancient_village_or_lantern and not has_structured_sections:
        return None

    # 1. Extract Total Duration
    total_dur = 15.0 if (tc_matches or len(shot_tag_matches) >= 3) else (10.0 if len(shot_tag_matches) == 2 else 6.0)
    m_dur = _re.search(r"\b(\d+(?:\.\d+)?)\s*-\s*second|\b(\d+(?:\.\d+)?)\s*seconds?\b|\b(\d+(?:\.\d+)?)\s*giây\b", lower)
    if m_dur:
        val_d = float(next(g for g in m_dur.groups() if g is not None))
        if 2.0 <= val_d <= 30.0:
            total_dur = val_d
    elif tc_matches:
        last_m = tc_matches[-1]
        end_sec = int(last_m.group(3)) * 60 + int(last_m.group(4))
        if 2 <= end_sec <= 30:
            total_dur = float(end_sec)

    # 2. Build Environment Walls & Props
    if is_xianxia_or_sect and not is_ancient_village_or_lantern:
        scene_name_vi = "Sân Đá Thanh Vân Tông (Cổ Trang Tu Tiên 3D)"
        walls = [
            {"x1": -8.0, "y1": -6.0, "x2": 8.0, "y2": -6.0, "h": 3.5, "type": "wall"},
            {"x1": -8.0, "y1": -6.0, "x2": -8.0, "y2": 3.2, "h": 3.2, "type": "wall"},
            {"x1": 8.0, "y1": -6.0, "x2": 8.0, "y2": 3.2, "h": 3.2, "type": "wall"},
        ]
        props = [
            {"id": "p_monument", "type": "monument", "label": "Bia Đá Linh Căn", "x": 0.0, "y": -3.05, "w": 1.05, "d": 0.65, "h": 2.35, "angle": 0},
            {"id": "p_stage", "type": "stage", "label": "Đài Đá Trung Tâm", "x": 0.0, "y": -2.55, "w": 3.4, "d": 2.6, "h": 0.20, "angle": 0},
            {"id": "p_hall", "type": "arch_gate", "label": "Đại Điện Tông Môn", "x": 0.0, "y": -5.55, "w": 5.2, "d": 0.85, "h": 3.4, "angle": 0},
            {"id": "p_pil_l", "type": "pillar", "label": "Cột Đá Trái", "x": -4.2, "y": -4.5, "w": 0.60, "d": 0.60, "h": 3.2, "angle": 0},
            {"id": "p_pil_r", "type": "pillar", "label": "Cột Đá Phải", "x": 4.2, "y": -4.5, "w": 0.60, "d": 0.60, "h": 3.2, "angle": 0},
        ]
    elif is_ancient_village_or_lantern:
        scene_name_vi = "Phố Đá Đèn Lồng Làng Vọng Hoa Ban Đêm (Hành Động 3D)"
        walls = [
            {"x1": -6.2, "y1": -6.2, "x2": 6.2, "y2": -6.2, "h": 3.2, "type": "wall"},
            {"x1": -4.8, "y1": -6.2, "x2": -4.8, "y2": 3.2, "h": 3.0, "type": "wall"},
            {"x1": 4.8, "y1": -6.2, "x2": 4.8, "y2": 3.2, "h": 3.0, "type": "wall"},
        ]
        props = [
            {"id": "p_stall_l", "type": "counter", "label": "Quầy Gỗ Cổ Trấn (Trái)", "x": -3.1, "y": -2.8, "w": 1.45, "d": 0.85, "h": 1.05, "angle": 12},
            {"id": "p_stall_r", "type": "counter", "label": "Quầy Gỗ Cổ Trấn (Phải)", "x": 3.1, "y": -2.2, "w": 1.45, "d": 0.85, "h": 1.05, "angle": -12},
            {"id": "p_lamp_l1", "type": "street_lamp", "label": "Đèn Lồng Đỏ Trái 1", "x": -2.35, "y": -3.8, "w": 0.42, "d": 0.42, "h": 2.65, "angle": 0},
            {"id": "p_lamp_r1", "type": "street_lamp", "label": "Đèn Lồng Đỏ Phải 1", "x": 2.35, "y": -3.8, "w": 0.42, "d": 0.42, "h": 2.65, "angle": 0},
            {"id": "p_lamp_l2", "type": "street_lamp", "label": "Đèn Lồng Đỏ Trái 2", "x": -2.35, "y": -1.1, "w": 0.42, "d": 0.42, "h": 2.65, "angle": 0},
            {"id": "p_lamp_r2", "type": "street_lamp", "label": "Đèn Lồng Đỏ Phải 2", "x": 2.35, "y": -1.1, "w": 0.42, "d": 0.42, "h": 2.65, "angle": 0},
            {"id": "p_tree_v", "type": "tree", "label": "Cây Cổ Thụ Đêm Mưa", "x": -3.5, "y": -4.9, "w": 1.15, "d": 1.15, "h": 2.85, "angle": 0},
        ]
    else:
        scene_name_vi = "Sân khấu / Phim trường điện ảnh 3D"
        walls = [
            {"x1": -7.5, "y1": -5.8, "x2": 7.5, "y2": -5.8, "h": 3.4, "type": "wall"},
            {"x1": -7.5, "y1": -5.8, "x2": -7.5, "y2": 3.0, "h": 3.4, "type": "wall"},
            {"x1": 7.5, "y1": -5.8, "x2": 7.5, "y2": 3.0, "h": 3.4, "type": "wall"},
        ]
        props = [
            {"id": "p_stage", "type": "stage", "label": "Bục Trung Tâm", "x": 0.0, "y": -3.2, "w": 3.4, "d": 2.2, "h": 0.25, "angle": 0},
        ]

    # 3. Extract Characters & Crowd Blocking
    actors = []
    if is_xianxia_or_sect and not is_ancient_village_or_lantern:
        has_kneel = any(k in lower for k in ["kneel", "kneeling", "quỳ"])
        p1_name = "Lam Phong" if "lam phong" in lower else "Nhân vật chính 1"
        p2_name = "Trưởng Lão (Elder)" if ("elder" in lower or "trưởng lão" in lower) else "Nhân vật 2"
        p3_name = "Triệu Hạo (Trieu Hao)" if ("trieu hao" in lower or "triệu hạo" in lower) else "Nhân vật 3"

        # Hero 1: Lam Phong kneeling before the stone testing monument
        actors.append({
            "id": "hero_1",
            "role": "hero",
            "pic_idx": 1,
            "label": f"{p1_name} (Ảnh 1 - {'Quỳ trước Bia' if has_kneel else 'Trung tâm'})",
            "x": 0.0,
            "y": -1.85,
            "angle": -90,
            "pose": "kneel" if has_kneel else "stand",
            "action": "reach" if ("lifts his right hand" in lower or "hand toward" in lower) else ("kneel" if has_kneel else "stand"),
            "radius": 0.25,
            "height": 1.18 if has_kneel else 1.72,
        })

        # Hero 2: Sect Elder standing near the monument speaking Mandarin
        if "elder" in lower or "trưởng lão" in lower:
            actors.append({
                "id": "hero_2",
                "role": "hero",
                "pic_idx": 2,
                "label": f"{p2_name} (Ảnh 2 - Thoại)",
                "x": -1.35,
                "y": -3.05,
                "angle": 65,
                "pose": "stand",
                "action": "talk",
                "radius": 0.25,
                "height": 1.72,
            })

        # Hero 3: Trieu Hao approaching from camera-right near the end (Shot 4: 00:11-00:15)
        if "trieu hao" in lower or "triệu hạo" in lower or "approaches from camera-right" in lower or "from screen-right" in lower:
            actors.append({
                "id": "hero_3",
                "role": "hero",
                "pic_idx": 3,
                "label": f"{p3_name} (Ảnh 3 - Bước vào)",
                "x": 2.85,
                "y": -1.55,
                "angle": 180,
                "pose": "stand",
                "action": "walk",
                "radius": 0.25,
                "height": 1.75,
                "walk_to": {"x": 1.05, "y": -1.75},
                "walk_start_u": 0.68,
            })

        # Two lines of disciples on left and right sides of the courtyard
        if "disciples" in lower or "đệ tử" in lower or "two lines" in lower:
            for row_i, dy_pos in enumerate([-1.1, -2.3, -3.5], start=1):
                actors.append({
                    "id": f"disc_l_{row_i}",
                    "role": "crowd",
                    "pic_idx": 0,
                    "label": f"Đệ tử Trái {row_i}",
                    "x": -2.95,
                    "y": dy_pos,
                    "angle": 0,
                    "pose": "stand",
                    "action": "stand",
                    "radius": 0.22,
                    "height": 1.70,
                })
                actors.append({
                    "id": f"disc_r_{row_i}",
                    "role": "crowd",
                    "pic_idx": 0,
                    "label": f"Đệ tử Phải {row_i}",
                    "x": 2.95,
                    "y": dy_pos,
                    "angle": 180,
                    "pose": "stand",
                    "action": "stand",
                    "radius": 0.22,
                    "height": 1.70,
                })
    else:
        # Tự động trích xuất tên nhân vật từ kịch bản (VD: "Suong, a 24-year-old female hunter")
        named_chars = []
        for m_nm in _re.finditer(r"\b([A-ZÀÁẠẢÃÂẦẤẬẨẪĂẰẮẶẲẴÈÉẸẺẼÊỀẾỆỂỄÌÍỊỈĨÒÓỌỎÕÔỒỐỘỔỖƠỜỚỢỞỠÙÚỤỦŨƯỪỨỰỬỮỲÝỴỶỸĐ][a-zàáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđ]+(?:\s+[A-Z][a-z]+)?)\s*,\s*a\s+\d+", text):
            nm = m_nm.group(1).strip()
            if nm.lower() not in ("shot", "for", "from", "with", "in", "at", "the") and nm not in named_chars:
                named_chars.append(nm)
        if not named_chars and ("suong" in lower or "sương" in lower):
            named_chars.append("Sương - Nữ Thợ Săn")
        c1_lbl = f"{named_chars[0]} (Ảnh 1)" if len(named_chars) >= 1 else "Nhân vật chính 1 (Ảnh 1)"
        has_hounds = any(k in lower for k in ["hound", "wolf", "wolves", "monster", "creature", "khuyển", "quái", "sói"])
        if has_hounds:
            actors = [
                {
                    "id": "hero_1", "role": "hero", "pic_idx": 1, "label": c1_lbl,
                    "x": 0.0, "y": -2.35, "angle": 90, "pose": "stand",
                    "action": "walk", "radius": 0.25, "height": 1.70,
                    "walk_to": {"x": 0.0, "y": -1.05}, "walk_start_u": 0.10,
                },
                {
                    "id": "hound_1", "role": "crowd", "pic_idx": 0, "label": "Hắc Khuyển Đá Rêu 1 (Trái)",
                    "x": -1.55, "y": -1.50, "angle": -25, "pose": "stand",
                    "action": "walk", "radius": 0.28, "height": 1.35,
                    "walk_to": {"x": -0.75, "y": -1.45}, "walk_start_u": 0.12,
                },
                {
                    "id": "hound_2", "role": "crowd", "pic_idx": 0, "label": "Hắc Khuyển Đá Rêu 2 (Phải)",
                    "x": 1.55, "y": -1.50, "angle": 205, "pose": "stand",
                    "action": "walk", "radius": 0.28, "height": 1.35,
                    "walk_to": {"x": 0.75, "y": -1.45}, "walk_start_u": 0.18,
                },
                {
                    "id": "hound_3", "role": "crowd", "pic_idx": 0, "label": "Hắc Khuyển Đá Rêu 3 (Sau)",
                    "x": 0.0, "y": -3.55, "angle": 90, "pose": "stand",
                    "action": "reach", "radius": 0.28, "height": 1.38,
                },
            ]
        else:
            c2_lbl = f"{named_chars[1]} (Ảnh 2)" if len(named_chars) >= 2 else "Nhân vật 2 (Ảnh 2)"
            has_walk_s = any(k in lower for k in ["walk", "run", "step", "dash", "leap", "approaches", "tiến", "bước"])
            actors = [
                {
                    "id": "hero_1", "role": "hero", "pic_idx": 1, "label": c1_lbl,
                    "x": 0.0, "y": -2.5, "angle": 90, "pose": "stand",
                    "action": "walk" if has_walk_s else "stand", "radius": 0.25, "height": 1.70,
                    **({"walk_to": {"x": 0.0, "y": -1.35}, "walk_start_u": 0.15} if has_walk_s else {}),
                },
                {
                    "id": "hero_2", "role": "hero", "pic_idx": 2, "label": c2_lbl,
                    "x": -1.35, "y": -3.2, "angle": 70, "pose": "stand", "action": "talk", "radius": 0.24, "height": 1.72,
                },
            ]

    # 4. Build Multi-Shot Camera Cuts from Timecodes (00:00-00:03...) OR [Shot 1]..[Shot N]
    shots = []
    if tc_matches:
        for idx_s, m_tc in enumerate(tc_matches, start=1):
            t0 = int(m_tc.group(1)) * 60 + int(m_tc.group(2))
            t1 = int(m_tc.group(3)) * 60 + int(m_tc.group(4))
            s_dur = max(1.0, float(t1 - t0))
            tc_str = f"{m_tc.group(1)}:{m_tc.group(2)}-{m_tc.group(3)}:{m_tc.group(4)}"
            desc_s = m_tc.group(5).strip()
            desc_low = desc_s.lower()

            target_id = "hero_1"
            if ("elder" in desc_low or "trưởng lão" in desc_low) and any(a["id"] == "hero_2" for a in actors):
                target_id = "hero_2"
            elif ("trieu hao" in desc_low or "triệu hạo" in desc_low) and "lam phong" not in desc_low and any(a["id"] == "hero_3" for a in actors):
                target_id = "hero_3"

            t_ac = next((a for a in actors if a["id"] == target_id), actors[0])
            tx, ty = float(t_ac["x"]), float(t_ac["y"])

            if "crane" in desc_low or "establishing" in desc_low or "wide" in desc_low:
                s_framing = "full_body"
                s_fov = 24
                s_name = f"Cảnh {idx_s} ({tc_str}): Toàn cảnh Hạ máy (Crane Down)"
                s_wps = [
                    {"x": 0.0, "y": 2.95, "z": 2.35},
                    {"x": 0.0, "y": 1.45, "z": 1.32},
                ]
            elif "side shot" in desc_low or "medium side" in desc_low or "lifts his right hand" in desc_low:
                s_framing = "medium"
                s_fov = 35
                s_name = f"Cảnh {idx_s} ({tc_str}): Góc nghiêng {t_ac['label'].split('(')[0].strip()} & Bia Đá"
                s_wps = [
                    {"x": round(tx - 2.25, 2), "y": round(ty - 0.35, 2), "z": 1.12},
                    {"x": round(tx - 1.75, 2), "y": round(ty - 0.45, 2), "z": 1.08},
                ]
            elif "close-up" in desc_low or "closeup" in desc_low or "close up" in desc_low:
                s_framing = "closeup"
                s_fov = 48
                s_name = f"Cảnh {idx_s} ({tc_str}): Cận trung {t_ac['label'].split('(')[0].strip()} phát ngôn"
                s_wps = [
                    {"x": round(tx + 0.20, 2), "y": round(ty + 1.55, 2), "z": 1.48},
                    {"x": round(tx + 0.10, 2), "y": round(ty + 1.32, 2), "z": 1.50},
                ]
            elif "eye level" in desc_low or "eye-level" in desc_low or "approaches from" in desc_low or "screen-right" in desc_low:
                s_framing = "full_body"
                s_fov = 30
                s_name = f"Cảnh {idx_s} ({tc_str}): Ngang tầm mắt & Triệu Hạo bước vào"
                s_wps = [
                    {"x": round(tx + 0.35, 2), "y": round(ty + 2.55, 2), "z": 1.06},
                    {"x": round(tx + 0.45, 2), "y": round(ty + 2.30, 2), "z": 1.02},
                ]
            else:
                s_framing = "full_body"
                s_fov = 28
                s_name = f"Cảnh {idx_s} ({tc_str}): Góc máy {idx_s}"
                s_wps = [
                    {"x": round(tx - 0.5, 2), "y": round(ty + 2.8, 2), "z": 1.24},
                    {"x": round(tx, 2), "y": round(ty + 2.4, 2), "z": 1.22},
                ]

            shots.append({
                "id": f"shot_{idx_s}",
                "name": s_name,
                "duration": s_dur,
                "target_actor_id": target_id,
                "fov_mm": s_fov,
                "framing": s_framing,
                "look_mode": "lock_hero",
                "ease_mode": "ease_out",
                "waypoints": s_wps,
                "note_en": desc_s,
            })
    elif shot_tag_matches:
        n_sh = len(shot_tag_matches)
        per_dur = round(max(2.0, total_dur / max(1, n_sh)), 1)
        for idx_s, m_sh in enumerate(shot_tag_matches, start=1):
            desc_s = " ".join(m_sh.group(2).strip().split())
            desc_low = desc_s.lower()
            target_id = "hero_1"
            t_ac = next((a for a in actors if a["id"] == target_id), actors[0])
            tx, ty = float(t_ac["x"]), float(t_ac["y"])
            cam_z_s = 0.82 if ("low wide" in desc_low or "low angle" in desc_low or "low-angle" in desc_low) else (2.05 if ("high angle" in desc_low or "crane" in desc_low or "overhead" in desc_low) else 1.28)
            if "close-up" in desc_low or "closeup" in desc_low or "close up" in desc_low:
                s_framing, s_fov = "closeup", 46
                s_lbl = "Cận cảnh (Close-up)"
                s_wps = [{"x": round(tx + 0.25, 2), "y": round(ty + 1.55, 2), "z": 1.48}, {"x": round(tx + 0.05, 2), "y": round(ty + 1.25, 2), "z": 1.52}]
            elif "medium" in desc_low or "side" in desc_low or "over-the-shoulder" in desc_low or "whip-pan" in desc_low:
                s_framing, s_fov = "medium", 34
                s_lbl = "Trung cảnh / Lia máy hành động"
                side_sign = -1.0 if idx_s % 2 == 1 else 1.0
                s_wps = [{"x": round(tx + side_sign * 1.65, 2), "y": round(ty + 1.55, 2), "z": cam_z_s}, {"x": round(tx + side_sign * 0.85, 2), "y": round(ty + 1.25, 2), "z": cam_z_s}]
            else:
                s_framing, s_fov = "full_body", 24 if "wide" in desc_low else 28
                s_lbl = "Toàn cảnh góc thấp (Low Wide)" if cam_z_s < 1.0 else "Toàn cảnh theo chân (Tracking)"
                s_wps = [{"x": round(tx - 0.55, 2), "y": round(ty + 2.95, 2), "z": cam_z_s}, {"x": round(tx + 0.25, 2), "y": round(ty + 1.85, 2), "z": round(cam_z_s + 0.14, 2)}]
            shots.append({
                "id": f"shot_{idx_s}",
                "name": f"Shot {idx_s} ({per_dur:g}s): {s_lbl}",
                "duration": per_dur,
                "target_actor_id": target_id,
                "fov_mm": s_fov,
                "framing": s_framing,
                "look_mode": "lock_hero",
                "ease_mode": "ease_out",
                "waypoints": s_wps,
                "note_en": desc_s[:240],
            })
    else:
        # Hỗ trợ tự động chia các nhịp cắt máy ngăn cách bởi dấu chấm phẩy `;` trong integrated_multimodal_description
        main_body = _re.split(r"\boverall_soundscape\s*:|\bnon_diegetic_music\s*:", text, flags=_re.IGNORECASE)[0]
        semi_clauses = [c.strip() for c in main_body.split(";") if len(c.strip()) >= 20]
        if 2 <= len(semi_clauses) <= 8:
            n_sh = len(semi_clauses)
            per_dur = round(max(2.0, total_dur / max(1, n_sh)), 1)
            t_ac = actors[0]
            tx, ty = float(t_ac["x"]), float(t_ac["y"])
            for idx_s, desc_s in enumerate(semi_clauses, start=1):
                desc_low = desc_s.lower()
                cam_z_s = 0.82 if ("low-angle" in desc_low or "low angle" in desc_low or "crouch" in desc_low) else 1.26
                if "close-up" in desc_low or "closeup" in desc_low or "spinning strike" in desc_low:
                    s_framing, s_fov = "closeup", 46
                    s_lbl = "Cận cảnh xoay máy (Close-up Strike)"
                    s_wps = [{"x": round(tx + 0.30, 2), "y": round(ty + 1.55, 2), "z": 1.46}, {"x": round(tx - 0.15, 2), "y": round(ty + 1.22, 2), "z": 1.50}]
                elif "over-the-shoulder" in desc_low or "rolls sideways" in desc_low or "lunges" in desc_low:
                    s_framing, s_fov = "medium", 34
                    s_lbl = "Góc qua vai (Over-the-Shoulder)" if "over-the-shoulder" in desc_low else "Trung cảnh chiến đấu & Thoại"
                    side_sign = -1.0 if idx_s % 2 == 0 else 1.0
                    s_wps = [{"x": round(tx + side_sign * 1.55, 2), "y": round(ty + 1.50, 2), "z": cam_z_s}, {"x": round(tx + side_sign * 0.80, 2), "y": round(ty + 1.20, 2), "z": cam_z_s}]
                else:
                    s_framing, s_fov = "full_body", 24 if ("pushes in" in desc_low or idx_s == 1) else 28
                    s_lbl = "Đẩy máy nhanh (Fast Push-in)" if "pushes in" in desc_low else ("Góc thấp kết cảnh (Final Low-Angle)" if "low-angle" in desc_low else "Toàn cảnh hành động")
                    s_wps = [{"x": round(tx - 0.45, 2), "y": round(ty + 3.05, 2), "z": cam_z_s}, {"x": round(tx + 0.15, 2), "y": round(ty + 1.75, 2), "z": round(cam_z_s + 0.12, 2)}]
                shots.append({
                    "id": f"shot_{idx_s}",
                    "name": f"Cắt cảnh {idx_s} ({per_dur:g}s): {s_lbl}",
                    "duration": per_dur,
                    "target_actor_id": "hero_1",
                    "fov_mm": s_fov,
                    "framing": s_framing,
                    "look_mode": "lock_hero",
                    "ease_mode": "ease_out",
                    "waypoints": s_wps,
                    "note_en": desc_s[:240],
                })

    if not shots:
        shots = [{
            "id": "shot_1",
            "name": "Cảnh 1: Toàn cảnh Hạ máy (Crane Down)",
            "duration": total_dur,
            "target_actor_id": "hero_1",
            "fov_mm": 26,
            "framing": "full_body",
            "look_mode": "lock_hero",
            "ease_mode": "ease_out",
            "waypoints": [{"x": 0.0, "y": 2.9, "z": 2.25}, {"x": 0.0, "y": 0.9, "z": 1.22}],
        }]

    prop_names = ", ".join(p["label"] for p in props)
    hero_names = ", ".join(a["label"] for a in actors if a["role"] == "hero")
    crowd_cnt = sum(1 for a in actors if a["role"] != "hero")
    crowd_suffix = f" + {crowd_cnt} nhân vật phụ" if crowd_cnt > 0 else ""

    return {
        "ok": True,
        "walls": walls,
        "props": props,
        "actors": actors,
        "waypoints": shots[0]["waypoints"],
        "shots": shots,
        "fov_mm": shots[0]["fov_mm"],
        "framing": shots[0]["framing"],
        "duration": total_dur,
        "h3_duration": total_dur,
        "original_script": text,
        "hero_desc": f"<Picture 1> ({actors[0]['label']})" + (f", <Picture 2> ({actors[1]['label']})" if len(actors) >= 2 else ""),
        "scene_desc": f"{scene_name_vi} ({prop_names})",
        "analysis": {
            "scene_vi": f"{scene_name_vi} ({len(props)} đạo cụ: {prop_names})",
            "actors_vi": f"{len(actors)} nhân vật ({hero_names}{crowd_suffix})",
            "camera_vi": f"{len(shots)} góc máy cắt tự động ({total_dur:g}s)",
            "ai_engine": "Deep Multi-Shot Screenplay Analyzer",
        },
    }


def build_cam01_scene_with_ai(idea_text: str, model: str = "gemini-3.1-pro", api_key: str = "", use_gemini: bool = True) -> dict:
    """
    Bộ Nhận Diện Prompt Thông Minh (Kết hợp Deep Screenplay Timecode/Multi-Shot Analyzer + Gemini Cookie API + Local Scene Engine):
    1. Nếu kịch bản là kịch bản phân cảnh có cấu trúc rõ ràng (`00:00-00:03`, `[Shot 1]..[Shot N]`, `SETTING:`, `CHARACTERS:`, Làng cổ Vọng Hoa, Tu tiên...):
       - Sử dụng bộ Deep Multi-Shot Screenplay Analyzer phản hồi tức thì (<0.05s) với bố cục nhân vật, đạo cụ và từng góc máy khớp 100% kịch bản.
    2. Nếu là kịch bản tự do khác: gọi Gemini Cookie API hoặc bộ nhận diện bối cảnh 3D.
    """
    idea = (idea_text or "").strip()
    lower = idea.lower()
    import re as _re

    # BƯỚC 0A: Nếu là kịch bản phân cảnh chuyên sâu có cấu trúc [Shot 1]..[Shot N] hoặc Timecode (00:00-00:03...)
    deep_res = _deep_parse_structured_screenplay(idea)
    if deep_res:
        return deep_res

    # BƯỚC 0B: Gọi Gemini Cookie API (3.1 Pro / 3.8 Flash / 4 Argon / 3.5 Flash-Lite) cho các kịch bản phức tạp khác
    if use_gemini and (api_key or len(idea) > 60):
        gem_res = _call_gemini_for_cam01_scene(idea, model=model, api_key=api_key)
        if gem_res and isinstance(gem_res.get("actors"), list) and isinstance(gem_res.get("shots"), list):
            allow_kneel = any(k in lower for k in ["kneeling", "kneel before", "quỳ"])
            for ac_g in gem_res["actors"]:
                if isinstance(ac_g, dict) and ac_g.get("pose") == "kneel" and not allow_kneel:
                    ac_g["pose"] = "stand"
                    ac_g["height"] = max(float(ac_g.get("height") or 1.70), 1.68)
            shots_g = gem_res["shots"]
            wps_0 = shots_g[0].get("waypoints") if shots_g else [{"x": 0.0, "y": 2.4, "z": 1.24}, {"x": 0.0, "y": 0.5, "z": 1.22}]
            props_g = gem_res.get("props") or (deep_res.get("props") if deep_res else [])
            walls_g = gem_res.get("walls") or (deep_res.get("walls") if deep_res else [{"x1": -7.5, "y1": -5.8, "x2": 7.5, "y2": -5.8, "h": 3.4, "type": "wall"}])
            dur_g = float(gem_res.get("duration") or (deep_res.get("duration") if deep_res else 5.0))
            prop_names_g = ", ".join(str(p.get("label") or p.get("type")) for p in props_g)
            return {
                "ok": True,
                "walls": walls_g,
                "props": props_g,
                "actors": gem_res["actors"],
                "waypoints": wps_0,
                "shots": shots_g,
                "fov_mm": int(shots_g[0].get("fov_mm") or 28),
                "framing": str(shots_g[0].get("framing") or "full_body"),
                "duration": dur_g,
                "h3_duration": float(gem_res.get("h3_duration") or dur_g),
                "original_script": idea,
                "hero_desc": str(gem_res.get("hero_desc") or ""),
                "scene_desc": str(gem_res.get("scene_desc") or ""),
                "analysis": {
                    "scene_vi": f"{gem_res.get('scene_name_vi') or 'Bối cảnh 3D'} ({len(props_g)} đạo cụ: {prop_names_g})",
                    "actors_vi": f"{len(gem_res['actors'])} nhân vật ({gem_res.get('_ai_source', 'Gemini')})",
                    "camera_vi": f"{len(shots_g)} góc máy cắt tự động ({dur_g:g}s)",
                    "ai_engine": gem_res.get("_ai_source", "Gemini"),
                },
            }

    if deep_res:
        return deep_res

    # 1. NHẬN DIỆN SỐ LƯỢNG NGƯỜI TRONG PROMPT NGẮN
    vn_num_map = {
        "một": 1, "hai": 2, "ba": 3, "bốn": 4, "tư": 4, "năm": 5,
        "sáu": 6, "bảy": 7, "tám": 8, "chín": 9, "mười": 10,
        "cặp đôi": 2, "đôi nam nữ": 2, "hai người": 2, "ba người": 3, "bốn người": 4, "năm người": 5,
        "two": 2, "three": 3, "four": 4, "five": 5, "six": 6,
    }
    total_people = None
    m_people = _re.search(r"\b(\d+)\s*(người|nhân vật|khách|cô gái|chàng trai|bạn|đàn ông|phụ nữ|ca sĩ|diễn viên|đệ tử|people|person|characters|men|women|girls|boys|disciples)\b", lower)
    if m_people:
        v = int(m_people.group(1))
        if 1 <= v <= 25:
            total_people = v
    if total_people is None:
        for k_word, k_val in vn_num_map.items():
            if _re.search(rf"\b{_re.escape(k_word)}\s*(người|nhân vật|khách|cô gái|chàng trai|bạn|đệ tử)?\b", lower):
                total_people = k_val
                break
    if total_people is None:
        pic_tags = set(_re.findall(r"<picture\s*(\d+)>|ảnh\s*(\d+)", lower))
        if pic_tags:
            total_people = max(len(pic_tags), 2)

    # 2. NHẬN DIỆN TƯ THẾ & HÀNH ĐỘNG CỦA NHÂN VẬT
    has_kneel = any(k in lower for k in ["quỳ", "quỳ gối", "kneel", "kneeling", "kneels"])
    has_sit = any(k in lower for k in ["ngồi", "sit", "sitting", "seated", "trên sofa", "trên ghế"])
    has_walk = any(k in lower for k in ["đi bộ", "bước vào", "bước tới", "bước đi", "tiến vào", "dạo bước", "walk", "walking", "steps forward", "approaches"])
    has_wave = any(k in lower for k in ["vẫy tay", "chào", "giơ tay", "wave", "waving"])
    has_talk = any(k in lower for k in ["nói chuyện", "trò chuyện", "thuyết trình", "hát", "biểu diễn", "talking", "speaking", "singing", "says"])
    has_drink = any(k in lower for k in ["cầm ly", "uống", "nâng ly", "cà phê", "rượu", "drinking", "holding a glass"])

    # 3. NHẬN DIỆN BỐI CẢNH CHÍNH & BỘ ĐẠO CỤ MẶC ĐỊNH THEO BỐI CẢNH
